-- INSTANT RE-EXEC: keep all startup implementation locals INSIDE one
-- function. Only pvSession remains live in the main Luau chunk, avoiding the
-- 200-register overflow in the item UI builder.
local pvSession = (function()
    local shared = (type(getgenv)=="function" and getgenv()) or _G
    local old = rawget(shared,"__porkVisualsSession") or rawget(_G,"__porkVisualsSession")
    if type(old)=="table" and type(old.shutdown)=="function" then
        pcall(old.shutdown)
    end
    _G.pvGen = (_G.pvGen or 0) + 1
    _G.pvInvRepinGen = (_G.pvInvRepinGen or 0) + 1
    _G.pvAutoTrade = false
    _G.pvBlockInProgress = false

    pcall(function()
        if _G.pvGuiAncestryConn then
            _G.pvGuiAncestryConn:Disconnect()
            _G.pvGuiAncestryConn=nil
        end
    end)
    local function clearPreviousRoots()
        -- CoreGui:GetChildren() can be security-restricted even if
        -- game:GetService("CoreGui") succeeds. Never let GUI cleanup abort startup.
        local containers = {}
        local part = Players.LocalPlayer
        local playerGui = part and part:FindFirstChild("PlayerGui")
        if playerGui then containers[#containers+1]=playerGui end
        local success,core=pcall(function() return game:GetService("CoreGui") end)
        if success and core then containers[#containers+1]=core end
        if type(gethui)=="function" then
            local good,result=pcall(gethui)
            if good and result then containers[#containers+1]=result end
        end
        local kill={porkVisuals=true,porkToggle=true,PorkVisualsFPSCounter=true,
                    pvTradeReq=true,pvTradeGUI=true,pvBlocked=true}
        local visited={}
        for _,root in ipairs(containers) do
            if root and not visited[root] then
                visited[root]=true
                local allowed,children=pcall(function() return root:GetChildren() end)
                if allowed and children then
                    for _,child in ipairs(children) do
                        if kill[child.Name] then pcall(function() child:Destroy() end) end
                    end
                end
            end
        end
    end
    clearPreviousRoots()

    local session={alive=true,generation=_G.pvGen,connections={},cleanups={},roots={},streamerHidden=false}
    session.streamerSaved=setmetatable({}, {__mode="k"})
    function session.setStreamerHidden(enabled)
        enabled=enabled==true
        session.streamerHidden=enabled
        for _,root in ipairs(session.roots) do
            if root then
                local success,isScreenGui=pcall(function() return root:IsA("ScreenGui") end)
                if success and isScreenGui then
                    if enabled then
                        if session.streamerSaved[root]==nil then
                            local readOk,wasEnabled=pcall(function() return root.Enabled end)
                            if readOk then session.streamerSaved[root]=wasEnabled end
                        end
                        pcall(function() root.Enabled=false end)
                    else
                        local wasEnabled=session.streamerSaved[root]
                        if wasEnabled~=nil then pcall(function() root.Enabled=wasEnabled end) end
                        session.streamerSaved[root]=nil
                    end
                end
            end
        end
    end
    function session.connect(signal,callback)
        local conn=signal:Connect(callback)
        if session.alive then
            session.connections[#session.connections+1]=conn
        else
            conn:Disconnect()
        end
        return conn
    end
    function session.addCleanup(fnValue)
        session.cleanups[#session.cleanups+1]=fnValue
    end
    function session.ownRoot(root)
        session.roots[#session.roots+1]=root
        if session.streamerHidden and root then
            local success,isScreenGui=pcall(function() return root:IsA("ScreenGui") end)
            if success and isScreenGui then
                local readOk,wasEnabled=pcall(function() return root.Enabled end)
                if readOk then session.streamerSaved[root]=wasEnabled end
                pcall(function() root.Enabled=false end)
            end
        end
        return root
    end
    function session.shutdown()
        if not session.alive then return end
        session.alive=false
        if _G.pvGen==session.generation then _G.pvGen=_G.pvGen+1 end
        _G.pvInvRepinGen=(_G.pvInvRepinGen or 0)+1
        _G.pvAutoTrade=false
        _G.pvBlockInProgress=false
        -- Remove visible windows before slower event and tool cleanup.
        for index=#session.roots,1,-1 do
            local root=session.roots[index]
            if root then pcall(function() root:Destroy() end) end
        end
        for index=#session.cleanups,1,-1 do pcall(session.cleanups[index]) end
        for index=#session.connections,1,-1 do
            pcall(function() session.connections[index]:Disconnect() end)
        end
        table.clear(session.connections)
        pcall(function()
            if _G.pvGuiAncestryConn then
                _G.pvGuiAncestryConn:Disconnect()
                _G.pvGuiAncestryConn=nil
            end
        end)
        clearPreviousRoots()
        if rawget(shared,"__porkVisualsSession")==session then
            shared.__porkVisualsSession=nil
        end
        if rawget(_G,"__porkVisualsSession")==session then
            _G.__porkVisualsSession=nil
        end
    end
    shared.__porkVisualsSession=session
    _G.__porkVisualsSession=session
    return session
end)()


