function pvTick(name, secs)
    if not _G.pvProfOn then task.wait(secs) return end
    _G.pvProf   = _G.pvProf   or {}
    _G.pvTickAt = _G.pvTickAt or {}
    local value = _G.pvProf[name]
    if not value then value={n=0,tot=0,max=0}; _G.pvProf[name]=value end
    local last = _G.pvTickAt[name]
    if last then
        local dtValue=(os.clock()-last)*1000
        value.n=value.n+1; value.tot=value.tot+dtValue; if dtValue>value.max then value.max=dtValue end
    end
    task.wait(secs)
    _G.pvTickAt[name]=os.clock()
end
function pvProf(name, fnValue)
    if not _G.pvProfOn then return fnValue() end
    _G.pvProf = _G.pvProf or {}
    local value = _G.pvProf[name]
    if not value then value = {n=0, tot=0, max=0}; _G.pvProf[name]=value end
    local t0Value = os.clock()
    local first,button = fnValue()
    local dtValue = (os.clock()-t0Value)*1000
    value.n = value.n + 1
    value.tot = value.tot + dtValue
    if dtValue > value.max then value.max = dtValue end
    return first,button
end
