local pvAPI = {}
do
    local genv = (getgenv and getgenv()) or _G
    local function firstOf(...)
        for _,number in ipairs({...}) do
            local func = rawget(genv, number)
            if type(func)~="function" then func = rawget(_G, number) end
            if type(func)~="function" then local success,result=pcall(function() return getfenv(0)[number] end); if success then func=result end end
            if type(func)=="function" then return func end
        end
    end
    pvAPI.gethui        = firstOf("gethui","get_hidden_gui","gethiddenui")
    pvAPI.setclipboard  = firstOf("setclipboard","toclipboard","set_clipboard","write_clipboard")
    pvAPI.getclipboard  = firstOf("getclipboard","get_clipboard","readclipboard","read_clipboard")
    pvAPI.getconnections= firstOf("getconnections","get_signal_cons")
    pvAPI.firetouch     = firstOf("firetouchinterest","firetouchinterest")
    pvAPI.mousemoveabs  = firstOf("mousemoveabs","mousemoveabsolute")
    pvAPI.mouse1press   = firstOf("mouse1press","mouse1down")
    pvAPI.mouse1release = firstOf("mouse1release","mouse1up")
    pvAPI.mouse1click   = firstOf("mouse1click")
    pvAPI.hookfunction  = firstOf("hookfunction","replaceclosure","hookfunc")
    pvAPI.setfpscap     = firstOf("setfpscap","set_fps_cap","setfpsmax")
    pvAPI.setfflag      = firstOf("setfflag","set_fflag","setfastflag")
    pvAPI.getcustomasset= firstOf("getcustomasset","getsynasset","getcustomasseturi")
    pvAPI.protectgui    = firstOf("protectgui","protect_gui")
    pvAPI.readfile      = firstOf("readfile")
    pvAPI.writefile     = firstOf("writefile")
    pvAPI.isfile        = firstOf("isfile")
    pvAPI.delfile       = firstOf("delfile","delfile")
    pvAPI.request       = firstOf("request","http_request","httprequest") or (syn and syn.request) or (http and http.request)

    pvAPI.has = {}
    for index,pvAPIItem in pairs(pvAPI) do if index~="has" then pvAPI.has[index] = (pvAPIItem ~= nil) end end


    if not gethui and pvAPI.gethui then
        pcall(function() genv.gethui = pvAPI.gethui end)
    end
    _G.pvAPI = pvAPI
end
do
    local function execName()
        local number
        pcall(function() if identifyexecutor then number = (identifyexecutor()) end end)
        pcall(function() if not number and getexecutorname then number = getexecutorname() end end)
        return tostring(number or ""):lower()
    end
    local name = execName()


    if name:find("xeno",1,true) then
        pcall(function()
            local screenGui=Instance.new("ScreenGui"); screenGui.Name="pvBlocked"; screenGui.IgnoreGuiInset=true
            screenGui.DisplayOrder=2e9; screenGui.Parent=(gethui and gethui()) or game:GetService("CoreGui")
            local frame=Instance.new("Frame"); frame.Size=UDim2.fromOffset(360,120)
            frame.Position=UDim2.new(0.5,-180,0,80); frame.BackgroundColor3=Color3.fromRGB(16,16,18)
            frame.BorderSizePixel=0; frame.Parent=screenGui
            local textLabel=Instance.new("TextLabel"); textLabel.Size=UDim2.new(1,-20,1,-20); textLabel.Position=UDim2.fromOffset(10,10)
            textLabel.BackgroundTransparency=1; textLabel.Font=Enum.Font.GothamBold; textLabel.TextSize=13; textLabel.TextWrapped=true
            textLabel.TextColor3=Color3.new(1,1,1)
            textLabel.Text="porkVisuals doesn't run on Xeno.\nXeno is compromised (ratted) -- use any other executor (Delta, Volt, Wave, Synapse, Codex...)."
            textLabel.Parent=frame
        end)
        return
    end
end
local function host()
    -- Prefer supported executor hidden-UI containers only when readable.
    -- CoreGui itself is not a safe fallback in restricted Plugin/client threads.
    if UIS.TouchEnabled then return playerGui2 end
    local getter=(pvAPI and pvAPI.gethui) or (type(gethui)=="function" and gethui)
    if type(getter)=="function" then
        local success,result=pcall(getter)
        if success and result then
            local readable=pcall(function() return result:GetChildren() end)
            if readable then return result end
        end
    end
    return playerGui2
end
