_invPending, _invArgs = false, nil

function pvInvOpen()
    local success,result = pcall(function()
        local playerGui3 = playerGui and playerGui:FindFirstChild("PlayerGui")
        playerGui3 = playerGui3 and playerGui3:FindFirstChild("MainGUI")
        local game2  = playerGui3 and playerGui3:FindFirstChild("Game")
        if not game2 then return false end
        for _,number in ipairs({"Inventory2","Inventory"}) do
            local inventory=game2:FindFirstChild(number)
            if inventory and inventory.Visible then return true end
        end
        return false
    end)
    return success and result or false
end
function invChanged(cat, id, number)


    if not pvInvOpen() then
        _G.pvPendingInv = {id, number}
        return
    end
    _invArgs = {cat or "Weapons", id, number}
    if _invPending then return end
    _invPending = true
    task.delay(0.2, function()
        _invPending = false
        local first = _invArgs or {"Weapons"}
        pcall(function() InvChangedEvent:Fire(first[1], first[2], first[3]) end)
    end)
end


function pvNormalInventoryLeaf(id)
    local entry=Sync and Sync.Weapons and Sync.Weapons[id]
    if not entry then return nil end
    local playerGui3=playerGui and playerGui:FindFirstChild("PlayerGui") and playerGui.PlayerGui:FindFirstChild("MainGUI")
    local game2=playerGui3 and playerGui3:FindFirstChild("Game")
    local inventory2=game2 and (game2:FindFirstChild("Inventory2") or game2:FindFirstChild("Inventory"))
    local main=inventory2 and inventory2:FindFirstChild("Main")
    local weap=main and main:FindFirstChild("Weapons")
    local its=weap and weap:FindFirstChild("Items")
    local root=its and its:FindFirstChild("Container")
    if not root then return nil end

    local function directContainer(x)
        return x and (x:FindFirstChild("Container") or x) or nil
    end
    if entry.Event=="Christmas" or entry.Event=="Halloween" then
        local holiday=root:FindFirstChild("Holiday")
        if not holiday then return nil end

        local container=holiday:FindFirstChild("Container") or holiday
        local evValue=container:FindFirstChild(tostring(entry.Event)) or holiday:FindFirstChild(tostring(entry.Event),true)
        return directContainer(evValue) or container
    elseif entry.Season then
        return directContainer(root:FindFirstChild("Current"))
    else
        return directContainer(root:FindFirstChild("Classic"))
    end
end


function pvNormalInventoryRow(id)
    local found
    pcall(function()
        local model=require(replicatedStorageService.Modules.InventoryModule)
        local root=model and model.MyInventory and model.MyInventory.Data and model.MyInventory.Data.Weapons
        local seen={}
        local function walk(value,depth)
            if found or type(value)~="table" or seen[value] or depth>10 then return end
            seen[value]=true
            if tostring(rawget(value,"DataID") or "")==tostring(id) then found=value return end
            for _,tItem in pairs(value) do if type(tItem)=="table" then walk(tItem,depth+1) end end
        end
        walk(root,0)
    end)
    return found
end

function pvNormalInventoryHasLiveTile(id, rowIndex)
    local leaf=pvNormalInventoryLeaf(id)
    local row=rowIndex and rowIndex[tostring(id)] or (not rowIndex and pvNormalInventoryRow(id))
    local func=row and row.Frame
    if func and func.Parent then
        if not leaf then return true end
        local success,result=pcall(function() return func==leaf or func:IsDescendantOf(leaf) end)
        if success and result then return true end
    end
    if leaf then
        for _,data in ipairs(leaf:GetChildren()) do
            if data:GetAttribute("pvNormalId")==tostring(id) and data.Parent then return true end
        end
    end
    return false
end

function pvInjectNormalInventoryTile(id,amount,rowIndex)
    local entry=Sync and Sync.Weapons and Sync.Weapons[id]
    if not entry then return false end
    local leaf=pvNormalInventoryLeaf(id)
    if not leaf then return false end


    local row=rowIndex and rowIndex[tostring(id)] or (not rowIndex and pvNormalInventoryRow(id))
    local rfValue=row and row.Frame
    if rfValue and rfValue.Parent then
        local success,result=pcall(function() return rfValue==leaf or rfValue:IsDescendantOf(leaf) end)
        if success and result then return true end
    end

    for _,data2 in ipairs(leaf:GetChildren()) do
        if data2:GetAttribute("pvNormalId")==tostring(id) then
            local data={}; for index,eItem in pairs(entry) do data[index]=eItem end
            data.Amount=amount or (ProfileData.Weapons.Owned[id] or 1); data.DataID=id
            pcall(function() _IMod().DisplayItem(data2,data,nil,true) end)
            pcall(pvEnforceTags,data2,entry)
            data2.Visible=true
            return true
        end
    end

    local tmpl=replicatedStorageService.Modules.InventoryModule:FindFirstChild("NewItem")
    if not tmpl then return false end
    local value=tmpl:Clone()
    value.Name="NewItem"
    value:SetAttribute("pvNormalInjected",true)
    value:SetAttribute("pvNormalId",tostring(id))
    local data={}; for index,eItem in pairs(entry) do data[index]=eItem end
    data.Amount=amount or (ProfileData.Weapons.Owned[id] or 1); data.DataID=id
    value.Parent=leaf
    pcall(function() _IMod().DisplayItem(value,data,nil,true) end)
    pcall(pvEnforceTags,value,entry)
    local actionButton=value:FindFirstChild("ActionButton",true) or value:FindFirstChild("Button",true)
    if actionButton and actionButton:IsA("GuiButton") then
        pvSession.connect(actionButton.Activated,function()
            pcall(function() EquipService:EquipItem("Weapons",id) end)
        end)
    end
    value.Visible=true
    return true
end


function pvSyncNormalInventoryItems(records,onDone)
    records=records or {}
    task.spawn(function()
        local total=#records
        local fired=0
        if total==1 then
            local result=records[1]
            local success=pcall(function() InvChangedEvent:Fire(result.cat or "Weapons",result.id,result.n) end)
            if success then fired=1 end
        elseif total>1 then
            local success=pcall(function() InvChangedEvent:Fire() end)
            if success then fired=1 end
        end


        if total>0 then task.wait(total==1 and 0.12 or 0.18) end

        -- Index native rows once per refresh instead of walking the entire
        -- inventory again for every spawned item (and again for every repair).
        local rowIndex = {}
        local indexed = pcall(function()
            local model = require(replicatedStorageService.Modules.InventoryModule)
            local root = model and model.MyInventory and model.MyInventory.Data and model.MyInventory.Data.Weapons
            assert(type(root)=="table")
            local seen, visited = {}, 0
            local function walk(value,depth)
                if type(value)~="table" or seen[value] or depth>10 then return end
                seen[value]=true
                local id=rawget(value,"DataID")
                if id then rowIndex[tostring(id)]=value end
                visited=visited+1
                if visited%100==0 then task.wait() end
                for _,tItem in pairs(value) do
                    if type(tItem)=="table" then walk(tItem,depth+1) end
                end
            end
            walk(root,0)
        end)
        if not indexed then rowIndex=nil end
        local repaired=0
        local sliceStart=os.clock()
        for index,record in ipairs(records) do
            if record.id and not pvNormalInventoryHasLiveTile(record.id,rowIndex) then
                if pvInjectNormalInventoryTile(record.id,record.n,rowIndex) then repaired=repaired+1 end
            end
            if os.clock()-sliceStart>=0.003 or index%8==0 then
                task.wait()
                sliceStart=os.clock()
            end
        end
        if onDone then pcall(onDone,total,fired,repaired) end
    end)
end

function pvForceInventoryRefresh()
    pcall(function() InvChangedEvent:Fire() end)
end
function pvBulkInvChanged(cat,id,number)

    pvForceInventoryRefresh()
end


function pvWeaponTopTab(id)
    local entry=Sync and Sync.Weapons and Sync.Weapons[id]
    if not entry then return "Current", "Season 1" end
    if entry.Event=="Christmas" or entry.Event=="Halloween" then return "Holiday", "Holiday" end
    if entry.Season then return "Current", "Season 1" end
    return "Classic", "Classic"
end
function pvShowSpawnedWeapon(id, searchIt)
    local top,label=pvWeaponTopTab(id)
    pcall(function()
        local playerGui3=playerGui and playerGui:FindFirstChild("PlayerGui") and playerGui.PlayerGui:FindFirstChild("MainGUI")
        local game2=playerGui3 and playerGui3:FindFirstChild("Game")
        local inventory2=game2 and (game2:FindFirstChild("Inventory2") or game2:FindFirstChild("Inventory"))
        local main=inventory2 and inventory2:FindFirstChild("Main")
        local weap=main and main:FindFirstChild("Weapons")
        local its=weap and weap:FindFirstChild("Items")
        local cont=its and its:FindFirstChild("Container")
        local tabs=(its and its:FindFirstChild("Tabs")) or (weap and weap:FindFirstChild("Tabs"))
        if not (cont and tabs) then return end


        for _,child in ipairs(cont:GetChildren()) do
            if child:IsA("GuiObject") then child.Visible=(child.Name==top) end
        end
        for _,value in ipairs(tabs:GetChildren()) do
            local view=value:FindFirstChild("View")
            if view then
                local onValue=(value.Name==top)
                local border=value:FindFirstChild("ViewBorder")
                if border and border:IsA("GuiObject") then border.Visible=onValue end
                if value:IsA("GuiObject") then value.BackgroundTransparency=onValue and 0.8 or 0.9 end
            end
        end


        if searchIt then
            local entry=Sync and Sync.Weapons and Sync.Weapons[id]
            local search=tabs:FindFirstChild("Search")
            local box=search and search:FindFirstChild("Container") and search.Container:FindFirstChild("SearchText")
            if box and box:IsA("TextBox") then
                local desired=tostring((entry and entry.ItemName) or id)
                if box.Text~=desired then box.Text=desired end
            end
        end
    end)
    return label
end
