_G.pvCfgEpoch = _G.pvCfgEpoch or 0
local function saveCfg()
    if not hasFile or saveQueued then return end
    saveQueued = true
    local epoch = _G.pvCfgEpoch
    task.delay(0.6, function()
        saveQueued = false


        if epoch ~= _G.pvCfgEpoch then return end
        pcall(function()
            if type(isfolder)=="function" and not isfolder(CFG_DIR) then makefolder(CFG_DIR) end
            local first = HttpService:JSONEncode(settings)
            if first ~= _lastCfgBlob then writefile(CFG_PATH, first); _lastCfgBlob = first end
            local button = HttpService:JSONEncode(savedSpawns)
            if button ~= _lastSpawnBlob then writefile(SPAWN_PATH, button); _lastSpawnBlob = button end
        end)
    end)
end
pcall(function()
    if hasFile and isfileSafe(CFG_PATH) then
        local value = HttpService:JSONDecode(readfile(CFG_PATH))
        for index,tItem in pairs(value) do settings[index]=tItem end
    end
end)
