local SCValue = IS_TOUCH and 1.1 or 1.1
local function pxValue(number) return math.floor(number*SCValue+0.5) end

function corner(index,result)
    local uiCorner=index:FindFirstChildOfClass("UICorner") or Instance.new("UICorner")
    uiCorner.CornerRadius=UDim.new(0,result or pxValue(7));uiCorner.Parent=index;return uiCorner
end


function bevel(inst, inset, hiCol, loCol, thick) do return inst end
    local value = thick or pxValue(2)
    local hiValue = hiCol or TValue.hi
    local loValue = loCol or TValue.lo
    local function edge(name,szValue,pos,col,z)
        local frame=Instance.new("Frame")
        frame.Name=name; frame.Size=szValue; frame.Position=pos
        frame.BackgroundColor3=col; frame.BorderSizePixel=0
        frame.ZIndex=(inst.ZIndex or 1)+(z or 1)
        frame.Parent=inst
        return frame
    end

    local topCol = inset and loValue or hiValue
    local botCol = inset and hiValue or loValue
    edge("mcTop",   UDim2.new(1,0,0,value),  UDim2.new(0,0,0,0),  topCol)
    edge("mcLeft",  UDim2.new(0,value,1,0),  UDim2.new(0,0,0,0),  topCol)
    edge("mcBottom",UDim2.new(1,0,0,value),  UDim2.new(0,0,1,-value), botCol)
    edge("mcRight", UDim2.new(0,value,1,0),  UDim2.new(1,-value,0,0), botCol)
    return inst
end
local function pad(index,layout,value,result,button) local uiPadding=Instance.new("UIPadding");uiPadding.PaddingLeft=UDim.new(0,layout);uiPadding.PaddingRight=UDim.new(0,result or layout);uiPadding.PaddingTop=UDim.new(0,value or layout);uiPadding.PaddingBottom=UDim.new(0,button or value or layout);uiPadding.Parent=index;return uiPadding end


local function stroke(index,trValue,thValue,col)
    local uiStroke=Instance.new("UIStroke");uiStroke.Color=col or TValue.line;uiStroke.Thickness=thValue or pxValue(2)
    uiStroke.Transparency=trValue or 0.5;uiStroke.ApplyStrokeMode=Enum.ApplyStrokeMode.Border;uiStroke.Parent=index;return uiStroke
end

