local function shadow(parent,spread,trValue)
    local imageLabel=Instance.new("ImageLabel")
    imageLabel.Name="Shadow";imageLabel.BackgroundTransparency=1
    imageLabel.Image="rbxassetid://6014261993";imageLabel.ImageColor3=Color3.new(0,0,0)
    imageLabel.ImageTransparency=trValue or 0.28
    imageLabel.ScaleType=Enum.ScaleType.Slice;imageLabel.SliceCenter=Rect.new(49,49,450,450)
    imageLabel.Size=UDim2.new(1,spread or 40,1,spread or 40)
    imageLabel.Position=UDim2.new(0,-(spread or 40)/2,0,-(spread or 40)/2+4)
    imageLabel.ZIndex=0;imageLabel.Parent=parent;return imageLabel
end
-- Clean up the previous PorkVisuals UI without letting its old
-- AncestryChanged remount callback fire after Destroy() locks Parent.
pcall(function()
    if _G.pvGuiAncestryConn then
        _G.pvGuiAncestryConn:Disconnect()
        _G.pvGuiAncestryConn=nil
    end
end)
for _,root in ipairs({HOST,playerGui2}) do
    local readable,children=pcall(function() return root:GetChildren() end)
    for _,child in ipairs(readable and children or {}) do
        if child.Name=="porkVisuals" or child.Name=="porkToggle" then
            -- Older builds did not store their connection globally, so disable
            -- AncestryChanged connections when the executor exposes getconnections.
            pcall(function()
                local gcValue=(pvAPI and pvAPI.getconnections) or getconnections
                if type(gcValue)=="function" then
                    for _,con in ipairs(gcValue(child.AncestryChanged)) do
                        pcall(function()
                            if type(con.Disable)=="function" then con:Disable()
                            elseif type(con.Disconnect)=="function" then con:Disconnect() end
                        end)
                    end
                end
            end)
            pcall(function() child:Destroy() end)
        end
    end
end

