-- Convert small animated GIFs into Roblox-playable PNG frame assets entirely
-- locally. GIF binaries cannot be played by ImageLabel; this decoder supports
-- GIF87a/89a palettes, LZW, transparency, disposal and interlacing.
local function pvDecodeGIF(bytes,shouldStop)
    if bytes:sub(1,6)~="GIF87a" and bytes:sub(1,6)~="GIF89a" then
        return nil,"Not a valid GIF image"
    end
    -- Time-sliced decoding: yield only when a short work budget has elapsed.
    -- This makes the import take longer but prevents multi-second UI stalls.
    local lastYield=os.clock()
    local function breathe(force)
        if shouldStop and shouldStop() then error("GIF load cancelled") end
        if force or os.clock()-lastYield>=0.003 then
            task.wait()
            lastYield=os.clock()
        end
    end
    local pos=7
    local function button()
        local number=bytes:byte(pos)
        if not number then error("Truncated GIF") end
        pos=pos+1
        return number
    end
    local function u16() local layout=button();return layout+button()*256 end
    local function palette(number)
        local entries={}
        for index=1,number do entries[index]=string.char(button(),button(),button(),255) end
        return entries
    end
    local function blocks()
        local chunks={}
        while true do
            local number=button()
            if number==0 then break end
            if pos+number-1>#bytes then error("Truncated GIF data block") end
            chunks[#chunks+1]=bytes:sub(pos,pos+number-1)
            pos=pos+number
        end
        return table.concat(chunks)
    end
    local function lzw(data,minSize,expected)
        if minSize<2 or minSize>8 then error("Unsupported GIF compression") end
        local clear=2^minSize
        local finish=clear+1
        local dict,nextCode,codeSize
        local function reset()
            dict={}
            for index=0,clear-1 do dict[index]=string.char(index) end
            nextCode=finish+1
            codeSize=minSize+1
        end
        reset()
        local index,accept,bits=1,0,0
        local function readCode()
            while bits<codeSize do
                local number=data:byte(index)
                if not number then return nil end
                accept=accept+number*2^bits
                bits=bits+8
                index=index+1
            end
            local code=bit32.band(accept,2^codeSize-1)
            accept=bit32.rshift(accept,codeSize)
            bits=bits-codeSize
            return code
        end
        local out,previous,total={},nil,0
        local step=0
        while total<expected do
            step=step+1
            if step%1024==0 then breathe() end
            local code=readCode()
            if code==nil or code==finish then break end
            if code==clear then
                reset()
                previous=nil
            else
                local entry=dict[code]
                if not entry and previous and code==nextCode then
                    entry=previous..previous:sub(1,1)
                end
                if not entry then error("Corrupt GIF LZW stream") end
                out[#out+1]=entry
                total=total+#entry
                if previous and nextCode<4096 then
                    dict[nextCode]=previous..entry:sub(1,1)
                    nextCode=nextCode+1
                    if nextCode==2^codeSize and codeSize<12 then
                        codeSize=codeSize+1
                    end
                end
                previous=entry
            end
        end
        if total<expected then error("Incomplete GIF frame") end
        return table.concat(out):sub(1,expected)
    end
    -- PNG format: 8-bit RGBA, filter 0, RFC1950 zlib + stored deflate blocks.
    -- Build the CRC lookup table once, shared by every generated GIF frame.
    local crcTable={}
    for index=0,255 do
        local child=index
        for _=1,8 do
            child=bit32.band(child,1)==1 and bit32.bxor(bit32.rshift(child,1),0xEDB88320) or bit32.rshift(child,1)
        end
        crcTable[index]=child
    end
    local function pngRGBA(item,handle,rgba)
        local function be32(number)
            return string.char(math.floor(number/16777216)%256,math.floor(number/65536)%256,math.floor(number/256)%256,number%256)
        end
        local function chunk(tag,payload)
            local crc=0xFFFFFFFF
            local body=tag..payload
            for index=1,#body do
                if index%4096==0 then breathe() end
                local idx=bit32.band(bit32.bxor(crc,body:byte(index)),255)
                crc=bit32.bxor(bit32.rshift(crc,8),crcTable[idx])
            end
            return be32(#payload)..body..be32(bit32.bxor(crc,0xFFFFFFFF))
        end
        local rows={}
        for y=0,handle-1 do
            if y%8==0 then breathe() end
            rows[#rows+1]="\0"..table.concat(rgba,"",y*item+1,(y+1)*item)
        end
        local raw=table.concat(rows)
        local first,bbValue=1,0
        for index=1,#raw do
            if index%8192==0 then breathe() end
            first=(first+raw:byte(index))%65521
            bbValue=(bbValue+first)%65521
        end
        local z={"\120\001"}
        local offset=1
        while offset<=#raw do
            local number=math.min(65535,#raw-offset+1)
            local inventory=65535-number
            z[#z+1]=string.char(offset+number>#raw and 1 or 0,number%256,math.floor(number/256),inventory%256,math.floor(inventory/256))
            z[#z+1]=raw:sub(offset,offset+number-1)
            offset=offset+number
            breathe()
        end
        z[#z+1]=be32(bbValue*65536+first)
        return "\137PNG\r\n\26\n"..chunk("IHDR",be32(item)..be32(handle)..string.char(8,6,0,0,0))
            ..chunk("IDAT",table.concat(z))..chunk("IEND","")
    end
    local function scaleCanvas(srcW,srcH,src,dstW,dstH)
        if srcW==dstW and srcH==dstH then return src end
        local out=table.create and table.create(dstW*dstH) or {}
        for y=0,dstH-1 do
            if y%8==0 then breathe() end
            local number=math.min(srcH-1,math.floor((y+0.5)*srcH/dstH))
            local srcRow=number*srcW
            local dstRow=y*dstW
            for x=0,dstW-1 do
                local number2=math.min(srcW-1,math.floor((x+0.5)*srcW/dstW))
                out[dstRow+x+1]=src[srcRow+number2+1]
            end
        end
        return out
    end
    local function decode()
        local width,height=u16(),u16()
        if width<1 or height<1 then
            error("GIF has invalid dimensions")
        end
        -- Huge source GIFs can consume hundreds of MB before resizing.
        if width*height>6000000 then
            error("GIF is too large to decode safely (maximum 6M source pixels)")
        end
        -- Animated wallpaper is viewed in a ~270px-wide panel, so decoding
        -- full 480px frames wastes CPU, file I/O and memory without adding
        -- visible detail at normal UI sizes. Static pictures are unaffected.
        local maxSide=320
        local scale=math.min(1,maxSide/math.max(width,height))
        local outWidth=math.max(1,math.floor(width*scale+0.5))
        local outHeight=math.max(1,math.floor(height*scale+0.5))
        local flags=button()
        button() -- background palette index
        button() -- pixel aspect ratio
        local globalPalette
        if bit32.band(flags,128)~=0 then globalPalette=palette(2^(bit32.band(flags,7)+1)) end
        local transparent=string.char(0,0,0,0)
        local canvas={}
        for index=1,width*height do
            if index%8192==0 then breathe() end
            canvas[index]=transparent
        end
        local frames={}
        local disposal=0
        local prevRect=nil
        local prevCanvas=nil
        local gce={delay=10,dispose=0,transparent=nil}
        local totalPixels=0
        while pos<=#bytes do
            breathe()
            local marker=button()
            if marker==0x3B then break end
            if marker==0x21 then
                local extension=button()
                if extension==0xF9 then
                    local number=button()
                    if number~=4 then error("Invalid GIF animation extension") end
                    local bits=button()
                    local delay=u16()
                    local trans=button()
                    button()
                    gce={delay=delay,dispose=bit32.band(bit32.rshift(bits,2),7),transparent=bit32.band(bits,1)==1 and trans or nil}
                else
                    blocks()
                end
            elseif marker==0x2C then
                local left,top,fwValue,fhValue=u16(),u16(),u16(),u16()
                local localFlags=button()
                if fwValue<1 or fhValue<1 or left+fwValue>width or top+fhValue>height then
                    error("GIF contains an invalid frame rectangle")
                end
                local colors=bit32.band(localFlags,128)~=0 and palette(2^(bit32.band(localFlags,7)+1)) or globalPalette
                if not colors then error("GIF has no palette") end
                local minSize=button()
                local compressed=blocks()
                if #frames>=48 or totalPixels+outWidth*outHeight>4000000 then
                    error("GIF too long for UI (max 48 frames / 4M frame pixels)")
                end
                if prevRect then
                    if disposal==2 then
                        for y=prevRect.top,prevRect.top+prevRect.height-1 do
                            if y%8==0 then breathe() end
                            for x=prevRect.left,prevRect.left+prevRect.width-1 do
                                canvas[y*width+x+1]=transparent
                            end
                        end
                    elseif disposal==3 and prevCanvas then
                        canvas=prevCanvas
                    end
                end
                local before=(gce.dispose==3) and table.clone(canvas) or nil
                local decoded=lzw(compressed,minSize,fwValue*fhValue)
                local yOrder={}
                if bit32.band(localFlags,64)~=0 then
                    for _,pass in ipairs({{0,8},{4,8},{2,4},{1,2}}) do
                        for y=pass[1],fhValue-1,pass[2] do yOrder[#yOrder+1]=y end
                    end
                else
                    for y=0,fhValue-1 do yOrder[#yOrder+1]=y end
                end
                local part=1
                for _,dy in ipairs(yOrder) do
                    if dy%8==0 then breathe() end
                    local row=(top+dy)*width+left+1
                    for x=0,fwValue-1 do
                        local ciValue=decoded:byte(part);part=part+1
                        if ciValue~=gce.transparent then canvas[row+x]=colors[ciValue+1] or transparent end
                    end
                end
                local renderCanvas=scale<1 and scaleCanvas(width,height,canvas,outWidth,outHeight) or canvas
                totalPixels=totalPixels+outWidth*outHeight
                frames[#frames+1]={png=pngRGBA(outWidth,outHeight,renderCanvas),delay=math.max(0.07,(gce.delay==0 and 10 or gce.delay)/100)}
                breathe(true) -- leave rendering time between decoded frames
                prevRect={left=left,top=top,width=fwValue,height=fhValue}
                prevCanvas=before
                disposal=gce.dispose
                gce={delay=10,dispose=0,transparent=nil}
                if #frames%4==0 then task.wait() end
            else
                error("Invalid GIF data")
            end
        end
        if #frames==0 then error("GIF contains no frames") end
        return frames
    end
    local success,result=pcall(decode)
    if success then return result end
    return nil,tostring(result)
end

-- One Custom theme input supports still images, small animated GIFs and
-- approved Roblox videos. Arbitrary MP4/WebM URLs are not directly playable
-- in Roblox; a playable Roblox video asset (video:12345) is recommended.
do
    -- Keep custom wallpapers almost flush with the rounded outer window.
    -- A fractional-pixel inset avoids the visible dark stripe of the old
    -- 2px inset. Do not use px(0.1), which rounds to 0.
    -- The image, video and dim layer share this corner geometry.
    local wallpaperInset=0.1
    local wallpaperCornerRadius=pxValue(14)-wallpaperInset
    local picture=Instance.new("ImageLabel")
    picture.Name="pvCustomBackgroundImage"
    picture.Size=UDim2.new(1,-wallpaperInset*2,1,-wallpaperInset*2)
    picture.Position=UDim2.fromOffset(wallpaperInset,wallpaperInset)
    picture.BackgroundTransparency=1
    picture.BorderSizePixel=0
    picture.ScaleType=Enum.ScaleType.Crop
    picture.ImageTransparency=0.10
    picture.ZIndex=0
    picture.Active=false
    picture.Visible=false
    picture.Parent=sky
    corner(picture,wallpaperCornerRadius)

    local video=Instance.new("VideoFrame")
    video.Name="pvCustomBackgroundVideo"
    video.Size=picture.Size
    video.Position=picture.Position
    video.BackgroundTransparency=1
    video.BorderSizePixel=0
    -- VideoFrame fills the panel; Roblox VideoFrame has no ScaleType property.
    video.Looped=true
    video.Volume=0
    video.Playing=false
    video.ZIndex=0
    video.Active=false
    video.Visible=false
    video.Parent=sky
    corner(video,wallpaperCornerRadius)

    local darken=Instance.new("Frame")
    darken.Name="pvCustomBackgroundDim"
    darken.Size=picture.Size
    darken.Position=picture.Position
    darken.BackgroundColor3=Color3.fromRGB(13,9,20)
    darken.BackgroundTransparency=0.48
    darken.BorderSizePixel=0
    darken.ZIndex=0
    darken.Active=false
    darken.Visible=false
    darken.Parent=sky
    corner(darken,wallpaperCornerRadius)

    local requestToken=0
    local activeKind="none"
    local temporaryFiles={}
    local animatedFrames=nil

    local function trim(value)
        return tostring(value or ""):match("^%s*(.-)%s*$") or ""
    end
    local function cleanupFiles(files)
        if pvAPI.delfile then
            for _,path in ipairs(files or {}) do pcall(pvAPI.delfile,path) end
        end
    end
    pvSession.addCleanup(function() cleanupFiles(temporaryFiles) end)

    function pvRefreshCustomBackgroundVisibility()
        local show=settings.uiTheme=="Custom"
        picture.Visible=show and (activeKind=="image" or activeKind=="gif")
        video.Visible=show and activeKind=="video"
        darken.Visible=show and activeKind~="none"
        if activeKind=="video" then
            pcall(function() video.Playing=show end)
        end
    end

    local function imageKind(bytes)
        if bytes:sub(1,8)=="\137PNG\r\n\26\n" then return "png" end
        if bytes:sub(1,3)=="\255\216\255" then return "jpg" end
        if bytes:sub(1,6)=="GIF89a" or bytes:sub(1,6)=="GIF87a" then return "gif" end
        if bytes:sub(1,4)=="RIFF" and bytes:sub(9,12)=="WEBP" then
            if bytes:sub(13,100):find("ANIM",1,true) then return "animated_webp" end
            return "webp"
        end
        if bytes:sub(5,8)=="ftyp" then return "mp4" end
        if bytes:sub(1,4)=="\026\069\223\163" then return "webm" end
        return nil
    end

    local function makeFolder()
        local success=pcall(function()
            if type(isfolder)=="function" and type(makefolder)=="function" and not isfolder(CFG_DIR) then
                makefolder(CFG_DIR)
            end
        end)
        return success
    end
    local function writeAsset(bytes,extension,files)
        if not (pvAPI.writefile and pvAPI.getcustomasset) then
            return nil,"This executor needs writefile and getcustomasset"
        end
        if not makeFolder() then return nil,"Could not create PorkHub folder" end
        local path=CFG_DIR.."/pv_wallpaper_"..HttpService:GenerateGUID(false).."."..extension
        local success2=pcall(pvAPI.writefile,path,bytes)
        if not success2 then return nil,"Could not write background file" end
        files[#files+1]=path
        local success,asset=pcall(pvAPI.getcustomasset,path)
        if not success or type(asset)~="string" or asset=="" then
            return nil,"Executor couldn't load the "..extension.." file"
        end
        return asset
    end
    local function getBytes(url)
        local body=nil
        if pvAPI.request then
            local success,response=pcall(pvAPI.request,{Url=url,Method="GET"})
            if success and type(response)=="table" then
                local status=tonumber(response.StatusCode or response.Status)
                if (status==200 or (not status and response.Success==true)) and type(response.Body)=="string" then
                    body=response.Body
                end
            end
        end
        if not body then body=httpGet(url) end
        if type(body)~="string" then return nil,"Couldn't download URL" end
        if #body<12 then return nil,"Image/video download is empty" end
        if #body>15*1024*1024 then return nil,"File must be under 15 MB" end
        return body
    end
    local function commit(kind,source,saveIt,files,asset,frames)
        if not isCurrent() then cleanupFiles(files);return end
        local previous=temporaryFiles
        temporaryFiles=files or {}
        activeKind=kind
        animatedFrames=frames
        picture.Image=kind=="video" and "" or (asset or (frames and frames[1].asset) or "")
        if kind~="video" then pcall(function() video.Playing=false;video.Video="" end) end
        if saveIt then settings.customBackground=source;saveCfg() end
        pvRefreshCustomBackgroundVisibility()
        cleanupFiles(previous)
    end

    -- Incremented for every new Apply/Reset; old GIF animations exit on change.
    local function startGifPlayback(frames,token)
        if #frames<=1 then return end
        task.spawn(function()
            local index=1
            while isCurrent() and requestToken==token and activeKind=="gif" and animatedFrames==frames do
                if settings.uiTheme=="Custom" then
                    local frame=frames[index]
                    picture.Image=frame.asset
                    task.wait(frame.delay)
                    index=(index%#frames)+1
                else
                    task.wait(0.20)
                end
            end
        end)
    end

    -- Try VideoFrame only for content Roblox can play. Verify that it loaded
    -- before overwriting the user's previous, working background.
    local function tryVideo(asset,source,saveIt,files,token,done)
        if not asset or asset=="" then cleanupFiles(files);done(false,"No video asset available");return end
        local oldVideo=video.Video
        local oldPlaying=video.Playing
        local success=pcall(function()
            video.Video=asset
            video.Looped=true
            video.Volume=0
            video.Playing=true
        end)
        if not success then
            pcall(function() video.Video=oldVideo;video.Playing=oldPlaying end)
            cleanupFiles(files)
            done(false,"This Roblox client can't play the video")
            return
        end
        task.spawn(function()
            local started=os.clock()
            local loaded=false
            while isCurrent() and requestToken==token and os.clock()-started<8 do
                local fine,result=pcall(function() return video.IsLoaded end)
                if fine and result then loaded=true;break end
                task.wait(0.2)
            end
            if requestToken~=token or not isCurrent() then cleanupFiles(files);return end
            if not loaded then
                pcall(function() video.Video=oldVideo;video.Playing=oldPlaying end)
                cleanupFiles(files)
                pvRefreshCustomBackgroundVisibility()
                done(false,"Video not playable here. Use an approved Roblox video ID (video:123)")
                return
            end
            commit("video",source,saveIt,files)
            done(true,"Looping video background applied")
        end)
    end

    local function processBytes(bytes,source,saveIt,token,done)
        local kind=imageKind(bytes)
        if not kind then done(false,"Unsupported file: use PNG/JPG/WebP/GIF or a Roblox video asset");return end
        if kind=="animated_webp" then
            done(false,"Animated WebP isn't playable here. Convert to GIF or Roblox video")
            return
        end
        local files={}
        if kind=="gif" then
            if not (pvAPI.writefile and pvAPI.getcustomasset) then
                done(false,"GIF playback needs writefile + getcustomasset")
                return
            end
            local frames,errorMessage=pvDecodeGIF(bytes,function() return requestToken~=token or not isCurrent() end)
            if not frames then done(false,"GIF couldn't load: "..tostring(errorMessage));return end
            for index,frame in ipairs(frames) do
                if token~=requestToken or not isCurrent() then cleanupFiles(files);return end
                local asset,why=writeAsset(frame.png,"png",files)
                frame.png=nil -- Don't keep raw PNG buffers after loading each frame.
                if not asset then cleanupFiles(files);done(false,why);return end
                frame.asset=asset
                task.wait() -- asset registration is costly; keep UI responsive between frames
            end
            if token~=requestToken or not isCurrent() then cleanupFiles(files);return end
            commit("gif",source,saveIt,files,nil,frames)
            startGifPlayback(frames,token)
            done(true,"Animated GIF background applied ("..#frames.." frames)")
        elseif kind=="mp4" or kind=="webm" then
            if not (pvAPI.getcustomasset and pvAPI.writefile) then
                done(false,"MP4/WebM need an approved Roblox video ID (video:123)")
                return
            end
            local asset,why=writeAsset(bytes,kind,files)
            if not asset then cleanupFiles(files);done(false,why.."; try a Roblox video ID");return end
            tryVideo(asset,source,saveIt,files,token,done)
        else
            local asset,why=writeAsset(bytes,kind,files)
            if not asset then cleanupFiles(files);done(false,why);return end
            if token~=requestToken or not isCurrent() then cleanupFiles(files);return end
            commit("image",source,saveIt,files,asset)
            done(true,"Custom image background applied")
        end
    end

    -- Automatic format detection from file signatures when available, and
    -- explicit `video:ID` for Roblox video assets (plain IDs remain images).
    function pvSetCustomBackground(source,persist,callback)
        source=trim(source)
        requestToken=requestToken+1
        local token=requestToken
        local function done(success,message)
            if callback and requestToken==token and isCurrent() then pcall(callback,success,message) end
        end
        if source=="" then
            commit("none","",persist,{})
            done(true,"Custom background reset")
            return true
        end
        if #source>2048 then done(false,"Background input is too long");return false end
        local videoId=source:match("^[Vv][Ii][Dd][Ee][Oo]:%s*(%d+)$")
            or source:match("^rbxvideo://(%d+)$")
            or source:match("roblox%.com/videos/(%d+)")
        if videoId then
            tryVideo("rbxassetid://"..videoId,source,persist,{},token,done)
            return true
        end
        local id=source:match("^(%d+)$") or source:match("^rbxassetid://(%d+)$")
        if not id and (source:find("roblox.com",1,true) or source:find("robloxusercontent.com",1,true)) then
            id=source:match("[?&]id=(%d+)") or source:match("/store/asset/(%d+)")
                or source:match("/library/(%d+)") or source:match("/catalog/(%d+)")
        end
        if id then
            commit("image",source,persist,{},"rbxassetid://"..id)
            done(true,"Roblox image background applied")
            return true
        end
        if source:match("^https://") then
            task.spawn(function()
                local bytes,errorMessage=getBytes(source)
                if token~=requestToken or not isCurrent() then return end
                if not bytes then done(false,errorMessage);return end
                processBytes(bytes,source,persist,token,done)
            end)
            return true
        end
        if source:match("^https?://") then
            done(false,"Please use HTTPS links")
            return false
        end
        if not pvAPI.readfile then
            done(false,"Local files need executor readfile")
            return false
        end
        task.spawn(function()
            local success,bytes=pcall(pvAPI.readfile,source)
            if requestToken~=token or not isCurrent() then return end
            if not success or type(bytes)~="string" then
                done(false,"Can't find/read that local file")
                return
            end
            if #bytes>15*1024*1024 then done(false,"File must be under 15 MB");return end
            processBytes(bytes,source,persist,token,done)
        end)
        return true
    end
end


-- CHRISTMAS BACKDROP: bundled image asset, preloaded locally for instant theme toggles.
do
    local wallpaperInset=0.1
    local wallpaperCornerRadius=pxValue(14)-wallpaperInset
    local picture=Instance.new("ImageLabel")
    picture.Name="pvChristmasBackgroundImage"
    picture.Size=UDim2.new(1,-wallpaperInset*2,1,-wallpaperInset*2)
    picture.Position=UDim2.fromOffset(wallpaperInset,wallpaperInset)
    picture.BackgroundTransparency=1
    picture.BorderSizePixel=0
    picture.ScaleType=Enum.ScaleType.Crop
    picture.ImageTransparency=0.07
    picture.ZIndex=0
    picture.Active=false
    picture.Visible=false
    picture.Parent=sky
    corner(picture,wallpaperCornerRadius)

    local darken=Instance.new("Frame")
    darken.Name="pvChristmasBackgroundDim"
    darken.Size=picture.Size
    darken.Position=picture.Position
    darken.BackgroundColor3=Color3.fromRGB(5,14,19)
    darken.BackgroundTransparency=0.58
    darken.BorderSizePixel=0
    darken.ZIndex=0
    darken.Active=false
    darken.Visible=false
    darken.Parent=sky
    corner(darken,wallpaperCornerRadius)

    local christmasAsset=""
    local christmasReady=false
    local christmasAttempted=false

    local function ensureBundledChristmasAsset()
        if christmasReady and christmasAsset~="" then return true end
        if christmasAttempted then return christmasAsset~="" end
        christmasAttempted=true
        if not (pvAPI and pvAPI.writefile and pvAPI.getcustomasset) then return false end
        local okFolder=pcall(function()
            if type(isfolder)=="function" and type(makefolder)=="function" and not isfolder(CFG_DIR) then
                makefolder(CFG_DIR)
            end
        end)
        if not okFolder then return false end
        local path=CFG_DIR.."/pv_builtin_christmas_bg_clean_68bbaaf6f5.png"
        -- Image is no longer embedded: place pv_builtin_christmas_bg_clean_68bbaaf6f5.png in CFG_DIR.
        if not isfileSafe(path) then return false end
        local okAsset,asset=pcall(function() return pvAPI.getcustomasset(path) end)
        if not okAsset or type(asset)~="string" or asset=="" then return false end
        christmasAsset=asset
        christmasReady=true
        picture.Image=asset
        return true
    end
    function pvHasBundledChristmasBackground()
        return ensureBundledChristmasAsset()
    end
    function pvRefreshChristmasBackgroundVisibility()
        local show=settings.uiTheme=="Christmas"
        if show then ensureBundledChristmasAsset() end
        picture.Visible=show and christmasAsset~=""
        darken.Visible=show and christmasAsset~=""
    end
    -- One small embedded atlas, reused by every snowflake across theme switches.
    -- The long literal avoids Luau's concatenation register limit.
    local snowAtlasAsset
    function pvSession.getChristmasSnowAtlas()
        if snowAtlasAsset then return snowAtlasAsset end
        if not (pvAPI.writefile and pvAPI.getcustomasset) then return nil end
        local path=CFG_DIR.."/pv_christmas_snowflakes_bf223464d0.png"
        local success,asset=pcall(function()
            if type(isfolder)=="function" and type(makefolder)=="function" and not isfolder(CFG_DIR) then makefolder(CFG_DIR) end
            -- Image is no longer embedded: place pv_christmas_snowflakes_bf223464d0.png in CFG_DIR.
            if not isfileSafe(path) then error("missing snowflake atlas png") end
            return pvAPI.getcustomasset(path)
        end)
        if success and type(asset)=="string" and asset~="" then snowAtlasAsset=asset end
        return snowAtlasAsset
    end
    task.defer(function()
        pcall(ensureBundledChristmasAsset)
        local asset=pvSession.getChristmasSnowAtlas()
        if asset and isCurrent() then
            pcall(function() game:GetService("ContentProvider"):PreloadAsync({asset}) end)
        end
    end)
end

-- HALLOWEEN UI: native, non-interactive ornaments, scoped to this window.
do
    local function piece(parent, name, x, y, item, handle, color, radius)
        local frame=Instance.new("Frame")
        frame.Name=name; frame.BorderSizePixel=0; frame.Active=false; frame.Selectable=false
        frame.Position=UDim2.fromOffset(pxValue(x),pxValue(y)); frame.Size=UDim2.fromOffset(pxValue(item),pxValue(handle))
        frame.BackgroundColor3=color; frame.ZIndex=1; frame.Parent=parent
        if radius then corner(frame,pxValue(radius)) end
        return frame
    end
    -- Draw unrotated scanline runs clipped against the actual rounded corner.
    -- Rotated Roblox Frames can escape ancestor clipping, so trim the geometry.
    for _,right in ipairs({false,true}) do
        local extent,radius=pxValue(60),pxValue(14)
        local web=Instance.new("Frame")
        web.Name="HalloweenWeb";web.BackgroundTransparency=1;web.Active=false
        web.Size=UDim2.fromOffset(extent,extent);web.ZIndex=0;web.ClipsDescendants=true;web.Parent=sky
        web.AnchorPoint=Vector2.new(right and 1 or 0,0)
        web.Position=UDim2.fromScale(right and 1 or 0,0)
        local pixels={}
        local function line(x1Value,y1Value,x2Value,y2Value)
            x1Value,y1Value,x2Value,y2Value=x1Value*SCValue,y1Value*SCValue,x2Value*SCValue,y2Value*SCValue
            local dx,dy=x2Value-x1Value,y2Value-y1Value
            local steps=math.max(1,math.ceil(math.max(math.abs(dx),math.abs(dy))*2))
            for index=0,steps do
                local x=math.floor(x1Value+dx*index/steps+0.5)
                local y=math.floor(y1Value+dy*index/steps+0.5)
                -- Check the entire pixel square, not just its center.
                local inside=x>=1 and y>=1 and x<extent-1 and y<extent-1
                if inside and x<radius and y<radius then
                    inside=(x-radius)^2+(y-radius)^2<=(radius-1)^2
                end
                if inside then
                    local sxValue=right and extent-1-x or x
                    pixels[y]=pixels[y] or {};pixels[y][sxValue]=true
                end
            end
        end
        for index=0,4 do
            local first=index*math.pi/8
            line(0,0,math.cos(first)*59,math.sin(first)*59)
        end
        for _,result in ipairs({19,36,55}) do
            for index=0,3 do
                local first,button=index*math.pi/8,(index+1)*math.pi/8
                line(math.cos(first)*result,math.sin(first)*result,math.cos(button)*result,math.sin(button)*result)
            end
        end
        for y,row in pairs(pixels) do
            local x=0
            while x<extent do
                if row[x] then
                    local first=x
                    repeat x=x+1 until not row[x]
                    local frame=Instance.new("Frame")
                    frame.Name="WebSilk";frame.BorderSizePixel=0;frame.Active=false
                    frame.Position=UDim2.fromOffset(first,y);frame.Size=UDim2.fromOffset(x-first,1)
                    frame.BackgroundColor3=Color3.fromRGB(179,164,150);frame.BackgroundTransparency=0.88
                    frame.ZIndex=1;frame.Parent=web
                else x=x+1 end
            end
        end
    end
    -- Small head-down spider hanging from the top-left web; native UI artwork.
    local spider=Instance.new("Frame")
    spider.Name="HalloweenSpider";spider.BackgroundTransparency=1;spider.Active=false
    spider.Size=UDim2.fromOffset(pxValue(24),pxValue(54));spider.Position=UDim2.fromOffset(pxValue(13),pxValue(34))
    spider.ZIndex=1;spider.Parent=win
    -- Extend the hanging silk upward to meet the web's 45-degree strand.
    -- The spider/body and animation travel stay in their existing positions.
    -- Match the same copper-grey and opacity used by the top-corner WebSilk strands.
    local thread=piece(spider,"SilkThread",12,-9,1,33,Color3.fromRGB(179,164,150))
    thread.BackgroundTransparency=0.76
    local body=Instance.new("Frame")
    body.Name="SpiderBody";body.BackgroundTransparency=1;body.Active=false
    body.Size=UDim2.fromOffset(pxValue(24),pxValue(31));body.Position=UDim2.fromOffset(0,pxValue(18))
    body.ZIndex=2;body.Parent=spider
    local legs={}
    local function leg(x1Value,y1Value,x2Value,y2Value)
        local dx,dy=x2Value-x1Value,y2Value-y1Value
        local func=piece(body,"SpiderLeg",(x1Value+x2Value)/2,(y1Value+y2Value)/2,math.sqrt(dx*dx+dy*dy),1,Color3.fromRGB(146,112,97),1)
        func.AnchorPoint=Vector2.new(0.5,0.5)
        func.Rotation=math.deg(math.atan2(dy,dx))
        func.BackgroundTransparency=0.12
        legs[#legs+1]=func
        return func
    end
    local bridge=piece(body,"SpiderBridge",11,0,2,10,Color3.fromRGB(125,96,84),1)
    bridge.BackgroundTransparency=0.16
    for _,side in ipairs({-1,1}) do
        for _,value in ipairs({{17,5,12,8,8},{18,7,15,10,12},{19,7,21,10,24},{20,4,24,5,28}}) do
            leg(12+side*2,value[1],12+side*value[2],value[3])
            leg(12+side*value[2],value[3],12+side*value[4],value[5])
        end
    end
    local abdomen=piece(body,"Abdomen",8,10,9,11,Color3.new(1,1,1),6)
    local shading=Instance.new("UIGradient");shading.Rotation=45
    shading.Color=ColorSequence.new({ColorSequenceKeypoint.new(0,Color3.fromRGB(155,123,103)),ColorSequenceKeypoint.new(0.4,Color3.fromRGB(82,50,46)),ColorSequenceKeypoint.new(1,Color3.fromRGB(25,12,18))})
    shading.Parent=abdomen
    local thorax=piece(body,"Thorax",9,18,7,6,Color3.fromRGB(51,26,35),4)
    local edge=Instance.new("UIStroke");edge.Color=Color3.fromRGB(178,133,105)
    edge.Thickness=0.6;edge.Transparency=0.45;edge.Parent=thorax
    leg(11,23,10,25);leg(14,23,15,25)
    do
        local startY,endY=pxValue(20),pxValue(12)
        -- Nine extra pixels above the former silk start; lower endpoint unchanged.
        local startLen,endLen=pxValue(35),pxValue(27)
        body.Position=UDim2.fromOffset(0,startY)
        body.Rotation=-1
        thread.Size=UDim2.fromOffset(pxValue(1),startLen)
        local bodyTw=Tween:Create(body,TweenInfo.new(1.8,Enum.EasingStyle.Sine,Enum.EasingDirection.InOut,-1,true),{
            Position=UDim2.fromOffset(0,endY),
            Rotation=2
        })
        local silkTw=Tween:Create(thread,TweenInfo.new(1.8,Enum.EasingStyle.Sine,Enum.EasingDirection.InOut,-1,true),{
            Size=UDim2.fromOffset(pxValue(1),endLen)
        })
        bodyTw:Play();silkTw:Play()
        for index,leg2 in ipairs(legs) do
            local dir=((leg2.Position.X.Offset or 0) < pxValue(12)) and -1 or 1
            local amp=((index % 2)==0) and 6 or 4
            local twValue=Tween:Create(leg2,TweenInfo.new(0.8+(index%3)*0.12,Enum.EasingStyle.Sine,Enum.EasingDirection.InOut,-1,true),{
                Rotation=leg2.Rotation + dir*amp
            })
            twValue:Play()
        end
    end
    -- Softly textured ivory crescent. Keep details low contrast at icon size:
    -- no crater outlines, bright dots, or orange "cheese" coloring.
    do
        local moon=Instance.new("Frame")
        moon.Name="HalloweenMoon"
        moon.Active=false;moon.Selectable=false
        moon.BackgroundTransparency=1
        -- Slightly smaller than before (20px instead of 24px), same centre.
        moon.Size=UDim2.fromOffset(pxValue(20),pxValue(20))
        moon.Position=UDim2.new(1,-pxValue(31),0,pxValue(61))
        -- Scale texture and crescent mask together so the proportions stay intact.
        local function moonPx(number) return pxValue(number*20/24) end
        moon.ClipsDescendants=true
        moon.ZIndex=2
        moon.Parent=win

        local gold=Instance.new("Frame")
        gold.Name="MoonGold"
        gold.Size=UDim2.fromScale(1,1)
        gold.BackgroundColor3=Color3.fromRGB(255,228,173)
        gold.BorderSizePixel=0
        gold.ZIndex=2
        gold.Parent=moon
        Instance.new("UICorner",gold).CornerRadius=UDim.new(1,0)

        -- Creamy moonlight rather than saturated pumpkin orange.
        local surface=Instance.new("UIGradient")
        surface.Name="MoonSoftShading"
        surface.Rotation=105
        surface.Color=ColorSequence.new({
            ColorSequenceKeypoint.new(0,Color3.fromRGB(255,245,210)),
            ColorSequenceKeypoint.new(0.38,Color3.fromRGB(255,231,177)),
            ColorSequenceKeypoint.new(0.72,Color3.fromRGB(250,214,152)),
            ColorSequenceKeypoint.new(1,Color3.fromRGB(231,178,112)),
        })
        surface.Parent=gold

        local function spot(name,x,y,item,handle,color,opacity)
            local frame=Instance.new("Frame")
            frame.Name=name
            frame.Active=false;frame.Selectable=false
            frame.BorderSizePixel=0
            frame.Position=UDim2.fromOffset(moonPx(x),moonPx(y))
            frame.Size=UDim2.fromOffset(moonPx(item),moonPx(handle))
            frame.BackgroundColor3=color
            frame.BackgroundTransparency=opacity
            frame.ZIndex=3
            frame.Parent=gold
            Instance.new("UICorner",frame).CornerRadius=UDim.new(1,0)
            return frame
        end

        -- Diffuse lunar maria: very faint irregular-looking tonal areas.
        -- They sit beneath the mask, so nothing bleeds across the inner edge.
        local mareColor=Color3.fromRGB(148,115,93)
        spot("MoonMareUpper",2.0,7.0,5.5,7.5,mareColor,0.94)
        spot("MoonMareLower",6.5,16.6,7.0,4.0,mareColor,0.95)

        -- Dimples are tiny, soft shadows rather than outlined holes.
        -- Even a thin white rim reads as cartoon cheese at icon size.
        local craterColor=Color3.fromRGB(158,117,81)
        for index,part in ipairs({
            {4.1,5.7,2.8,0.84},
            {3.7,13.5,2.2,0.87},
            {10.5,19.8,2.5,0.87},
        }) do
            local crater=spot("MoonCrater"..index,part[1],part[2],part[3],part[3],craterColor,part[4])
            local diffuse=Instance.new("UIGradient")
            diffuse.Rotation=50
            diffuse.Transparency=NumberSequence.new({
                NumberSequenceKeypoint.new(0,0.65),
                NumberSequenceKeypoint.new(0.5,0),
                NumberSequenceKeypoint.new(1,0.7),
            })
            diffuse.Parent=crater
        end

        -- The inner circular cover follows the moving panel background.
        local cutout=Instance.new("Frame")
        cutout.Name="MoonCutout"
