        local function matchBackground()
            if not win.Parent or not moon.Parent then return end
            local points=galaxy.Color.Keypoints
            if #points<2 then return end
            local number=math.max(1,win.AbsoluteSize.Y)
            local centerY=moon.AbsolutePosition.Y+moon.AbsoluteSize.Y*0.5
            local relative=(centerY-win.AbsolutePosition.Y)/number
            local number2=math.clamp(relative-galaxy.Offset.Y,0,1)
            cutout.BackgroundColor3=points[1].Value:Lerp(points[#points].Value,number2)
        end
        pvSession.connect(galaxy:GetPropertyChangedSignal("Color"),matchBackground)
        pvSession.connect(galaxy:GetPropertyChangedSignal("Offset"),matchBackground)
        pvSession.connect(win:GetPropertyChangedSignal("AbsoluteSize"),matchBackground)
        task.defer(matchBackground)
    end
    local rim=Instance.new("UIGradient")
    rim.Rotation=25;rim.Color=ColorSequence.new(Color3.fromRGB(255,157,57),Color3.fromRGB(158,79,34))
