local function drag(handle)
    local data,spValue,siValue
    pvSession.connect(handle.InputBegan,function(index)
        if settings.uiLocked then return end
        if index.UserInputType==Enum.UserInputType.MouseButton1 or index.UserInputType==Enum.UserInputType.Touch then
            data=true;spValue=win.Position;siValue=index.Position
            pvSession.connect(index.Changed,function() if index.UserInputState==Enum.UserInputState.End then data=false end end)
        end
    end)
    pvSession.connect(UIS.InputChanged,function(index)
        if data and not settings.uiLocked and (index.UserInputType==Enum.UserInputType.MouseMovement or index.UserInputType==Enum.UserInputType.Touch) then
            local ddValue=index.Position-siValue
            win.Position=UDim2.new(spValue.X.Scale,spValue.X.Offset+ddValue.X,spValue.Y.Scale,spValue.Y.Offset+ddValue.Y)
        end
    end)
end


do
    local dragging, dStart, wStart = false, nil, nil
    local function inCaption(pos)
        local wpValue, wsValue = win.AbsolutePosition, win.AbsoluteSize
        return pos.X >= wpValue.X and pos.X <= wpValue.X + wsValue.X - pxValue(46)
           and pos.Y >= wpValue.Y and pos.Y <= wpValue.Y + pxValue(30)
    end
    pvSession.connect(UIS.InputBegan,function(index)
        if settings.uiLocked then return end
        if (index.UserInputType==Enum.UserInputType.MouseButton1 or index.UserInputType==Enum.UserInputType.Touch)
           and win.Visible and inCaption(index.Position) then
            dragging=true; dStart=index.Position; wStart=win.Position
        end
    end)
    pvSession.connect(UIS.InputEnded,function(index)
        if index.UserInputType==Enum.UserInputType.MouseButton1 or index.UserInputType==Enum.UserInputType.Touch then
            if dragging then dragging=false; if _G.pvSaveWinGeom then _G.pvSaveWinGeom() end end
        end
    end)
    pvSession.connect(UIS.InputChanged,function(index)
        if dragging and not settings.uiLocked
           and (index.UserInputType==Enum.UserInputType.MouseMovement or index.UserInputType==Enum.UserInputType.Touch) then
            local ddValue=index.Position-dStart
            win.Position=UDim2.new(wStart.X.Scale, wStart.X.Offset+ddValue.X, wStart.Y.Scale, wStart.Y.Offset+ddValue.Y)
        end
    end)
end
local hidden=false
function setHidden(text)


    _G.pvUiAnimToken = (_G.pvUiAnimToken or 0) + 1
    local token = _G.pvUiAnimToken
    hidden=text

    pcall(function() if _G.pvUiTweenWin then _G.pvUiTweenWin:Cancel() end end)
    pcall(function() if _G.pvUiTweenSettle then _G.pvUiTweenSettle:Cancel() end end)
    pcall(function() uiScale.Scale=1 end)

    if text then
        -- v66: close instantly. Open animation below is unchanged.
        pvSavedWinPos = pvSavedWinPos or win.Position
        if win.Visible then pvSavedWinPos=win.Position end

        pcall(function() if _G.pvUiTweenWin then _G.pvUiTweenWin:Cancel() end end)
        pcall(function() if _G.pvUiTweenSettle then _G.pvUiTweenSettle:Cancel() end end)

        win.Visible=false
        win.Position=pvSavedWinPos
        win.BackgroundTransparency=0
        uiScale.Scale=1

    else
        if pvSavedWinPos then win.Position=pvSavedWinPos end
        local base=win.Position

        local fromPos=UDim2.new(
            base.X.Scale,base.X.Offset,
            base.Y.Scale,base.Y.Offset+pxValue(10)
        )
        local settlePos=UDim2.new(
            base.X.Scale,base.X.Offset,
            base.Y.Scale,base.Y.Offset-pxValue(1)
        )

        uiScale.Scale=1
        win.Position=fromPos
        win.BackgroundTransparency=0.18
        win.Visible=true

        _G.pvUiTweenWin=Tween:Create(
            win,
            TweenInfo.new(0.23,Enum.EasingStyle.Quint,Enum.EasingDirection.Out),
            {Position=settlePos,BackgroundTransparency=0}
        )
        _G.pvUiTweenWin:Play()

        task.delay(0.23,function()
            if _G.pvUiAnimToken~=token or hidden then return end
            _G.pvUiTweenSettle=Tween:Create(
                win,
                TweenInfo.new(0.08,Enum.EasingStyle.Sine,Enum.EasingDirection.Out),
                {Position=base}
            )
            _G.pvUiTweenSettle:Play()
        end)

        task.delay(0.32,function()
            if _G.pvUiAnimToken~=token or hidden then return end
            win.Position=base
            win.BackgroundTransparency=0
            uiScale.Scale=1
        end)
    end
end
local keyActions={}
local keyCapture=nil

keyActions.toggleUI = function() setHidden(not hidden, false) end
keyActions.streamerMode = function()
    local enabled=not pvSession.streamerHidden
    pvSession.setStreamerHidden(enabled)
    if not enabled then notify("Streamer Mode OFF — PorkVisuals UI restored") end
end
keyActions.panic    = function() setHidden(true, false) end
pvSession.connect(UIS.InputBegan,function(index,gui2)
    if not isCurrent() then return end
    if index.UserInputType~=Enum.UserInputType.Keyboard then return end
    local knValue=index.KeyCode.Name
    if keyCapture then local callback=keyCapture;keyCapture=nil;callback(knValue);return end
    -- FPS toggle remains available when another game action consumes the key,
    -- but never while typing into chat or any other text box.
    if UIS:GetFocusedTextBox() then return end
    if settings.keys.restoreFPS==knValue and keyActions.restoreFPS then
        task.spawn(keyActions.restoreFPS)
        return
    end
    if gui2 then return end
    for act,key in pairs(settings.keys) do
        if key~="" and key==knValue then
            local fnValue=keyActions[act]
            if fnValue then task.spawn(fnValue) end
        end
    end
end)
