do


    local moved,lastTap=false,0
    local startX,startY=0,0
    local function tap()
        if moved then return end
        local now=os.clock()
        if now-lastTap < 0.30 then return end
        lastTap=now
        setHidden(not hidden,false)
    end
    pvSession.connect(tog.MouseButton1Click,tap)
    pvSession.connect(tog.Activated,tap)
    pvSession.connect(tog.TouchTap,tap)
    pvSession.connect(tog.InputBegan,function(index)
        if index.UserInputType==Enum.UserInputType.Touch
        or index.UserInputType==Enum.UserInputType.MouseButton1 then
            moved=false; startX,startY=index.Position.X,index.Position.Y
        end
    end)
    pvSession.connect(tog.InputChanged,function(index)


        if index.UserInputType==Enum.UserInputType.Touch
        or index.UserInputType==Enum.UserInputType.MouseMovement then
            local dx,dy=index.Position.X-startX, index.Position.Y-startY
            if (dx*dx+dy*dy) > 100 then moved=true end
        end
    end)


    pvSession.connect(tog.InputEnded,function(index)
        if index.UserInputType==Enum.UserInputType.Touch and not moved then tap() end
    end)
    _G.pvToggleUI = tap
end

task.spawn(function()
    local myGen=_G.pvGen
    while _G.pvGen==myGen do
        pvTick("toggle-reparent", 2)
        if pvSession.alive and togGui.Parent==nil then pcall(function() togGui.Parent=TOG_HOST end) end
        if tog.Parent==nil then pcall(function() tog.Parent=togGui end) end
    end
end)
do
    local data,spValue,siValue
    pvSession.connect(tog.InputBegan,function(index)
        if index.UserInputType==Enum.UserInputType.MouseButton1 or index.UserInputType==Enum.UserInputType.Touch then
            data=true;spValue=tog.Position;siValue=index.Position
            pvSession.connect(index.Changed,function() if index.UserInputState==Enum.UserInputState.End then data=false end end)
        end
    end)
    pvSession.connect(UIS.InputChanged,function(index)
        if data and (index.UserInputType==Enum.UserInputType.MouseMovement or index.UserInputType==Enum.UserInputType.Touch) then
            local ddValue=index.Position-siValue
            tog.Position=UDim2.new(spValue.X.Scale,spValue.X.Offset+ddValue.X,spValue.Y.Scale,spValue.Y.Offset+ddValue.Y)
        end
    end)
end
function pvControlDepth(button)
    if button:FindFirstChild("HalloweenControlDepth") then return end
    local depth=Instance.new("UIGradient")
    depth.Name="HalloweenControlDepth";depth.Rotation=90
    depth.Color=ColorSequence.new(Color3.new(1,1,1),Color3.fromRGB(213,207,222))
    if settings.uiTheme=="Christmas" then depth.Color=ColorSequence.new(Color3.new(1,1,1),Color3.fromRGB(204,215,219)) end
    depth.Enabled=settings.uiTheme=="Halloween" or settings.uiTheme=="Christmas";depth.Parent=button
end
function pvConfigColor(button)
    local role=button:GetAttribute("pvConfigRole")
    if settings.uiTheme=="Christmas" then
        if role=="SAVE CONFIG" then return Color3.fromRGB(34,103,70) end
        if role=="LOAD CONFIG" then return Color3.fromRGB(121,94,44) end
        return Color3.fromRGB(145,37,54)
    end
    if settings.uiTheme~="Halloween" then return button:GetAttribute("pvConfigOriginal") end
    if role=="SAVE CONFIG" then return Color3.fromRGB(163,77,22) end
    if role=="LOAD CONFIG" then return Color3.fromRGB(86,56,125) end
    return Color3.fromRGB(104,39,51)
end
local pages,navBtns={},{}
_G.pvTabDrag=nil
_G.pvTabMoved=false
local function showPage(number)
    for index,page in pairs(pages) do page.Visible=(index==number) end
    for index,navBtn in pairs(navBtns) do
        local onValue=(index==number)
        Tween:Create(navBtn,TweenInfo.new(0.16),{
            BackgroundColor3=onValue and (settings.uiTheme=="Christmas" and Color3.fromRGB(113,35,49) or TValue.pink) or TValue.black,
            BackgroundTransparency=onValue and 0 or 0.28,
        }):Play()
        navBtn.TextColor3=onValue and Color3.fromRGB(255,244,230) or TValue.sub
        navBtn.Font=Enum.Font.GothamBold
    end
    -- Restore the heading of the active subview when returning to a tab.
    pcall(function()
        local trade=pages.Trade
        local blockPanel=trade and trade:FindFirstChild("TradeBlockPanel")
        if number=="Settings" and pvSession.activeSettingsPanel then
            pageTitle.Text=pvSession.activeSettingsPanel:GetAttribute("Heading")
        elseif number=="Trade" and blockPanel and blockPanel.Visible then
            pageTitle.Text="PLAYER PANEL"
        else
            pageTitle.Text=string.upper(number)
        end
        -- The picker uses the heading space for its weapon list. Switching
        -- to another tab restores that tab's normal centered heading.
        local picker=blockPanel and blockPanel:FindFirstChild("InventoryWeaponPicker")
        pageTitle.Visible=not (number=="Trade" and blockPanel and blockPanel.Visible
            and picker and picker.Visible)
    end)
end
local function relayoutTabs()
    local vis={}
    for _,navBtn in pairs(navBtns) do if navBtn.Parent==nav then vis[#vis+1]=navBtn end end
    local number=math.max(#vis,1)
    for _,visItem in ipairs(vis) do visItem.Size=UDim2.new(1/number,-pxValue(3),1,0) end
end


function pvTabDragMove(mxValue)
    local data=_G.pvTabDrag; if not data or not data.Parent then return end
    local vis={}
    for _,navBtn in pairs(navBtns) do if navBtn.Parent==nav then vis[#vis+1]=navBtn end end
    table.sort(vis,function(first,child) return first.LayoutOrder<child.LayoutOrder end)
    local idx=0
    for _,visItem in ipairs(vis) do
        if visItem~=data then
            local cxValue=visItem.AbsolutePosition.X + visItem.AbsoluteSize.X/2
            if mxValue>cxValue then idx=idx+1 end
        end
    end
    local others={}
    for _,visItem in ipairs(vis) do if visItem~=data then others[#others+1]=visItem end end
    table.insert(others, math.clamp(idx+1,1,#others+1), data)
    for index,other in ipairs(others) do other.LayoutOrder=index end
end
function pvSaveTabOrder()
    -- Export the intended tab order even if an old config contained a swap.
    settings.tabOrder={"Items","Trade","Settings"}
    pcall(saveCfg)
end
function pvApplyTabOrder()
    -- Fixed top-level order. Older configurations may contain an accidental
    -- drag-swapped order; never restore it over the intended tabs.
    local order={Items=1,Trade=2,Settings=3}
    settings.tabOrder={"Items","Trade","Settings"}
    for name,navBtn in pairs(navBtns) do
        if order[name] then navBtn.LayoutOrder=order[name] end
    end
end
pvSession.connect(UIS.InputChanged,function(index)
    if not _G.pvTabDrag then return end
    if index.UserInputType~=Enum.UserInputType.MouseMovement and index.UserInputType~=Enum.UserInputType.Touch then return end
    if math.abs(index.Position.X-(_G.pvTabStartX or index.Position.X)) > pxValue(6) then _G.pvTabMoved=true end
    if _G.pvTabMoved then pcall(pvTabDragMove, index.Position.X) end
end)

local function makePage(name,hidden)
    local textButton=Instance.new("TextButton")
    textButton.Size=UDim2.new(1/3,-pxValue(3),1,0)
    textButton.Text=string.upper(name);textButton.Font=Enum.Font.GothamBold;textButton.TextSize=pxValue(9)
    textButton.TextColor3=TValue.sub;textButton.TextTruncate=Enum.TextTruncate.AtEnd
    textButton.BackgroundColor3=TValue.black;textButton.BackgroundTransparency=0.28

    textButton.AutoButtonColor=false
    if not hidden then textButton.Parent=nav end
    corner(textButton,pxValue(7))
    pvControlDepth(textButton)
    pcall(pvSmoothButton,textButton)
    pvSession.connect(textButton.MouseEnter,function()
        local current; for index,page in pairs(pages) do if page.Visible then current=index end end
        if current~=name then Tween:Create(textButton,TweenInfo.new(0.12),{BackgroundColor3=TValue.pinkDim,BackgroundTransparency=0.12}):Play() end
    end)
    pvSession.connect(textButton.MouseLeave,function()
        local current; for index,page in pairs(pages) do if page.Visible then current=index end end
        if current~=name then Tween:Create(textButton,TweenInfo.new(0.12),{BackgroundColor3=TValue.black,BackgroundTransparency=0.28}):Play() end
    end)
    local frame=Instance.new("Frame");frame.Size=UDim2.new(1,0,1,0);frame.BackgroundTransparency=1;frame.Visible=false;frame.Parent=pageHost
    pages[name]=frame;navBtns[name]=textButton
    textButton.LayoutOrder = _G.pvNavN or 0; _G.pvNavN = textButton.LayoutOrder + 1

    -- Use normal button activation instead of dragging to reorder tabs.
    -- This prevents accidental Trade/Items swaps on touch and mouse.
    pvSession.connect(textButton.Activated,function()
        -- The Player Panel is a remembered Trade subview. Only clicking Trade
        -- WHILE already on Trade returns to normal Trade controls. A click
        -- from Settings/Items simply reveals whichever Trade subview was open.
        if name=="Trade" and frame.Visible and type(pvSession.playerPanelReturn)=="function" then
            pvSession.playerPanelReturn()
        elseif name=="Settings" and frame.Visible and pvSession.settingsPanelReturn then
            pvSession.settingsPanelReturn()
        end
        showPage(name)
    end)
    relayoutTabs()
    return frame
end
local function scroll(parent)
    local scrollingFrame=Instance.new("ScrollingFrame")
    scrollingFrame.Size=UDim2.new(1,0,1,0);scrollingFrame.BackgroundTransparency=1;scrollingFrame.BorderSizePixel=0
    scrollingFrame.ScrollBarThickness=2;scrollingFrame.ScrollBarImageColor3=Color3.new(1,1,1);scrollingFrame.ScrollBarImageTransparency=0.65
    scrollingFrame.CanvasSize=UDim2.new();scrollingFrame.AutomaticCanvasSize=Enum.AutomaticSize.Y;scrollingFrame.Parent=parent

    scrollingFrame.ScrollingDirection=Enum.ScrollingDirection.Y
    scrollingFrame.VerticalScrollBarInset=Enum.ScrollBarInset.Always
    scrollingFrame.Active=true
    pad(scrollingFrame,pxValue(3),pxValue(3),pxValue(6),pxValue(5))


    local uiListLayout=Instance.new("UIListLayout");uiListLayout.Padding=UDim.new(0,pxValue(7))
    uiListLayout.SortOrder=Enum.SortOrder.LayoutOrder;uiListLayout.Parent=scrollingFrame
    return scrollingFrame
end

PINK_OFF = Color3.fromRGB(41,35,48)
PINK_ON  = Color3.fromRGB(157,61,17)
local BTN_BG, BTN_TR = PINK_OFF, 0

-- Weapon rows follow the selected UI theme without altering weapon data or clicks.
-- Custom gets its own softly tinted, rounded glass cards so the user's wallpaper
-- remains visible and the list matches the Custom theme's panel/border styling.
-- Pork and Halloween deliberately retain their original appearance.
function pvStyleWeaponSurface(inst)
    local role=inst:GetAttribute("pvWeaponSurface")
    if not role then return end
    local halloween=settings.uiTheme=="Halloween"
    local custom=settings.uiTheme=="Custom"
    local christmas=settings.uiTheme=="Christmas"
    local color,transparency
    if role=="List" then
        -- Don't put a second opaque rectangular tray on top of the custom photo.
        color=Color3.fromRGB(14,14,16)
        transparency=(halloween or custom or christmas) and 1 or 0.15
    elseif role=="Row" then
        local selected=inst:GetAttribute("pvWeaponSelected")==true
        if christmas then
            color=selected and PINK_ON or Color3.fromRGB(26,38,44)
            transparency=selected and 0.04 or 0.24
        elseif custom then
            -- A slightly transparent plum glass surface lets the custom image
            -- show through; a fine pink outline echoes the window's edge.
            color=selected and PINK_ON or Color3.fromRGB(31,24,38)
            transparency=selected and 0.16 or 0.43
        else
            color=selected and PINK_ON or (halloween and Color3.fromRGB(38,32,45) or BTN_BG)
            transparency=selected and 0 or (halloween and 0.03 or 0.25)
        end

        -- Maintain the old row radius when changing back to either other theme.
        local rounding=inst:FindFirstChildOfClass("UICorner")
        if rounding then rounding.CornerRadius=UDim.new(0,pxValue(custom and 8 or 5)) end

        local depth=inst:FindFirstChild("pvHalloweenCardDepth")
        if halloween and not depth then
            depth=Instance.new("UIGradient")
            depth.Name="pvHalloweenCardDepth";depth.Rotation=90
            depth.Color=ColorSequence.new(Color3.new(1,1,1),Color3.fromRGB(220,220,220))
            depth.Parent=inst
        end
        if depth then depth.Enabled=halloween end
        local outline=inst:FindFirstChild("pvHalloweenWeaponOutline")
        if halloween and not outline then
            outline=Instance.new("UIStroke")
            outline.Name="pvHalloweenWeaponOutline"
            outline.ApplyStrokeMode=Enum.ApplyStrokeMode.Border
            outline.LineJoinMode=Enum.LineJoinMode.Round
            outline.Parent=inst
        end
        if outline then
            outline.Enabled=halloween
            if halloween then
                outline.Color=selected and Color3.fromRGB(255,164,64) or Color3.fromRGB(117,83,128)
                outline.Thickness=1
                outline.Transparency=selected and 0.12 or 0.54
            end
        end

        local customOutline=inst:FindFirstChild("pvCustomWeaponOutline")
        if (custom or christmas) and not customOutline then
            customOutline=Instance.new("UIStroke")
            customOutline.Name="pvCustomWeaponOutline"
            customOutline.ApplyStrokeMode=Enum.ApplyStrokeMode.Border
            customOutline.LineJoinMode=Enum.LineJoinMode.Round
            customOutline.Parent=inst
        end
        if customOutline then
            customOutline.Enabled=custom or christmas
            if christmas then
                customOutline.Color=selected and Color3.fromRGB(246,208,130) or Color3.fromRGB(112,156,120)
                customOutline.Thickness=selected and 1.2 or 0.8
                customOutline.Transparency=selected and 0.16 or 0.55
            elseif custom then
                customOutline.Color=selected and Color3.fromRGB(255,115,192) or Color3.fromRGB(235,113,190)
                customOutline.Thickness=0.8
                customOutline.Transparency=selected and 0.22 or 0.68
            end
        end
    end
    if color and inst.BackgroundColor3~=color then inst.BackgroundColor3=color end
    if transparency~=nil and inst.BackgroundTransparency~=transparency then inst.BackgroundTransparency=transparency end
end

-- Selected player targets use a distinct, theme-aware highlight.
function pvStylePlayerTarget(button)
    if not button:GetAttribute("pvPlayerTargetSelected") then return end
    local halloween=settings.uiTheme=="Halloween"
    button.BackgroundColor3=halloween and Color3.fromRGB(112,55,20) or Color3.fromRGB(30,78,47)
    button.BackgroundTransparency=0
    button.TextColor3=halloween and Color3.fromRGB(255,191,106) or Color3.fromRGB(140,240,170)
    local outline=button:FindFirstChildOfClass("UIStroke")
    if outline then outline.Color=button.TextColor3;outline.Transparency=0.1 end
end

-- CHRISTMAS UI: floating snowflake field, winter chrome, no top snow.
do
    pvSession.attachChristmas=(function()
        local RunService = game:GetService("RunService")
        local Theme = {}
        local rgb = Color3.fromRGB
        local CValue = {
            night=rgb(5,19,22), pine=rgb(12,43,35), forest=rgb(17,65,47),
            panel=rgb(13,40,34), gold=rgb(234,195,122), goldDark=rgb(128,91,46),
            red=rgb(140,39,57), redDark=rgb(84,23,36), cream=rgb(255,244,221),
            muted=rgb(168,205,190), ice=rgb(216,244,255), ice2=rgb(232,247,255), green=rgb(93,218,157),
        }
        Theme.Colors = CValue
        local function corner(obj, radius)
            local uiCorner=obj:FindFirstChildOfClass("UICorner") or Instance.new("UICorner")
            uiCorner.CornerRadius=UDim.new(0,radius); uiCorner.Parent=obj; return uiCorner
        end
        local function round(obj)
            local uiCorner=Instance.new("UICorner"); uiCorner.CornerRadius=UDim.new(0.5,0); uiCorner.Parent=obj
        end
        local function block(parent, name, pos, size, color, z, alpha, radius)
            local frame=Instance.new("Frame")
            frame.Name=name; frame.BackgroundColor3=color; frame.BorderSizePixel=0; frame.BackgroundTransparency=alpha or 0
            frame.Position=pos; frame.Size=size; frame.ZIndex=z; frame.Active=false; frame.Selectable=false
            if radius then corner(frame,radius) end
            frame.Parent=parent; return frame
        end
        local function gradient(parent, name, stops, angle)
            local uiGradient=Instance.new("UIGradient"); uiGradient.Name=name; uiGradient.Rotation=angle or 90
            local keys={}; for index,stop in ipairs(stops) do keys[index]=ColorSequenceKeypoint.new(stop[1],stop[2]) end
            uiGradient.Color=ColorSequence.new(keys); uiGradient.Parent=parent; return uiGradient
        end
        local function edge(parent, name, color, thickness, alpha)
            local uiStroke=Instance.new("UIStroke"); uiStroke.Name=name; uiStroke.ApplyStrokeMode=Enum.ApplyStrokeMode.Border
            uiStroke.Color=color; uiStroke.Thickness=thickness; uiStroke.Transparency=alpha or 0; uiStroke.Parent=parent; return uiStroke
        end
        local function layer(parent,name,z)
            local func=block(parent,name,UDim2.fromScale(0,0),UDim2.fromScale(1,1),CValue.night,z,1)
            func.ClipsDescendants=true; func.Interactable=false; return func
        end
        local function line(parent,name,x1Value,y1Value,x2Value,y2Value,thickness,color,z,alpha)
            local dx,dy=x2Value-x1Value,y2Value-y1Value
            local func=block(parent,name,UDim2.fromOffset((x1Value+x2Value)/2,(y1Value+y2Value)/2),UDim2.fromOffset(math.sqrt(dx*dx+dy*dy),thickness),color,z,alpha,1)
            func.AnchorPoint=Vector2.new(.5,.5); func.Rotation=math.deg(math.atan2(dy,dx)); return func
        end
        local function disk(parent,name,x,y,item,handle,color,z,alpha)
            local func=block(parent,name,UDim2.fromOffset(x,y),UDim2.fromOffset(item,handle),color,z,alpha)
            func.AnchorPoint=Vector2.new(.5,.5); round(func); return func
        end
        local function colorGradient(parent,name,first,button)
            return gradient(parent,name,{{0,first},{1,button}},90)
        end
        function Theme.Attach(window, options)
            assert(window:IsA("Frame"),"Attach expects a Frame")
            options=options or {}
            local old=window:FindFirstChild("ChristmasBackdrop")
            assert(not old,"Destroy the previous theme handle before attaching again")
            local bezier=options.BackgroundZ or 0; local ozValue=options.OrnamentZ or 20
            local hasBundled=type(pvHasBundledChristmasBackground)=="function" and pvHasBundledChristmasBackground() or false
            local back=layer(window,"ChristmasBackdrop",bezier)
            back:SetAttribute("pvChristmasArt",true)
            local front=layer(window,"ChristmasTrim",ozValue)
            front:SetAttribute("pvChristmasArt",true)
            local wallpaper=block(back,"ForestNight",UDim2.fromScale(0,0),UDim2.fromScale(1,1),rgb(12,31,34),bezier,hasBundled and 0.80 or 0.10,15)
            local wallGrad=gradient(wallpaper,"EvergreenSky",{{0,rgb(24,50,48)},{.42,rgb(14,24,30)},{.77,rgb(10,17,24)},{1,rgb(18,30,35)}},90)
            if hasBundled then wallGrad.Transparency=NumberSequence.new({NumberSequenceKeypoint.new(0,.15),NumberSequenceKeypoint.new(1,.42)}) end
            -- Use a two-layer outer stroke so the rounded corners keep the same visual weight
            -- as Halloween, without bringing back any extra inner outline.
            local rimBase=edge(window,"ChristmasGoldRimBase",rgb(154,108,56),2.3,.42)
            rimBase:SetAttribute("pvChristmasArt",true)
            local rim=edge(window,"ChristmasGoldRim",Color3.new(1,1,1),1.45,.04)
            rim:SetAttribute("pvChristmasArt",true)
            gradient(rim,"ChampagneMetal",{{0,rgb(143,97,45)},{.2,rgb(255,226,161)},{.45,rgb(193,145,75)},{.72,rgb(255,241,177)},{1,rgb(132,87,44)}},45)
            local glow=block(back,"WinterLight",UDim2.fromScale(0,0),UDim2.fromScale(1,1),Color3.new(1,1,1),bezier+1,0,15)
            local ggValue=gradient(glow,"WinterLightFade",{{0,rgb(64,96,90)},{.38,rgb(21,40,40)},{1,rgb(8,13,20)}},112)
            ggValue.Transparency=NumberSequence.new(hasBundled and {
                NumberSequenceKeypoint.new(0,.78),NumberSequenceKeypoint.new(.45,.95),NumberSequenceKeypoint.new(1,.98)
            } or {
                NumberSequenceKeypoint.new(0,.62),NumberSequenceKeypoint.new(.48,.90),NumberSequenceKeypoint.new(1,.98)
            })
            local divider=window:FindFirstChild("RefinedAccent")
            local dividerWasVisible=divider and divider.Visible
            if divider then divider.Visible=false end

            -- Top lights removed by request.
            local lights=nil
            local bulbs={}
            -- Floating crystal field: high-resolution, antialiased snowflake art.
            -- Background flakes stay behind controls; a few soft edge flakes
            -- remain visible even on opaque pages. No layout offsets or top snow.
            local atlas=pvSession.getChristmasSnowAtlas()
            local random=Random.new(231225); local flakes={}
            local function snowflake(parent,size,z,alpha,variant)
                if atlas then
                    local imageLabel=Instance.new("ImageLabel")
                    imageLabel.Name="ChristmasSnowflake"; imageLabel.BackgroundTransparency=1
                    imageLabel.BorderSizePixel=0; imageLabel.Active=false; imageLabel.Selectable=false
                    imageLabel.AnchorPoint=Vector2.new(.5,.5); imageLabel.Size=UDim2.fromOffset(size,size)
                    imageLabel.ZIndex=z; imageLabel.Image=atlas; imageLabel.ImageTransparency=alpha
                    imageLabel.ImageRectOffset=Vector2.new(128*variant,0); imageLabel.ImageRectSize=Vector2.new(128,128)
                    imageLabel.Parent=parent
                    return imageLabel
                end
                -- Native six-arm backup for clients without local image support.
                local func=block(parent,"ChristmasSnowflake",UDim2.fromScale(.5,.5),UDim2.fromOffset(size,size),CValue.night,z,1)
                func.AnchorPoint=Vector2.new(.5,.5)
                local child=size/2; local result=size*.33
                for key=0,5 do
                    local first=key*math.pi/3; local dx,dy=math.cos(first),math.sin(first)
                    line(func,"CrystalArm",child,child,child+dx*result,child+dy*result,1,CValue.ice,z+1,alpha)
                    for _,sign in ipairs({-1,1}) do
                        local unit=first+sign*math.pi/3
                        local bxValue,byValue=child+dx*result*.56,child+dy*result*.56
                        line(func,"CrystalBranch",bxValue,byValue,bxValue+math.cos(unit)*result*.35,byValue+math.sin(unit)*result*.35,.8,CValue.ice,z+1,alpha)
                    end
                end
                return func
            end
            -- Stratified positions: one background crystal per cell, and
            -- equal foreground coverage along each edge, including the top.
            -- Small jitter keeps the field organic without creating clusters.
            for index=1,42 do
                local near=index>28
                local size=pxValue(near and random:NextNumber(11,19) or random:NextNumber(15,27))
                local alpha=near and random:NextNumber(.48,.64) or random:NextNumber(.22,.46)
                local x,y
                if near then
                    local jValue=index-29
                    local row=math.floor(jValue/2)
                    x=(jValue%2==0 and .065 or .935)+random:NextNumber(-.008,.008)
                    y=.085+row*.146+random:NextNumber(-.012,.012)
                else
                    local jValue=index-1
                    local col,row=jValue%4,math.floor(jValue/4)
                    x=.15+col*(.70/3)+random:NextNumber(-.035,.035)
                    y=.092+row*.144+random:NextNumber(-.020,.020)
                end
                local func=snowflake(near and front or back,size,near and ozValue+1 or bezier+2,alpha,(index-1)%4)
                func.Position=UDim2.fromScale(x,y)
                local rotation=random:NextNumber(0,360);func.Rotation=rotation
                flakes[index]={f=func,x=x,y=y,size=size,alpha=alpha,phase=random:NextNumber(0,math.pi*2),
                    speed=random:NextNumber(.22,.52),rotation=rotation,spin=random:NextNumber(4,13)*(index%2==0 and 1 or -1),near=near}
            end
            local handle={Snow=options.Snow~=false,Lights=options.Lights~=false,ReducedMotion=options.ReducedMotion==true}
            local stopped=false; local elapsed=0; local accept=0
            local visible=window.Visible; local conn; local visConn; local destroyConn
            local function updateVisibility()
                visible=window.Visible
                for _,flake in ipairs(flakes) do flake.f.Visible=handle.Snow end
                if lights then lights.Visible=handle.Lights end
            end
            function handle:SetSnow(onValue) self.Snow=onValue==true; updateVisibility() end
            function handle:SetLights(onValue) self.Lights=onValue==true; updateVisibility() end
            function handle:SetReducedMotion(onValue)
                self.ReducedMotion=onValue==true
                if self.ReducedMotion then for _,bulb in ipairs(bulbs) do bulb.glow.BackgroundTransparency=.95; bulb.inner.BackgroundTransparency=.84; bulb.bulb.BackgroundTransparency=0 end end
            end
            function handle:Destroy()
                if stopped then return end; stopped=true
                if conn then conn:Disconnect() end; if visConn then visConn:Disconnect() end; if destroyConn then destroyConn:Disconnect() end
                if divider and divider.Parent then divider.Visible=dividerWasVisible end
                back:Destroy();front:Destroy();rim:Destroy();rimBase:Destroy()
            end
            updateVisibility()
            visConn=window:GetPropertyChangedSignal("Visible"):Connect(updateVisibility)
            destroyConn=window.Destroying:Connect(function() handle:Destroy() end)
            conn=RunService.Heartbeat:Connect(function(dtValue)
                if stopped or not visible or handle.ReducedMotion or not window.Parent then accept=0; return end
                local ancestor=window.Parent
                while ancestor do
                    if (ancestor:IsA("GuiObject") and not ancestor.Visible) or (ancestor:IsA("ScreenGui") and not ancestor.Enabled) then accept=0; return end
                    ancestor=ancestor.Parent
                end
                accept=accept+math.min(dtValue,.1); if accept<1/30 then return end
                local step=accept; accept=0; elapsed=elapsed+step
                if handle.Snow then
                    for _,flake in ipairs(flakes) do
                        local phase=elapsed*flake.speed+flake.phase
                        local x=flake.x+(flake.near and .009 or .025)*math.sin(phase)
                        local y=flake.y+(flake.near and .015 or .029)*math.sin(phase*.71+flake.phase)
                        -- Bound rotated sprites inside the panel, including when resized.
                        local dim=window.AbsoluteSize
                        local number=math.min(.49,(flake.size*.72+3)/math.max(1,dim.X))
                        local number2=math.min(.49,(flake.size*.72+3)/math.max(1,dim.Y))
                        flake.f.Position=UDim2.fromScale(math.clamp(x,number,1-number),math.clamp(y,number2,1-number2))
                        flake.f.Rotation=(flake.rotation+elapsed*flake.spin)%360
                        if flake.f:IsA("ImageLabel") then
                            flake.f.ImageTransparency=math.clamp(flake.alpha+.14*math.sin(phase*1.5),0,1)
                        end
                    end
                end
                if handle.Lights and lights then
                    for index,bulb in ipairs(bulbs) do
                        local value=.5+.5*math.sin(elapsed*1.85+index*.74)
                        bulb.glow.BackgroundTransparency=.97-.06*value
                        bulb.inner.BackgroundTransparency=.88-.16*value
                        bulb.bulb.BackgroundTransparency=.05*(1-value)
                    end
                end
            end)
            return handle
        end
        return Theme.Attach
    end)()
    pvSession.addCleanup(function()
        if pvSession.christmasArt then pvSession.christmasArt:Destroy();pvSession.christmasArt=nil end
    end)
end

-- Appearance only: apply to this panel and its own FPS widget, never game UI.
do
    local pairsOfColors={
        {Color3.fromRGB(140,240,170),Color3.fromRGB(255,191,106),Color3.fromRGB(140,240,170)},
        {Color3.fromRGB(255,255,255),Color3.fromRGB(255,244,230),Color3.fromRGB(255,248,235)},
        {Color3.fromRGB(206,206,212),Color3.fromRGB(200,187,181),Color3.fromRGB(195,207,211)},
        {Color3.fromRGB(18,18,20),Color3.fromRGB(18,16,20),Color3.fromRGB(17,27,32)},
        {Color3.fromRGB(30,30,34),Color3.fromRGB(34,29,34),Color3.fromRGB(28,39,44)},
        {Color3.fromRGB(120,120,130),Color3.fromRGB(112,85,122),Color3.fromRGB(104,127,132)},
        {Color3.fromRGB(255,96,182),Color3.fromRGB(255,151,51),Color3.fromRGB(232,198,143)},
        {Color3.fromRGB(150,46,104),Color3.fromRGB(137,64,26),Color3.fromRGB(86,53,59)},
        {Color3.fromRGB(34,34,38),Color3.fromRGB(24,21,25),Color3.fromRGB(22,34,40)},
        {Color3.fromRGB(85,85,85),Color3.fromRGB(56,43,39),Color3.fromRGB(56,76,81)},
        {Color3.fromRGB(20,20,20),Color3.fromRGB(12,13,20),Color3.fromRGB(10,16,23)},
        {Color3.fromRGB(255,110,190),Color3.fromRGB(255,173,80),Color3.fromRGB(246,218,172)},
        {Color3.fromRGB(255,140,205),Color3.fromRGB(255,206,128),Color3.fromRGB(230,208,174)},
        {Color3.fromRGB(226,60,150),Color3.fromRGB(255,145,52),Color3.fromRGB(211,180,143)},
        {Color3.fromRGB(255,120,200),Color3.fromRGB(255,151,51),Color3.fromRGB(240,211,162)},
        {Color3.fromRGB(255,190,230),Color3.fromRGB(247,225,176),Color3.fromRGB(226,216,198)},
        {Color3.fromRGB(255,225,245),Color3.fromRGB(255,242,224),Color3.fromRGB(248,244,235)},
        {Color3.fromRGB(30,28,34),Color3.fromRGB(41,35,48),Color3.fromRGB(31,44,49)},
        {Color3.fromRGB(236,64,160),Color3.fromRGB(157,61,17),Color3.fromRGB(113,35,49)},
        {Color3.fromRGB(150,150,158),Color3.fromRGB(255,165,68),Color3.fromRGB(206,179,137)},
        {Color3.fromRGB(20,20,22),Color3.fromRGB(25,21,26),Color3.fromRGB(21,32,38)},
        {Color3.fromRGB(255,100,188),Color3.fromRGB(255,165,68),Color3.fromRGB(232,197,147)},
        {Color3.fromRGB(194,181,175),Color3.fromRGB(194,181,175),Color3.fromRGB(166,187,193)},
        {Color3.fromRGB(34,29,34),Color3.fromRGB(34,29,34),Color3.fromRGB(29,41,46)},
        {Color3.fromRGB(12,13,20),Color3.fromRGB(12,13,20),Color3.fromRGB(11,19,25)},
        {Color3.fromRGB(14,14,16),Color3.fromRGB(14,14,16),Color3.fromRGB(14,23,30)},
        {Color3.fromRGB(38,32,45),Color3.fromRGB(38,32,45),Color3.fromRGB(26,38,44)},
        {Color3.fromRGB(255,166,64),Color3.fromRGB(255,166,64),Color3.fromRGB(243,215,169)},
    }
    -- Cache only theme-relevant properties; never scan the UI tree on a switch.
    local originalT={}
    local colorMap={}
    local function colorKey(child)
        return math.floor(child.R*255+0.5)*65536+math.floor(child.G*255+0.5)*256+math.floor(child.B*255+0.5)
    end
    for _,pair in ipairs(pairsOfColors) do
        -- First match wins, preserving the original palette's shared accents.
        for _,pairItem in ipairs(pair) do
            local key=colorKey(pairItem)
            if not colorMap[key] then colorMap[key]=pair end
        end
    end
    local function convert(color,halloween,christmas)
        local pair=colorMap[colorKey(color)]
        if pair and (color==pair[1] or color==pair[2] or color==pair[3]) then return pair[christmas and 3 or (halloween and 2 or 1)] end
        return color
    end
    for key,color in pairs(TValue) do originalT[key]=convert(color,false) end
    local entries={}
    local chrome={}
    local pageBuckets={}
    local registeredRoots={}
    local epoch=0
    local function bucketFor(inst)
        local parent=inst.Parent
        while parent and parent~=gui do
            if parent.Parent==pageHost then
                if not pageBuckets[parent] then pageBuckets[parent]={} end
                return pageBuckets[parent]
            end
            parent=parent.Parent
        end
        return chrome
    end
    local function write(inst,prop,value)
        if inst[prop]~=value then inst[prop]=value end
    end
    local function style(entry)
        local inst=entry.inst
        if not inst.Parent then return end
        local handle=settings.uiTheme=="Halloween"
        local x=settings.uiTheme=="Christmas"
        for _,prop in ipairs(entry.props) do
            local value=inst[prop]
            local target=convert(value,handle,x)
            if target~=value then inst[prop]=target end
        end
        if entry.decoration then write(inst,"Visible",handle) end
        if entry.rim then
            local control=inst.Name=="HalloweenControlDepth"
            if control then inst.Color=ColorSequence.new(Color3.new(1,1,1),x and Color3.fromRGB(204,215,219) or Color3.fromRGB(213,207,222)) end
            write(inst,"Enabled",handle or (x and control))
        end
        if entry.header then
            write(inst,"Enabled",not handle)
            local version=inst.Parent==verLbl
            write(inst,"Thickness",x and 0.75 or 1)
            write(inst,"Transparency",x and 0.65 or (version and 0.55 or 0.52))
        end
        if entry.surface then pvStyleWeaponSurface(inst) end
        if inst:GetAttribute("pvConfigRole") then inst.BackgroundColor3=pvConfigColor(inst) end
        if inst:GetAttribute("pvPlayerTargetSelected") then pvStylePlayerTarget(inst) end
    end
    local function unregister(inst)
        local entry=entries[inst]
        if not entry then return end
        local bucket,index=entry.bucket,entry.index
        local last=bucket[#bucket]
        bucket[index]=last;bucket[#bucket]=nil
        if last and last~=entry then last.index=index end
        entries[inst]=nil
    end
    local function register(inst)
        if entries[inst] or not inst.Parent then return end
        local art=inst
        while art and art~=gui do
            if art:GetAttribute("pvChristmasArt") then return end
            art=art.Parent
        end
        local props={}
        local function capture(prop)
            if colorMap[colorKey(inst[prop])] then props[#props+1]=prop end
        end
        if inst:IsA("GuiObject") then capture("BackgroundColor3") end
        if inst:IsA("TextLabel") or inst:IsA("TextButton") or inst:IsA("TextBox") then capture("TextColor3") end
        if inst:IsA("TextBox") then capture("PlaceholderColor3") end
        if inst:IsA("UIStroke") then capture("Color") end
        if inst:IsA("ScrollingFrame") then capture("ScrollBarImageColor3") end
        local decoration=inst.Name=="HalloweenWeb" or inst.Name=="HalloweenMoon" or inst.Name=="HalloweenSpider"
        local rim=inst.Name=="HalloweenInnerRim" or inst.Name=="HalloweenBorderDepth" or inst.Name=="HalloweenControlDepth"
        local header=inst.Name=="pvHeaderTextOutline"
        local surface=inst:GetAttribute("pvWeaponSurface")~=nil
        if #props==0 and not decoration and not rim and not header and not surface then return end
        local bucket=bucketFor(inst)
        local entry={inst=inst,props=props,decoration=decoration,rim=rim,header=header,surface=surface,bucket=bucket,index=#bucket+1}
        entries[inst]=entry;bucket[#bucket+1]=entry
        style(entry)
    end
    function pvRegisterThemeRoot(root)
        if registeredRoots[root] then return end
        registeredRoots[root]=true
        local pending={}
        local queued=false
        local function queue(inst)
            pending[#pending+1]=inst
            if queued then return end
            queued=true
            task.defer(function()
                local index,count,started=1,0,os.clock()
                while index<=#pending and root.Parent and isCurrent() do
                    local item=pending[index];index=index+1
                    if item.Parent and item:IsDescendantOf(root) then register(item) end
                    count=count+1
                    if count>=64 or os.clock()-started>=0.001 then
                        task.wait();count=0;started=os.clock()
                    end
                end
                pending={};queued=false
            end)
        end
        local added=pvSession.connect(root.DescendantAdded,queue)
        local removed=pvSession.connect(root.DescendantRemoving,unregister)
        pvSession.connect(root.Destroying,function()
            added:Disconnect();removed:Disconnect();registeredRoots[root]=nil
            -- Drop references even if destruction suppresses descendant callbacks.
            for inst,entry in pairs(entries) do
                if inst:IsDescendantOf(root) then unregister(inst) end
            end
        end)
        -- Enumeration happens once when a root is registered, never per switch.
        for _,inst in ipairs(root:GetDescendants()) do queue(inst) end
    end
    function pvSetUITheme(name,persist)
        local requested=(name=="Pork UI" or name=="Halloween" or name=="Christmas" or name=="Custom") and name or "Pork UI"
        if epoch>0 and settings.uiTheme==requested then
            if pvRefreshCustomBackgroundVisibility then pvRefreshCustomBackgroundVisibility() end
            if pvRefreshChristmasBackgroundVisibility then pvRefreshChristmasBackgroundVisibility() end
            if type(pvSession.refreshUpgradeHelperTheme)=="function" then
                pvSession.refreshUpgradeHelperTheme()
            end
            if persist then saveCfg() end
            return
        end
        settings.uiTheme=requested
        if pvRefreshCustomBackgroundVisibility then pvRefreshCustomBackgroundVisibility() end
        if pvRefreshChristmasBackgroundVisibility then pvRefreshChristmasBackgroundVisibility() end
        epoch=epoch+1
        local token=epoch
        local handle=requested=="Halloween"
        local x=requested=="Christmas"
        -- Match the version number and UI palette to the active theme.
        verLbl.TextColor3=convert(Color3.fromRGB(255,110,190),handle,x)
        brandOutline.Enabled=true
        brandOutline.Thickness=x and 0.85 or 1
        brandOutline.Transparency=x and 0.60 or 0.5
        for key,color in pairs(originalT) do TValue[key]=convert(color,handle,x) end
        PINK_OFF=convert(Color3.fromRGB(30,28,34),handle,x)
        PINK_ON=convert(Color3.fromRGB(236,64,160),handle,x)
        BTN_BG=PINK_OFF
        galaxy.Color=ColorSequence.new(x and Color3.fromRGB(27,48,47) or (handle and Color3.fromRGB(39,25,43) or Color3.fromRGB(14,14,16)),x and Color3.fromRGB(11,17,24) or (handle and Color3.fromRGB(12,13,20) or Color3.fromRGB(14,14,16)))
        winStroke.Enabled=not x
        if x and not pvSession.christmasArt then
            pvSession.christmasArt=pvSession.attachChristmas(win,{BackgroundZ=0,OrnamentZ=20})
        elseif not x and pvSession.christmasArt then
            pvSession.christmasArt:Destroy();pvSession.christmasArt=nil
        end
        if type(pvSession.refreshUpgradeHelperTheme)=="function" then
            pvSession.refreshUpgradeHelperTheme()
        end
        if persist then saveCfg() end
        task.spawn(function()
            local work={chrome}
            for page,bucket in pairs(pageBuckets) do if page.Parent and page.Visible then work[#work+1]=bucket end end
            for page,bucket in pairs(pageBuckets) do if page.Parent and not page.Visible then work[#work+1]=bucket end end
            local count,started=0,os.clock()
            for _,bucket in ipairs(work) do
                local index=1
                while index<=#bucket do
                    if token~=epoch or not gui.Parent or not isCurrent() then return end
                    style(bucket[index]);index=index+1;count=count+1
                    if count>=64 or os.clock()-started>=0.001 then
                        task.wait();count=0;started=os.clock()
                    end
                end
            end
            if token==epoch then
                for name,navBtn in pairs(navBtns) do
                    local page=pages[name]
                    if page and navBtn.Parent then
                        navBtn.BackgroundColor3=page.Visible and (x and PINK_ON or TValue.pink) or TValue.black
                    end
                end
            end
            -- Player-card gradients are ColorSequences, not individual
            -- Color3 props registered by the main theme engine.
            -- Update existing cards directly without refreshing inventories.
            if token==epoch and type(pvSession.refreshPlayerPanelTheme)=="function" then
                pvSession.refreshPlayerPanelTheme()
            end
        end)
    end
    pvRegisterThemeRoot(gui)
    pvRegisterThemeRoot(togGui)
    pvSetUITheme(settings.uiTheme,false)
end

-- Smooth mouse-wheel scrolling for every Pork Hub ScrollingFrame, including
-- dropdowns and scroll panels created later. Native scrollbars, touch gestures,
-- layout spacing, and drag-to-scroll remain enabled and unchanged.
-- Kept in its own scope so it doesn't add long-lived Luau main-chunk locals.
do
    local RunService=game:GetService("RunService")
    local tracked={}
    local lastWheel=-100

    local function track(scrollingFrame)
        if not scrollingFrame:IsA("ScrollingFrame") or tracked[scrollingFrame]
            or scrollingFrame:GetAttribute("pvNoSmoothScroll") == true then return end
        local state={shown=scrollingFrame.CanvasPosition.Y,target=scrollingFrame.CanvasPosition.Y,active=false,writing=false}
        tracked[scrollingFrame]=state
        pvSession.connect(scrollingFrame:GetPropertyChangedSignal("CanvasPosition"),function()
            if state.writing or not isCurrent() then return end
            local raw=scrollingFrame.CanvasPosition.Y
            -- Only ease wheel movement; normal scrollbar dragging, programmed
            -- scrolls, and touch scrolling keep their original behaviour.
            if os.clock()-lastWheel>0.28 or not scrollingFrame.Visible then
                state.shown=raw
                state.target=raw
                state.active=false
                return
            end
            local limit=math.max(0,scrollingFrame.AbsoluteCanvasSize.Y-scrollingFrame.AbsoluteWindowSize.Y)
            if limit<=0 then
                state.shown=raw
                state.target=raw
                state.active=false
                return
            end
            local delta=raw-state.shown
            if math.abs(delta)<0.1 then return end
            state.target=math.clamp(state.target+delta,0,limit)
            state.writing=true
            scrollingFrame.CanvasPosition=Vector2.new(scrollingFrame.CanvasPosition.X,state.shown)
            state.writing=false
            -- Discard leftover wheel momentum; the easing below replaces it.
            pcall(function() scrollingFrame:ResetScrollVelocity() end)
            state.active=true
        end)
        pvSession.connect(scrollingFrame.Destroying,function() tracked[scrollingFrame]=nil end)
    end

    for _,desc in ipairs(gui:GetDescendants()) do
        if desc:IsA("ScrollingFrame") then track(desc) end
    end
    pvSession.connect(gui.DescendantAdded,function(desc)
        if desc:IsA("ScrollingFrame") then track(desc) end
    end)
    -- A scrollbar drag takes priority over a recent wheel gesture.
    pvSession.connect(UIS.InputBegan,function(input)
        if input.UserInputType==Enum.UserInputType.MouseButton1
          or input.UserInputType==Enum.UserInputType.Touch then
            lastWheel=-100
        end
    end)
    pvSession.connect(UIS.InputChanged,function(input)
        if input.UserInputType~=Enum.UserInputType.MouseWheel or not win.Visible then return end
        local pos=UIS:GetMouseLocation()
        local atValue=win.AbsolutePosition
        local szValue=win.AbsoluteSize
        if pos.X>=atValue.X and pos.X<=atValue.X+szValue.X
          and pos.Y>=atValue.Y and pos.Y<=atValue.Y+szValue.Y then
            lastWheel=os.clock()
        end
    end)
    pvSession.connect(RunService.RenderStepped,function(dtValue)
        if not isCurrent() then return end
        local blend=1-math.exp(-math.min(dtValue,0.1)*19)
        for key,state in pairs(tracked) do
            if state.active then
                if not key.Parent then
                    tracked[key]=nil
                else
                    local limit=math.max(0,key.AbsoluteCanvasSize.Y-key.AbsoluteWindowSize.Y)
                    state.target=math.clamp(state.target,0,limit)
                    state.shown=state.shown+(state.target-state.shown)*blend
                    if math.abs(state.target-state.shown)<0.45 then
                        state.shown=state.target
                        state.active=false
                    end
                    state.writing=true
                    key.CanvasPosition=Vector2.new(key.CanvasPosition.X,state.shown)
                    state.writing=false
                end
            end
        end
    end)
    pvSession.addCleanup(function() table.clear(tracked) end)
end

function pvSmoothButton(button)
    if not button or not button:IsA("GuiButton") or button:GetAttribute("pvSmoothButton") then return button end
    button:SetAttribute("pvSmoothButton",true)

    local pvSmoothScale=button:FindFirstChild("pvSmoothScale")
    if not pvSmoothScale then
        pvSmoothScale=Instance.new("UIScale")
        pvSmoothScale.Name="pvSmoothScale"
        pvSmoothScale.Scale=1
        pvSmoothScale.Parent=button
    end

    local glow=button:FindFirstChild("pvSmoothGlow")
    if not glow then
        glow=Instance.new("UIStroke")
        glow.Name="pvSmoothGlow"
        glow.ApplyStrokeMode=Enum.ApplyStrokeMode.Border
        glow.Color=TValue.pink
        glow.Thickness=1
        glow.Transparency=0.88
        glow.Parent=button
    end

    local hovered=false
    local pressed=false
    local scaleTween=nil
    local glowTween=nil
    local settleToken=0

    local function scaleTo(value,value2,style,dir)
        if scaleTween then pcall(function() scaleTween:Cancel() end) end
        -- Keep native-size glyphs stable; glow still supplies hover/press feedback.
        pvSmoothScale.Scale=1
    end

    local function glowTo(trValue,thValue,value)
        if glowTween then pcall(function() glowTween:Cancel() end) end
        glowTween=Tween:Create(
            glow,
            TweenInfo.new(value or 0.12,Enum.EasingStyle.Sine,Enum.EasingDirection.Out),
            {Transparency=trValue,Thickness=thValue}
        )
        glowTween:Play()
    end

    local function release()
        if not pressed then return end
        pressed=false
        settleToken=settleToken+1
        local myValue=settleToken


        local rest=hovered and 1.012 or 1
        scaleTo(1.022,0.075,Enum.EasingStyle.Back,Enum.EasingDirection.Out)
        glowTo(hovered and 0.42 or 0.80, hovered and 1.25 or 1, 0.11)

        task.delay(0.075,function()
            if myValue~=settleToken or pressed or not button.Parent then return end
            scaleTo(rest,0.115,Enum.EasingStyle.Quint,Enum.EasingDirection.Out)
        end)
    end

    pvSession.connect(button.MouseEnter,function()
        hovered=true
        if not pressed then
            scaleTo(1.012,0.14,Enum.EasingStyle.Quint,Enum.EasingDirection.Out)
            glowTo(0.42,1.25,0.14)
        end
    end)

    pvSession.connect(button.MouseLeave,function()
        hovered=false
        if not pressed then
            scaleTo(1,0.16,Enum.EasingStyle.Quint,Enum.EasingDirection.Out)
            glowTo(0.88,1,0.16)
        end
    end)

    pvSession.connect(button.InputBegan,function(index)
        if index.UserInputType==Enum.UserInputType.MouseButton1
        or index.UserInputType==Enum.UserInputType.Touch then
            pressed=true
            settleToken=settleToken+1
            scaleTo(0.958,0.055,Enum.EasingStyle.Quint,Enum.EasingDirection.Out)
            glowTo(0.08,1.65,0.055)
        end
    end)

    pvSession.connect(button.InputEnded,function(index)
        if index.UserInputType==Enum.UserInputType.MouseButton1
        or index.UserInputType==Enum.UserInputType.Touch then
            release()
        end
    end)


    pvSession.connect(button.MouseButton1Up,release)

    return button
end


function mcClick(button, fnValue)
    pcall(pvSmoothButton,button)
    local last=0
    local function goValue()
        local now=os.clock()
        if now-last < 0.25 then return end
        last=now
        fnValue(button)
    end
    pvSession.connect(button.MouseButton1Click,goValue)
    pvSession.connect(button.Activated,goValue)
    pcall(function() pvSession.connect(button.TouchTap,goValue) end)
    button.Active=true
    button.Selectable=true
    return button
end

local function btn(parent,text,cbValue)
    local textButton=Instance.new("TextButton")
    textButton.Size=UDim2.new(1,0,0,pxValue(30))
    textButton.BackgroundColor3=BTN_BG;textButton.BackgroundTransparency=BTN_TR
    textButton.Text=string.upper(text);textButton.Font=Enum.Font.GothamBold;textButton.TextSize=pxValue(9)+1
    textButton.TextColor3=TValue.txt;textButton.TextTruncate=Enum.TextTruncate.AtEnd
    textButton.AutoButtonColor=false;textButton.Parent=parent
    corner(textButton,pxValue(8))
    stroke(textButton,0.42,1,TValue.line)
    pvControlDepth(textButton)
    pvSession.connect(textButton.MouseEnter,function()
        if textButton:GetAttribute("pvPlayerTargetSelected") or textButton:GetAttribute("pvUpgradeTier") then return end

        Tween:Create(
            textButton,
            TweenInfo.new(0.16,Enum.EasingStyle.Sine,Enum.EasingDirection.Out),
            {BackgroundColor3=PINK_OFF:Lerp(PINK_ON,0.52),BackgroundTransparency=0}
        ):Play()
    end)
    pvSession.connect(textButton.MouseLeave,function()
        if textButton:GetAttribute("pvPlayerTargetSelected") or textButton:GetAttribute("pvUpgradeTier") then return end
        Tween:Create(
            textButton,
            TweenInfo.new(0.18,Enum.EasingStyle.Sine,Enum.EasingDirection.Out),
            {BackgroundColor3=PINK_OFF,BackgroundTransparency=BTN_TR}
        ):Play()
    end)

    mcClick(textButton, function() if cbValue then cbValue(textButton) end end)
    return textButton
end
local function lbl(parent,text,szValue,col)
    local textLabel=Instance.new("TextLabel")
    textLabel.Size=UDim2.new(1,0,0,pxValue(16));textLabel.AutomaticSize=Enum.AutomaticSize.Y
    textLabel.BackgroundTransparency=1;textLabel.Text=text;textLabel.Font=Enum.Font.GothamBold
    textLabel.TextSize=pxValue(szValue or 9);textLabel.TextWrapped=true;textLabel.TextXAlignment=Enum.TextXAlignment.Left
    textLabel.TextColor3=col or TValue.sub;textLabel.Parent=parent
    return textLabel
end
local function box(parent,phValue)
    local textBox=Instance.new("TextBox")
    textBox.Size=UDim2.new(1,0,0,pxValue(28))
    textBox.BackgroundColor3=BTN_BG;textBox.BackgroundTransparency=BTN_TR
    textBox.PlaceholderText=phValue;textBox.Text="";textBox.Font=Enum.Font.GothamMedium;textBox.TextSize=pxValue(10)
    textBox.TextColor3=TValue.txt;textBox.PlaceholderColor3=TValue.sub;textBox.ClearTextOnFocus=false
    textBox.TextXAlignment=Enum.TextXAlignment.Center
    textBox.Parent=parent
    corner(textBox,pxValue(8));pad(textBox,pxValue(8))
    local outline=stroke(textBox,0.82,1,TValue.line)
    pvSession.connect(textBox.Focused,function() Tween:Create(outline,TweenInfo.new(0.15),{Color=TValue.pink,Transparency=0.35}):Play() end)
    pvSession.connect(textBox.FocusLost,function() Tween:Create(outline,TweenInfo.new(0.15),{Color=TValue.line,Transparency=0.82}):Play() end)
    return textBox
end
pvSession.configRefresh={}
local function toggle(parent,label,init,cbValue)
    local textButton=Instance.new("TextButton")
    textButton.Size=UDim2.new(1,0,0,pxValue(30))
    textButton.BackgroundColor3=BTN_BG;textButton.BackgroundTransparency=BTN_TR
    textButton.Font=Enum.Font.GothamBold;textButton.TextSize=pxValue(8)+1;textButton.TextColor3=TValue.txt
    textButton.TextTruncate=Enum.TextTruncate.AtEnd
    textButton.AutoButtonColor=false;textButton.Parent=parent
    corner(textButton,pxValue(8))
    stroke(textButton,0.55,1,TValue.line)
    local state=init
    local function rfValue()
        textButton.Text=string.upper(label).."  "..(state and "ON" or "OFF")
        Tween:Create(textButton,TweenInfo.new(0.14),{
            BackgroundColor3=state and PINK_ON or BTN_BG,
            BackgroundTransparency=state and 0 or BTN_TR,
        }):Play()
        textButton.TextColor3=TValue.txt
    end
    mcClick(textButton, function() state=not state;rfValue();if cbValue then cbValue(state) end end)
    local settingKey=({["Auto Block After Trade"]="autoBlock",["ULTRA OPTIMIZER"]="ultraFpsBooster",
        ["Lock UI (freeze position)"]="uiLocked"})[label]
    if settingKey then
        pvSession.configRefresh[#pvSession.configRefresh+1]=function()
            state=settingKey=="autoBlock" and settings[settingKey]~=false or settings[settingKey]==true
            rfValue()
        end
    end
    rfValue();return textButton
end


function pvDropdown(parent,label,order,entries,onPick)
    local holder=Instance.new("Frame")
    holder.Size=UDim2.new(1,0,0,pxValue(30));holder.BackgroundTransparency=1
    holder.LayoutOrder=order or 0;holder.ClipsDescendants=false;holder.Parent=parent
    local bar=Instance.new("TextButton")
