    bar.Font=Enum.Font.GothamBold;bar.TextSize=pxValue(9);bar.TextColor3=TValue.txt
    local curLabel=label
    local panel
    local function setBar() bar.Text=curLabel.."   "..(panel and panel.Visible and "\u{25B2}" or "\u{25BC}") end
    setBar()
    bar.AutoButtonColor=false;bar.Parent=holder
    corner(bar,pxValue(8))
    local uiStroke=Instance.new("UIStroke");uiStroke.Color=TValue.pink;uiStroke.Thickness=pxValue(1);uiStroke.Transparency=0.4;uiStroke.Parent=bar
    panel=Instance.new("Frame")
    panel.Size=UDim2.new(1,0,0,pxValue(140));panel.Position=UDim2.new(0,0,0,pxValue(30))
