    panel.Visible=false;panel.Parent=holder
    corner(panel,pxValue(8))
    local uiStroke2=Instance.new("UIStroke");uiStroke2.Color=TValue.pink;uiStroke2.Thickness=pxValue(1);uiStroke2.Transparency=0.45;uiStroke2.Parent=panel
    local textBox=Instance.new("TextBox")
    textBox.Size=UDim2.new(1,-pxValue(8),0,pxValue(22));textBox.Position=UDim2.new(0,pxValue(4),0,pxValue(4))
    textBox.BackgroundColor3=Color3.fromRGB(30,28,34);textBox.BackgroundTransparency=0
    textBox.PlaceholderText="search...";textBox.Text="";textBox.ClearTextOnFocus=false
    textBox.Font=Enum.Font.GothamBold;textBox.TextSize=pxValue(8);textBox.TextColor3=TValue.txt
    textBox.PlaceholderColor3=TValue.sub;textBox.Parent=panel
    corner(textBox,pxValue(6))
    local scrollingFrame=Instance.new("ScrollingFrame")
    scrollingFrame.Size=UDim2.new(1,-pxValue(8),1,-pxValue(32));scrollingFrame.Position=UDim2.new(0,pxValue(4),0,pxValue(29))
    scrollingFrame.BackgroundTransparency=1;scrollingFrame.BorderSizePixel=0
    scrollingFrame.ScrollBarThickness=pxValue(3);scrollingFrame.ScrollBarImageColor3=PINK_ON
    scrollingFrame.VerticalScrollBarInset=Enum.ScrollBarInset.Always
    scrollingFrame.CanvasSize=UDim2.new();scrollingFrame.Parent=panel
    local uiListLayout=Instance.new("UIListLayout");uiListLayout.Padding=UDim.new(0,pxValue(2))
    uiListLayout.SortOrder=Enum.SortOrder.LayoutOrder;uiListLayout.Parent=scrollingFrame
    local rows={}
    for index,entry in ipairs(entries) do
        local textButton=Instance.new("TextButton")
        textButton.Size=UDim2.new(1,-pxValue(4),0,pxValue(22));textButton.LayoutOrder=index
        textButton.BackgroundColor3=PINK_OFF;textButton.BackgroundTransparency=0
        textButton.Text=entry.label;textButton.Font=Enum.Font.GothamBold;textButton.TextSize=pxValue(8)
        textButton.TextColor3=TValue.txt;textButton.TextTruncate=Enum.TextTruncate.AtEnd
        textButton.AutoButtonColor=false;textButton.Parent=scrollingFrame
        corner(textButton,pxValue(5))
        pvSession.connect(textButton.MouseEnter,function()
            Tween:Create(textButton,TweenInfo.new(0.14,Enum.EasingStyle.Sine,Enum.EasingDirection.Out),
                {BackgroundColor3=PINK_OFF:Lerp(PINK_ON,0.55)}):Play()
        end)
        pvSession.connect(textButton.MouseLeave,function()
            Tween:Create(textButton,TweenInfo.new(0.16,Enum.EasingStyle.Sine,Enum.EasingDirection.Out),
                {BackgroundColor3=PINK_OFF}):Play()
        end)
        mcClick(textButton,function()
            panel.Visible=false
            curLabel=label..":  "..entry.label
            setBar()
            holder.Size=UDim2.new(1,0,0,pxValue(30))
            if onPick then onPick(entry) end
        end)
        rows[#rows+1]={btn=textButton,nm=entry.label:lower()}
    end
    scrollingFrame.CanvasSize=UDim2.new(0,0,0,uiListLayout.AbsoluteContentSize.Y+pxValue(4))
    textBox:GetPropertyChangedSignal("Text"):Connect(function()
        local query=textBox.Text:lower()
        for _,row in ipairs(rows) do row.btn.Visible=(query=="" or row.nm:find(query,1,true)~=nil) end
        scrollingFrame.CanvasSize=UDim2.new(0,0,0,uiListLayout.AbsoluteContentSize.Y+pxValue(4))
    end)
    mcClick(bar,function()
        local open=not panel.Visible
        panel.Visible=open
        setBar()
        holder.Size=UDim2.new(1,0,0,open and pxValue(172) or pxValue(30))
    end)
    return holder
end
local function notify(msg)
    if not msg then return end
    local success = pcall(function() return _pvNotify(msg) end)
    if not success then pcall(print,"[porkVisuals] "..tostring(msg)) end
end
_toast, _toastTok = nil, 0
-- Slim panel-following notification; preserve the original 2.1s display + 0.25s exit.
do
    local activeTweens = {}
    -- Parent-relative placement inherits the panel's drag, resize and UIScale.
    -- Allow the attached strip to extend beyond the panel's bottom edge.
    win.ClipsDescendants = false
    local function placeToast()
        if not _toast or not _toast.Parent then return end
        local width=math.max(40,math.floor(win.AbsoluteSize.X)-20)
        local bounds=game:GetService("TextService"):GetTextSize(_toast.Message.Text,12,Enum.Font.GothamBold,Vector2.new(width,10000))
        _toast.Size=UDim2.new(1,0,0,math.max(32,math.ceil(bounds.Y)+14))
        _toast.Position=UDim2.new(0,0,1,5)
    end
    local function animate(obj, info, props)
        local tween = Tween:Create(obj, info, props)
        activeTweens[#activeTweens+1] = tween
        tween:Play()
    end
    -- Fade individual surfaces instead of rasterizing text in a CanvasGroup.
    local function fadeToast(value,alpha,seconds)
        local targets={
            {value,"BackgroundTransparency",alpha},
            {value.Message,"TextTransparency",alpha},
            {value.Outline,"Transparency",0.55+0.45*alpha},
            {value.TimerTrack,"BackgroundTransparency",alpha},
            {value.TimerTrack.Bar,"BackgroundTransparency",alpha},
        }
        for _,entry in ipairs(targets) do
            if seconds then animate(entry[1],TweenInfo.new(seconds),{[entry[2]]=entry[3]})
            else entry[1][entry[2]]=entry[3] end
        end
    end
    function _pvNotify(msg)
        for _, tween in ipairs(activeTweens) do tween:Cancel() end
        activeTweens = {}
        _toastTok = _toastTok + 1
        local tok = _toastTok
        if not _toast or _toast.Parent ~= win then
            local frame = Instance.new("Frame")
            frame.Name = "pvToast"
            frame.AnchorPoint = Vector2.new(0,0)
            frame.Size = UDim2.new(1,0,0,32)
            frame.BackgroundColor3 = TValue.glass
            frame.BorderSizePixel = 0
            frame.ZIndex = 100
            frame.Visible = false
            frame.Parent = win
            corner(frame,7)
            local outline = Instance.new("UIStroke")
            outline.Name = "Outline"
            outline.Color = TValue.pink
            outline.Transparency = 0.55
            outline.Thickness = 1
            outline.Parent = frame
            local label = Instance.new("TextLabel")
            label.Name = "Message"
            label.BackgroundTransparency = 1
            label.Position = UDim2.fromOffset(10,2)
            label.Size = UDim2.new(1,-20,1,-9)
            label.Font = Enum.Font.GothamBold
            label.TextSize = 12
            label.TextScaled = false
            label.TextStrokeTransparency = 1
            label.TextColor3 = TValue.txt
            label.TextWrapped = true
            label.TextXAlignment = Enum.TextXAlignment.Left
            label.TextYAlignment = Enum.TextYAlignment.Center
            label.ZIndex = 101
            label.Parent = frame
            local track = Instance.new("Frame")
            track.Name = "TimerTrack"
            track.BorderSizePixel = 0
            track.BackgroundColor3 = TValue.pane
            track.Position = UDim2.new(0,10,1,-5)
            track.Size = UDim2.new(1,-20,0,2)
            track.ZIndex = 101
            track.Parent = frame
            corner(track,3)
            local bar = Instance.new("Frame")
            bar.Name = "Bar"
            bar.BorderSizePixel = 0
            bar.BackgroundColor3 = TValue.pink
            bar.Size = UDim2.fromScale(1,1)
            bar.ZIndex = 102
            bar.Parent = track
            corner(bar,3)
            _toast = frame
        end
        local value = _toast
        local bar = value.TimerTrack.Bar
        value.Message.Text = tostring(msg)
        fadeToast(value,1)
        bar.Size = UDim2.fromScale(1,1)
        placeToast()
        value.Visible = true
        fadeToast(value,0,0.18)
        animate(bar,TweenInfo.new(2.1,Enum.EasingStyle.Linear),
            {Size=UDim2.fromScale(0,1)})
        task.delay(2.1,function()
            if tok ~= _toastTok or not value.Parent then return end
            fadeToast(value,1,0.25)
            task.wait(0.3)
            if tok == _toastTok and value.Parent then value.Visible=false end
        end)
    end
end
-- Integrated draggable FPS counter.
do
local Players = game:GetService("Players")
