local fpsChristmasBG = Instance.new("ImageLabel")
fpsChristmasBG.Name = "FPSChristmasBackground"
fpsChristmasBG.Size = UDim2.fromScale(1,1)
fpsChristmasBG.BackgroundTransparency = 1
fpsChristmasBG.BorderSizePixel = 0
fpsChristmasBG.ScaleType = Enum.ScaleType.Crop
fpsChristmasBG.ImageTransparency = 0.28
fpsChristmasBG.ZIndex = 0
fpsChristmasBG.Visible = false
fpsChristmasBG.Parent = panel
corner:Clone().Parent = fpsChristmasBG

local fpsChristmasDim = Instance.new("Frame")
fpsChristmasDim.Name = "FPSChristmasDim"
fpsChristmasDim.Size = UDim2.fromScale(1,1)
fpsChristmasDim.BackgroundColor3 = Color3.fromRGB(7,26,24)
fpsChristmasDim.BackgroundTransparency = 0.22
fpsChristmasDim.BorderSizePixel = 0
fpsChristmasDim.ZIndex = 1
fpsChristmasDim.Visible = false
fpsChristmasDim.Parent = panel
corner:Clone().Parent = fpsChristmasDim

local fpsSnowLayer = Instance.new("Frame")
fpsSnowLayer.Name = "FPSChristmasSnow"
fpsSnowLayer.Size = UDim2.fromScale(1,1)
fpsSnowLayer.BackgroundTransparency = 1
fpsSnowLayer.BorderSizePixel = 0
fpsSnowLayer.ClipsDescendants = true
fpsSnowLayer.ZIndex = 2
fpsSnowLayer.Visible = false
fpsSnowLayer.Parent = panel
corner:Clone().Parent = fpsSnowLayer

local fpsFlakes = {}
do
    local atlas = pvSession.getChristmasSnowAtlas and pvSession.getChristmasSnowAtlas() or nil
    local rng = Random.new(1225)
    local function spawnFlake(size, alpha, x, y, spin, speed, phase, variant)
        local imageLabel = Instance.new("ImageLabel")
        imageLabel.Name = "ChristmasSnowflake"
        imageLabel.BackgroundTransparency = 1
        imageLabel.BorderSizePixel = 0
        imageLabel.AnchorPoint = Vector2.new(0.5,0.5)
        imageLabel.Size = UDim2.fromOffset(size,size)
        imageLabel.Position = UDim2.fromScale(x,y)
        imageLabel.ZIndex = 2
        imageLabel.ImageTransparency = alpha
        if atlas then
            imageLabel.Image = atlas
            imageLabel.ImageRectOffset = Vector2.new(128*variant,0)
            imageLabel.ImageRectSize = Vector2.new(128,128)
        end
        imageLabel.Parent = fpsSnowLayer
        fpsFlakes[#fpsFlakes+1] = {f=imageLabel,x=x,y=y,size=size,alpha=alpha,spin=spin,speed=speed,phase=phase,rotation=rng:NextNumber(0,360)}
    end
    -- A 28px-tall counter needs its own sparse, low-contrast snowflake field.
    -- Stagger across the upper and lower edges, clear of the close button.
    for index=1,6 do
        local size = (index%3==0) and 10 or 8
        local x = 0.085 + (index-1)*0.145
        local y = index%2==0 and 0.75 or 0.25
        spawnFlake(size, rng:NextNumber(0.70,0.83), x, y,
            rng:NextNumber(3,7) * ((index % 2 == 0) and 1 or -1), rng:NextNumber(0.18,0.34), rng:NextNumber(0, math.pi*2), (index-1)%4)
    end
end

local function refreshFPSChristmasVisual()
    local christmas = settings.uiTheme == "Christmas"
    local image = ""
    pcall(function()
        local src = sky and sky:FindFirstChild("pvChristmasBackgroundImage")
