    end)
    fpsChristmasBG.Image = image
    fpsChristmasBG.Visible = christmas and image ~= ""
    fpsChristmasDim.Visible = christmas
    fpsSnowLayer.Visible = christmas
    panel.BackgroundTransparency = christmas and 0.08 or 0
end
