-- The counter has its own ScreenGui so hiding the main panel does not hide FPS.
local connections = {}
local function connect(signal, callback)
    connections[#connections+1] = signal:Connect(callback)
end
local dragging, dragStart, startPosition, touch
connect(panel.InputBegan, function(input)
    if input.UserInputType == Enum.UserInputType.MouseButton1
        or input.UserInputType == Enum.UserInputType.Touch then
        dragging = true
        dragStart = input.Position
        startPosition = panel.Position
        touch = input.UserInputType == Enum.UserInputType.Touch and input or nil
    end
end)
connect(UserInputService.InputChanged, function(input)
    if not dragging then return end
    if (touch and input == touch) or (not touch and input.UserInputType == Enum.UserInputType.MouseMovement) then
        local delta = input.Position - dragStart
        panel.Position = UDim2.new(startPosition.X.Scale,startPosition.X.Offset+delta.X,
            startPosition.Y.Scale,startPosition.Y.Offset+delta.Y)
    end
end)
connect(UserInputService.InputEnded, function(input)
    if input == touch or input.UserInputType == Enum.UserInputType.MouseButton1 then
        dragging = false
        touch = nil
    end
end)

-- Average rendered frames over a half-second window, not instantaneous 1/dt.
local frames, elapsed = 0, 0
local statsService = game:GetService("Stats")
local pingItem
local fpsAnimElapsed, fpsAnimAccum = 0, 0
local fpsThemeMarker = ""
local function readPingMs()
    local success, value = pcall(function()
        if not pingItem or not pingItem.Parent then
            local network = statsService:FindFirstChild("Network")
            local serverStats = network and network:FindFirstChild("ServerStatsItem")
            pingItem = serverStats and serverStats:FindFirstChild("Data Ping")
        end
        return pingItem and pingItem:GetValue()
    end)
    if success and type(value)=="number" and value==value and value>=0 and value<math.huge then
        return tostring(math.floor(value+0.5))
    end
    return "--"
end
connect(RunService.RenderStepped, function(dtValue)
    if not isCurrent() then gui:Destroy(); return end
    local currentTheme = tostring(settings.uiTheme or "")
    if currentTheme ~= fpsThemeMarker then
        fpsThemeMarker = currentTheme
        refreshFPSChristmasVisual()
    end
    if fpsSnowLayer.Visible and gui.Enabled then
        fpsAnimAccum = fpsAnimAccum + math.min(dtValue,0.1)
        if fpsAnimAccum >= 1/30 then
            local step = fpsAnimAccum
            fpsAnimAccum = 0
            fpsAnimElapsed = fpsAnimElapsed + step
            for _,flake in ipairs(fpsFlakes) do
                local phase = fpsAnimElapsed*flake.speed + flake.phase
                local x = flake.x + 0.006*math.sin(phase)
                local y = flake.y + 0.018*math.sin(phase*0.78 + flake.phase)
                local dim = panel.AbsoluteSize
                local number = math.min(0.46,(flake.size*0.72+2)/math.max(1,dim.X))
                local number2 = math.min(0.46,(flake.size*0.72+2)/math.max(1,dim.Y))
                flake.f.Position = UDim2.fromScale(math.clamp(x,number,1-number), math.clamp(y,number2,1-number2))
                flake.f.Rotation = (flake.rotation + fpsAnimElapsed*flake.spin) % 360
                flake.f.ImageTransparency = math.clamp(flake.alpha + 0.045*math.sin(phase*1.5), 0, 1)
            end
        end
    end
    if not gui.Enabled then frames, elapsed = 0, 0; return end
    frames = frames + 1
    elapsed = elapsed + dtValue
    if elapsed >= 0.5 then
        local fps = math.floor(frames / elapsed + 0.5)
        label.Text = "FPS: " .. fps .. "  |  Ping: " .. readPingMs() .. " ms"
        label.TextColor3 = fps >= 50 and (settings.uiTheme=="Halloween" and Color3.fromRGB(255,191,106) or Color3.fromRGB(140,240,170))
            or fps >= 30 and Color3.fromRGB(255,210,110)
            or Color3.fromRGB(255,120,130)
        frames, elapsed = 0, 0
    end
end)
keyActions.restoreFPS = function()
    if not isCurrent() then return end
    gui.Enabled = not gui.Enabled
    frames, elapsed = 0, 0
    notify(gui.Enabled and "FPS counter shown" or "FPS counter hidden")
end
connect(close.Activated, function()
    gui.Enabled = false
    local restoreKey = settings.keys and settings.keys.restoreFPS
    if type(restoreKey)=="string" and restoreKey~="" then
        notify("FPS counter removed, press "..restoreKey.." to restore")
    else
        notify("FPS counter removed, set keybind to restore")
    end
end)
pvSession.connect(gui.Destroying,function()
    for _, connection in ipairs(connections) do connection:Disconnect() end
    table.clear(connections)
end)

end
local RANK={
    Ancient=1, Godly=2, Unique=3,
    Legendary=4, Christmas=5, Halloween=5,
    Rare=6, Uncommon=7, Common=8,
    Classic=9, Vintage=9,
}
local items,seen={},{}
local _ItemService
local function _getIS()
    if _ItemService~=nil then return _ItemService end
    _ItemService=false
    for _,data in ipairs(replicatedStorageService:GetDescendants()) do
        if data:IsA("ModuleScript") and data.Name=="ItemService" then
            local success,errorMessage=pcall(require,data); if success then _ItemService=errorMessage end; break
        end
    end
    return _ItemService
end
local function resolveImg(id,rawImg)
    local isValue=_getIS()
    if isValue then
        local success,result=pcall(function() return isValue:GetDisplayInfo(id,"Weapons") end)
        if success and result and result.Image and tostring(result.Image)~="" then return tostring(result.Image) end
    end
    local img=tostring(rawImg or "")
    if img~="" and img:match("^%d+$") then img="rbxassetid://"..img end
    return img
end


function pvFixImg(img)
    img=tostring(img or "")
    if img=="" then return "" end
    if img:match("^%d+$") then return "rbxassetid://"..img end
    if img:find("Thumbs/Asset",1,true) or img:find("thumbnail",1,true) then
        local aid=img:match("[Aa]ssetId=(%d+)") or img:match("[?&]id=(%d+)") or img:match("(%d+)%D*$")
        if aid then return "rbxthumb://type=Asset&w=150&h=150&id="..aid end
    end
    return img
end
local function addCat(catName,kind,tradable)
    local data=Sync[catName]
    if type(data)~="table" then return end
    for id,info in pairs(data) do
        local name = type(info)=="table" and tostring(info.ItemName or info.Name or "") or ""
        if name~="" and not name:find("%?") then
            local rar=tostring(info.Rarity or "")


            local misc = (tostring(info.ItemType or "")=="Misc")


            local randomBox = name:find("Random",1,true)~=nil


            local orange = (rar=="Unique" and name~="Corrupt")
                           or name=="Clown" or name=="SharkSeeker" or name=="Dartbringer"
            local flat = name:lower():gsub("[^%a%d]","")


            local isNik = flat:find("niksscythe",1,true) or flat:find("nikscythe",1,true)
                          or flat:find("nikilis",1,true)


            local key=kind.."|"..tostring(id)
            if not (name:find("Test") or name=="Missing" or orange or misc or randomBox) and not seen[key] then
                seen[key]=true
                local img=(kind=="Weapon") and resolveImg(id,info.Image) or tostring(info.Image or "")
                img=pvFixImg(img)
                local isEvo = (info.EvoIndex~=nil) or (info.EvoBaseID~=nil)

                local text = tostring(id):match("_(%d%d%d%d)$")
                table.insert(items,{
                    id=id,name=name,kind=kind,cat=catName,
                    base=name,
                    yr=text,
                    type=tostring(info.ItemType or kind),
                    chroma=info.Chroma==true,rarity=rar,evo=isEvo,
                    fx=(info.FX==true) or (info.Effect~=nil) or (info.Particles~=nil),
                    img=img,tradable=tradable and not isEvo,
                    noSpawnAll=isNik or nil,
                })
            end
        end
    end
end
addCat("Weapons","Weapon",true)



table.sort(items,function(first,button)
    local raValue = RANK[first.rarity] or 9
    local rbValue = RANK[button.rarity] or 9
    if raValue ~= rbValue then return raValue < rbValue end
    if first.name ~= button.name then return first.name < button.name end
    return first.id < button.id
end)
local byId={} for _,item in ipairs(items) do byId[item.id]=item end
local weapons={} for _,item in ipairs(items) do if item.kind=="Weapon" then weapons[#weapons+1]=item end end


pcall(function()
    local swValue=Sync and Sync.Weapons
    if swValue and ProfileData.Weapons and ProfileData.Weapons.Owned then
        local removed=false
        for id in pairs(ProfileData.Weapons.Owned) do
            local entry=swValue[id]
            local enm = entry and tostring(entry.ItemName or entry.Name or "") or ""
            local rar = entry and tostring(entry.Rarity or "") or ""


            local orange   = (rar=="Unique" and enm~="Corrupt")
                             or enm=="Clown" or enm=="SharkSeeker" or enm=="Dartbringer"
            local junk      = entry and (tostring(entry.ItemType or "")=="Misc" or enm:find("Random",1,true))
            local aliasFake = (not byId[id]) and (type(savedSpawns)=="table" and savedSpawns[id]==true)
            if orange or junk or aliasFake then
                ProfileData.Weapons.Owned[id]=nil
                if type(savedSpawns)=="table" then savedSpawns[id]=nil end
                removed=true
            end
        end
        if removed then pcall(function() invChanged("Weapons") end) end
    end

    if type(settings.loadout)=="table" and type(settings.loadout.owned)=="table" then
        for id in pairs(settings.loadout.owned) do if not byId[id] then settings.loadout.owned[id]=nil end end
    end
    if type(savedSpawns)=="table" then
        for id in pairs(savedSpawns) do if not byId[id] then savedSpawns[id]=nil end end
    end
    pcall(saveCfg)
end)
local function isDefault(id)
    local item=byId[id]
    return id=="DefaultKnife" or id=="DefaultGun" or (item and (item.name=="Default Knife" or item.name=="Default Gun"))
end
local function spawnItem(id, amount, record, saveToConfig)
    if isDefault(id) then return end
    local item=byId[id]; local cat=(item and item.cat) or "Weapons"
    local playerData=ProfileData[cat]; if not (playerData and playerData.Owned) then return end
    amount=math.clamp(math.floor(amount or 1),1,999)


    local total = (item and item.evo) and 1 or math.clamp((playerData.Owned[id] or 0)+amount,1,999)
    playerData.Owned[id]=total
    invChanged(cat,id,total)
    if record~=false and cat=="Weapons" then
        settings.loadout.owned[id]=total
        if saveToConfig ~= false then
            savedSpawns[id] = true
        end
        saveCfg()
    end
end
local function equipItem(id,record)
    local item=byId[id]; if not item or item.kind~="Weapon" then return end
    local slot=(item.type=="Gun") and "Gun" or "Knife"
    ProfileData.Weapons.Equipped[slot]=id
    pcall(function() EquipService.EquippedChanged:Fire(slot,id) end)
    if record~=false then
        if slot=="Knife" then settings.loadout.knife=id else settings.loadout.gun=id end
        pcall(saveCfg)
    end
end
local skinCache={}
pcall(function() if hasFile and isfileSafe(SKIN_PATH) then skinCache=HttpService:JSONDecode(readfile(SKIN_PATH)) or {} end end)
local skinDirty=false
local function saveSkins()
    if not hasFile then return end
    skinDirty=false
    pcall(function()
        if type(isfolder)=="function" and not isfolder(CFG_DIR) then makefolder(CFG_DIR) end
        writefile(SKIN_PATH,HttpService:JSONEncode(skinCache))
    end)
end
local function skinCount() local number=0 for _ in pairs(skinCache) do number+=1 end return number end
local function meshFromAsset(id)
    local success,objs=pcall(function() return game:GetObjects("rbxassetid://"..tostring(id)) end)
    if not (success and objs) then return nil end
    local model,value
    for _,obj in ipairs(objs) do
        if obj:IsA("MeshPart") and obj.MeshId~="" then
            model,value=obj.MeshId:match("%d+"),(obj.TextureID or ""):match("%d+")
        end
        if not model then
            for _,data in ipairs(obj:GetDescendants()) do
                if data:IsA("SpecialMesh") and data.MeshId~="" then
                    model,value=data.MeshId:match("%d+"),(data.TextureId or ""):match("%d+");break
                elseif data:IsA("MeshPart") and data.MeshId~="" then
                    model,value=data.MeshId:match("%d+"),(data.TextureID or ""):match("%d+")
                end
            end
        end
        pcall(function() obj:Destroy() end)
        if model then break end
    end
    return model,value
end
local fetching={}
local function fetchSkin(name,cbValue)
    if skinCache[name] then if cbValue then cbValue(skinCache[name]) end return end
    if fetching[name] then return end
    fetching[name]=true
    task.spawn(function()
        local queries={
            "MM2 "..name,
            "Murder Mystery 2 "..name,
            name.." MM2 knife",
            name.." murder mystery",
        }


        local function norm(text) return tostring(text):lower():gsub("[^%a%d]","") end
        local target=norm(name)
        local function namesFor(ids)
            if #ids==0 then return {} end
            local result=httpGet("https://apis.roblox.com/toolbox-service/v1/items/details?assetIds="..table.concat(ids,","))
            local map={}
            if result then
                local okj,result2=pcall(function() return HttpService:JSONDecode(result) end)
                if okj and result2 and result2.data then
                    for _,dataItem in ipairs(result2.data) do
                        local first=dataItem.asset or {}
                        if first.id then map[first.id]=tostring(first.name or "") end
                    end
                end
            end
            return map
        end
        local got
        for _,query in ipairs(queries) do
            local result=httpGet("https://apis.roblox.com/toolbox-service/v1/marketplace/10?keyword="..HttpService:UrlEncode(query).."&limit=12")
            if result then
                local okj,data=pcall(function() return HttpService:JSONDecode(result) end)
                if okj and data and data.data then
                    local ids={}
                    for _,dataItem in ipairs(data.data) do
                        local aid=dataItem.id or (dataItem.asset and dataItem.asset.id)
                        if aid then ids[#ids+1]=aid end
                    end
                    local nameMap=namesFor(ids)
                    for _,aid in ipairs(ids) do
                        local anValue=norm(nameMap[aid] or "")

                        if anValue~="" and anValue:find(target,1,true) then
                            local model,value=meshFromAsset(aid)


                            local mid = model and tostring(model):match("%d+")
                            if model and not (mid and _G.pvBadMesh and _G.pvBadMesh[mid]) then
                                got={mesh=model,tex=value or ""};break
                            end
                            task.wait(0.05)
                        end
                    end
                end
            end
            if got then break end
            task.wait(0.1)
        end
        if got then skinCache[name]=got;skinDirty=true;saveSkins() end
        fetching[name]=nil
        if cbValue then cbValue(got) end
    end)
end
local function paintTool(tool,data)
    local handle=tool and tool:FindFirstChild("Handle")
    if not (handle and data and data.mesh) then return false end
    pcall(function()
        if handle:IsA("MeshPart") then
            handle.MeshId="rbxassetid://"..data.mesh
            if data.tex and data.tex~="" then handle.TextureID="rbxassetid://"..data.tex end
        else
            local specialMesh=handle:FindFirstChildWhichIsA("SpecialMesh")
            if not specialMesh then specialMesh=Instance.new("SpecialMesh");specialMesh.Parent=handle end
            specialMesh.MeshType=Enum.MeshType.FileMesh
            specialMesh.MeshId="rbxassetid://"..data.mesh
            if data.tex and data.tex~="" then specialMesh.TextureId="rbxassetid://"..data.tex end
        end
        handle.Transparency=0
    end)
    return true
end
local function clearHolster()
    local child=playerGui.Character; if not child then return end
    for _,x in ipairs(child:GetChildren()) do
        if x.Name=="porkHolster" then pcall(function() x:Destroy() end) end
    end
end
local function holsterFromMesh(meshId, texId, base, cframe)
    if not meshId then return end
    local model=Instance.new("Model");model.Name="porkHolster"
    local part=Instance.new("Part");part.Name="Handle";part.Size=Vector3.new(0.3,0.3,1.4)
    part.Transparency=1;part.CanCollide=false;part.Massless=true;part.Parent=model
    local specialMesh=Instance.new("SpecialMesh");specialMesh.MeshType=Enum.MeshType.FileMesh
    specialMesh.MeshId="rbxassetid://"..meshId
    if texId and texId~="" then specialMesh.TextureId="rbxassetid://"..texId end
    specialMesh.Scale=Vector3.new(0.55,0.55,0.55);specialMesh.Parent=part
    model.PrimaryPart=part;model.Parent=playerGui.Character
    model:PivotTo(base.CFrame*cframe)
    local weldConstraint=Instance.new("WeldConstraint");weldConstraint.Part0=base;weldConstraint.Part1=part;weldConstraint.Parent=part
end
function weaponDisplaySources()
    local character=playerGui.Character
    local out={}
    if not character then return out end
    for _,def in ipairs({{"DisplayRefKnife","Knife"},{"DisplayRefGun","Gun"}}) do
        local override=character:FindFirstChild(def[1])
        local src=override and override.Value
        if not src then
            local weaponDisplays=workspace:FindFirstChild("WeaponDisplays")
            src = weaponDisplays and weaponDisplays:FindFirstChild(def[2].."Display")
        end
        if src then out[def[2]]=src end
    end
    return out
end
function cacheFromDisplay()
    local srcs=weaponDisplaySources()
    for slot,src in pairs(srcs) do
        local id=ProfileData.Weapons.Equipped[slot]
        local item=id and byId[id]
        if item then
            local mesh,texture
            if src:IsA("MeshPart") and src.MeshId~="" then
                mesh,texture=src.MeshId:match("%d+"),(src.TextureID or ""):match("%d+")
            else
                local specialMesh=src:FindFirstChildWhichIsA("SpecialMesh")
                if specialMesh and specialMesh.MeshId~="" then mesh,texture=specialMesh.MeshId:match("%d+"),(specialMesh.TextureId or ""):match("%d+") end
            end
            if mesh then
                local current=skinCache[item.name]
                if not (current and current.mesh==mesh) then
                    skinCache[item.name]={mesh=mesh,tex=texture or ""}
                    skinDirty=true;pcall(saveSkins)
                end
            end
        end
    end
end
function showRealEquipped()
    local character=playerGui.Character
    if not character then return false,"no character" end
    local lower=character:FindFirstChild("LowerTorso") or character:FindFirstChild("Torso")
    if not lower then return false,"no torso" end
    local srcs=weaponDisplaySources()
    if not (srcs.Knife or srcs.Gun) then return false,"no weapon displays" end
    pcall(clearHolster)
    for _,slot in ipairs({"Knife","Gun"}) do
        local src=srcs[slot]
        if src then
            local success=pcall(function()
                local model=Instance.new("Model");model.Name="porkHolster"
                local part=src:Clone()
                part.Name="Handle";part.Anchored=false;part.CanCollide=false;part.Massless=true
                for _,data in ipairs(part:GetChildren()) do
                    if data:IsA("Weld") or data:IsA("WeldConstraint") or data:IsA("Motor6D") then data:Destroy() end
                end
                part.Parent=model
                model.PrimaryPart=part;model.Parent=character
                local cframe=(slot=="Knife")
                    and CFrame.new(0.75,-0.55,0.15)*CFrame.Angles(math.rad(180),0,math.rad(12))
                    or  CFrame.new(-0.75,-0.55,0.15)*CFrame.Angles(math.rad(180),0,math.rad(-12))
                model:PivotTo(lower.CFrame*cframe)
                local weldConstraint=Instance.new("WeldConstraint");weldConstraint.Part0=lower;weldConstraint.Part1=part;weldConstraint.Parent=part
            end)
            if not success then return false,"clone failed" end
        end
    end
    pcall(cacheFromDisplay)
    return true
end
bodyWorn={}
local function showOnBody(knifeW, gunW, onDone)


    if knifeW or gunW then settings.bodyCleared=false
    elseif settings.bodyCleared then if onDone then onDone(false,"cleared") end return end
    local char=playerGui.Character
    if not char then if onDone then onDone(false,"no character") end return end
    local lower=char:FindFirstChild("LowerTorso") or char:FindFirstChild("Torso")
    if not lower then if onDone then onDone(false,"no torso") end return end
    if knifeW then bodyWorn.Knife=knifeW end
    if gunW   then bodyWorn.Gun=gunW   end
    local need,missing={},{}
    for _,def in ipairs({{bodyWorn.Knife,"Knife"},{bodyWorn.Gun,"Gun"}}) do
        if def[1] and not skinCache[def[1].name] then need[#need+1]=def[1] end
    end
    local function paintAllNow()
        pcall(clearHolster)
        for _,def in ipairs({{bodyWorn.Knife,"Knife"},{bodyWorn.Gun,"Gun"}}) do
            local item,slot=def[1],def[2]
            if item then
                local data=skinCache[item.name]
                if data and data.mesh then
                    local meshId=tostring(data.mesh):match("%d+")
                    local texId =data.tex and tostring(data.tex):match("%d+") or nil
                    if meshId then
                        local cframe=(slot=="Knife")
                            and CFrame.new(0.75,-0.55,0.15)*CFrame.Angles(math.rad(180),0,math.rad(12))
                            or  CFrame.new(-0.75,-0.55,0.15)*CFrame.Angles(math.rad(180),0,math.rad(-12))
                        pcall(holsterFromMesh, meshId, texId, lower, cframe)
                    end
                else
                    missing[#missing+1]=item.name
                end
            end
        end
        if onDone then onDone(true, (#missing>0) and ("no mesh: "..table.concat(missing,", ")) or nil) end
    end
    if #need==0 then paintAllNow() return end
    local left=#need
    for _,needItem in ipairs(need) do
        fetchSkin(needItem.name,function()
            left=left-1
            if left<=0 then paintAllNow() end
        end)
    end
end
pvSession.connect(playerGui.CharacterAdded,function()
    task.wait(1.5)
    if bodyWorn.Knife or bodyWorn.Gun then pcall(showOnBody,nil,nil) end
end)
local function applyBodySkins()
    if pvInventoryVisualSync then return end
    if settings.bodyCleared then return end
    if bodyWorn.Knife or bodyWorn.Gun then return end
    if not settings.bodySkins then return end
    local char=playerGui.Character; if not char then return end
    local kwValue=settings.loadout.knife and byId[settings.loadout.knife]
    local gwValue=settings.loadout.gun   and byId[settings.loadout.gun]
    clearHolster()
    local lower=char:FindFirstChild("LowerTorso") or char:FindFirstChild("Torso")
    if not lower then return end
    for _,def in ipairs({{kwValue,"Knife"},{gwValue,"Gun"}}) do
        local item,slot=def[1],def[2]
        if item then
            local held = char:FindFirstChild(slot)
            if held then
                local handle = held:FindFirstChild("Handle")
                if handle then
                    local meshId, texId
                    if handle:IsA("MeshPart") then
                        meshId = handle.MeshId:match("%d+")
                        texId = handle.TextureID:match("%d+")
                    else
                        local specialMesh = handle:FindFirstChildWhichIsA("SpecialMesh")
                        if specialMesh then
                            meshId = specialMesh.MeshId:match("%d+")
                            texId = specialMesh.TextureId:match("%d+")
                        end
                    end
                    if meshId then
                        local cframe = (slot=="Knife")
                            and CFrame.new(0.75,-0.55,0.15)*CFrame.Angles(math.rad(180),0,math.rad(12))
                            or  CFrame.new(-0.75,-0.55,0.15)*CFrame.Angles(math.rad(180),0,math.rad(-12))
                        holsterFromMesh(meshId, texId, lower, cframe)
                        local data=skinCache[item.name]
                        if data then paintTool(held,data) end
                    end
                end
            end
        end
    end
end
task.spawn(function()
    while gui.Parent and isCurrent() do
        if settings.bodySkins then pcall(applyBodySkins) end
        task.wait(1.5)
    end
end)
