local buildRunning=false
local function buildAllSkins(onProgress,onDone)
    if buildRunning then return end
    buildRunning=true
    task.spawn(function()
        local todo={}
        for _,weapon in ipairs(weapons) do if not skinCache[weapon.name] then todo[#todo+1]=weapon.name end end
        for index,todoItem in ipairs(todo) do
            if not buildRunning then break end
            local done=false
            fetchSkin(todoItem,function() done=true end)
            local value=0
            while not done and value<8 do task.wait(0.2);value+=0.2 end
            if onProgress then pcall(onProgress,index,#todo,skinCount()) end
        end
        buildRunning=false
        saveSkins()
        if onDone then pcall(onDone,skinCount()) end
    end)
end
