function pvIsMobileLayout()
    if PV_FORCE_MOBILE_TRADE then return true end


    local live = playerGui2:FindFirstChild("TradeGUI")
    local container = live and live:FindFirstChild("Container") and live.Container:FindFirstChild("Items")
    if container then
        local mob = container:FindFirstChild("_mO")
        local main= container:FindFirstChild("Main")
        if mob and mob.Visible then return true end
        if main and main.Visible then return false end
    end


    return IS_TOUCH == true
end

