local function spoofSurface()


    local stale = playerGui2:FindFirstChild("pvTradeGUI")
    if stale then pcall(function() stale:Destroy() end) end
    local mine = nil


    local tmpl = pvFindTrade(game:GetService("StarterGui"))
    if not tmpl then return nil end
    if mine then pcall(function() mine:Destroy() end) end
    local clone = tmpl:Clone()
    clone.Name = "pvTradeGUI"
    clone.ResetOnSpawn = false
    for _,data in ipairs(clone:GetDescendants()) do
        if data:IsA("LocalScript") or data:IsA("ModuleScript") or data:IsA("Script") then
            pcall(function() data:Destroy() end)
        end
    end


    pcall(function()
        for _,data in ipairs(clone:GetDescendants()) do
            if data.Name=="NewItem" then
                local itemName=data:FindFirstChild("ItemName",true)
                itemName=itemName and itemName:FindFirstChild("Label")
                local txt=itemName and tostring(itemName.Text):lower() or ""
                if txt:find("nik",1,true) then pcall(function() data:Destroy() end) end
            end
        end
    end)


    pcall(pvApplyLayout, clone)
    clone.Enabled = true
    clone:GetPropertyChangedSignal("Enabled"):Connect(function()
        if clone.Parent and not clone.Enabled and _G.pvSpoofActive then clone.Enabled=true end
    end)
    clone.Parent = playerGui2
    if tradeUsable(clone) then spoofGui = clone; return clone end
    return nil
end
