    Rare      = Color3.fromHex("#00c800"),
    Legendary = Color3.fromHex("#dc0005"),
    Unique    = Color3.fromHex("#fa8c00"),
    Godly     = Color3.fromHex("#ff00b3"),
    Ancient   = Color3.fromHex("#640aff"),
    Classic   = Color3.fromHex("#e6c800"),
