local function offerColour(srcFrame,rid)
    if srcFrame then
        local itemName=srcFrame:FindFirstChild("ItemName",true)
        if itemName and itemName:IsA("GuiObject") then return itemName.BackgroundColor3 end
    end
    if rid then
        local success,result=pcall(function() return _getIS():GetDisplayInfo(rid,"Weapons") end)
        if success and result and typeof(result.Color)=="Color3" then return result.Color end
        local entry=Sync.Weapons and Sync.Weapons[rid]
        if entry and entry.Rarity and RARITY_COL[entry.Rarity] then return RARITY_COL[entry.Rarity] end
    end
    local item=rid and byId[rid]
    return (item and RARITY_COL[item.rarity]) or GREY_SLOT
end


local function pvOfferBadge(slot, id)
    local tags = slot:FindFirstChild("Tags", true)
    if not tags then return end
    local entry = id and Sync.Weapons and Sync.Weapons[id]
    local isEvo = (entry and ((entry.EvoIndex~=nil) or (entry.EvoBaseID~=nil))) or false
    local want = {
        Chroma=(entry and entry.Chroma==true) or false,
        FX=(entry and entry.FX==true) or false,
        Evo=isEvo,
        Christmas=false, Halloween=false, Unique=false,
    }
    local any=false
    for _,child in ipairs(tags:GetChildren()) do
        if child:IsA("GuiObject") and want[child.Name]~=nil then
            child.Visible=want[child.Name]
            if want[child.Name] then any=true end
        end
    end
    tags.Visible=any
end
local function enforceOffer()
    local child=offerCont(); if not child then return end
    for index=1,4 do
        local newItem=child:FindFirstChild("NewItem"..index);local oValue=offered[index]
        if newItem then
            if oValue then
                local icon=newItem:FindFirstChild("Icon",true); if icon and icon.Image~=oValue.icon then icon.Image=oValue.icon end
                local itemName=newItem:FindFirstChild("ItemName",true);local label=itemName and itemName:FindFirstChild("Label")
                if label and label.Text~=oValue.name then label.Text=oValue.name end
                if itemName and oValue.col and itemName.BackgroundColor3~=oValue.col then itemName.BackgroundColor3=oValue.col end
                local amount=newItem:FindFirstChild("Amount",true)
                if amount and amount:IsA("TextLabel") then
                    local want=(oValue.count and oValue.count>1) and ("x"..oValue.count) or ""
                    if amount.Text~=want then amount.Text=want end
                end

                pcall(pvOfferBadge, newItem, oValue.id)
                if not newItem.Visible then newItem.Visible=true end
            else
                if newItem.Visible then newItem.Visible=false end
                local tags=newItem:FindFirstChild("Tags",true)
                if tags and tags.Visible then tags.Visible=false end
                local icon=newItem:FindFirstChild("Icon",true); if icon and icon.Image~="" then icon.Image="" end
                local itemName=newItem:FindFirstChild("ItemName",true)
                if itemName and itemName:IsA("GuiObject") and itemName.BackgroundColor3~=GREY_SLOT then
                    itemName.BackgroundColor3=GREY_SLOT
                end
                local amount=newItem:FindFirstChild("Amount",true)
                if amount and amount:IsA("TextLabel") and amount.Text~="" then amount.Text="" end
            end
        end
    end
end
reserved = {}
local applyReserved = function() end
local _lastAdd={}
local function addOffer(name,icon,id,srcFrame)
    if #name==0 then return false,"no item" end


    if _G.pvOfferLocked then return false,"offer locked - both accepted" end
    local rid=id or nameToId(name)
    if name=="Default Knife" or name=="Default Gun" or rid=="DefaultKnife" or rid=="DefaultGun" then
        return false,"can't offer defaults"
    end
    local item=rid and byId[rid]
    if item and item.kind=="Pet" then return false,"pets aren't tradable" end
    if item and item.evo then return false,"evos aren't tradable" end
    if srcFrame and srcFrame:GetAttribute("pvEvo") == true then
        return false,"evos aren't tradable"
    end
    if rid then
        local ent=Sync.Weapons and Sync.Weapons[rid]
        if ent and (ent.EvoBaseID ~= nil or ent.EvoIndex ~= nil) then
            return false,"evos aren't tradable"
        end
    end


    local dkey = rid or name
    local now=os.clock()
    if _lastAdd[dkey] and (now-_lastAdd[dkey])<0.1 then return false end
    _lastAdd[dkey]=now
    local owned = (rid and ProfileData.Weapons.Owned[rid]) or 0
    local held  = (rid and reserved[rid]) or 0
    for _,offeredItem in ipairs(offered) do


        if (rid and offeredItem.id==rid) or (not rid and not offeredItem.id and offeredItem.name==name) then
            if rid and held >= owned then
                return false,"you only have "..owned
            end
            offeredItem.count=(offeredItem.count or 1)+1
            if rid then reserved[rid]=held+1 end
            pcall(enforceOffer);pcall(armCooldown);pcall(applyReserved,rid)
            return true
        end
    end
    if #offered>=4 then return false,"offer full (4 slots)" end
    if rid and held >= owned then return false,"you only have "..owned end
    table.insert(offered,{name=name,icon=icon or "",id=rid,count=1,src=srcFrame,
                          col=offerColour(srcFrame,rid)})
    if rid then reserved[rid]=held+1 end
    pcall(enforceOffer);pcall(armCooldown);pcall(applyReserved,rid)


    if _G.pvSyncFake then task.defer(function() pcall(_G.pvSyncFake) end) end
    return true
end
local function consumeOffered()
    for _,offeredItem in ipairs(offered) do
        local id=offeredItem.id
        if id then
            local have=ProfileData.Weapons.Owned[id] or 0
            local number=have-(offeredItem.count or 1)
            if number>0 then ProfileData.Weapons.Owned[id]=number else ProfileData.Weapons.Owned[id]=nil end
            invChanged("Weapons",id,math.max(number,0))
        end
    end
    offered = {}
    _lastAdd = {}
    reserved = {}
    pcall(applyReserved)
    pcall(saveCfg)
end
local function rarityInfo(rar)
    local value=Sync and Sync.Rarities and Sync.Rarities[rar]
    if not value then return 999,nil end
    local col=value.Color
    if typeof(col)~="Color3" then
        col = value.Hex and Color3.fromHex(tostring(value.Hex)) or nil
    end
    return tonumber(value.Sort) or 999, col
end
