pvTagsByName = pvTagsByName or {}
function pvRealTagsFrame(want)
    want = want or "Chroma"
    local cached = pvTagsByName[want]
    if cached and cached.Parent==nil then return cached end
    local found
    pcall(function()

        local roots = {
            playerGui2:FindFirstChild("TradeGUI"),
            playerGui2:FindFirstChild("pvTradeGUI"),
            playerGui2:FindFirstChild("MainGUI"),
            game:GetService("StarterGui"):FindFirstChild("TradeGUI"),
        }
        for _,src in ipairs(roots) do
            if src then
                for _,data in ipairs(src:GetDescendants()) do
                    if data.Name=="Tags" and data:IsA("GuiObject") and data:FindFirstChild(want) then
                        found=data break
                    end
                end
            end
            if found then break end
        end
    end)
    if found then
        pvTagsByName[want] = found:Clone()
        return pvTagsByName[want]
    end
end


function pvTileTag(value, which, szX, szY, posX, posBottom)

    for _,data in ipairs(value:GetDescendants()) do
        if data:IsA("GuiObject") and (data.Name=="pvTags" or data.Name=="Chroma"
           or data.Name=="FX" or data.Name=="Evo" or (data.Name:sub(1,5)=="pvTag")) then
            pcall(function() data:Destroy() end)
        end
    end
    if not which then return end
    local proto = pvRealTagsFrame(which)
    local src = proto and proto:FindFirstChild(which)
    if not src then return end
    local tag = src:Clone()
    tag.Name       = "pvTag"..which
    tag.Visible    = true
    tag.Size       = UDim2.fromOffset(szX or 56, szY or 17)
    tag.Position   = UDim2.new(0, posX or 4, 1, posBottom or -46)
    tag.AnchorPoint= Vector2.new(0,0)
    tag.ZIndex     = 30
    local bg  = tag:FindFirstChild("BG")
    local lbl = tag:FindFirstChild("TagName")


    local frameHasGradient = tag:FindFirstChildOfClass("UIGradient") ~= nil
    if bg and not frameHasGradient then

        tag.BackgroundTransparency = 1
        bg.AnchorPoint=Vector2.new(0,0); bg.Position=UDim2.new(0,0,0,0)
        bg.Size=UDim2.new(1,0,1,0); bg.ZIndex=30
        bg.ScaleType=Enum.ScaleType.Stretch
        bg.BackgroundTransparency=1; bg.ImageTransparency=0
        if lbl then
            lbl.AnchorPoint=Vector2.new(0,0); lbl.Position=UDim2.new(0,0,0,0)
            lbl.Size=UDim2.new(1,0,1,0); lbl.ZIndex=31
            lbl.TextScaled=true; lbl.BackgroundTransparency=1
            local cons=lbl:FindFirstChildOfClass("UITextSizeConstraint") or Instance.new("UITextSizeConstraint")
            cons.MinTextSize=8; cons.MaxTextSize=15; cons.Parent=lbl
            lbl.TextWrapped=false
            lbl.TextXAlignment=Enum.TextXAlignment.Center
            lbl.TextYAlignment=Enum.TextYAlignment.Center
        end
    else


        local arc=tag:FindFirstChildOfClass("UIAspectRatioConstraint")
        if arc then arc:Destroy() end
        if lbl then
            lbl.TextScaled=true
            local cons=lbl:FindFirstChildOfClass("UITextSizeConstraint") or Instance.new("UITextSizeConstraint")
            cons.MinTextSize=8; cons.MaxTextSize=15; cons.Parent=lbl
            lbl.TextWrapped=false
        end
    end
    tag.Parent = value
    return tag
end


