function pvActiveWeaponCont(vpValue)
    local root = vpValue.Main.Weapons.Items.Container
    for _,tab in ipairs({"Current","Classic","Holiday"}) do
        local scrollingFrame = root:FindFirstChild(tab)
        if scrollingFrame and scrollingFrame.Visible then
            return scrollingFrame:FindFirstChild("Container"), tab
        end
    end

    local current = root:FindFirstChild("Current")
    return current and current:FindFirstChild("Container"), "Current"
end


function pvWeaponTab(entry)
    local Event = entry.Event
    if Event then
        if Event~="Christmas" and Event~="Halloween" then return "Current" end
        return Event
    elseif entry.Season then
        return "Current"
    else
        return "Classic"
    end
end
function pvWeaponTabCont(vpValue, entry)
    local root = vpValue.Main.Weapons.Items.Container
    local tab = pvWeaponTab(entry)
    if tab=="Christmas" then
        local x=root.Holiday.Container:FindFirstChild("Christmas")
        return x and x:FindFirstChild("Container"), "Christmas"
    elseif tab=="Halloween" then
        local x=root.Holiday.Container:FindFirstChild("Halloween")
        return x and x:FindFirstChild("Container"), "Halloween"
    elseif tab=="Classic" then
        return root.Classic:FindFirstChild("Container"), "Classic"
    end
    return root.Current:FindFirstChild("Container"), "Current"
end


function pvEnforceTags(value, entry)
    local tags = value:FindFirstChild("Tags", true)
    if not tags then return end
    local isEvo = (entry.EvoIndex~=nil) or (entry.EvoBaseID~=nil)


    local want = {
        Chroma    = (entry.Chroma==true),
        FX        = (entry.FX==true),
        Evo       = isEvo,
        Christmas = false,
        Halloween = false,
        Unique    = false,
    }
    for _,child in ipairs(tags:GetChildren()) do
        if child:IsA("GuiObject") and want[child.Name]~=nil then
            pcall(function() child.Visible = want[child.Name] end)
        end
    end
end


function pvTileIs(value, entry)
    local itemName = value:FindFirstChild("ItemName", true)
    local label = itemName and (itemName:FindFirstChild("Label") or (itemName:IsA("TextLabel") and itemName))
    if not (label and label:IsA("TextLabel")) then return false end
    if tostring(label.Text) ~= tostring(entry.ItemName) then return false end
    local tags = value:FindFirstChild("Tags", true)
    local chroma = tags and tags:FindFirstChild("Chroma")
    local isChroma = (chroma and chroma:IsA("GuiObject") and chroma.Visible and tags.Visible) and true or false
    return isChroma == (entry.Chroma == true)
end

function pvTileAmount(value)
    local amount = value:FindFirstChild("Amount", true)
    local number = amount and amount:IsA("TextLabel") and tonumber(tostring(amount.Text):match("(%d+)"))
    return (number and number > 0) and number or 1
end


function pvProfileExtras(vpValue, spoofed)
    pcall(function()
        local prof = vpValue.Main.Profile.Container.Profile
        for _, name in ipairs({"Trophies", "Season1Stats"}) do
            local func = prof:FindFirstChild(name)
