function pvInjectProfile(vpValue, forceName)
    local key
    if forceName then
        key = tostring(forceName):lower():gsub("^%s+",""):gsub("%s+$","")
    else
        local success,uname = pcall(function() return tostring(vpValue.Main.Profile.Container.Username.Text) end)
        if not success then return end
        key = (uname or ""):lower():gsub("'s.*$",""):gsub("^%s+",""):gsub("%s+$","")
    end


    pcall(function()
        local root=vpValue.Main.Weapons.Items.Container
        for _,path in ipairs({ root.Current.Container,
                               root.Classic.Container,
                               root.Holiday.Container.Christmas.Container,
                               root.Holiday.Container.Halloween.Container }) do
            for _,data in ipairs(path:GetChildren()) do
                if data:GetAttribute("pvGiven") then pcall(function() data:Destroy() end)
                elseif data:GetAttribute("pvMergedReal") then

                    pcall(function() data.Visible = true; data:SetAttribute("pvMergedReal", nil) end)
                end
            end
        end
    end)
    local gave = (key~="" and _G.pvGaveTo[key]) or {}
    if #gave == 0 and not forceName then return end
    local tmpl = game:GetService("ReplicatedStorage").Modules.InventoryModule:FindFirstChild("NewItem")
    if not tmpl then return end
    local Sync = require(game:GetService("ReplicatedStorage").Database.Sync)

    local agg, order = {}, {}
    for index=#gave,1,-1 do
        local gui2 = gave[index]
        if gui2.id then
            if not agg[gui2.id] then agg[gui2.id] = 0; order[#order+1] = gui2.id end
            agg[gui2.id] = agg[gui2.id] + (tonumber(gui2.count) or 1)
        end
    end

    if forceName then
        for _,data in ipairs({"DefaultKnife","DefaultGun"}) do
            if Sync.Weapons[data] and not agg[data] then agg[data] = 1; order[#order+1] = data end
        end
    end
    for index,id in ipairs(order) do
        local entry = Sync.Weapons[id]
        if entry then
            local cont = pvWeaponTabCont(vpValue, entry)
            if cont then
                local amount = agg[id]

                for _,data in ipairs(cont:GetChildren()) do
                    if data.Name=="NewItem" and not data:GetAttribute("pvGiven") and data.Visible and pvTileIs(data, entry) then
                        amount = amount + pvTileAmount(data)
                        pcall(function() data.Visible = false; data:SetAttribute("pvMergedReal", true) end)
                        break
                    end
                end
                local gui2 = {id = id, count = amount}
                local value = tmpl:Clone()
                value.Name = "NewItem"
                value:SetAttribute("pvGiven", true)
                value.LayoutOrder = -100 + index


                local data = {}; for index2,eItem in pairs(entry) do data[index2]=eItem end
                data.Amount = gui2.count or 1; data.DataID = gui2.id
                value.Parent = cont
                pcall(function() _IMod().DisplayItem(value, data, nil, true) end)
                pcall(pvEnforceTags, value, entry)
            end
        end
    end
end


function pvBotStats(name)
    _G.pvBotStatsCache = _G.pvBotStatsCache or {}
    local child = _G.pvBotStatsCache[name]
    if child then return child end
    local seed = 7
    for index = 1, #name do seed = (seed * 31 + name:byte(index)) % 2147483647 end
    local rng = Random.new(seed)
    local level = rng:NextInteger(15, 100)
    local prestige = (level >= 85 and rng:NextNumber() < 0.45) and rng:NextInteger(1, 3) or 0
    local rounds = rng:NextInteger(90, 900)
    child = {
        Level = level, Prestige = prestige,
        Eliminations = math.floor(rounds * rng:NextNumber(0.09, 0.15) * rng:NextNumber(1.6, 3.4)),
        Victories    = math.floor(rounds * rng:NextNumber(0.08, 0.13) * rng:NextNumber(0.25, 0.55)),
        Survivals    = math.floor(rounds * rng:NextNumber(0.30, 0.55)),
    }
    _G.pvBotStatsCache[name] = child
    return child
end


-- Visual-player stats are SIMULATED, not the real account's MM2 records.
-- There is no fixed murder/sheriff/innocent stat count per level. XP can
-- accumulate through different game modes and the Season 1 counters were reset.
-- Use stable username-based variation in playstyle and season participation,
-- rather than misleadingly fitting every level to a single player screenshot.
function pvVisualLevelStats(name, requestedLevel)
    local level=math.clamp(math.floor(tonumber(requestedLevel) or 1),1,100)
    local seed=37
    local normalized=tostring(name or "VisualPlayer"):lower()
    for index=1,#normalized do
        seed=(seed*131+normalized:byte(index))%2147483647
    end
    local rng=Random.new(seed)
    -- Players specialise differently: murderer, sheriff, survivor or balanced.
    -- These are illustrative proportions, not verified MM2 level formulas.
    local styles={
        {1.90,0.63,0.83}, -- murderer-leaning
        {0.67,2.10,0.95}, -- sheriff-leaning
        {0.59,0.71,1.65}, -- survival-leaning
        {1.00,1.00,1.00}, -- balanced
        {1.27,0.87,1.17}, -- mixed
    }
    local style=styles[rng:NextInteger(1,#styles)]
    local activity=rng:NextNumber(0.55,1.70)
    -- Different amounts of the player's history can fall after Season 1's
    -- reset. Some established characters show very low season counters.
    local resetFraction=(rng:NextNumber()<0.18)
        and rng:NextNumber(0.06,0.29) or rng:NextNumber(0.48,1.00)
    local progress=(level/78)^1.22
    local rounds=520*progress*activity*resetFraction
    return {
        Level=level,
        Prestige=0,
        Eliminations=math.max(0,math.floor(rounds*0.26*style[1]*rng:NextNumber(0.87,1.13)+0.5)),
        Victories=math.max(0,math.floor(rounds*0.078*style[2]*rng:NextNumber(0.86,1.14)+0.5)),
        Survivals=math.max(0,math.floor(rounds*0.47*style[3]*rng:NextNumber(0.90,1.10)+0.5)),
    }
end

function pvBotInventory(name)
    if not _G.pvInvSkeleton then
        pcall(function()
            _G.pvInvSkeleton = replicatedStorageService.Remotes.Extras.GetFullInventory:InvokeServer(playerGui.Name)
        end)
    end
    local base = _G.pvInvSkeleton or {}
    local data = {}
    for index, baseItem in pairs(base) do data[index] = baseItem end
    local owned = {DefaultKnife = 1, DefaultGun = 1}
    for _, gui2 in ipairs(_G.pvGaveTo[tostring(name):lower()] or {}) do
        if gui2.id then owned[gui2.id] = (owned[gui2.id] or 0) + (tonumber(gui2.count) or 1) end
    end
    for _, cat in ipairs({"Weapons", "Effects", "Perks", "Emotes", "Radios", "Pets"}) do
        local src = type(base[cat]) == "table" and base[cat] or {}
        local entries = {}
        for index, srcItem in pairs(src) do entries[index] = srcItem end
        entries.Owned = (cat == "Weapons") and owned or {}
        entries.Equipped = (cat == "Weapons") and {Knife = "DefaultKnife", Gun = "DefaultGun"} or {}
        data[cat] = entries
    end
    return data
end
function pvOpenBotProfile(name, overrideLevel, overrideStats)
    local vpValue = playerGui2.MainGUI.Game.ViewProfile
    local VPM = require(replicatedStorageService.Modules.ViewProfileModule)
    local pcValue = (VPM.GUI and VPM.GUI.ProfileContainer) or vpValue.Main.Profile.Container
    local state = pvBotStats(name)
    if overrideLevel ~= nil then
        -- Only visual players receive estimated Season 1 profile stats;
        -- normal trade bots retain their own cached bot stats.
        state=pvVisualLevelStats(name,overrideLevel)
        -- Explicit user-entered overrides beat simulated values. Empty fields
        -- leave the respective statistic on its automatic estimate.
        if type(overrideStats)=="table" then
            for _,key in ipairs({"Eliminations","Victories","Survivals"}) do
                local number=tonumber(overrideStats[key])
                if number and number>=0 and number<=9999999 and number==math.floor(number) then
                    state[key]=number
                end
            end
        end
    end
    _G.pvBotProfileName = name
    _G.pvSpoofProfileName = nil

    pcall(function()
        local username = pcValue:FindFirstChild("Username") or pcValue.Parent:FindFirstChild("Username")
        username.Text = name
    end)

    pcall(function()
        local lcValue = pcValue.Character.CharacterIcon.LevelFrame.LevelContainer
        lcValue.Icon.Level.Text = state.Level
        pcall(function() lcValue.Icon.Image = require(replicatedStorageService.RankIconsEmpty)[state.Level] end)
        lcValue.Prestige.Visible = state.Prestige > 0
        if state.Prestige > 0 then lcValue.Prestige.Text = ({"I","II","III","IV","V"})[state.Prestige] end
    end)

    pcall(function()
        local character = pcValue.Character
        for _, button in ipairs({"Elite","Builder","WeaponDesigner","MM2Creator","BetaTester","Clown"}) do
            local func = character:FindFirstChild(button); if func then func.Visible = false end
        end
    end)

    pcall(function()
        local scale = pcValue.Profile.Season1Stats
        scale.Visible = true
        scale.Container.Eliminations.Amount.Text = state.Eliminations
        scale.Container.Saves.Amount.Text = state.Victories
        scale.Container.Survivals.Amount.Text = state.Survivals
    end)

    pcall(function()
        local trValue = pcValue.Profile.Trophies
        trValue.Visible = true
        for _, value in ipairs(trValue.Container:GetChildren()) do if value:IsA("Frame") then value:Destroy() end end
    end)

    VPM.DisplayInventoryFromData(vpValue, name, pvBotInventory(name))

    local okW = pcall(function() require(replicatedStorageService.Modules.WindowService):ViewFrame("ViewProfile") end)
    if not okW then pcall(function() vpValue.Visible = true end) end

    task.spawn(function()


        local uid = pvUserIdOf(name)
        if not uid then
            local seed = 11
            for index = 1, #name do seed = (seed * 37 + name:byte(index)) % 2147483647 end
            uid = Random.new(seed):NextInteger(20000000, 3500000000)
        end
        local img = ""
        pcall(function()
            img = Players:GetUserThumbnailAsync(uid, Enum.ThumbnailType.AvatarBust, Enum.ThumbnailSize.Size352x352)
        end)
        pcall(function() pcValue.Character.CharacterIcon.Image = img end)
        pcall(function() vpValue.Nav.Profile.Icon.Image = img end)
    end)
end


_G.pvUidCache = _G.pvUidCache or {}
function pvUserIdOf(name)
    local key=tostring(name):lower()
    if _G.pvUidCache[key]~=nil then return _G.pvUidCache[key] end

    for _,part in ipairs(game:GetService("Players"):GetPlayers()) do
        if part.Name:lower()==key then _G.pvUidCache[key]=part.UserId; return part.UserId end
    end

    local uid
    pcall(function() uid = game:GetService("Players"):GetUserIdFromNameAsync(name) end)
    _G.pvUidCache[key] = uid or false
    return uid
end

function pvSpoofProfile(name)
    local playersService=game:GetService("Players").LocalPlayer.PlayerGui
    local viewProfile=playersService.MainGUI.Game:FindFirstChild("ViewProfile")
    if not viewProfile then return end
    _G.pvSpoofProfileName = name
    _G.pvLastProfileKey = nil
    pcall(function()
        for _,data in ipairs(viewProfile:GetDescendants()) do
            if data:IsA("TextLabel") and data.Name=="Username" then
                if tostring(data.Text):find("'s") then
                    data.Text = name.."'s"..(tostring(data.Text):match("'s(.*)") or "")
                else
                    data.Text = name
                end
            end
        end
    end)


    task.spawn(function()
        local uid = pvUserIdOf(name)
        if not uid then return end
        local thumb = ("rbxthumb://type=AvatarBust&id=%d&w=352&h=352"):format(uid)


        for _=1,10 do
            if _G.pvSpoofProfileName~=name then break end
            pcall(function()
                local charFrame = viewProfile.Main.Profile.Container:FindFirstChild("Character")
                if charFrame then
                    for _,data in ipairs(charFrame:GetDescendants()) do
                        if data:IsA("ImageLabel") then data.Image = thumb end
                    end
                end
                local nav = viewProfile:FindFirstChild("Nav")
                local icon = nav and nav:FindFirstChild("Profile")
                icon = icon and icon:FindFirstChild("Icon")
                if icon and icon:IsA("ImageLabel") then icon.Image = thumb end

                for _,data in ipairs(viewProfile:GetDescendants()) do
                    if data:IsA("ImageLabel") and tostring(data.Image):find("AvatarBust",1,true) then data.Image=thumb end
                end
            end)
            task.wait(0.2)
        end
    end)


    pcall(function()
        local root=viewProfile.Main.Weapons.Items.Container
        for _,path in ipairs({ root.Current.Container, root.Classic.Container,
                               root.Holiday.Container.Christmas.Container,
                               root.Holiday.Container.Halloween.Container }) do
            for _,data in ipairs(path:GetChildren()) do
                if data.Name=="NewItem" and not data:GetAttribute("pvGiven") then pcall(function() data:Destroy() end) end
            end
        end
    end)
    pcall(function() viewProfile.Visible=true end)
    task.wait(0.1)
    pvProfileExtras(viewProfile, true)
    pvInjectProfile(viewProfile, name)
end

task.spawn(function()
    local myGen=_G.pvGen
    local playersService=game:GetService("Players").LocalPlayer.PlayerGui
    while _G.pvGen==myGen do
        pcall(function()
            local mainGUI = playersService:FindFirstChild("MainGUI")
