                if forceName then want = math.max(want, 1) end
                pcall(pvProfileExtras, mainGUI, forceName ~= nil)


                if key ~= _G.pvLastProfileKey then
                    _G.pvLastProfileKey = key
                    pvInjectProfile(mainGUI, forceName)
                elseif want>0 and not havePv then
                    pvInjectProfile(mainGUI, forceName)
                end
            else
