                _G.pvBotProfileName = nil
                _G.pvLastProfileKey = nil
            end
        end)
        pvTick("view-profile", 0.5)
    end
end)

pvTagProto = pvTagProto or {}
function pvRealTag(which)
    if pvTagProto[which] and pvTagProto[which].Parent==nil then return pvTagProto[which] end
    local found
    pcall(function()
        for _,src in ipairs({ game:GetService("StarterGui"):FindFirstChild("TradeGUI"),
                              playerGui2:FindFirstChild("TradeGUI") }) do
            if src then
                for _,data in ipairs(src:GetDescendants()) do
                    if data.Name==which and data.Parent and data.Parent.Name=="Tags" then found=data break end
                end
            end
            if found then break end
        end
    end)
    if found then
        local child=found:Clone(); child.Visible=true
        pvTagProto[which]=child
        return child
    end
end
local _fxProto=nil
