tileTmplCache=nil
function gridCont(scroll)
    local items2=scroll:FindFirstChild("Items")
    items2=items2 and items2:FindFirstChild("Container")
    items2=items2 and items2:FindFirstChild("Current")
    items2=items2 and items2:FindFirstChild("Container")
    return items2
end


function pvGridScroll(catFrame)
    if not catFrame then return nil,nil end
    if catFrame:IsA("ScrollingFrame") then
        return catFrame, gridCont(catFrame)
    end
    local items2=catFrame:FindFirstChild("Items")
    items2=items2 and items2:FindFirstChild("Container")
    items2=items2 and items2:FindFirstChild("Current")
    if not items2 or not items2:IsA("ScrollingFrame") then return nil,nil end
    return items2, items2:FindFirstChild("Container")
end
function tileTemplate(scroll,waitFor)
    if tileTmplCache and tileTmplCache.Parent==nil then return tileTmplCache end
    local real=realTileTemplate()
    if real then tileTmplCache=real; return real end
    local deadline=os.clock()+(waitFor or 0)
    repeat
        local cont=gridCont(scroll)
        if cont then
            for _,child in ipairs(cont:GetChildren()) do
                if child.Name=="NewItem" then
                    tileTmplCache=child:Clone()
                    return tileTmplCache
                end
            end
        end
        if os.clock()<deadline then task.wait(0.1) end
    until os.clock()>=deadline
end
local function gridRarity(id,cat)
    local value=Sync and Sync[cat]
    local entry=value and value[id]
    return entry and tostring(entry.Rarity or entry.rarity or "") or ""
end
local function renderGrid(cat,scroll,cont,tmpl)


    cont = cont or (function() local success,result=pcall(function() return scroll.Items.Container.Current.Container end); return success and result or nil end)()
    if not cont then return 0 end
    for _,child in ipairs(cont:GetChildren()) do
        if child.Name=="NewItem" then child:Destroy() end
    end
    local list={}
    do
        local success,tbl = pcall(function() return _IM().GenerateInventoryTables(ProfileData,"Trading") end)
        if success and tbl and tbl.Data then
            local ok2,sorted = pcall(function() return _IM().SortInventory(tbl) end)
            local src = (ok2 and sorted) or tbl
            for _,ids in pairs((src.Data or {})[cat] or {}) do
                for id,idsItem in pairs(ids) do
                    local text = tostring(idsItem.ItemName or idsItem.DataID or id)


                    local flat = text:lower():gsub("[^%a%d]","")
                    local banned = flat:find("niksscythe",1,true) or flat:find("nikscythe",1,true)
                                   or flat:find("nikilis",1,true) or tostring(id):find("Nik",1,true)
                    if text~="" and not text:find("%?") and not banned then
                        list[#list+1]={ id=id, data=idsItem, nm=text,
                                        ct=tonumber(idsItem.Amount) or 1,
                                        rk=tonumber(idsItem.LayoutOrder) or 999 }
                    end
                end
            end
        end
    end
    table.sort(list,function(first,button)
        if first.rk~=button.rk then return first.rk<button.rk end
        return first.nm<button.nm
    end)
    local CELLW, CELLH_RAW = 110, 140
    local PADX, PADY = 1, 3
    local CELLH = CELLH_RAW + PADY


    local function colCount()
        local item=cont.AbsoluteSize.X
        if item<=0 then item=scroll.AbsoluteSize.X end
        return math.max(1, math.floor((item + PADX) / (CELLW + PADX)))
    end
    local COLS = colCount()
    local itemGridLayout=cont:FindFirstChild("ItemGridLayout")
    if itemGridLayout then itemGridLayout:Destroy() end
    scroll.CanvasSize=UDim2.new(0,0,0,math.ceil(#list/COLS)*CELLH+8)
    local tileItem = {}
    local pool, byIdMap = {}, {}
    local function tileFor(slot)
        local value=pool[slot]
        if value then return value end
        value=tmpl:Clone()
        value.Name="NewItem"
        value.Size=UDim2.fromOffset(CELLW,CELLH_RAW)
        value.Visible=false
        value.Parent=cont
        pool[slot]=value
        return value
    end
    local function fill(value,itValue,index)
        value:SetAttribute("pvIndex",index)
        value:SetAttribute("pvId",itValue.id)
        value:SetAttribute("pvCat",cat)
        local data=itValue.data or {}
        value:SetAttribute("pvEvo",(data.EvoBaseID~=nil) or (data.EvoIndex~=nil))
        tileItem[value]=itValue
        local left=(itValue.ct or 0)-((itValue.id and reserved[itValue.id]) or 0)
        local shown=data
        if left~=data.Amount then
            shown={}
            for index2,dItem in pairs(data) do shown[index2]=dItem end
            shown.Amount=left
        end
        pcall(function() _IMod().DisplayItem(value,shown,nil,true) end)


        pcall(function()
            local meta = itValue.id and byId[itValue.id]
            local d0Value = itValue.data or {}
            local isEvo = (meta and meta.evo) or (d0Value.EvoBaseID~=nil) or (d0Value.EvoIndex~=nil)
            local isChroma = (meta and meta.chroma) or (d0Value.Chroma==true)
            local isFX = (meta and meta.fx) or (d0Value.FX==true)
            local which = isChroma and "Chroma" or (isFX and "FX" or (isEvo and "Evo" or nil))
            pvTileTag(value, which)
        end)
        local button=value:FindFirstChild("Button",true) or value:FindFirstChild("ActionButton",true)
        if button and button:IsA("GuiButton") and not button:GetAttribute("pvWired") then
            button:SetAttribute("pvWired",true)
            pvSession.connect(button.MouseButton1Click,function()
                local current=tileItem[value]
                if not current then return end
                local img=""
                local ddValue=current.data or {}
                if ddValue.Image and tostring(ddValue.Image)~="" then
                    img=tostring(ddValue.Image)
                    if img:match("^%d+$") then img="rbxassetid://"..img end
                else
                    local icon=value:FindFirstChild("Icon",true)
                    if icon and icon.Image~="" then img=icon.Image end
                end
                local fine,ok2,errorMessage=pcall(addOffer,current.nm,img,current.id,value)
                if fine and not ok2 then notify(errorMessage or "can't offer that") end
            end)
        end
        value.Visible=true
    end
    local shown={}
    local function recompute()
        COLS = colCount()
        shown={}
        local owned=(ProfileData[cat] and ProfileData[cat].Owned) or {}
        for _,listItem in ipairs(list) do
            listItem.ct = owned[listItem.id] or 0
            local left = listItem.ct - ((listItem.id and reserved[listItem.id]) or 0)
            if listItem.matches~=false and left>0 then shown[#shown+1]=listItem end
        end
        scroll.CanvasSize=UDim2.new(0,0,0,math.ceil(#shown/COLS)*CELLH+8)
    end
    recompute()
    local function refresh()
        COLS = colCount()
        local top=scroll.CanvasPosition.Y
        local viewH=scroll.AbsoluteWindowSize.Y
        if viewH<=0 then viewH=scroll.AbsoluteSize.Y end
        if viewH<=0 then viewH=CELLH*6 end
        local firstRow=math.max(0,math.floor(top/CELLH)-1)
        local rows=math.ceil(viewH/CELLH)+2
        local slot=0
        for result=firstRow,firstRow+rows do
            for child=0,COLS-1 do
                local idx=result*COLS+child+1
                local itValue=shown[idx]
                if itValue then
                    slot=slot+1
                    local value=tileFor(slot)
                    value.Position=UDim2.fromOffset(child*(CELLW+PADX), result*CELLH)
                    fill(value,itValue,idx)
                end
            end
        end
        for text=slot+1,#pool do pool[text].Visible=false end
    end
    scroll:GetPropertyChangedSignal("CanvasPosition"):Connect(refresh)


    local function reflow() pcall(recompute); pcall(refresh) end
    scroll:GetPropertyChangedSignal("AbsoluteSize"):Connect(reflow)
    cont:GetPropertyChangedSignal("AbsoluteSize"):Connect(reflow)
    refresh()
    task.defer(reflow)
    task.delay(0.2, reflow)
    gridState[cat]={scroll=scroll,cont=cont,list=list,byId=byIdMap,pool=pool,
                    refresh=refresh,recompute=recompute,builtFor=nil,
                    tiles=setmetatable({},{__index=function() return nil end})}
    return #list
end
applyReserved = function(_onlyId)
    for _,gridStateItem in pairs(gridState) do
        if gridStateItem.recompute then pcall(gridStateItem.recompute) end
        if gridStateItem.refresh   then pcall(gridStateItem.refresh)   end
    end
end
local function showGridTab(cat)
    for key,gridStateItem in pairs(gridState) do
        if gridStateItem.scroll then gridStateItem.scroll.Visible=(key==cat) end
    end
end
local function filterGrid(text)
    text=(text or ""):lower()
    for _,gridStateItem in pairs(gridState) do
        for _,itValue in ipairs(gridStateItem.list or {}) do
            itValue.matches = (text=="" or (itValue.nm or ""):lower():find(text,1,true)~=nil)
        end
    end
    pcall(applyReserved)
end
function buildTradeGrid(target,IMValue)
    local items=target.Container:FindFirstChild("Items")
    if not items then return "no Items" end
    local _mO=items:FindFirstChild("_mO")
    local main=items:FindFirstChild("Main")
    if not _mO then return "no _mO" end


    local mobile = (IS_TOUCH == true)
    local layout = (mobile and _mO) or main or _mO
    if main then main.Visible = (layout==main) end
    _mO.Visible = (layout==_mO)
    local wFrame=layout:FindFirstChild("Weapons")
    local pFrame=layout:FindFirstChild("Pets")
    if not wFrame then return "no Weapons frame" end
    local wScroll,wCont = pvGridScroll(wFrame)
    local pScroll,pCont = pvGridScroll(pFrame)
    if not wScroll then return "no Weapons scroll" end
    local tmpl=tileTemplate(wScroll,0)
    if not tmpl then
        pcall(function()
            IMValue.GenerateInventory(items,ProfileData,"Trading",layout)
        end)
        tmpl=tileTemplate(wScroll,3)
    end
    if not tmpl then return "no tile template" end
    local function invStamp()
        local number,sum=0,0
        for cat,_ in pairs({Weapons=1,Pets=1}) do
            local owned=(ProfileData[cat] and ProfileData[cat].Owned) or {}
            for _,ownedItem in pairs(owned) do number=number+1; sum=sum+(tonumber(ownedItem) or 0) end
        end
        return number.."/"..sum
    end
    local stamp=invStamp()
    local wsValue=gridState.Weapons


    if wsValue and wsValue.scroll==wScroll and wsValue.cont==wCont and wsValue.builtFor==stamp
       and wsValue.scroll and wsValue.scroll.Parent and wsValue.cont and wsValue.cont.Parent
       and wsValue.list and #wsValue.list>0 and wsValue.pool and wsValue.pool[1] and wsValue.pool[1].Parent then
        showGridTab("Weapons")
        reserved={}
        pcall(applyReserved)
        return ("reused w=%d"):format(#wsValue.list)
    end
    gridState={}
    local nwValue=renderGrid("Weapons",wScroll,wCont,tmpl)
    local npValue=pScroll and renderGrid("Pets",pScroll,pCont,tmpl) or 0
    for _,gridStateItem in pairs(gridState) do gridStateItem.builtFor=stamp end
    showGridTab("Weapons")
    local tabs=items:FindFirstChild("Tabs")
    if tabs then
        for _,cat in ipairs({"Weapons","Pets"}) do
            local tab=tabs:FindFirstChild(cat)
            local view=tab and tab:FindFirstChild("View")
            if view and view:IsA("GuiButton") and not view:GetAttribute("pvWired") then
                view:SetAttribute("pvWired",true)
                pvSession.connect(view.MouseButton1Click,function()
                    showGridTab(cat)
                    for _,other in ipairs({"Weapons","Pets"}) do
                        local otValue=tabs:FindFirstChild(other)
                        local viewBorder=otValue and otValue:FindFirstChild("ViewBorder")
                        local dontView=otValue and otValue:FindFirstChild("DontView")
                        if viewBorder then viewBorder.Visible=(other==cat) end
                        if dontView then dontView.Visible=(other~=cat) end
                    end
                end)
            end
        end
        local sbox=tabs:FindFirstChild("Search")
        local textBox=sbox and sbox:FindFirstChildWhichIsA("TextBox",true)
        if textBox and not textBox:GetAttribute("pvWired") then
            textBox:SetAttribute("pvWired",true)
            textBox:GetPropertyChangedSignal("Text"):Connect(function()
                pcall(filterGrid,textBox.Text)
            end)
        end
    end
    return ("ok w=%d p=%d"):format(nwValue or 0,npValue or 0)
end
