local function hookOfferSlots()
    if not spoofOpen then return end
    local child=offerCont(); if not child then return end
    for index=1,4 do
        local newItem=child:FindFirstChild("NewItem"..index)
        local actionButton=newItem and newItem:FindFirstChild("ActionButton",true)
        if actionButton then
            if getconnections then
                pcall(function() for _,ccValue in ipairs(getconnections(actionButton.MouseButton1Click)) do pcall(function() ccValue:Disconnect() end) end end)
            elseif actionButton:GetAttribute("pR") then actionButton=nil else actionButton:SetAttribute("pR",true) end
            if actionButton then pvSession.connect(actionButton.MouseButton1Click,function()
                if _G.pvOfferLocked then return end
                local oValue=offered[index]
                if not oValue then return end
                if oValue.id and reserved[oValue.id] then
                    local result=reserved[oValue.id]-1
                    reserved[oValue.id] = (result>0) and result or nil
                end
                local changed=oValue.id
                if (oValue.count or 1)>1 then
                    oValue.count=oValue.count-1
                else
                    _lastAdd[oValue.name]=nil
                    table.remove(offered,index)
                end
                pcall(enforceOffer);pcall(armCooldown);pcall(applyReserved,changed)
            end) end
        end
    end
end
