function pvRandomPartner()
    local pool={}
    for _,player in ipairs(Players:GetPlayers()) do
        if player~=playerGui and not (_G.pvBlocked and _G.pvBlocked[player.Name]) then pool[#pool+1]=player.Name end
    end
    if #pool==0 then for _,pvFriendName in ipairs(pvFriendNames) do pool[#pool+1]=pvFriendName end end
    if #pool==0 then for _,FAKE_NAMESItem in ipairs(FAKE_NAMES) do pool[#pool+1]=FAKE_NAMESItem end end
