function cleanupTradeSpoof()
    spoofTradeSerial = spoofTradeSerial + 1 -- cancel delayed callbacks from this trade
    spoofOpen = false;_G.pvSpoofActive=false
    spoofBusy = false
    _G.pvSpoofName = nil
    _G.pvOfferLocked=false
    pcall(clearOffer)
    if _G.pvRestoreMM2 then pcall(_G.pvRestoreMM2) end
    if tradeModules.mainBtnConnection then
        pcall(function() tradeModules.mainBtnConnection:Disconnect() end)
        tradeModules.mainBtnConnection = nil
    end
    if tradeModules.confBtnConnection then
        pcall(function() tradeModules.confBtnConnection:Disconnect() end)
        tradeModules.confBtnConnection = nil
    end
    if tradeModules.cancBtnConnection then
        pcall(function() tradeModules.cancBtnConnection:Disconnect() end)
        tradeModules.cancBtnConnection = nil
    end
    for _,key in ipairs({"mainBtnActivatedConnection", "confBtnActivatedConnection",
                         "cancBtnActivatedConnection"}) do
        if tradeModules[key] then
            pcall(function() tradeModules[key]:Disconnect() end)
            tradeModules[key] = nil
        end
    end
    pcall(function()
        local mine = playerGui2:FindFirstChild("pvTradeGUI")
        while mine do
            pcall(function() mine.Enabled = false end)
            pcall(function() mine:Destroy() end)
            mine = playerGui2:FindFirstChild("pvTradeGUI")
        end
    end)
    if tradeModules.TM then
        pcall(function()
            tradeModules.TM.ResetCooldown(true)
            if tradeModules.originalInventory then
                tradeModules.TM.TradeInventory = tradeModules.originalInventory
            end
        end)
    end
    tradeModules = {}
end
