        for _,part in ipairs(Players:GetPlayers()) do
            if part.Name:lower()==want or tostring(part.DisplayName):lower()==want then player=part break end
        end
    end
    if not player then notify(name.." left the server"); return end
    local success,msg = autoBlockPlayer(player)
    notify(pvBlockNotice(success,msg,player.Name))
end
