local function nextTradeName()
    local pool={}
    for _,part in ipairs(Players:GetPlayers()) do
        if part~=Players.LocalPlayer and not (_G.pvBlocked and _G.pvBlocked[part.Name]) then pool[#pool+1]=part.Name end
    end
    for _,pvNPCRosterItem in ipairs(_G.pvNPCRoster) do pool[#pool+1]=pvNPCRosterItem end
    for _,realName in ipairs(realNames) do pool[#pool+1]=realName end
    if #pool==0 then return "trader" end
    _G.pvTradeIdx=(_G.pvTradeIdx % #pool)+1
    return pool[_G.pvTradeIdx]
end

