local function addAutoItem(itValue)
    local swValue=(Sync and Sync.Weapons) or {}
    local item=byId[itValue.id]
    local entry=swValue[itValue.id]
    local name=(item and item.name) or (entry and (entry.ItemName or entry.Name))
    local img=(item and item.img) or (entry and entry.Image) or ""
    if not name then return nil end
    local isChroma=(item and item.chroma) or (entry and entry.Chroma) or false
    offered[#offered+1]={name=isChroma and ("Chroma "..name) or name,id=itValue.id,icon=img,count=1,
                         col=offerColour(nil,itValue.id)}
    pcall(enforceOffer)
    return #offered
end

local function invScroll()
    local target=tradeRoot(); if not target then return end


    local success,result=pcall(function() return target.Container.Items._mO.Weapons end)
    if success and result and result:IsA("ScrollingFrame") and result.Visible and result.Parent.Visible then return result end
    local ok2,sf2=pcall(function() return target.Container.Items.Main.Weapons.Items.Container.Current end)
    if ok2 and sf2 and sf2:IsA("ScrollingFrame") then return sf2 end
    if success and result and result:IsA("ScrollingFrame") then return result end
end

local function scrollSearch()
    local scrollingFrame=invScroll(); if not scrollingFrame then return end
    local maxY=math.max(0, scrollingFrame.AbsoluteCanvasSize.Y - scrollingFrame.AbsoluteWindowSize.Y)
    if maxY<=1 then return end
    local y=math.random(0,math.floor(maxY))
    pcall(function()
        Tween:Create(scrollingFrame,TweenInfo.new(0.8,Enum.EasingStyle.Quad,Enum.EasingDirection.InOut),
            {CanvasPosition=Vector2.new(0,y)}):Play()
    end)
end
keyActions.autoTrade = function()
    if _G.pvAutoTrade then notify("Auto-trade already running");return end
    _G.pvAutoTrade=true
    notify("Auto-trade ON -- cycling players")
    task.spawn(function()
        while _G.pvAutoTrade and gui.Parent and isCurrent() do
            local name=nextTradeName()
            notify("Auto-trade: "..name)
            pcall(function() startTradeSpoof(name, true, true) end)


            local number=math.clamp(tonumber(settings.autoTradeDelay) or 1.0, 0.25, 10)
            task.wait(1.0*number)
            offered={};reserved={}
            local added=0


            for _,AUTO_OFFERItem in ipairs(AUTO_OFFER) do
                if not _G.pvAutoTrade or not spoofOpen or added>=4 then break end
                pcall(scrollSearch)
                task.wait(0.6*number)
                local slot=addAutoItem(AUTO_OFFERItem)
                if slot then
                    added=added+1
                    for child=2,(AUTO_OFFERItem.count or 1) do
                        if not _G.pvAutoTrade or not spoofOpen then break end
                        task.wait(0.8*number)
                        if offered[slot] then offered[slot].count=child end
                        pcall(enforceOffer)
                    end
                end
            end


            while _G.pvAutoTrade and spoofOpen do
                task.wait(0.5)
                pcall(enforceOffer)
            end
            if _G.pvAutoTrade then task.wait(1.5*number) end
        end
        _G.pvAutoTrade=false
    end)
end
