        textButton.BackgroundColor3=BTN_BG;textButton.BackgroundTransparency=BTN_TR
        textButton.AutoButtonColor=false;textButton.Parent=chipRow
        corner(textButton,pxValue(6));stroke(textButton,0.85,1,Color3.fromRGB(140,140,150))
        chips[textButton]=val
        local function paint(cbValue,onValue)
            Tween:Create(cbValue,TweenInfo.new(0.14),{
                BackgroundColor3=onValue and PINK_ON or BTN_BG,
                BackgroundTransparency=onValue and 0 or BTN_TR,
            }):Play()
            cbValue.TextColor3=onValue and Color3.fromRGB(255,255,255) or TValue.sub
        end
        mcClick(textButton,function()
            filt=val
            for key,chip2 in pairs(chips) do paint(key,chip2==filt) end


            _G.pvItemFilterToken=(_G.pvItemFilterToken or 0)+1
            local myToken=_G.pvItemFilterToken
            task.defer(function()
                if _G.pvItemFilterToken==myToken then rebuild() end
            end)
        end)
        paint(textButton,val=="All")
        return textButton
    end
    chip("All","All",pxValue(28));chip("Knife","Knife",pxValue(34));chip("Gun","Gun",pxValue(30))
    chip("Chroma","Chroma",pxValue(38))


    do
        local textButton=Instance.new("TextButton")
        textButton.Size=UDim2.new(0,pxValue(52),1,0);textButton.Text="RND ALL";textButton.Font=Enum.Font.GothamBold;textButton.TextSize=pxValue(7)
        textButton.BackgroundColor3=Color3.fromRGB(122,74,206);textButton.BackgroundTransparency=0
        textButton.AutoButtonColor=false;textButton.TextColor3=Color3.new(1,1,1);textButton.Parent=chipRow
        corner(textButton,pxValue(6));stroke(textButton,0.7,1,Color3.fromRGB(168,128,236))
        mcClick(textButton,function()
            task.spawn(function()


            local slider = _G.pvSpawnCount or 1
            local hiValue = (slider > 1) and slider or 30


            local function rollAmount()
                local number=math.random()*100
                local first
                if     number < 26 then first = math.random(1,2)
                elseif number < 46 then first = math.random(3,5)
                elseif number < 63 then first = math.random(6,9)
                elseif number < 77 then first = math.random(10,14)
                elseif number < 88 then first = math.random(15,19)
                elseif number < 96 then first = math.random(20,25)
                else               first = math.random(26,30)
                end
                return math.clamp(first,1,hiValue)
            end
            local number=0
            local lastId, lastAmt
            for _,item in ipairs(items) do
                if item.kind=="Weapon" and not isDefault(item.id) and not item.noSpawnAll then
                    local playerData=ProfileData[item.cat]
                    if playerData and playerData.Owned then
                        local amt = item.evo and 1 or rollAmount()
                        playerData.Owned[item.id]=amt
                        if item.cat=="Weapons" then settings.loadout.owned[item.id]=amt end
                        savedSpawns[item.id]=true
                        lastId, lastAmt = item.id, amt
                        number=number+1
                    end
                end
                if number%250==0 then task.wait() end
            end


            pcall(function() pvBulkInvChanged("Weapons", lastId, lastAmt) end)
            pcall(saveCfg)
            notify("Randomly spawned "..number.." weapons")
            end)
        end)
    end


    local listArea=Instance.new("Frame")
    listArea.Size=UDim2.new(1,0,1,-pxValue(120));listArea.Position=UDim2.new(0,0,0,pxValue(84))

    listArea:SetAttribute("pvWeaponSurface","List")
    pvStyleWeaponSurface(listArea)
    listArea.Parent=pItems
    corner(listArea,pxValue(8))
    local grid=Instance.new("ScrollingFrame")
    -- Original compact weapon-list spacing. A minimal 1px inset prevents
    -- the half-pixel UIStroke from touching the scrolling viewport edges.
    grid.Size=UDim2.new(1,-pxValue(6),1,-pxValue(6));grid.Position=UDim2.new(0,pxValue(3),0,pxValue(3))
    grid.BackgroundTransparency=1;grid.BorderSizePixel=0
    grid.ScrollBarThickness=pxValue(3);grid.ScrollBarImageColor3=PINK_ON
    grid.VerticalScrollBarInset=Enum.ScrollBarInset.Always
    grid.CanvasSize=UDim2.new();grid.Parent=listArea
    local inset=Instance.new("UIPadding")
    inset.PaddingLeft=UDim.new(0,pxValue(1))
    inset.PaddingRight=UDim.new(0,pxValue(1))
    inset.PaddingTop=UDim.new(0,pxValue(1))
    inset.PaddingBottom=UDim.new(0,pxValue(1))
    inset.Parent=grid
    local uiListLayout2=Instance.new("UIListLayout")
    uiListLayout2.Padding=UDim.new(0,pxValue(4))
    uiListLayout2.SortOrder=Enum.SortOrder.LayoutOrder
    uiListLayout2.Parent=grid
    local function paintRow(button,onValue)
        button:SetAttribute("pvWeaponSurface","Row")
        button:SetAttribute("pvWeaponSelected",onValue==true)
        pvStyleWeaponSurface(button)
    end
    _G.pvItemRowsV63={}
    function rebuild()
        local text=string.lower(search.Text)
        local shown=0
        local cache=_G.pvItemRowsV63


        if cache and next(cache) then
            for _,entry in pairs(cache) do
                local item=entry.w
                local button=entry.b
                if button and button.Parent then
                    local pfValue
                    if filt=="All" then pfValue=true
                    elseif filt=="Chroma" then pfValue=(item.chroma or (item.name and item.name:lower():find("chroma")~=nil))
                    elseif filt=="Pet" then pfValue=(item.kind=="Pet")
                    else pfValue=(item.kind=="Weapon" and item.type==filt) end

                    if not item.disp then
                        local text2=tostring(item.type or "")
                        if text2=="Gun" and not item.name:lower():find("gun",1,true) then item.disp=item.name.." Gun"
                        else item.disp=item.name end
                    end
                    if not item.lname then
                        item.lname=string.lower(item.disp.." "..item.name.." "..tostring(item.type or ""))
                    end

                    local psValue=(text=="") or string.find(item.lname,text,1,true)
                    local visible=(pfValue and psValue) and true or false
                    button.Visible=visible
                    if visible then
                        shown=shown+1
                        button.LayoutOrder=shown
                    end
                end
            end

            grid.CanvasSize=UDim2.new(0,0,0,uiListLayout2.AbsoluteContentSize.Y+pxValue(8))
            pcall(function() pageTitle.Text=("Items   %d"):format(shown) end)
            return
        end


        for _,child in ipairs(grid:GetChildren()) do
            if child:IsA("TextButton") then child:Destroy() end
        end
        for _,item in ipairs(items) do
            local pfValue
            if filt=="All" then pfValue=true
            elseif filt=="Chroma" then pfValue=(item.chroma or (item.name and item.name:lower():find("chroma")~=nil))
            elseif filt=="Pet" then pfValue=(item.kind=="Pet")
            else pfValue=(item.kind=="Weapon" and item.type==filt) end


            if not item.disp then
                local text2=tostring(item.type or "")
                if text2=="Gun" and not item.name:lower():find("gun",1,true) then item.disp=item.name.." Gun"
                else item.disp=item.name end
            end
            if not item.lname then item.lname=string.lower(item.disp.." "..item.name.." "..tostring(item.type or "")) end
            local psValue=(text=="") or string.find(item.lname,text,1,true)
            if pfValue and psValue then
                shown=shown+1


                if shown<=1200 then
                    local id=item.id
                    local textButton=Instance.new("TextButton")
                    textButton.Size=UDim2.new(1,-pxValue(4),0,pxValue(26));textButton.LayoutOrder=shown
                    textButton.Text=""
                    textButton.AutoButtonColor=false
                    textButton.Parent=grid;corner(textButton,pxValue(5))
                    _G.pvItemRowsV63[id]={b=textButton,w=item}

                    local ico=Instance.new("ImageLabel")
                    ico.Size=UDim2.fromOffset(pxValue(22),pxValue(22))
                    ico.Position=UDim2.new(0,pxValue(3),0.5,-pxValue(11))
                    ico.BackgroundTransparency=1
                    ico.Image=tostring(item.img or "")
                    ico.ScaleType=Enum.ScaleType.Fit
                    ico.ZIndex=2;ico.Parent=textButton

                    local nml=Instance.new("TextLabel")
                    nml.Size=UDim2.new(1,-pxValue(104),1,0);nml.Position=UDim2.new(0,pxValue(29),0,0)
                    nml.BackgroundTransparency=1
                    nml.Font=Enum.Font.GothamBold;nml.TextSize=pxValue(11)
                    nml.TextColor3=TValue.txt;nml.TextXAlignment=Enum.TextXAlignment.Left
                    nml.TextTruncate=Enum.TextTruncate.AtEnd
                    nml.Text=(item.disp or item.name)..(item.kind=="Pet" and "   [pet]" or "")
                    nml.ZIndex=2;nml.Parent=textButton

                    local badge=Instance.new("Frame")
                    badge.Size=UDim2.new(0,pxValue(70),1,0);badge.Position=UDim2.new(1,-pxValue(72),0,0)
                    badge.BackgroundTransparency=1;badge.ZIndex=2;badge.Parent=textButton
                    local uiListLayout3=Instance.new("UIListLayout")
                    uiListLayout3.FillDirection=Enum.FillDirection.Horizontal
                    uiListLayout3.HorizontalAlignment=Enum.HorizontalAlignment.Right
                    uiListLayout3.VerticalAlignment=Enum.VerticalAlignment.Center
                    uiListLayout3.Padding=UDim.new(0,pxValue(2));uiListLayout3.Parent=badge


                    local function mkBadge(which)
                        local proto = pvRealTagsFrame(which)
                        local src = proto and proto:FindFirstChild(which)
                        if not src then return end
                        local tag = src:Clone()
                        tag.Name       = "pvTag"..which
                        tag.Visible    = true
                        tag.Size       = UDim2.fromOffset(pxValue(30),pxValue(12))
                        tag.Position   = UDim2.new(0,0,0,0)
                        tag.AnchorPoint= Vector2.new(0,0)
                        tag.ZIndex     = 3
                        local bg  = tag:FindFirstChild("BG")
                        local lbl = tag:FindFirstChild("TagName")
                        if bg then


                            tag.BackgroundTransparency = 1
                            bg.AnchorPoint=Vector2.new(0,0)
                            bg.Position=UDim2.new(0,0,0,0)
                            bg.Size=UDim2.new(1,0,1,0)
                            bg.ZIndex=3
                            bg.ScaleType=Enum.ScaleType.Stretch
                            bg.BackgroundTransparency=1
                            bg.ImageTransparency=0
                            if lbl then
                                lbl.AnchorPoint=Vector2.new(0,0)
                                lbl.Position=UDim2.new(0,0,0,0)
                                lbl.Size=UDim2.new(1,0,1,0)
                                lbl.ZIndex=4
                                lbl.TextScaled=true
                                lbl.BackgroundTransparency=1
                                local cons=lbl:FindFirstChildOfClass("UITextSizeConstraint")
                                            or Instance.new("UITextSizeConstraint")
                                cons.MinTextSize=5; cons.MaxTextSize=pxValue(10); cons.Parent=lbl
                                lbl.TextWrapped=false
                            end
                        else


                            local arc=tag:FindFirstChildOfClass("UIAspectRatioConstraint")
                            if arc then arc:Destroy() end
                            if lbl then
                                lbl.TextScaled=true
                                local cons=lbl:FindFirstChildOfClass("UITextSizeConstraint")
                                            or Instance.new("UITextSizeConstraint")
                                cons.MinTextSize=5; cons.MaxTextSize=pxValue(10); cons.Parent=lbl
                                lbl.TextWrapped=false
                            end
                        end
                        tag.Parent=badge
                    end

                    if item.chroma then mkBadge("Chroma") end
                    if item.fx     then mkBadge("FX")     end
                    if item.evo    then mkBadge("Evo")    end
                    paintRow(textButton, sel[id]==true)
                    pvSession.connect(textButton.MouseButton1Click,function()
                        if sel[id] then
                            sel[id]=nil
                            if selected==id then selected=next(sel) end
                        else
                            sel[id]=true;selected=id
                        end
                        paintRow(textButton, sel[id]==true)
                        local number=selCount()
                        pcall(function() pageTitle.Text=(number==0) and "Items" or (number==1) and ("Items   "..((byId[selected] or {}).name or "")) or ("Items   "..number.." selected") end)


                    end)
                end
            end
        end
        grid.CanvasSize=UDim2.new(0,0,0,uiListLayout2.AbsoluteContentSize.Y+pxValue(8))
        pcall(function() pageTitle.Text=("Items   %d"):format(shown) end)
    end
    local deb
    search:GetPropertyChangedSignal("Text"):Connect(function()
        if deb then task.cancel(deb) end
        deb=task.delay(0.15,rebuild)
    end)
    task.defer(rebuild)
    local act=Instance.new("Frame")
    act.Size=UDim2.new(1,0,0,pxValue(30));act.Position=UDim2.new(0,0,1,-pxValue(30))
    act.BackgroundTransparency=1;act.Parent=pItems
    local uiListLayout3=Instance.new("UIListLayout");uiListLayout3.FillDirection=Enum.FillDirection.Horizontal
    uiListLayout3.Padding=UDim.new(0,pxValue(4));uiListLayout3.SortOrder=Enum.SortOrder.LayoutOrder;uiListLayout3.Parent=act

    do
        local spawnOneBtn=btn(act,"Spawn",function()
        local ids=selIds()
        if #ids==0 then notify("Pick an item");return end
        local cnt=math.clamp(_G.pvSpawnCount or 1,1,999)
        local oneLastId, oneLastAmt
        local oneChanges={}
        for _,id in ipairs(ids) do
            local item=byId[id]
            if item then
                local playerData=ProfileData[item.cat]
                if playerData and playerData.Owned and not isDefault(id) then
                    playerData.Owned[id] = item.evo and 1 or math.clamp((playerData.Owned[id] or 0) + cnt, 1, 9999)
                    if item.cat=="Weapons" then settings.loadout.owned[id]=playerData.Owned[id] end
                    savedSpawns[id]=true
                    oneLastId, oneLastAmt = id, playerData.Owned[id]
                    oneChanges[#oneChanges+1]={cat=item.cat,id=id,n=playerData.Owned[id]}
                end
            end
        end
        local spawnedTab
        if oneLastId then


            pcall(function()
                pvSyncNormalInventoryItems(oneChanges,function(missing,fired,fallback)
                    if isCurrent() then
                        pcall(pvShowSpawnedWeapon,oneLastId,#ids==1)
                        if #ids==1 and fallback>0 then notify("MM2 cache fallback rendered "..tostring((byId[oneLastId] or {}).name or oneLastId)) end
                    end
                end)
            end)

            spawnedTab=select(2,pvWeaponTopTab(oneLastId))
        end
        pcall(saveCfg)
        local msg=(#ids==1 and ("Spawned "..(byId[ids[1]].name)) or ("Spawned "..#ids.." items")).."  (x"..cnt..")"
        if #ids==1 and spawnedTab then msg=msg.." -> "..spawnedTab end
        notify(msg)
    end)
        spawnOneBtn.Size=UDim2.new(0.33,-pxValue(4),1,0);spawnOneBtn.LayoutOrder=1
    end


    PV_NEVER_SPAWN = {"niksscythe","nikscythe","nikilis"}
    function pvIsUltraRare(name)
        local number=pvNorm(name or "")
        for _,pat in ipairs(PV_NEVER_SPAWN) do
            if number:find(pat,1,true) then return true end
        end
        return false
    end

    PV_OWN_CHANCE = {
        [1]=0.04,
        [2]=0.10,
        [3]=0.00,
        [4]=0.30,
        [5]=0.35,
        [6]=0.55,
        [7]=0.72,
        [8]=0.85,
        [9]=0.05,
    }
    do
        local realisticBtn=btn(act,"Realistic",function()
        local number,skipped,seenN=0,0,0
        local rLastId, rLastAmt
        for _,item in ipairs(items) do
            seenN=seenN+1
            if item.kind=="Weapon" and not isDefault(item.id) then
                local result=RANK[item.rarity] or 8
                if pvIsUltraRare(item.name) or result==3 then
                    skipped=skipped+1
                elseif math.random() <= (PV_OWN_CHANCE[result] or 0.5) then
                    local amt
                    if result<=3 then amt=1
                    elseif result<=5 then amt=math.random(1,3)
                    else amt=math.random(1,8) end
                    local playerData=ProfileData[item.cat]
                    if playerData and playerData.Owned then
                        playerData.Owned[item.id]=item.evo and 1 or ((playerData.Owned[item.id] or 0)+amt)
                        if item.cat=="Weapons" then settings.loadout.owned[item.id]=playerData.Owned[item.id] end
                        savedSpawns[item.id]=true
                        rLastId, rLastAmt = item.id, playerData.Owned[item.id]
                        number=number+1
                    end
                end
            end
            if seenN%250==0 then task.wait() end
        end
        pcall(function() pvBulkInvChanged("Weapons", rLastId, rLastAmt) end)
        pcall(saveCfg)
        notify("Realistic inventory: "..number.." weapons ("..skipped.." ultra-rares skipped)")
    end)
        realisticBtn.Size=UDim2.new(0.33,-pxValue(4),1,0);realisticBtn.LayoutOrder=2
    end

    do
        local spawnAllBtn=btn(act,"Spawn All",function()
        local number=0
        local aLastId, aLastAmt
        local bulkChanges={}
        local tabCounts={Current=0,Classic=0,Holiday=0}


        for itemIndex,item in ipairs(items) do
            local pfValue
            if     filt=="Chroma" then pfValue=(item.chroma or (item.name and item.name:lower():find("chroma")~=nil))
            elseif filt=="Knife" or filt=="Gun" then pfValue=(item.kind=="Weapon" and item.type==filt)
            else                       pfValue=(item.kind=="Weapon") end
            if pfValue and not isDefault(item.id) and not item.noSpawnAll then
                local playerData=ProfileData[item.cat]
                if playerData and playerData.Owned then


                    playerData.Owned[item.id] = item.evo and 1 or math.clamp((playerData.Owned[item.id] or 0) + (_G.pvSpawnCount or 1), 1, 9999)
                    if item.cat=="Weapons" then settings.loadout.owned[item.id]=playerData.Owned[item.id] end
                    savedSpawns[item.id] = true
                    aLastId, aLastAmt = item.id, playerData.Owned[item.id]
                    bulkChanges[#bulkChanges+1]={cat=item.cat,id=item.id,n=playerData.Owned[item.id]}
                    local top=pvWeaponTopTab(item.id)
                    tabCounts[top]=(tabCounts[top] or 0)+1
                    number=number+1
                end
            end
            if itemIndex % 40 == 0 then task.wait() end
        end


        pcall(function()


            pvSyncNormalInventoryItems(bulkChanges)
        end)
        pcall(saveCfg)


        notify("All weapons spawned successfully")
    end)
    spawnAllBtn.Size=UDim2.new(0.34,-pxValue(4),1,0);spawnAllBtn.LayoutOrder=3
    keyActions.spawnAll = function()
        for _,con in ipairs(getconnections(spawnAllBtn.MouseButton1Click)) do con:Fire() end
    end

        keyActions.spawnRandom = function()
            for _,con in ipairs(getconnections(spawnAllBtn.MouseButton1Click)) do con:Fire() end
        end
    end
end
do
    local text=scroll(pTrade)

    local pbox
    do
        -- Keep the picker in the trade layout so it cannot be clipped by
        -- the outer scrolling frame or cover the trade action buttons.
        local picker=Instance.new("Frame")
        picker.Name="PartnerPicker"
        picker.Size=UDim2.new(1,0,0,pxValue(28))
        picker.BackgroundTransparency=1
        picker.Parent=text
        pbox=box(picker,"partner name")
        pbox.Size=UDim2.new(1,-pxValue(32),0,pxValue(28))

        local arrow=Instance.new("TextButton")
        arrow.Name="PartnerDropdownButton"
        arrow.Size=UDim2.fromOffset(pxValue(28),pxValue(28))
        arrow.Position=UDim2.new(1,-pxValue(28),0,0)
        arrow.BackgroundColor3=BTN_BG
        arrow.BackgroundTransparency=BTN_TR
        arrow.TextColor3=TValue.txt
        arrow.Font=Enum.Font.GothamBold
        arrow.TextSize=pxValue(14)
        arrow.Text="v"
        arrow.Parent=picker
        corner(arrow,pxValue(8))
        stroke(arrow,0.82,1,TValue.line)

        local list=Instance.new("ScrollingFrame")
        list.Name="ServerPartners"
        list.Position=UDim2.fromOffset(0,pxValue(33))
        list.Size=UDim2.new(1,0,0,0)
        list.BackgroundColor3=BTN_BG
        list.BackgroundTransparency=BTN_TR
        list.BorderSizePixel=0
        list.ScrollBarThickness=pxValue(3)
        list.ScrollBarImageColor3=TValue.pink
        list.ScrollingDirection=Enum.ScrollingDirection.Y
        list.CanvasSize=UDim2.new()
        list.AutomaticCanvasSize=Enum.AutomaticSize.Y
        list.Visible=false
        list.Active=true
        list.Parent=picker
        corner(list,pxValue(8))
        local layout=Instance.new("UIListLayout")
        layout.SortOrder=Enum.SortOrder.LayoutOrder
        layout.Parent=list
        local opened=false
        local function close()
            opened=false
            list.Visible=false
            arrow.Text="v"
            picker.Size=UDim2.new(1,0,0,pxValue(28))
        end
        local function refresh(leaving)
            for _,child in ipairs(list:GetChildren()) do
                if child:IsA("GuiObject") then child:Destroy() end
            end
            local members={}
            for _,player in ipairs(Players:GetPlayers()) do
                if player~=leaving then members[#members+1]=player end
            end
            table.sort(members,function(first,button)
                local anValue,bnValue=first.DisplayName:lower(),button.DisplayName:lower()
                if anValue==bnValue then return first.Name:lower()<button.Name:lower() end
                return anValue<bnValue
            end)
            for index,player in ipairs(members) do
                local row=Instance.new("TextButton")
                row.Name="Player_"..player.UserId
                row.Size=UDim2.new(1,-pxValue(5),0,pxValue(34))
                row.LayoutOrder=index
                row.BackgroundTransparency=1
                row.Font=Enum.Font.GothamMedium
                row.TextSize=pxValue(10)
                row.TextColor3=TValue.txt
                row.TextXAlignment=Enum.TextXAlignment.Left
                row.TextTruncate=Enum.TextTruncate.AtEnd
                row.Text=player.DisplayName.." (@"..player.Name..")"
                row.Parent=list
                pad(row,pxValue(8))
                -- Destroying each row also disconnects its click handler.
                row.Activated:Connect(function()
                    if player.Parent~=Players then refresh(player);return end
                    pbox.Text=player.Name
                    pbox:ReleaseFocus()
                    close()
                end)
            end
            local height=pxValue(34)*math.min(#members,5)
            list.Size=UDim2.new(1,0,0,height)
            picker.Size=UDim2.new(1,0,0,opened and (pxValue(33)+height) or pxValue(28))
        end
        pvSession.connect(arrow.Activated,function()
            if opened then close();return end
            opened=true
            refresh()
            list.CanvasPosition=Vector2.new(0,0)
            list.Visible=true
            arrow.Text="^"
        end)
        pvSession.connect(Players.PlayerAdded,function()
            if opened then refresh() end
        end)
        pvSession.connect(Players.PlayerRemoving,function(player)
            if opened then refresh(player) end
        end)
        pvSession.connect(pbox.Focused,close)
        pvSession.connect(pTrade:GetPropertyChangedSignal("Visible"),function()
            if not pTrade.Visible then close() end
        end)
    end


    local function partnerName()
        if #pbox.Text>0 then return pbox.Text end
        return _G.pvLastPartner or pvRandomPartner()
    end

    -- Called only after the second (non-auto) visual spoof trade completes.
    pvSession.clearUpgradePartnerInput = function(completedName)
        if pbox and pbox.Parent then
            local matchesText = pvSession.sameTradePartner(pbox.Text, completedName)
            if matchesText or pvSession.sameTradePartner(pbox.PlaceholderText, completedName) then
                pbox.PlaceholderText = "partner name"
            end
            if matchesText then pbox.Text = "" end
        end
        -- The fallback recent-partner picker must not resurrect this same user.
        if pvSession.sameTradePartner(_G.pvLastPartner, completedName) then
            _G.pvLastPartner = nil
        end
    end

    local function spoofWithRequest(fallback)
        local typed = pbox and tostring(pbox.Text):match("^%s*(.-)%s*$") or ""
        local target = (typed~="" ) and typed or fallback
        if not target or target=="" then return end


        if typed=="" then pcall(function() pbox.PlaceholderText = target end) end
        local shown, why = false, nil
        if pvFakeTradeSent then
            shown, why = pvFakeTradeSent(target, function(who)
                local success,errorMessage=startTradeSpoof(who)
