            end
            pvSession.spawnUpgradePlayer(function(target)
                if not isCurrent() or target~=_G.pvVisualWeaponTarget then return end
                if spoofOpen or spoofBusy then notify("Close the current trade and try again");return end
                -- Keep an empty input empty so the next upgrade is random too.
                if pbox and pbox.Parent then pbox.PlaceholderText=target.Name end
                task.delay(5,function()
                    local function stillReady()
                        return isCurrent() and settings.fakeUpgradeSpawn
                            and target==_G.pvVisualWeaponTarget
                            and target.Character and target.Character.Parent
                    end
                    if not stillReady() then return end
                    if spoofOpen or spoofBusy then notify("Fake upgrade request skipped: another trade is open");return end
                    if type(pvFakeTradeRequest)~="function" then
                        notify("Fake upgrade request is unavailable");return
                    end
                    local shown,why=pvFakeTradeRequest(function()
                        if not stillReady() then return end
                        if spoofOpen or spoofBusy then notify("Close the current trade first");return end
                        if pbox and pbox.Parent then pbox.Text=target.Name end
                        local success,errorMessage=startTradeSpoof(target.Name,true,nil,target,preset)
                        notify(success and ("fake upgrade started with "..target.Name) or (errorMessage or "failed"))
                    end,target.Name)
                    if not shown then notify("Could not show fake upgrade request: "..tostring(why or "unavailable")) end
                end)
            end, tostring(pbox and pbox.Text or ""))
            return
        end
        -- Keep the original fake-request/Accept/upgrade flow unchanged.
