                notify(success and ("fake upgrade started with "..who) or (errorMessage or "failed"))
            end, typed)
        end

        if shown then
            -- Show the same username that pvFakeTradeRequest actually used.
            if pbox and pbox.Parent and selectedName then
                pbox.Text = tostring(selectedName)
            end
        else
            local who = partnerName()
            local success,errorMessage=startTradeSpoof(who,true,nil,nil,preset)
            if success then
                if pbox and pbox.Parent then pbox.Text = tostring(who) end
            end
            notify(success and "fake upgrade started" or (errorMessage or "failed"))
        end
    end)
