        local chooseWeapons=Instance.new("TextButton")
        chooseWeapons.Name="ChooseAllowedWeapons"
        chooseWeapons.Position=UDim2.fromOffset(0,0)
        chooseWeapons.Size=UDim2.new(0.54,-pxValue(4),1,0)
        chooseWeapons.BackgroundColor3=TValue.black
        chooseWeapons.BackgroundTransparency=0.08
        chooseWeapons.BorderSizePixel=0
        chooseWeapons.Font=Enum.Font.GothamBold
        chooseWeapons.TextSize=pxValue(8)
        chooseWeapons.TextColor3=TValue.txt
        chooseWeapons.Parent=filterToolbar
