                and "Inventory auto-block ON (verified inventories only)"
                or "Inventory auto-block OFF")
        end)

        -- The top Trade tab returns to the Trade controls; no back widget.

        local search=box(panel,"Search display name or @username...")
        search.Name="BlockPlayerSearch"
        search.Position=UDim2.fromOffset(pxValue(5),pxValue(44))
        search.Size=UDim2.new(1,-pxValue(10),0,pxValue(30))
        search.ClearTextOnFocus=false

        local status=Instance.new("TextLabel")
        status.Name="PlayerCount"
        status.Size=UDim2.new(1,-pxValue(12),0,pxValue(18))
        status.Position=UDim2.fromOffset(pxValue(7),pxValue(80))
        status.BackgroundTransparency=1
        status.Text="AVAILABLE PLAYERS"
        status.Font=Enum.Font.GothamBold
        status.TextSize=pxValue(9)
        status.TextColor3=TValue.sub
        status.TextXAlignment=Enum.TextXAlignment.Left
        status.Parent=panel

        local roster=Instance.new("ScrollingFrame")
        roster.Name="BlockPlayerRoster"
        roster.Position=UDim2.fromOffset(pxValue(4),pxValue(101))
        roster.Size=UDim2.new(1,-pxValue(8),1,-pxValue(106))
        roster.BackgroundTransparency=1
        roster.BorderSizePixel=0
        roster.Active=true
        roster.ScrollingDirection=Enum.ScrollingDirection.Y
        roster.ScrollBarThickness=pxValue(3)
        roster.ScrollBarImageColor3=TValue.pink
        roster.CanvasSize=UDim2.new()
        roster.AutomaticCanvasSize=Enum.AutomaticSize.Y
        roster.Parent=panel

        local rosterPadding=Instance.new("UIPadding")
        rosterPadding.PaddingLeft=UDim.new(0,pxValue(2))
        rosterPadding.PaddingRight=UDim.new(0,pxValue(5))
        rosterPadding.PaddingTop=UDim.new(0,pxValue(2))
        rosterPadding.PaddingBottom=UDim.new(0,pxValue(8))
        rosterPadding.Parent=roster

        local layout=Instance.new("UIListLayout")
        layout.SortOrder=Enum.SortOrder.LayoutOrder
        layout.Padding=UDim.new(0,pxValue(6))
        layout.Parent=roster

        local pendingUserId=nil
        local sendingTradeUserId=nil
        local tradeRequestSerial=0
        local lastTradeRequestAt=-math.huge
        local refresh

        -- Real per-player inventory only. A failed/missing remote is shown as
        -- unavailable: never infer another player's weapons from their avatar.
        -- The USD ranking uses the SAME PV_VALUES / PV_VALUES_CHROMA tables as
        -- the live-pulls logger later in this file.
        local weaponSnapshots={}
        -- Retain the last confirmed inventory only for this running session.
        -- A new Player object on rejoin must always fetch fresh server data.
        local lastKnownWeapons={}
        local lastKnownTotals={}
        local SNAPSHOT_SECONDS=180
        local FAILURE_RETRY_SECONDS=10
        -- First attempt starts immediately in a background task. When a player
        -- is still joining, retry on a short, bounded schedule without UI polling.
        -- Avoid repeated huge RemoteFunction replies during a player's join.
        -- Give MM2 time to replicate rather than rapid-fire seven retries.
        local INVENTORY_RETRY_DELAYS={0,2.5,5.0,8.0}
        -- Limit concurrent server calls so large lobbies do not send a burst.
        local INVENTORY_MAX_PARALLEL=1 -- isolate server responses; avoid join bursts
        local inventoryActive=0
        local inventoryNextRequestAt=0
        -- A single full-inventory reply may cause a Roblox-side decode spike.
        -- Space *all* initial and verification replies apart even if the
        -- request itself returns instantly.
        local INVENTORY_RESPONSE_GAP=2.25
        local lastPlayerJoinAt=-math.huge
        local inventoryRefreshQueued=false
        local function queueInventoryRefresh()
            if inventoryRefreshQueued or not panel.Visible or not pTrade.Visible then return end
            inventoryRefreshQueued=true
            -- Join scans and value changes are coalesced into one UI refresh.
            -- Longer delay while auto-block is active avoids a card redraw
            -- competing with an inventory response and a native block prompt.
            local delaySeconds=settings.inventoryAutoBlockEnabled and 0.85 or 0.35
            task.delay(delaySeconds,function()
                if not isCurrent() then inventoryRefreshQueued=false; return end
                while _G.pvBlockInProgress do
                    if not isCurrent() then inventoryRefreshQueued=false; return end
                    task.wait(0.20)
                end
                inventoryRefreshQueued=false
                if panel.Visible and pTrade.Visible and refresh then refresh() end
            end)
        end
        local function canLoad(player,snapshot)
            return isCurrent() and player.Parent==Players
                and weaponSnapshots[player.UserId]==snapshot
                and snapshot.state=="loading"
        end
        -- Share one server-request gate between initial inventory reads AND
        -- second-pass auto-block verification. They previously used different
        -- counters and could both receive huge payloads in one frame.
        local function invokeInventoryThrottled(player,stillValid)
            while inventoryActive>=INVENTORY_MAX_PARALLEL
                or os.clock()<inventoryNextRequestAt
                or _G.pvBlockInProgress do
                if not stillValid() then return false,nil end
                task.wait(0.12)
            end
            if not stillValid() then return false,nil end
            local remote=replicatedStorageService:FindFirstChild("Remotes")
            remote=remote and remote:FindFirstChild("Extras")
            remote=remote and remote:FindFirstChild("GetFullInventory")
            if not (remote and remote:IsA("RemoteFunction")) then return false,nil end
            inventoryActive+=1
            -- Stagger the start of expensive requests; don't hold the UI thread.
            inventoryNextRequestAt=os.clock()+INVENTORY_RESPONSE_GAP
            local success,data=pcall(function() return remote:InvokeServer(player.Name) end)
            -- The critical separation is *after* decoding the previous
            -- response, not just between the InvokeServer start times.
            inventoryNextRequestAt=math.max(inventoryNextRequestAt,os.clock()+INVENTORY_RESPONSE_GAP)
            inventoryActive=math.max(0,inventoryActive-1)
            return success,data
        end
        local function requestInventory(player,snapshot)
            return invokeInventoryThrottled(player,function()
                return canLoad(player,snapshot)
            end)
        end

        local function bestWeaponsFromInventory(data)
            local weaponsData=type(data)=="table" and data.Weapons
            local owned=type(weaponsData)=="table" and weaponsData.Owned
            if type(owned)~="table" then return nil end
            local top={}
            local ownedIds={}
            local totalUSD=0
            local catalog=Sync and Sync.Weapons
            local standard=type(PV_VALUES)=="table" and PV_VALUES or {}
            local chromas=type(PV_VALUES_CHROMA)=="table" and PV_VALUES_CHROMA or {}
            local processed=0
            for id,qty in pairs(owned) do
                processed+=1
                -- Inventory parsing runs in its own task. Yield every small batch
                -- so large joining inventories cannot stall rendering/UI input.
                if processed%8==0 then task.wait() end
                local amount=tonumber(qty)
                if type(qty)=="table" then amount=tonumber(qty.Amount or qty.Count) end
                if amount and amount>0 then
                    ownedIds[tostring(id)]=true
                    local info=catalog and (catalog[id] or catalog[tostring(id)])
                    if type(info)=="table" then
                        local shown=tostring(info.ItemName or id)
                        local base=shown:gsub("^[Cc]hroma%s+","")
                        local chroma=info.Chroma==true or shown~=base
                        local worth=(chroma and chromas[base]) or standard[base]
                        if type(worth)=="number" and worth>0 then
                            local ownedCount=math.floor(amount)
                            totalUSD+=worth*ownedCount
                            -- Keep just three best entries, avoiding a full sort
                            -- and hundreds of extra tables for large inventories.
                            local position=#top+1
                            for index=1,#top do
                                local candidate=top[index]
                                if worth>candidate.value or
                                    (worth==candidate.value and shown<candidate.name) then
                                    position=index
                                    break
                                end
                            end
                            if position<=3 then
                                table.insert(top,position,{
                                    id=tostring(id),name=shown,chroma=chroma,
                                    value=worth,amount=ownedCount,image=info.Image
                                })
                                if #top>3 then table.remove(top,4) end
                            end
                        end
                    end
                end
            end
            return top,math.floor(totalUSD*100+0.5)/100,ownedIds
        end

        local function loadPlayerWeapons(player)
            local id=player.UserId
            local old=weaponSnapshots[id]
            if old and old.player==player then
                local cooldown=old.state=="ready" and SNAPSHOT_SECONDS or FAILURE_RETRY_SECONDS
                if old.state=="loading" or os.clock()-old.at<cooldown then
                    return old
                end
            end

            -- A rejoin creates a different Player instance even for the same UserId.
            -- Use previous confirmed items only as a labelled last-seen preview.
            local snapshot={
                player=player, state="loading", at=os.clock(),
                items=lastKnownWeapons[id],
                totalUSD=lastKnownTotals[id]
            }
            weaponSnapshots[id]=snapshot
            task.spawn(function()
                for attempt,delaySeconds in ipairs(INVENTORY_RETRY_DELAYS) do
                    if delaySeconds>0 then task.wait(delaySeconds) end
                    if not canLoad(player,snapshot) then return end

                    local success,data=requestInventory(player,snapshot)
                    if not canLoad(player,snapshot) then return end

                    -- Built-in USD tables initialize later during startup.
                    if success and type(data)=="table" then
                        local deadline=os.clock()+15
                        while canLoad(player,snapshot)
                            and not (type(PV_VALUES)=="table" and type(PV_VALUES_CHROMA)=="table")
                            and os.clock()<deadline do
                            task.wait(0.10)
                        end
                    end
                    if not canLoad(player,snapshot) then return end
                    local ranked,totalUSD,ownedIds
                    if success and type(PV_VALUES)=="table"
                        and type(PV_VALUES_CHROMA)=="table" then
                        ranked,totalUSD,ownedIds=bestWeaponsFromInventory(data)
                    end
                    -- Inventory ranking is time-sliced, so re-check the player
                    -- and snapshot after it yields before publishing results.
                    if not canLoad(player,snapshot) then return end
                    if ranked then
                        -- Some sessions briefly return an empty inventory while
                        -- the player is loading. Verify again before caching it.
                        local owned=type(data.Weapons)=="table" and data.Weapons.Owned
                        local populated=type(owned)=="table" and next(owned)~=nil
                        if populated or attempt==#INVENTORY_RETRY_DELAYS then
                            snapshot.items=ranked
                            snapshot.totalUSD=totalUSD
                            snapshot.ownedIds=ownedIds
                            -- Empty/partially replicated inventories aren't safe to
                            -- use as evidence that a player lacks a weapon.
                            snapshot.freshOwned=populated==true
                            snapshot.state="ready"
                            snapshot.at=os.clock()
                            lastKnownWeapons[id]=ranked
                            lastKnownTotals[id]=totalUSD
                            queueInventoryRefresh()
                            if snapshot.freshOwned and onInventoryReady then
                                onInventoryReady(player,snapshot)
                            end
                            return
                        end
                    end
                end
                if not isCurrent() or weaponSnapshots[id]~=snapshot
                    or player.Parent~=Players then return end
                snapshot.state="unavailable"
                snapshot.at=os.clock()
                -- Preserve last-confirmed items; do not replace them with nil.
                queueInventoryRefresh()
            end)
            -- An unresponsive InvokeServer must not leave an endless spinner.
            task.delay(30,function()
                if not isCurrent() or weaponSnapshots[id]~=snapshot
                    or player.Parent~=Players then return end
                if snapshot.state=="loading" then
                    snapshot.state="unavailable"
                    snapshot.at=os.clock()
                    queueInventoryRefresh()
                end
            end)
            return snapshot
        end

        -- Pre-fetch all current players without showing or building any cards.
        -- Returned results are cached by UserId, including the last valid data
        -- when a player leaves and later rejoins.
        task.defer(function()
            for _,other in ipairs(Players:GetPlayers()) do
                if other~=playerGui and isCurrent() then
                    loadPlayerWeapons(other)
                    task.wait(0.24)
                end
            end
        end)

        local function addWeaponModel(preview,item)
            local function install(entry)
                if not isCurrent() or not preview.Parent or not entry or not entry.template then return end
                local cardPreview=preview:GetAttribute("pvCardWeaponPreview")==true
                local helperPreview=preview:GetAttribute("pvHelperWeaponPreview")==true
                -- Helper models are opt-in: avoid unexpected asset loads, and
                -- reject callbacks that return after 3D was switched off.
                if helperPreview then
                    if preview:GetAttribute("pvAllowHelper3D")~=true then return end
                    local success,descendants=pcall(function() return entry.template:GetDescendants() end)
                    if not success or #descendants>48 or preview:FindFirstChild("Weapon3D") then return end
                end
                -- Auto-block on: headshots, weapon icons and USD values remain;
                -- defer 3D cloning to avoid joining-inventory frame spikes.
                if cardPreview and (settings.inventoryAutoBlockEnabled
                    or not panel.Visible or preview:GetAttribute("pvAllowCard3D")~=true) then return end
                local selector=preview:FindFirstAncestor("InventoryWeaponPicker")
                if selector then
                    -- Picker 3D previews are strictly opt-in per visible tile.
                    -- A scroll or page change disables this flag immediately,
                    -- even for asynchronous callbacks from old model requests.
                    if not selector.Visible or preview:GetAttribute("pvAllowPicker3D")~=true then return end
                    local safe,descendants=pcall(function() return entry.template:GetDescendants() end)
                    if not safe or #descendants>65 then return end
                    if preview:FindFirstChild("Weapon3D") then return end
                elseif cardPreview then
                    local safe,descendants=pcall(function() return entry.template:GetDescendants() end)
                    if not safe or #descendants>55 or preview:FindFirstChild("Weapon3D") then return end
                end
                pcall(function()
                    local viewportFrame=Instance.new("ViewportFrame")
                    viewportFrame.Name="Weapon3D"
                    viewportFrame.Size=UDim2.fromScale(1,1)
                    viewportFrame.BackgroundTransparency=1
                    viewportFrame.BorderSizePixel=0
                    viewportFrame.Active=false -- touch/click should reach the weapon tile
                    viewportFrame.Ambient=Color3.fromRGB(205,196,210)
                    viewportFrame.LightColor=Color3.fromRGB(255,244,231)
                    viewportFrame.LightDirection=Vector3.new(-1,-1,-2)
                    viewportFrame.Parent=preview
                    local world=Instance.new("WorldModel")
                    world.Parent=viewportFrame
                    local model=Instance.new("Model")
                    model.Name="WeaponPreview"
                    model.Parent=world
                    local weapon=entry.template:Clone()
                    weapon.Parent=model
                    if (selector and preview:GetAttribute("pvAllowPicker3D")~=true)
                        or (cardPreview and (not panel.Visible
                            or preview:GetAttribute("pvAllowCard3D")~=true))
                        or (helperPreview and preview:GetAttribute("pvAllowHelper3D")~=true) then
                        viewportFrame:Destroy()
                        return
                    end
                    local parts=0
                    for _,desc in ipairs(weapon:GetDescendants()) do
                        if desc:IsA("BasePart") then
                            desc.Anchored=true
                            desc.CanCollide=false
                            parts+=1
                        elseif desc:IsA("Script") or desc:IsA("LocalScript") then
                            desc:Destroy()
                        end
                    end
                    if parts==0 then viewportFrame:Destroy();return end
                    local bounds,dim=model:GetBoundingBox()
                    model:PivotTo(CFrame.new(-bounds.Position)*model:GetPivot())
                    local radius=math.max(dim.X,dim.Y,dim.Z,0.5)
                    local camera=Instance.new("Camera")
                    camera.FieldOfView=40
                    camera.CFrame=CFrame.lookAt(Vector3.new(radius*1.5,radius*0.85,radius*2.15),Vector3.zero)
                    camera.Parent=viewportFrame
                    viewportFrame.CurrentCamera=camera
                    if (selector and preview:GetAttribute("pvAllowPicker3D")~=true)
                        or (cardPreview and (not panel.Visible
                            or preview:GetAttribute("pvAllowCard3D")~=true))
                        or (helperPreview and preview:GetAttribute("pvAllowHelper3D")~=true) then
                        viewportFrame:Destroy()
                        return
                    end
                    local image=preview:FindFirstChild("WeaponIcon")
                    if image then image.Visible=false end
                end)
            end
            local cached=_G.pvHeldAssetCache
            if type(cached)=="table" and type(cached[item.id])=="table" then
                install(cached[item.id]);return
            end
            if type(pvLoadExactHeldGun)=="function" then
                pcall(pvLoadExactHeldGun,item.id,function(success,entry)
                    if success then install(entry) end
                end)
                -- Another screen may already be loading this asset; its
                -- original loader allows only one callback per weapon ID.
                task.spawn(function()
                    -- No per-frame scan: at most eight 1-second checks, and
                    -- stop as soon as the preview is gone or the model appears.
                    for _=1,8 do
                        task.wait(1)
                        if not isCurrent() or not preview.Parent
                            or (helperPreview and preview:GetAttribute("pvAllowHelper3D")~=true)
                            or preview:FindFirstChild("Weapon3D") then return end
                        local asset=_G.pvHeldAssetCache
                        if type(asset)=="table" and type(asset[item.id])=="table" then
                            install(asset[item.id]);return
                        end
                        if type(asset)=="table" and asset[item.id]==false then return end
                    end
                end)
            end
        end

        -- The upgrade helper uses this same renderer for its 46x38 previews.
        -- It lives outside the Player Panel, so it skips the roster/picker limits.
        pvSession.renderWeapon3D = addWeaponModel

        -- Lightweight player-card previews: the icon appears immediately.
        -- Only two *visible* 3D models may exist at once. Build after joins and
        -- scrolling settle; discard invisible models to avoid GPU spikes.
        local cardPreviewJobs=setmetatable({}, {__mode="k"})
        local activeCardPreviews=setmetatable({}, {__mode="k"})
        local cardPreviewWorkerRunning=false
        local lastCardScrollAt=-math.huge
        local MAX_VISIBLE_CARD_MODELS=2
        local function cardPreviewVisible(preview)
            if not preview.Parent or not preview:IsDescendantOf(roster) then return false end
            local y=preview.AbsolutePosition.Y
            local handle=preview.AbsoluteSize.Y
            local top=roster.AbsolutePosition.Y
            local bottom=top+roster.AbsoluteSize.Y
            return y+handle>top+pxValue(6) and y<bottom-pxValue(6)
        end
        local function ensureCardPreviewWorker()
            -- 3D is disabled only while the auto-block scanner is enabled;
            -- lightweight weapon images still render without delay.
            if settings.inventoryAutoBlockEnabled then return end
            if cardPreviewWorkerRunning then return end
            cardPreviewWorkerRunning=true
            task.spawn(function()
                task.wait(1.4)
                while isCurrent() do
                    if settings.inventoryAutoBlockEnabled then break end
                    local active=0
                    for preview,item in pairs(activeCardPreviews) do
                        if not preview.Parent or not panel.Visible or not pTrade.Visible
                            or not cardPreviewVisible(preview) then
                            if preview.Parent then
                                preview:SetAttribute("pvAllowCard3D",false)
                                local viewport=preview:FindFirstChild("Weapon3D")
                                if viewport then viewport:Destroy() end
                                local icon=preview:FindFirstChild("WeaponIcon")
                                if icon then icon.Visible=true end
                                cardPreviewJobs[preview]=item
                            end
                            activeCardPreviews[preview]=nil
                        else
                            active+=1
                        end
                    end
                    local pending=false
                    for preview in pairs(cardPreviewJobs) do
                        if not preview.Parent then
                            cardPreviewJobs[preview]=nil
                        else
                            pending=true
                        end
                    end
                    if not panel.Visible or not pTrade.Visible then
                        -- No UI work while viewing Settings/Items. Pending icons
                        -- are upgraded only after the Player Panel is reopened.
                        break
                    end
                    if not pending and active==0 then break end
                    local allowed=panel.Visible and pTrade.Visible
                        and not _G.pvBlockInProgress
                        and os.clock()-lastPlayerJoinAt>=8.0
                        and os.clock()-lastCardScrollAt>=0.8
                    if allowed and active<MAX_VISIBLE_CARD_MODELS then
                        local chosen,chosenItem
                        for preview,item in pairs(cardPreviewJobs) do
                            if cardPreviewVisible(preview) then
                                chosen,chosenItem=preview,item
                                break
                            end
                        end
                        if chosen then
                            cardPreviewJobs[chosen]=nil
                            chosen:SetAttribute("pvAllowCard3D",true)
                            activeCardPreviews[chosen]=chosenItem
                            addWeaponModel(chosen,chosenItem)
                            -- Do not clone several meshes in the same frame.
                            task.wait(1.15)
                        else
                            task.wait(0.65)
                        end
                    else
                        task.wait(0.65)
                    end
                end
                cardPreviewWorkerRunning=false
            end)
        end
        local function scheduleWeaponModel(preview,item)
            preview:SetAttribute("pvCardWeaponPreview",true)
            cardPreviewJobs[preview]=item
            ensureCardPreviewWorker()
        end
        -- When auto-block turns on, release the few existing viewport models.
        -- Turning it off resumes the deferred 3D previews automatically.
        pvSession.connect(filterToggle.Activated,function()
            task.defer(function()
                if not isCurrent() then return end
                if settings.inventoryAutoBlockEnabled then
                    for preview,item in pairs(activeCardPreviews) do
                        if preview.Parent then
                            preview:SetAttribute("pvAllowCard3D",false)
                            local viewport=preview:FindFirstChild("Weapon3D")
                            if viewport then viewport:Destroy() end
                            local icon=preview:FindFirstChild("WeaponIcon")
                            if icon then icon.Visible=true end
                            cardPreviewJobs[preview]=item
                        end
                        activeCardPreviews[preview]=nil
                    end
                else
                    ensureCardPreviewWorker()
                end
            end)
        end)
        pvSession.connect(roster:GetPropertyChangedSignal("CanvasPosition"),function()
            lastCardScrollAt=os.clock()
        end)
        pvSession.connect(panel:GetPropertyChangedSignal("Visible"),function()
            if panel.Visible and pTrade.Visible and next(cardPreviewJobs)~=nil then
                ensureCardPreviewWorker()
            end
        end)
        pvSession.connect(pTrade:GetPropertyChangedSignal("Visible"),function()
            if pTrade.Visible and panel.Visible then
                queueInventoryRefresh()
                if next(cardPreviewJobs)~=nil then ensureCardPreviewWorker() end
            end
        end)


        -- Player cards share the same tinted glass as the parent theme.
        -- Avoid the old near-black tile backgrounds, especially on Halloween
        -- and photo-based Custom UI. A small accent tint preserves contrast
        -- without making a solid rectangular plate inside the window.
        local function playerCardGlass()
            local theme=settings.uiTheme
            local halloween=theme=="Halloween"
            local custom=theme=="Custom"
            local tint=TValue.pane:Lerp(TValue.pinkDim,halloween and 0.10 or 0.08)
            return tint,halloween,custom
        end

        local function styleBlockPanelWeaponTile(tile)
            if not (tile and tile.Parent) then return end
            local tint,halloween,custom=playerCardGlass()
            -- Halloween weapon tiles use the same soft purple-charcoal
            -- surface as WEAPONS and AUTO: OFF (rather than darkening black).
            tile.BackgroundColor3=halloween and TValue.black or tint
            tile.BackgroundTransparency=halloween and 0.08 or (custom and 0.52 or 0.26)
            local tileStroke=tile:FindFirstChild("pvBlockPanelTileStroke")
            if not (tileStroke and tileStroke:IsA("UIStroke")) then
                tileStroke=stroke(tile,0.45,1,TValue.line)
                tileStroke.Name="pvBlockPanelTileStroke"
            end
            tileStroke.Color=TValue.line
            tileStroke.Transparency=custom and 0.55 or (halloween and 0.43 or 0.38)
            tileStroke.Thickness=1
        end

        local function styleBlockPanelCard(row)
            if not (row and row.Parent) then return end
            local tint,halloween,custom=playerCardGlass()
            -- Same Halloween background and opacity as the WEAPONS and
            -- AUTO: OFF toolbar buttons. Keep the orange outline for contrast.
            row.BackgroundColor3=halloween and TValue.black or tint
            row.BackgroundTransparency=halloween and 0.08 or (custom and 0.48 or 0.25)

            local cardStroke=row:FindFirstChild("pvBlockCardStroke")
            if not (cardStroke and cardStroke:IsA("UIStroke")) then
                cardStroke=stroke(row,0.35,1,TValue.pink)
                cardStroke.Name="pvBlockCardStroke"
            end
            cardStroke.Color=TValue.pink
            cardStroke.Transparency=custom and 0.46 or (halloween and 0.32 or 0.32)
            cardStroke.Thickness=1

            -- The old gradient ended at T.black, making a large black box.
            -- Keep a very faint tint-only gradient instead, so the window's
            -- Halloween/Custom background can show through the card.
            local depth=row:FindFirstChild("pvBlockCardDepth")
            if not (depth and depth:IsA("UIGradient")) then
                depth=Instance.new("UIGradient")
                depth.Name="pvBlockCardDepth"
                depth.Rotation=90
                depth.Parent=row
            end
            depth.Color=ColorSequence.new({
                ColorSequenceKeypoint.new(0,tint:Lerp(TValue.pink,0.035)),
                ColorSequenceKeypoint.new(1,tint:Lerp(TValue.pane,0.12)),
            })
            depth.Transparency=NumberSequence.new({
                NumberSequenceKeypoint.new(0,0.02),
                NumberSequenceKeypoint.new(1,0.10),
            })
            -- Even a faint depth gradient makes Halloween cards look nearly
            -- solid black. The matching toolbar buttons have no gradient.
            depth.Enabled=not halloween

            local avatar=row:FindFirstChild("Avatar")
            if avatar then
                local avatarStroke=avatar:FindFirstChild("pvAvatarStroke")
                if not (avatarStroke and avatarStroke:IsA("UIStroke")) then
                    avatarStroke=stroke(avatar,0.22,1,TValue.pinkDim)
                    avatarStroke.Name="pvAvatarStroke"
                end
                avatarStroke.Color=TValue.pinkDim
                avatarStroke.Transparency=0.18
                avatarStroke.Thickness=1
            end

            local tradeButton=row:FindFirstChild("TradeUser")
            if tradeButton and tradeButton:IsA("TextButton") then
                tradeButton.BackgroundColor3=TValue.pane
                tradeButton.BackgroundTransparency=custom and 0.40 or (halloween and 0.30 or 0.24)
                tradeButton.TextColor3=TValue.txt
                local tradeStroke=tradeButton:FindFirstChild("pvTradeStroke")
                if not (tradeStroke and tradeStroke:IsA("UIStroke")) then
                    tradeStroke=stroke(tradeButton,0.35,1,TValue.line)
                    tradeStroke.Name="pvTradeStroke"
                end
                tradeStroke.Color=TValue.line
                tradeStroke.Transparency=0.30
                tradeStroke.Thickness=1
            end

            local blockButton=row:FindFirstChild("BlockUser")
            if blockButton and blockButton:IsA("TextButton") then
                local blocked=string.upper(tostring(blockButton.Text))=="BLOCKED"
                if blocked then
                    blockButton.BackgroundColor3=TValue.black
                    blockButton.BackgroundTransparency=0.20
                    blockButton.TextColor3=TValue.sub
                else
                    blockButton.BackgroundColor3=TValue.pinkDim
                    blockButton.BackgroundTransparency=0
                    blockButton.TextColor3=TValue.txt
                end
                local blockStroke=blockButton:FindFirstChild("pvBlockStroke")
                if not (blockStroke and blockStroke:IsA("UIStroke")) then
                    blockStroke=stroke(blockButton,0.22,1,TValue.pink)
                    blockStroke.Name="pvBlockStroke"
                end
                blockStroke.Color=blocked and TValue.line or TValue.pink
                blockStroke.Transparency=blocked and 0.34 or 0.18
                blockStroke.Thickness=1
            end
        end

        local function displayUSDTotal(number)
            local whole,cents=("%.2f"):format(math.max(0,number)):match("^(%d+)(%.%d+)$")
            whole=whole:reverse():gsub("(%d%d%d)","%1,"):reverse():gsub("^,","")
            return "$"..whole..cents
        end

        local function showTopWeapons(row,player)
            local summary=loadPlayerWeapons(player)
            local label=Instance.new("TextLabel")
            label.Name="WeaponValueHeader"
            label.Position=UDim2.fromOffset(pxValue(9),pxValue(85))
            label.Size=UDim2.new(0.63,-pxValue(9),0,pxValue(14))
            label.BackgroundTransparency=1
            label.Text=(summary.state~="ready" and summary.items and #summary.items>0)
                and "TOP WEAPONS  /  LAST SEEN"
                or "TOP WEAPONS  /  USD VALUE"
            label.Font=Enum.Font.GothamBold
            label.TextSize=pxValue(8)
            label.TextColor3=TValue.sub
            label.TextXAlignment=Enum.TextXAlignment.Left
            label.Parent=row

            -- Total of all USD-priced owned weapons (including duplicates),
            -- not only the three shown underneath. Show "LAST" on rejoin while
            -- the server is refreshing that player's real inventory.
            if type(summary.totalUSD)=="number" then
                local totalLabel=Instance.new("TextLabel")
                totalLabel.Name="InventoryTotal"
                totalLabel.Position=UDim2.new(0.63,0,0,pxValue(85))
                totalLabel.Size=UDim2.new(0.37,-pxValue(9),0,pxValue(14))
                totalLabel.BackgroundTransparency=1
                totalLabel.Text=(summary.state=="ready" and "TOTAL " or "LAST ")
                    ..displayUSDTotal(summary.totalUSD)
                totalLabel.Font=Enum.Font.GothamBold
                totalLabel.TextSize=pxValue(8)
                totalLabel.TextTruncate=Enum.TextTruncate.AtEnd
                -- Match the adjacent TOP WEAPONS header in every UI theme.
                totalLabel.TextColor3=TValue.sub
                totalLabel.TextXAlignment=Enum.TextXAlignment.Right
                totalLabel.Parent=row
            end

            local items=summary and summary.items
            if not items or #items==0 then
                local msg=Instance.new("TextLabel")
                msg.Name="WeaponsPlaceholder"
                msg.Position=UDim2.fromOffset(pxValue(9),pxValue(110))
                msg.Size=UDim2.new(1,-pxValue(18),0,pxValue(26))
                msg.BackgroundTransparency=1
                msg.Font=Enum.Font.GothamMedium
                msg.TextSize=pxValue(9)
                msg.TextColor3=TValue.sub
                msg.TextXAlignment=Enum.TextXAlignment.Center
                msg.Text=summary.state=="loading" and "Loading weapon values..."
                    or summary.state=="unavailable" and "Inventory not available"
                    or "No USD-priced weapons found"
                msg.Parent=row
                return false
            end

            local tray=Instance.new("Frame")
            tray.Name="Top3Weapons"
            tray.Position=UDim2.fromOffset(pxValue(6),pxValue(105))
            tray.Size=UDim2.new(1,-pxValue(12),0,pxValue(76))
            tray.BackgroundTransparency=1
            tray.Parent=row
            local arrange=Instance.new("UIListLayout")
            arrange.FillDirection=Enum.FillDirection.Horizontal
            arrange.SortOrder=Enum.SortOrder.LayoutOrder
            arrange.Padding=UDim.new(0,pxValue(4))
            arrange.Parent=tray
            for index,item in ipairs(items) do
                local tile=Instance.new("Frame")
                tile.Name="TopWeapon_"..index
                tile.LayoutOrder=index
                tile.Size=UDim2.new(1/3,-pxValue(3),1,0)
                tile.BackgroundColor3=TValue.black
                tile.BackgroundTransparency=0.12
                tile.BorderSizePixel=0
                tile.Parent=tray
                corner(tile,pxValue(7))
                styleBlockPanelWeaponTile(tile)

                local preview=Instance.new("Frame")
                preview.Name="WeaponPreview"
                preview.Position=UDim2.new(0.5,-pxValue(23),0,pxValue(2))
                preview.Size=UDim2.fromOffset(pxValue(46),pxValue(38))
                preview.BackgroundTransparency=1
                preview.ClipsDescendants=true
                preview.Parent=tile
                local icon=Instance.new("ImageLabel")
                icon.Name="WeaponIcon"
                icon.Size=UDim2.fromScale(1,1)
                icon.BackgroundTransparency=1
                icon.ScaleType=Enum.ScaleType.Fit
                icon.Parent=preview
                pcall(function() icon.Image=resolveImg(item.id,item.image) end)
                scheduleWeaponModel(preview,item)

                local name=Instance.new("TextLabel")
                name.Name="WeaponName"
                name.Position=UDim2.fromOffset(pxValue(3),pxValue(40))
                name.Size=UDim2.new(1,-pxValue(6),0,pxValue(13))
                name.BackgroundTransparency=1
                name.Text=item.name
                name.TextColor3=TValue.txt
                name.TextSize=pxValue(8)
                name.Font=Enum.Font.GothamMedium
                name.TextTruncate=Enum.TextTruncate.AtEnd
                name.Parent=tile

                local price=Instance.new("TextLabel")
                price.Name="USDPrice"
                price.Position=UDim2.fromOffset(pxValue(3),pxValue(55))
                price.Size=UDim2.new(1,-pxValue(6),0,pxValue(15))
                price.BackgroundTransparency=1
                price.Text=("$%.2f"):format(item.value)
                price.TextColor3=TValue.pink
                price.TextSize=pxValue(10)
                price.Font=Enum.Font.GothamBold
                price.Parent=tile
            end
            return true
        end

