            tileGrid.Parent=grid

            local function sizePickerTiles()
                local available=grid.AbsoluteSize.X
                    -pxValue(7)-pxValue(13)-pxValue(6)-grid.ScrollBarThickness-pxValue(3)
                if available<=0 then return end
                local width=math.max(pxValue(48),math.floor(available/2))
                tileGrid.CellSize=UDim2.fromOffset(width,pxValue(82))
            end
            local function updatePickerCanvas()
                if not grid.Parent then return end
                local fullHeight=tileGrid.AbsoluteContentSize.Y+pxValue(6)+pxValue(12)
                grid.CanvasSize=UDim2.fromOffset(0,math.max(grid.AbsoluteSize.Y,fullHeight))
            end
            pvSession.connect(grid:GetPropertyChangedSignal("AbsoluteSize"),function()
                sizePickerTiles()
                updatePickerCanvas()
            end)
            pvSession.connect(tileGrid:GetPropertyChangedSignal("AbsoluteContentSize"),updatePickerCanvas)
            task.defer(sizePickerTiles)

            local footer=Instance.new("Frame")
            footer.Name="WeaponSelectorFooter"
            footer.Position=UDim2.new(0,pxValue(7),1,-pxValue(43))
            footer.Size=UDim2.new(1,-pxValue(14),0,pxValue(35))
            -- No boxed footer tray. The arrows and page label sit directly
            -- on the same themed window surface as the Items page controls.
            footer.BackgroundTransparency=1
            footer.BorderSizePixel=0
            footer.Parent=picker
            local previous=Instance.new("TextButton")
            previous.Name="PreviousWeapons"
            previous.Position=UDim2.fromOffset(pxValue(4),pxValue(4))
            previous.Size=UDim2.fromOffset(pxValue(38),pxValue(27))
            previous.BackgroundColor3=TValue.pane
            previous.BorderSizePixel=0
            previous.Text="<"
            previous.Font=Enum.Font.GothamBold
            previous.TextSize=pxValue(11)
            previous.TextColor3=TValue.txt
            previous.Parent=footer
            corner(previous,pxValue(7))
            local pageStatus=Instance.new("TextLabel")
            pageStatus.Name="WeaponPageCount"
            pageStatus.Position=UDim2.fromOffset(pxValue(49),pxValue(5))
            pageStatus.Size=UDim2.new(1,-pxValue(98),0,pxValue(29))
            pageStatus.BackgroundTransparency=1
            pageStatus.Font=Enum.Font.GothamMedium
            pageStatus.TextSize=pxValue(8)
            pageStatus.TextXAlignment=Enum.TextXAlignment.Center
            pageStatus.TextTruncate=Enum.TextTruncate.AtEnd
            pageStatus.TextColor3=TValue.txt
            pageStatus.Parent=footer
            local nextPage=Instance.new("TextButton")
            nextPage.Name="NextWeapons"
            nextPage.AnchorPoint=Vector2.new(1,0)
            nextPage.Position=UDim2.new(1,-pxValue(4),0,pxValue(5))
            nextPage.Size=UDim2.fromOffset(pxValue(40),pxValue(29))
            nextPage.BackgroundColor3=TValue.pane
            nextPage.BorderSizePixel=0
            nextPage.Text=">"
            nextPage.Font=Enum.Font.GothamBold
            nextPage.TextSize=pxValue(11)
            nextPage.TextColor3=TValue.txt
            nextPage.Parent=footer
            corner(nextPage,pxValue(7))

            local entries=nil
            local rarity="ALL"
            local currentPage=1
            -- Eight previews per page, progressively loaded; don't try to
            -- construct 16 ViewportFrames when the user opens the picker.
            local PAGE_SIZE=8
            local rebuild,buildRarityTabs
            local dirty=false
            local catalogBusy=false
            local previewGeneration=0
            local currentPreviewJobs={}
            local activePicker3D={}
            local lastScrollAt=-math.huge
            local idleScrollWorker=false
            local pickerScrollActive=false
            local lastPickerTap=-math.huge

            local function clearPicker3D()
                -- Only visit the small active set, not the entire weapon list.
                -- Static thumbnails remain visible while the scroll moves.
                for preview in pairs(activePicker3D) do
                    activePicker3D[preview]=nil
                    if preview.Parent then
                        preview:SetAttribute("pvAllowPicker3D",false)
                        local model=preview:FindFirstChild("Weapon3D")
                        if model then model:Destroy() end
                        local icon=preview:FindFirstChild("WeaponIcon")
                        if icon then icon.Visible=true end
                    end
                end
            end

            -- The weapons catalog is assembled in small batches on a worker.
            -- Opening the panel therefore never waits for all MM2 items to be
            -- scanned and sorted on the UI thread.
            local function catalog()
                if entries then return entries end
                if not catalogBusy then
                    catalogBusy=true
                    task.spawn(function()
                        local found={}
                        local number=0
                        for id,info in pairs(Sync.Weapons or {}) do
                            if not isCurrent() then return end
                            if type(info)=="table" then
                                local typ=tostring(info.ItemType or "")
                                if typ=="Knife" or typ=="Gun" then
                                    local name=tostring(info.ItemName or id)
                                    -- The game includes unrevealed gun records
                                    -- named "???" with silhouette thumbnails.
                                    -- Normal Pork Hub Items already skips those
                                    -- records; the whitelist picker should too.
                                    -- They cannot be reliably identified as a
                                    -- selectable, owned weapon until revealed.
                                    if name=="" or name:find("?",1,true) then
                                        -- Also discard a previously selected
                                        -- placeholder so it cannot silently
                                        -- keep triggering auto-block checks.
                                        local unknownId=tostring(id)
                                        if weaponWhitelist[unknownId]==true then
                                            weaponWhitelist[unknownId]=nil
                                            dirty=true
                                            filterVersion+=1
                                        end
                                    else
                                        local text2=tostring(info.Rarity or "Other")
                                        local base=name:gsub("^[Cc]hroma%s+","")
                                        local chroma=info.Chroma==true or base~=name
                                        local price=(chroma and type(PV_VALUES_CHROMA)=="table"
                                            and PV_VALUES_CHROMA[base])
                                            or (type(PV_VALUES)=="table" and PV_VALUES[base])
                                        found[#found+1]={
                                            id=tostring(id),name=name,rarity=text2,
                                            searchName=name:lower(),
                                            value=type(price)=="number" and price or nil,
                                            image=info.Image
                                        }
                                    end
                                end
                            end
                            number+=1
                            if number%48==0 then task.wait() end
                        end
                        local rank={Ancient=1,Godly=2,Unique=3,Vintage=4,
                            Legendary=5,Rare=6,Uncommon=7,Common=8,Other=9}
                        table.sort(found,function(first,button)
                            local x,y=rank[first.rarity] or 9,rank[button.rarity] or 9
                            if x~=y then return x<y end
                            if first.name~=button.name then return first.name<button.name end
                            return first.id<button.id
                        end)
                        if not isCurrent() then return end
                        entries=found
                        catalogBusy=false
                        if picker.Visible then
                            buildRarityTabs()
                            rebuild()
                        end
                    end)
                end
                return nil
            end

            local function updateChip(chip,name)
                local selected=(name==rarity)
                chip.BackgroundColor3=selected and TValue.pinkDim or TValue.pane
                chip.BackgroundTransparency=selected and 0.04 or 0.22
                chip.TextColor3=selected and TValue.txt or TValue.sub
                local edge=chip:FindFirstChild("RarityChipOutline")
                if edge then
                    edge.Color=selected and TValue.pink or TValue.line
                    edge.Transparency=selected and 0.34 or 0.82
                end
            end
            buildRarityTabs=function()
                for _,child in ipairs(rarities:GetChildren()) do
                    if child:IsA("TextButton") then child:Destroy() end
                end
                -- Hide Vintage as a separate picker filter. Vintage items
                -- remain available under ALL and still count for whitelist checks.
                local names={"ALL","Ancient","Godly","Unique",
                    "Legendary","Rare","Uncommon","Common"}
                local known={Vintage=true}
                for _,name in ipairs(names) do known[name]=true end
                for _,entry in ipairs(entries or {}) do
                    if not known[entry.rarity] then
                        known[entry.rarity]=true
                        names[#names+1]=entry.rarity
                    end
                end
                -- 3 columns keeps LEGENDARY and UNCOMMON readable at
                -- the same size as the shorter rarity labels.
                local columns=3
                local rows=math.ceil(#names/columns)
                chipsLayout.FillDirectionMaxCells=columns
                chipsLayout.CellSize=UDim2.new(1/columns,-pxValue(6),0,pxValue(24))
                local rarityHeight=rows*28+pxValue(1)
                rarities.Size=UDim2.new(1,-pxValue(10),0,pxValue(rarityHeight))
                local bulkTop=69+rarityHeight+5
                bulkBar.Position=UDim2.fromOffset(pxValue(5),pxValue(bulkTop))
                -- Reserve a real row for these actions so they never overlap
                -- or crop the rarity chips, weapon tiles, or bottom pagination.
                local gridTop=bulkTop+24+7
                grid.Position=UDim2.fromOffset(pxValue(7),pxValue(gridTop))
                -- Leave a slightly smaller reserve for the footer so the
                -- second row is less cropped while still clearing pagination.
                grid.Size=UDim2.new(1,-pxValue(14),1,-pxValue(gridTop+54))
                task.defer(function()
                    if grid.Parent then sizePickerTiles();updatePickerCanvas() end
                end)
                for index,name in ipairs(names) do
                    local chip=Instance.new("TextButton")
                    chip.Name="Rarity_"..name
                    chip.LayoutOrder=index
                    chip.BackgroundColor3=TValue.black
                    chip.BorderSizePixel=0
                    chip.Text=string.upper(name)
                    chip.TextTruncate=Enum.TextTruncate.AtEnd
                    chip.TextScaled=false
                    chip.TextSize=pxValue(8)
                    chip.Font=Enum.Font.GothamBold
                    chip.AutoButtonColor=false
                    chip.Parent=rarities
                    corner(chip,pxValue(7))
                    local chipEdge=stroke(chip,0.82,1,TValue.line)
                    chipEdge.Name="RarityChipOutline"
                    updateChip(chip,name)
                    chip.Activated:Connect(function()
                        rarity=name
                        currentPage=1
                        activeBulkAction=nil
                        updateBulkButtons()
                        -- Don't recreate the whole row of tabs on each click.
                        for _,child in ipairs(rarities:GetChildren()) do
                            if child:IsA("TextButton") then
                                updateChip(child,child.Name:sub(#"Rarity_"+1))
                            end
                        end
                        rebuild()
                    end)
                end
            end

            -- 3D previews are expensive to clone/render on low-end clients.
            -- Show lightweight icons while moving the list, then upgrade only
            -- TWO tiles actually visible after scrolling has settled.
            local loadPickerPreviews
            local function visibleTile(preview)
                if not preview or not preview.Parent or not preview:IsDescendantOf(grid) then return false end
                local tile=preview.Parent
                local top=tile.AbsolutePosition.Y
                local bottom=top+tile.AbsoluteSize.Y
                local viewTop=grid.AbsolutePosition.Y
                local viewBottom=viewTop+grid.AbsoluteSize.Y
                return bottom>viewTop+pxValue(6) and top<viewBottom-pxValue(6)
            end

            loadPickerPreviews=function(jobs)
                previewGeneration+=1
                local token=previewGeneration
                task.spawn(function()
                    -- Never clone model geometry while a wheel/touch scroll is active.
                    task.wait(3.0)
                    if not isCurrent() or not picker.Visible
                        or token~=previewGeneration or _G.pvBlockInProgress
                        or os.clock()-lastScrollAt<2.6
                        or os.clock()-lastPickerTap<2.6 then return end
                    local upgraded=0
                    for _,job in ipairs(jobs) do
                        if not isCurrent() or not picker.Visible
                            or token~=previewGeneration or _G.pvBlockInProgress
                            or os.clock()-lastPickerTap<2.6 then return end
                        if visibleTile(job.preview) then
                            job.preview:SetAttribute("pvAllowPicker3D",true)
                            activePicker3D[job.preview]=true
                            -- Existing cached models load instantly. Missing
                            -- models use the existing async loader, never the
                            -- frame-by-frame scrolling path.
                            addWeaponModel(job.preview,job.entry)
                            upgraded+=1
                            if upgraded>=1 then break end
                            task.wait(0.30)
                        end
                    end
                end)
            end

            local function notePickerScroll()
                if not picker.Visible then return end
                lastScrollAt=os.clock()
                -- The shared smooth-scroll controller adjusts CanvasPosition
                -- every frame. Drop expensive 3D previews ONCE at the start of
                -- a gesture, not again on each eased movement/update.
                if not pickerScrollActive then
                    pickerScrollActive=true
                    previewGeneration+=1
                    clearPicker3D()
                end
                if idleScrollWorker then return end
                idleScrollWorker=true
                -- Coalesce scroll updates into one idle worker. Model loading
                -- never runs during motion and doesn't slow down wheel easing.
                task.spawn(function()
                    while isCurrent() and picker.Visible do
                        local remaining=0.70-(os.clock()-lastScrollAt)
                        if remaining<=0 then break end
                        task.wait(math.clamp(remaining,0.08,0.25))
                    end
                    idleScrollWorker=false
                    pickerScrollActive=false
                    if isCurrent() and picker.Visible and #currentPreviewJobs>0 then
                        loadPickerPreviews(currentPreviewJobs)
                    end
                end)
            end
            pvSession.connect(grid:GetPropertyChangedSignal("CanvasPosition"),notePickerScroll)
            pvSession.connect(grid.InputChanged,function(input)
                if input.UserInputType==Enum.UserInputType.MouseWheel
                    or input.UserInputType==Enum.UserInputType.Touch then
                    notePickerScroll()
                end
            end)
            pvSession.connect(grid.InputBegan,function(input)
                if input.UserInputType==Enum.UserInputType.Touch then
                    notePickerScroll()
                end
            end)

            rebuild=function()
                -- Invalidate old 3D loads before destroying any grid tiles.
                previewGeneration+=1
                clearPicker3D()
                currentPreviewJobs={}
                for _,child in ipairs(grid:GetChildren()) do
                    if child:IsA("GuiObject") then child:Destroy() end
                end
                local all=catalog()
                if not all then
                    local loading=Instance.new("TextLabel")
                    loading.Name="LoadingWeapons"
                    loading.BackgroundTransparency=1
                    loading.Size=UDim2.new(1,-pxValue(12),0,pxValue(52))
                    loading.Text="Loading weapon list..."
                    loading.TextColor3=TValue.sub
                    loading.TextSize=pxValue(10)
                    loading.Font=Enum.Font.GothamMedium
                    loading.Parent=grid
                    task.defer(updatePickerCanvas)
                    pageStatus.Text=("Loading · %d selected"):format(selectedWeaponCount())
                    previous.Active=false
                    nextPage.Active=false
                    return
                end
                local text2=tostring(pickerSearch.Text or ""):lower()
                local filtered={}
                for _,entry in ipairs(all) do
                    if (rarity=="ALL" or entry.rarity==rarity)
                        and (text2=="" or entry.searchName:find(text2,1,true)) then
                        filtered[#filtered+1]=entry
                    end
                end
                local pages=math.max(1,math.ceil(#filtered/PAGE_SIZE))
                currentPage=math.clamp(currentPage,1,pages)
                pageStatus.Text=("%d / %d · %d selected"):format(
                    currentPage,pages,selectedWeaponCount())
                previous.Active=currentPage>1
                nextPage.Active=currentPage<pages
                previous.TextColor3=previous.Active and TValue.txt or TValue.sub
                nextPage.TextColor3=nextPage.Active and TValue.txt or TValue.sub
                previous.BackgroundTransparency=previous.Active and 0 or 0.45
                nextPage.BackgroundTransparency=nextPage.Active and 0 or 0.45
                grid.CanvasPosition=Vector2.zero
                if #filtered==0 then
                    local empty=Instance.new("TextLabel")
                    empty.Name="NoMatchingWeapons"
                    empty.Size=UDim2.new(1,-pxValue(12),0,pxValue(50))
                    empty.Text="No matching weapons"
                    empty.TextSize=pxValue(10)
                    empty.TextColor3=TValue.sub
                    empty.BackgroundTransparency=1
                    empty.Parent=grid
                    task.defer(updatePickerCanvas)
                    return
                end
                local previewJobs={}
                for index=(currentPage-1)*PAGE_SIZE+1,math.min(#filtered,currentPage*PAGE_SIZE) do
                    local entry=filtered[index]
                    local tile=Instance.new("TextButton")
                    tile.Name="Pick_"..entry.id
                    tile.LayoutOrder=index
                    -- Subtle glass-style cards echo the Items rows; no
                    -- solid grey blocks sitting on a dark picker rectangle.
                    tile.BackgroundColor3=weaponWhitelist[entry.id]==true and TValue.pinkDim or TValue.pane
                    tile.BackgroundTransparency=weaponWhitelist[entry.id]==true and 0.18 or 0.45
                    tile.BorderSizePixel=0
                    tile.Text=""
                    -- The visible card is presentation only; a dedicated
                    -- topmost hitbox receives clicks even over a ViewportFrame.
                    tile.Active=false
                    tile.Selectable=false
                    tile.AutoButtonColor=false
                    -- Build off-tree to avoid UI layout work for every label.
                    corner(tile,pxValue(8))
                    local outline=stroke(tile,0.40,1,weaponWhitelist[entry.id]==true and TValue.pink or TValue.line)

                    local imageHolder=Instance.new("Frame")
                    imageHolder.Name="WeaponPreview"
                    imageHolder.Position=UDim2.new(0.5,-pxValue(22),0,pxValue(2))
                    imageHolder.Size=UDim2.fromOffset(pxValue(44),pxValue(37))
                    imageHolder.BackgroundTransparency=1
                    imageHolder.ClipsDescendants=true
                    imageHolder.Active=false
                    imageHolder.Parent=tile
                    local image=Instance.new("ImageLabel")
                    image.Name="WeaponIcon"
                    image.Size=UDim2.fromScale(1,1)
                    image.BackgroundTransparency=1
                    image.ScaleType=Enum.ScaleType.Fit
                    image.Active=false
                    image.Parent=imageHolder
                    -- Do not call resolveImg() here: its first call may
                    -- require ItemService and scan ReplicatedStorage, causing
                    -- a long freeze when opening the weapon selector.
                    -- Use the catalog's image directly; the 3D model upgrades
                    -- it later without blocking the UI.
                    image.Image=pvFixImg(entry.image)
                    previewJobs[#previewJobs+1]={preview=imageHolder,entry=entry}

                    local title=Instance.new("TextLabel")
                    title.Name="WeaponName"
                    title.Position=UDim2.fromOffset(pxValue(4),pxValue(39))
                    title.Size=UDim2.new(1,-pxValue(8),0,pxValue(13))
                    title.BackgroundTransparency=1
                    title.Active=false
                    title.Font=Enum.Font.GothamBold
                    title.TextSize=pxValue(8)
                    title.TextTruncate=Enum.TextTruncate.AtEnd
                    title.TextColor3=TValue.txt
                    title.Text=entry.name
                    title.Parent=tile
                    local price=Instance.new("TextLabel")
                    price.Name="RarityAndUSD"
                    price.Position=UDim2.fromOffset(pxValue(4),pxValue(53))
                    price.Size=UDim2.new(1,-pxValue(8),0,pxValue(11))
                    price.BackgroundTransparency=1
                    price.Active=false
                    price.Font=Enum.Font.GothamMedium
                    price.TextSize=pxValue(7)
                    price.TextColor3=TValue.sub
                    price.Text=entry.rarity..(entry.value and (" · $%.2f"):format(entry.value) or "")
                    price.TextTruncate=Enum.TextTruncate.AtEnd
                    price.Parent=tile
                    local selected=Instance.new("TextLabel")
                    selected.Name="SelectedStatus"
                    selected.Position=UDim2.fromOffset(pxValue(4),pxValue(67))
                    selected.Size=UDim2.new(1,-pxValue(8),0,pxValue(11))
                    selected.BackgroundTransparency=1
                    selected.Active=false
                    selected.Font=Enum.Font.GothamBold
                    selected.TextSize=pxValue(7)
                    selected.TextColor3=weaponWhitelist[entry.id]==true and TValue.pink or TValue.sub
                    selected.Text=weaponWhitelist[entry.id]==true and "TAP TO REMOVE" or "TAP TO SELECT"
                    selected.Parent=tile

                    -- A loaded 3D ViewportFrame can cover the card and swallow
                    -- its second tap. Keep exactly ONE interactive button over
                    -- the entire card (including its image, text and 3D model).
                    local hitbox=Instance.new("TextButton")
                    hitbox.Name="WeaponSelectHitbox"
                    hitbox.Position=UDim2.fromScale(0,0)
                    hitbox.Size=UDim2.fromScale(1,1)
                    hitbox.BackgroundTransparency=1
                    hitbox.BorderSizePixel=0
                    hitbox.Text=""
                    hitbox.AutoButtonColor=false
                    hitbox.Active=true
                    hitbox.ZIndex=tile.ZIndex+8
                    hitbox.Parent=tile

                    local weaponId=entry.id
                    local lastToggle=-math.huge
                    hitbox.Activated:Connect(function()
                        if not isCurrent() or not picker.Visible then return end
                        -- Guard against a duplicated click dispatch, but allow
                        -- a real second click to deselect the same weapon.
                        local now=os.clock()
                        if now-lastToggle<0.10 then return end
                        lastToggle=now
                        if weaponWhitelist[weaponId]==true then
                            weaponWhitelist[weaponId]=nil
                        else
                            weaponWhitelist[weaponId]=true
                        end
                        dirty=true
                        filterVersion+=1
                        lastPickerTap=os.clock()
                        activeBulkAction=nil
                        updateBulkButtons()
                        local onValue=weaponWhitelist[weaponId]==true
                        -- Always restore the SAME original tile colours when
                        -- deselected, not just the status text.
                        tile.BackgroundColor3=onValue and TValue.pinkDim or TValue.pane
                        tile.BackgroundTransparency=onValue and 0.18 or 0.45
                        outline.Color=onValue and TValue.pink or TValue.line
                        selected.Text=onValue and "TAP TO REMOVE" or "TAP TO SELECT"
                        selected.TextColor3=onValue and TValue.pink or TValue.sub
                        pageStatus.Text=("%d / %d · %d selected"):format(
                            currentPage,pages,selectedWeaponCount())
                        updateFilterToolbar()
                        -- The entire grid is NOT rebuilt, and there are NO
                        -- disk writes/JSON encoding on weapon taps. Save once
                        -- when the user leaves the weapon selector instead.
                        -- Cancel pending model clones until taps have stopped.
                        loadPickerPreviews(currentPreviewJobs)
                    end)
                    -- Commit the fully assembled tile only once.
                    tile.Parent=grid
                end
                currentPreviewJobs=previewJobs
                task.defer(updatePickerCanvas)
                loadPickerPreviews(previewJobs)
            end

            -- Bulk actions update the existing (at most eight) visible card
            -- colours in place, with no tile/model rebuild or disk writes.
            -- Save and recheck player inventories only after DONE, just like
            -- single-weapon selection.
            local function applyRarityBulk(makeSelected)
                if not isCurrent() or not picker.Visible then return end
                local all=catalog()
                if not all then return end
                local changed=false
                for _,entry in ipairs(all) do
                    if rarity=="ALL" or entry.rarity==rarity then
                        local wasSelected=weaponWhitelist[entry.id]==true
                        if wasSelected~=makeSelected then
                            weaponWhitelist[entry.id]=makeSelected and true or nil
                            changed=true
                        end
                    end
                end
                if not changed then return true end
                dirty=true
                filterVersion+=1
                lastPickerTap=os.clock()
                -- Do not rebuild the grid: restyle only tiles on this page.
                for _,tile in ipairs(grid:GetChildren()) do
                    if tile:IsA("TextButton") and tile.Name:sub(1,5)=="Pick_" then
                        local onValue=weaponWhitelist[tile.Name:sub(6)]==true
                        tile.BackgroundColor3=onValue and TValue.pinkDim or TValue.pane
                        tile.BackgroundTransparency=onValue and 0.18 or 0.45
                        local border=tile:FindFirstChildWhichIsA("UIStroke")
                        if border then border.Color=onValue and TValue.pink or TValue.line end
                        local label=tile:FindFirstChild("SelectedStatus")
                        if label then
                            label.Text=onValue and "TAP TO REMOVE" or "TAP TO SELECT"
                            label.TextColor3=onValue and TValue.pink or TValue.sub
                        end
                    end
                end
                pageStatus.Text=pageStatus.Text:gsub("%d+ selected",
                    tostring(selectedWeaponCount()).." selected")
                updateFilterToolbar()
                -- Defer any 3D upgrades until interaction has gone idle.
                loadPickerPreviews(currentPreviewJobs)
                return true
            end
            pvSession.connect(bulkSelect.Activated,function()
                if activeBulkAction=="select" then
                    -- Tap Select All again to undo that bulk selection.
                    if applyRarityBulk(false) then activeBulkAction=nil end
                else
                    if applyRarityBulk(true) then activeBulkAction="select" end
                end
                updateBulkButtons()
            end)
            -- Deselect All is valid only when at least one weapon in the
            -- CURRENT rarity is selected (ALL checks the full catalog).
            -- Check the cached catalog, not the UI's eight visible cards, so
            -- selections on another page are counted with no extra UI work.
            local function hasSelectedWeaponInRarity()
                if not entries then return false end
                for _,entry in ipairs(entries) do
                    if (rarity=="ALL" or entry.rarity==rarity)
                        and weaponWhitelist[entry.id]==true then
                        return true
                    end
                end
                return false
            end
            pvSession.connect(bulkDeselect.Activated,function()
                -- No weapon selected in this rarity: don't clear the existing
                -- highlight, refresh the UI, or touch the saved whitelist.
                if not isCurrent() or not picker.Visible
                    or not hasSelectedWeaponInRarity() then return end
                if applyRarityBulk(false) then
                    activeBulkAction="deselect"
                    updateBulkButtons()
                end
            end)

            local function closePicker()
                previewGeneration+=1 -- cancel outstanding 3D work
                pickerScrollActive=false
                clearPicker3D()
                currentPreviewJobs={}
                picker.Visible=false
                pickerOpen=false
                usePickerHeadingSpace(false)
                filterToolbar.Visible=true
                search.Visible=true
                status.Visible=true
                roster.Visible=true
                local hadEdits=dirty
                dirty=false
                if hadEdits and selectedWeaponCount()==0 and settings.inventoryAutoBlockEnabled then
                    settings.inventoryAutoBlockEnabled=false
                end
                if hadEdits then saveCfg() end
                updateFilterToolbar()
                -- Editing pauses all auto-block work. Recheck only once when
                -- the picker closes, even if no selections were changed.
                if recheckAllPlayers and (hadEdits or settings.inventoryAutoBlockEnabled) then
                    recheckAllPlayers()
                end
                if refresh then refresh() end
            end
            pvSession.connect(done.Activated,closePicker)
            pvSession.connect(previous.Activated,function()
                if currentPage>1 then currentPage-=1; rebuild() end
            end)
            pvSession.connect(nextPage.Activated,function()
                currentPage+=1; rebuild()
            end)
            local searchSerial=0
            pvSession.connect(pickerSearch:GetPropertyChangedSignal("Text"),function()
                searchSerial+=1
                local token=searchSerial
                currentPage=1
                task.delay(0.13,function()
                    if isCurrent() and picker.Visible and token==searchSerial then
                        rebuild()
                    end
                end)
            end)

            openWeaponPicker=function()
                if not isCurrent() then return end
                pickerOpen=true
                filterVersion+=1 -- pause checks until Done is pressed
                usePickerHeadingSpace(true)
                picker.Visible=true
                filterToolbar.Visible=false
                search.Visible=false
                status.Visible=false
                roster.Visible=false
                rarity="ALL"
                currentPage=1
                activeBulkAction=nil
                updateBulkButtons()
                -- The first open is nonblocking; catalog construction and 3D
                -- previews run in background tasks after the panel appears.
                buildRarityTabs()
                rebuild()
            end
            pvSession.connect(navBtns.Trade.Activated,function()
                -- When already on Player Panel, Trade returns to the normal
                -- Trade page; don't leave the selector overlay orphaned.
                if pickerOpen then closePicker() end
            end)
        end)()

        -- The old _G.pvBlocked table records past script actions, not current
        -- Roblox account blocks. Never use it to decide the button label.
        -- Read the live Roblox blocked-user list, keyed by UserId, and also
        -- listen for native Block/Unblock events when they are available.
        local verifiedBlockedIds=nil
        local blockStatusSerial=0
        -- A native Block/Unblock notification is newer than GetCore's cached
        -- list. In particular, GetCore can keep reporting a just-unblocked
        -- account as blocked when that player leaves and rejoins. Remember
        -- native changes by UserId for this hub session, not by Player object.
        local nativeBlockChanges={}
        local function nativeBlockChangeFor(id)
            local change=nativeBlockChanges[id]
            if not change then return nil end
            if change.expires and os.clock()>change.expires then
                nativeBlockChanges[id]=nil
                return nil
            end
            return change.blocked
        end
        local function applyNativeBlockChange(userId,isBlocked)
            local id=tonumber(userId)
            if not id or id<=0 then return end
            blockStatusSerial+=1 -- invalidate any older in-flight snapshot
            -- Keep explicit unblocks until another native event. A newly
            -- confirmed block needs only a brief override while Core catches
            -- up; it must not conceal a later external unblock indefinitely.
            nativeBlockChanges[id]=isBlocked
                and {blocked=true,expires=os.clock()+6}
                or {blocked=false}
            verifiedBlockedIds=verifiedBlockedIds or {}
            verifiedBlockedIds[id]=isBlocked and true or nil
            if type(_G.pvBlocked)=="table" then
                for _,player in ipairs(Players:GetPlayers()) do
                    if player.UserId==id then
                        _G.pvBlocked[player.Name]=isBlocked and true or nil
                    end
                end
            end
            if panel.Visible then queueInventoryRefresh() end
        end
        local function requestNativeBlockStatus()
            blockStatusSerial+=1
            local serial=blockStatusSerial
            task.spawn(function()
                -- GetCore may yield and can be unavailable early in startup.
                local success,ids=pcall(function()
                    return game:GetService("StarterGui"):GetCore("GetBlockedUserIds")
                end)
                if not isCurrent() or serial~=blockStatusSerial then return end
                local changed=(verifiedBlockedIds==nil)
                if success and type(ids)=="table" then
                    local current={}
                    for key,value in pairs(ids) do
                        local id=tonumber(value==true and key or value)
                        if id and id>0 then current[id]=true end
                    end
                    -- Native events are authoritative for the remainder of
                    -- this client session. Never let a delayed cached GetCore
                    -- read put BLOCKED back after an explicit unblock.
                    for id in pairs(nativeBlockChanges) do
                        local override=nativeBlockChangeFor(id)
                        if override~=nil then
                            current[id]=override and true or nil
                        end
                    end
                    if verifiedBlockedIds then
                        for _,player in ipairs(Players:GetPlayers()) do
                            if player~=playerGui and (not not verifiedBlockedIds[player.UserId])~=(not not current[player.UserId]) then
                                changed=true;break
                            end
                        end
                    end
                    verifiedBlockedIds=current
                    if type(_G.pvBlocked)=="table" then
                        for _,player in ipairs(Players:GetPlayers()) do
                            if player~=playerGui then
                                _G.pvBlocked[player.Name]=current[player.UserId] and true or nil
                            end
                        end
                    end
                else
                    -- Don't display stale BLOCKED badges after a failed read.
                    changed=verifiedBlockedIds~=nil
                    verifiedBlockedIds=nil
                end
                if changed then queueInventoryRefresh() end
            end)
        end
        local function currentlyBlocked(player)
            local nativeChange=nativeBlockChangeFor(player.UserId)
            if nativeChange~=nil then return nativeChange end
            return verifiedBlockedIds~=nil
                and verifiedBlockedIds[player.UserId]==true
        end

        -- Opt-in, conservative inventory filter: ANY selected item allows the
        -- player. Never block from cached/last-seen results, pending data, or
        -- an empty inventory response. Re-fetch after a delay to confirm.
        local autoBlockWorking=false
        local autoQueued=setmetatable({}, {__mode="k"})
        local autoAttempted=setmetatable({}, {__mode="k"})
        local function allowedByWhitelist(owned)
            for id,selected in pairs(weaponWhitelist) do
                if selected==true and owned[tostring(id)]==true then return true end
            end
            return false
        end
        local function liveFilterCandidate(player,snapshot,version)
            return isCurrent() and settings.inventoryAutoBlockEnabled==true
                and not pickerOpen
                and selectedWeaponCount()>0 and version==filterVersion
                and player~=playerGui and player.Parent==Players
                and weaponSnapshots[player.UserId]==snapshot
                and snapshot.player==player and snapshot.state=="ready"
                and snapshot.freshOwned==true
                and type(snapshot.ownedIds)=="table"
                -- Blocking an already-blocked account is unnecessary and
                -- must not trigger a second enormous inventory response.
                and not currentlyBlocked(player)
                and not allowedByWhitelist(snapshot.ownedIds)
        end
        scheduleFilterCheck=function(player,snapshot)
            local version=filterVersion
            if not liveFilterCandidate(player,snapshot,version) then return end
            if autoQueued[player]==version or autoAttempted[player]==version then return end
            autoQueued[player]=version
            task.spawn(function()
                local function stillValid()
                    return liveFilterCandidate(player,snapshot,version)
                end
                task.wait(5.0) -- let join replication and rendering settle
                if not stillValid() then return end
                -- Second independent server read, serialized in the SAME
                -- request lane as the normal ranking scan (no overlapping
                -- full-inventory replies when multiple users join).
                local success,data=invokeInventoryThrottled(player,stillValid)
                if not success or not stillValid() then return end
                local weapons=type(data)=="table" and data.Weapons
                local owned=type(weapons)=="table" and weapons.Owned
                if type(owned)~="table" or next(owned)==nil then return end
                -- Parse in tiny slices rather than locking up the game when
                -- a large inventory arrives. Stop instantly if the player
                -- leaves or the selected whitelist changes.
                local liveOwned={}
                local confirmedCount=0
                local scanned=0
                for id,amount in pairs(owned) do
                    scanned+=1
                    if scanned%8==0 then
                        task.wait()
                        if not stillValid() then return end
                    end
                    local count=type(amount)=="table" and tonumber(amount.Amount or amount.Count)
                        or tonumber(amount)
                    if count and count>0 then
                        liveOwned[tostring(id)]=true
                        confirmedCount+=1
                    end
                end
                if confirmedCount==0 or allowedByWhitelist(liveOwned) then return end
                local originalCount=0
                for _ in pairs(snapshot.ownedIds) do originalCount+=1 end
                if confirmedCount<originalCount then return end
                if verifiedBlockedIds==nil then
                    requestNativeBlockStatus()
                    task.wait(0.6)
                end
                if not stillValid() or verifiedBlockedIds==nil or currentlyBlocked(player) then return end
                -- One block at a time: no overlapping native confirmation UI.
                local busyDeadline=os.clock()+12
                while autoBlockWorking or _G.pvBlockInProgress or pendingUserId do
                    if not stillValid() or os.clock()>busyDeadline then return end
                    task.wait(0.3)
                end
                if not stillValid() or currentlyBlocked(player) then return end
                -- autoBlockPlayer is defined later in the original hub; it may
                -- not yet be ready if MM2 returns an inventory unusually fast.
                local deadline=os.clock()+8
                while type(autoBlockPlayer)~="function" and os.clock()<deadline do
                    if not stillValid() then return end
                    task.wait(0.2)
                end
                if type(autoBlockPlayer)~="function" or not stillValid() then return end
                autoBlockWorking=true
                autoAttempted[player]=version
                local ran,didBlock,reason=pcall(autoBlockPlayer,player)
                autoBlockWorking=false
                if not isCurrent() then return end
                if ran and didBlock==true then
                    applyNativeBlockChange(player.UserId,true)
                    notify("Auto-blocked "..player.Name.." (no selected weapons)")
                elseif not ran then
                    warn("[Player Panel] Auto-block failed for "..player.Name..": "..tostring(didBlock))
                else
                    -- A native prompt may need a manual confirmation; never
                    -- claim it was blocked unless the existing helper verifies.
                    warn("[Player Panel] Block wasn't verified: "..tostring(reason))
                end
                requestNativeBlockStatus()
            end)
        end
        onInventoryReady=scheduleFilterCheck
        recheckAllPlayers=function()
            filterVersion+=1 -- invalidate old pending tasks on any change
            if not settings.inventoryAutoBlockEnabled or selectedWeaponCount()==0 then return end
            requestNativeBlockStatus()
            for _,player in ipairs(Players:GetPlayers()) do
                if player~=playerGui then
                    local snapshot=loadPlayerWeapons(player)
                    if snapshot.state=="ready" then
                        scheduleFilterCheck(player,snapshot)
                    end
                end
            end
        end
        task.defer(function()
            if isCurrent() and settings.inventoryAutoBlockEnabled
                and selectedWeaponCount()>0 then
                recheckAllPlayers()
            end
        end)
        local function watchNativeBlockEvent(coreName,blocked)
            local starterGuiService=game:GetService("StarterGui")
            for attempt=1,16 do
                if not isCurrent() then return end
                local success,event=pcall(function() return starterGuiService:GetCore(coreName) end)
                if success and event then
                    local signal
                    if typeof(event)=="Instance" and event:IsA("BindableEvent") then
                        signal=event.Event
                    elseif typeof(event)=="RBXScriptSignal" then
                        signal=event
                    end
                    if signal then
                        pvSession.connect(signal,function(target)
                            local id=(typeof(target)=="Instance" and target:IsA("Player"))
                                and target.UserId or tonumber(target)
                            if id then applyNativeBlockChange(id,blocked) end
                            -- Read back Roblox's account state after the event.
                            task.delay(0.3,function()
                                if isCurrent() then requestNativeBlockStatus() end
                            end)
                        end)
                        return
                    end
                end
                task.wait(0.5)
            end
        end
        task.spawn(watchNativeBlockEvent,"PlayerBlockedEvent",true)
        task.spawn(watchNativeBlockEvent,"PlayerUnblockedEvent",false)
        -- Some Roblox clients expose the utility's status-changed event but
        -- not the StarterGui Core event. Listen to it as a second source so
        -- unblocks done through the native player menu repaint immediately.
        task.spawn(function()
            if not isCurrent() then return end
            local util=pvBlockUtil
            for _=1,25 do
                if not isCurrent() then return end
                if type(util)=="table" then break end
                task.wait(0.2)
                util=pvBlockUtil
            end
            if type(util)~="table" or type(util.GetBlockedStatusChangedEvent)~="function" then return end
            local success,event=pcall(function() return util:GetBlockedStatusChangedEvent() end)
            if not success or not event then return end
            local signal=event
            if typeof(event)=="Instance" and event:IsA("BindableEvent") then
                signal=event.Event
            end
            if typeof(signal)=="RBXScriptSignal" then
                pvSession.connect(signal,function(userId,blocked)
                    if typeof(blocked)=="boolean" then
                        applyNativeBlockChange(userId,blocked)
                    end
                end)
            end
        end)
        -- In case blocks are changed through another menu or the native event
        -- isn't available, refresh slowly only while Block Panel is visible.
        task.spawn(function()
            while isCurrent() do
                task.wait(4)
                if isCurrent() and panel.Visible then requestNativeBlockStatus() end
            end
        end)

        -- Mirror MM2's native outgoing-request panel when sending a real
        -- request from a Block Panel card. Do not use pvFakeTradeSent: that
        -- routine fabricates an acceptance and opens a local spoof trade.
        -- Only SendRequest is used here; the game's own Cancel button keeps
        -- its native connection, so we do not transmit a duplicate cancellation.
        local pendingTrade=nil

        local function clearPendingTrade(owner)
            local state=pendingTrade
            if not state or (owner and owner~=state) then return end
            pendingTrade=nil
            for _,conn in ipairs(state.connections) do
                pcall(function() conn:Disconnect() end)
            end
            -- Do not overwrite another request that the game may have opened.
            pcall(function()
                if state.sending.Parent and state.sending.Visible then
                    state.sending.Visible=false
                end
                if state.username.Parent and state.username.Text==state.name then
                    state.username.Text=state.previousName
                end
                if state.root.Parent and state.root.Visible
                    and not (state.receiving and state.receiving.Visible) then
                    state.root.Visible=false
                end
            end)
            if panel.Visible and refresh then refresh() end
        end

        local function showNativePending(player)
            if pendingTrade then return false,"A trade request is already pending" end
            local main=playerGui2:FindFirstChild("MainGUI")
            local gameUI=main and main:FindFirstChild("Game")
            local leaderboard=gameUI and gameUI:FindFirstChild("Leaderboard")
            local container=leaderboard and leaderboard:FindFirstChild("Container")
            local root=container and container:FindFirstChild("TradeRequest")
            local sending=root and root:FindFirstChild("SendingRequest")
            local receiving=root and root:FindFirstChild("ReceivingRequest")
            local username=sending and sending:FindFirstChild("Username")
            local cancel=sending and sending:FindFirstChild("Cancel")
            if not (root and sending and username and cancel and cancel:IsA("GuiButton")) then
                return false,"The native MM2 pending-request UI is unavailable"
            end
            if root.Visible and (sending.Visible or (receiving and receiving.Visible)) then
                return false,"There is already a trade request on screen"
            end
            local state={
                root=root,sending=sending,receiving=receiving,
                username=username,name=player.Name,previousName=username.Text,
                player=player,connections={}
            }
            pendingTrade=state
            -- This is the actual game's SendingRequest screen, not a clone.
            username.Text=player.Name
            if receiving then receiving.Visible=false end
            sending.Visible=true
            root.Visible=true

            local function watch(signal,fnValue)
                state.connections[#state.connections+1]=pvSession.connect(signal,fnValue)
            end
            watch(cancel.Activated,function()
                -- Allow MM2's existing Cancel handler to run before cleanup.
                task.defer(function() clearPendingTrade(state) end)
            end)
            watch(root:GetPropertyChangedSignal("Visible"),function()
                if not root.Visible then clearPendingTrade(state) end
            end)
            watch(sending:GetPropertyChangedSignal("Visible"),function()
                if not sending.Visible then clearPendingTrade(state) end
            end)
            -- A pending request is short-lived. Check only during this one
            -- request (not each frame) and never let a stale UI linger.
            task.spawn(function()
                local started=os.clock()
                while isCurrent() and pendingTrade==state do
                    task.wait(0.45)
                    if pendingTrade~=state then return end
                    if player.Parent~=Players or not root.Parent then
                        clearPendingTrade(state)
                        return
                    end
                    -- When the other player accepts, MM2 opens the real trade.
                    local actual=pvFindTrade(playerGui2)
                    if actual and actual.Enabled and not _G.pvSpoofActive then
                        clearPendingTrade(state)
                        return
                    end
                    -- MM2 may close the request through its own client code.
                    if not root.Visible or not sending.Visible then
                        clearPendingTrade(state)
                        return
                    end
                    if os.clock()-started>30 then
                        clearPendingTrade(state)
                        return
                    end
                end
            end)
            return true,state
        end
        pvSession.addCleanup(function() clearPendingTrade() end)

        -- Real MM2 server request to the selected Player instance.
        local function tradeWithCardPlayer(player,button)
            if not isCurrent() or not player or player==playerGui or player.Parent~=Players then
                notify("That player is no longer in your server")
                return
            end
            if pendingTrade then
                notify("You already have a trade request pending")
                return
            end
            if sendingTradeUserId then
                notify("A trade request is already being sent")
                return
            end
            if os.clock()-lastTradeRequestAt<2.5 then
                notify("Wait a moment before sending another trade request")
                return
            end
            local trade=replicatedStorageService:FindFirstChild("Trade")
            local request=trade and trade:FindFirstChild("SendRequest")
            if not (request and request:IsA("RemoteFunction")) then
                notify("MM2's trade request service is unavailable")
                return
            end
            local shown,stateOrReason=showNativePending(player)
            if not shown then
                notify(stateOrReason)
                return
            end
            local pendingState=stateOrReason
            lastTradeRequestAt=os.clock()
            tradeRequestSerial+=1
            local token=tradeRequestSerial
            sendingTradeUserId=player.UserId
            if button and button.Parent then
                button.Text="SENDING..."
                button.Active=false
                button.AutoButtonColor=false
            end
            local function finish(message,closePending)
                if not isCurrent() or tradeRequestSerial~=token then return end
                tradeRequestSerial+=1
                sendingTradeUserId=nil
                if closePending then clearPendingTrade(pendingState) end
                if button and button.Parent then
                    button.Text=(pendingTrade==pendingState) and "PENDING" or "TRADE"
                    button.Active=(pendingTrade==nil)
                    button.AutoButtonColor=(pendingTrade==nil)
                end
                if panel.Visible and refresh then refresh() end
                if message then notify(message) end
            end
            task.spawn(function()
                local success,response=pcall(function()
                    return request:InvokeServer(player)
                end)
                if not isCurrent() or tradeRequestSerial~=token then return end
                if player.Parent~=Players then
                    finish("Player left before the request completed",true)
                elseif not success then
                    finish("Trade request failed: "..tostring(response),true)
                else
                    -- MM2 can return false from SendRequest even when it has
                    -- dispatched the request. That return value is not a
                    -- reliable rejection signal: leave the native pending
                    -- screen in place, and do not show a false failure toast.
                    -- Only show a success toast for non-false replies; false
                    -- is treated as unconfirmed, not as confirmed success.
                    finish(response==false and nil or ("Trade request sent to "..player.Name),false)
                end
            end)
            task.delay(9,function()
                if isCurrent() and tradeRequestSerial==token then
                    -- An InvokeServer timeout should not pretend the server
                    -- confirmed the request; release the pending screen.
                    finish("Trade request status couldn't be confirmed",true)
                end
            end)
        end

        local function back()
            panel.Visible=false
            text.Visible=true
            search.Text=""
            -- Don't overwrite SETTINGS/ITEMS when switching tabs.
            if pTrade.Visible then pageTitle.Text="TRADE" end
        end

        -- makePage calls this ONLY if Trade was already the visible tab.
        -- Returning from Settings/Items never resets the Player Panel.
        pvSession.playerPanelReturn=function()
            if panel.Visible then back() end
        end

        -- Incremental roster: keep the existing player cards and ViewportFrames.
        -- Rebuilding all cards on every inventory/status update was the main
        -- source of the Player Panel's UI spikes.
        local rowsById={}
        refresh=function(leaving)
            if not isCurrent() then return end
            local previousScroll=roster.CanvasPosition.Y
            local text2=string.lower(tostring(search.Text or "")):match("^%s*(.-)%s*$")
            local members={}
            for _,player in ipairs(Players:GetPlayers()) do
                if player~=leaving and player~=playerGui then
                    local match=string.lower(player.Name.." "..player.DisplayName)
                    if text2=="" or string.find(match,text2,1,true) then
                        members[#members+1]=player
                    end
                end
            end
            -- Preload/cached snapshots are already underway; this call never
            -- waits for InvokeServer and does not rebuild the whole roster.
            local totals={}
            for _,member in ipairs(members) do
                local snapshot=loadPlayerWeapons(member)
                totals[member.UserId]=snapshot and snapshot.totalUSD
            end
            table.sort(members,function(first,button)
                local avValue,bvValue=totals[first.UserId],totals[button.UserId]
                local ahValue,bhValue=type(avValue)=="number",type(bvValue)=="number"
                if ahValue~=bhValue then return ahValue end -- known values before unknown
                if ahValue and avValue~=bvValue then return avValue>bvValue end
                local anValue,bnValue=first.DisplayName:lower(),button.DisplayName:lower()
                if anValue==bnValue then return first.Name:lower()<button.Name:lower() end
                return anValue<bnValue
            end)
            status.Text=("PLAYERS  ·  %d"):format(#members)
            local empty=roster:FindFirstChild("NoPlayersFound")
            if #members==0 then
                if not empty then
                    empty=Instance.new("TextLabel")
                    empty.Name="NoPlayersFound"
                    empty.Size=UDim2.new(1,-pxValue(4),0,pxValue(66))
                    empty.LayoutOrder=1
                    empty.BackgroundTransparency=1
                    empty.TextColor3=TValue.sub
                    empty.Font=Enum.Font.GothamMedium
                    empty.TextSize=pxValue(10)
                    empty.Parent=roster
                end
                empty.Text=(text2~="") and "No matching players" or "No other players available"
            elseif empty then
                empty:Destroy()
            end

            local visible={}
            for index,player in ipairs(members) do
                local id=player.UserId
                visible[id]=true
                local existing=rowsById[id]
                if existing and (existing.player~=player or not existing.row.Parent) then
                    existing.row:Destroy()
                    rowsById[id]=nil
                    existing=nil
                end
                if existing then
                    -- Only change button states and changed weapon tiles.
                    local row=existing.row
                    row.LayoutOrder=index
                    local tradeButton=row:FindFirstChild("TradeUser")
                    if tradeButton then
                        local busy=(pendingTrade~=nil or sendingTradeUserId~=nil)
                        tradeButton.Text=(pendingTrade and pendingTrade.player==player)
                            and "PENDING" or "TRADE"
                        tradeButton.Active=not busy
                        tradeButton.AutoButtonColor=not busy
                    end
                    local action=row:FindFirstChild("BlockUser")
                    if action then
                        local blocked=currentlyBlocked(player)
                        local waiting=pendingUserId~=nil
                        action.Text=blocked and "BLOCKED"
                            or (pendingUserId==id and "WAIT...") or "BLOCK"
                        action.BackgroundColor3=blocked and TValue.black or TValue.pinkDim
                        action.BackgroundTransparency=blocked and 0.34 or 0
                        action.TextColor3=blocked and TValue.sub or TValue.txt
                        action.Active=not(blocked or waiting)
                        action.AutoButtonColor=not(blocked or waiting)
                    end
                    -- Colour gradients/strokes are expensive to reapply on
                    -- every inventory status change. Explicit theme changes
                    -- still repaint via refreshPlayerPanelTheme below.
                    if existing.cardTheme~=settings.uiTheme then
                        styleBlockPanelCard(row)
                        existing.cardTheme=settings.uiTheme
                    end
                    local summary=loadPlayerWeapons(player)
                    if existing.snapshot~=summary or existing.state~=summary.state
                        or existing.items~=summary.items then
                        for _,name in ipairs({"Top3Weapons","WeaponValueHeader","InventoryTotal","WeaponsPlaceholder"}) do
                            local old=row:FindFirstChild(name)
                            if old then old:Destroy() end
                        end
                        local hasWeapons=showTopWeapons(row,player)
                        row.Size=UDim2.new(1,-pxValue(4),0,pxValue(hasWeapons and 189 or 145))
                        existing.snapshot=summary
                        existing.state=summary.state
                        existing.items=summary.items
                    end
                else
                local row=Instance.new("Frame")
                row.Name="BlockRow_"..tostring(player.UserId)
                row.Size=UDim2.new(1,-pxValue(4),0,pxValue(189))
                row.LayoutOrder=index
                row.BackgroundColor3=TValue.pane
                row.BackgroundTransparency=0.12
                row.BorderSizePixel=0
                row.Parent=roster
                corner(row,pxValue(9))
                stroke(row,0.72,1,TValue.line)

                -- Use the player's real Roblox profile headshot (not initials).
                -- The rbxthumb URL is resolved by Roblox without a blocking web call.
                local avatar=Instance.new("ImageLabel")
                avatar.Name="Avatar"
                avatar.Size=UDim2.fromOffset(pxValue(30),pxValue(30))
                avatar.Position=UDim2.fromOffset(pxValue(9),pxValue(7))
                avatar.BackgroundTransparency=1 -- Show only the actual headshot; no pink disc
                avatar.BorderSizePixel=0
                avatar.ScaleType=Enum.ScaleType.Crop
                avatar.Image=("rbxthumb://type=AvatarHeadShot&id=%d&w=150&h=150"):format(player.UserId)
                avatar.Parent=row
                corner(avatar,pxValue(15))

                local nameLabel=Instance.new("TextLabel")
                nameLabel.Name="DisplayName"
                nameLabel.Position=UDim2.fromOffset(pxValue(46),pxValue(7))
                nameLabel.Size=UDim2.new(1,-pxValue(56),0,pxValue(16))
                nameLabel.BackgroundTransparency=1
                nameLabel.Text=player.DisplayName
                nameLabel.Font=Enum.Font.GothamBold
                nameLabel.TextSize=pxValue(10)
                nameLabel.TextColor3=TValue.txt
                nameLabel.TextTruncate=Enum.TextTruncate.AtEnd
                nameLabel.TextXAlignment=Enum.TextXAlignment.Left
                nameLabel.Parent=row

                local username=Instance.new("TextLabel")
                username.Name="Username"
                username.Position=UDim2.fromOffset(pxValue(46),pxValue(24))
                username.Size=UDim2.new(1,-pxValue(56),0,pxValue(13))
                username.BackgroundTransparency=1
                username.Text="@"..player.Name
                username.Font=Enum.Font.GothamMedium
                username.TextSize=pxValue(9)
                username.TextColor3=TValue.sub
                username.TextTruncate=Enum.TextTruncate.AtEnd
                username.TextXAlignment=Enum.TextXAlignment.Left
                username.Parent=row

                -- A full-width pair of action buttons lives on its own line.
                -- Nothing overlaps the username or the weapon preview cards.
                local tradeButton=Instance.new("TextButton")
                tradeButton.Name="TradeUser"
                tradeButton.Position=UDim2.fromOffset(pxValue(8),pxValue(46))
                tradeButton.Size=UDim2.new(0.5,-pxValue(12),0,pxValue(29))
                tradeButton.BackgroundColor3=TValue.black
                tradeButton.BackgroundTransparency=0.13
                tradeButton.BorderSizePixel=0
                tradeButton.Text=(pendingTrade and pendingTrade.player==player) and "PENDING" or "TRADE"
                tradeButton.TextColor3=TValue.txt
                tradeButton.Font=Enum.Font.GothamBold
                tradeButton.TextSize=pxValue(9)
                tradeButton.AutoButtonColor=(pendingTrade==nil and sendingTradeUserId==nil)
                tradeButton.Active=(pendingTrade==nil and sendingTradeUserId==nil)
                tradeButton.Parent=row
                corner(tradeButton,pxValue(8))
                stroke(tradeButton,0.62,1,TValue.line)
                tradeButton.Activated:Connect(function()
                    tradeWithCardPlayer(player,tradeButton)
                end)

                local blocked=currentlyBlocked(player)
                local waiting=pendingUserId~=nil
                local action=Instance.new("TextButton")
                action.Name="BlockUser"
                action.Position=UDim2.new(0.5,pxValue(4),0,pxValue(46))
                action.Size=UDim2.new(0.5,-pxValue(12),0,pxValue(29))
                action.BackgroundColor3=blocked and TValue.black or TValue.pinkDim
                action.BackgroundTransparency=blocked and 0.34 or 0
                action.BorderSizePixel=0
                action.Text=blocked and "BLOCKED"
                    or (pendingUserId==player.UserId and "WAIT...") or "BLOCK"
                action.TextColor3=blocked and TValue.sub or TValue.txt
                action.Font=Enum.Font.GothamBold
                action.TextSize=pxValue(9)
                action.AutoButtonColor=not (blocked or waiting)
                action.Active=not (blocked or waiting)
                action.Parent=row
                corner(action,pxValue(8))
                if not blocked then stroke(action,0.67,1,TValue.pink) end

                action.Activated:Connect(function()
                    if pendingUserId or player==playerGui or player.Parent~=Players then return end
                    if currentlyBlocked(player) then return end
                    if type(autoBlockPlayer)~="function" then
                        notify("Block service is still loading")
                        return
                    end
                    pendingUserId=player.UserId
                    action.Text="WAIT..."
                    action.Active=false
                    action.AutoButtonColor=false
                    queueInventoryRefresh()
                    task.spawn(function()
                        -- Same function/notice path used by the existing
                        -- Trade > Block Player button. No separate block API.
                        local callOk,didBlock,reason=pcall(autoBlockPlayer,player)
                        if not isCurrent() then return end
                        pendingUserId=nil
                        if callOk then
                            -- The existing Block Player function already verifies
                            -- success through Roblox. Update just this account now.
                            if didBlock==true then
                                applyNativeBlockChange(player.UserId,true)
                            end
                            notify(pvBlockNotice(didBlock,reason,player.Name))
                        else
                            notify("Block failed: "..tostring(didBlock))
                        end
                        if panel.Visible then queueInventoryRefresh() end
                        requestNativeBlockStatus()
                    end)
                end)
                local hasWeapons=showTopWeapons(row,player)
                if not hasWeapons then
                    row.Size=UDim2.new(1,-pxValue(4),0,pxValue(145))
                end
                styleBlockPanelCard(row)
                local snap=weaponSnapshots[player.UserId]
                rowsById[player.UserId]={row=row,player=player,snapshot=snap,
                    state=snap and snap.state,items=snap and snap.items,
                    cardTheme=settings.uiTheme}
                end
            end
            -- Discard only vanished / filtered rows, never the whole roster.
            for id,entry in pairs(rowsById) do
                if not visible[id] then
                    if entry.row then entry.row:Destroy() end
                    rowsById[id]=nil
                end
            end
            roster.CanvasPosition=Vector2.new(0,previousScroll)
        end

        -- Repaint the few existing cards when switching Pork / Halloween /
        -- Custom. Do not refresh inventory data or re-create any 3D previews.
        pvSession.refreshPlayerPanelTheme=function()
            if not isCurrent() then return end
            for _,entry in pairs(rowsById) do
                local row=entry.row
                if row and row.Parent then
                    styleBlockPanelCard(row)
                    entry.cardTheme=settings.uiTheme
                    local tray=row:FindFirstChild("Top3Weapons")
                    if tray then
                        for _,tile in ipairs(tray:GetChildren()) do
                            if tile:IsA("Frame") then styleBlockPanelWeaponTile(tile) end
                        end
                    end
                end
            end
        end

        pvSession.connect(search:GetPropertyChangedSignal("Text"),function()
            if panel.Visible then refresh() end
        end)
        pvSession.connect(Players.PlayerAdded,function(player)
            lastPlayerJoinAt=os.clock()
            -- Do not keep a failed cache or the old Player instance on rejoin.
            -- Last confirmed weapon data is retained separately until refreshed.
            weaponSnapshots[player.UserId]=nil
            -- Allow the join/avatar/character burst to settle before the
            -- first potentially huge full inventory response arrives.
            -- This still scans even if Player Panel is not the active tab.
            task.delay(settings.inventoryAutoBlockEnabled and 1.8 or 0.85,function()
                if isCurrent() and player.Parent==Players and player~=playerGui then
                    loadPlayerWeapons(player)
                end
            end)
            -- A returning Player instance must not inherit its previous
            -- BLOCKED badge. Keep an explicit native Unblock event if we saw
            -- one; discard only this player's old list result, not everyone.
            if type(_G.pvBlocked)=="table" then _G.pvBlocked[player.Name]=nil end
            if verifiedBlockedIds then verifiedBlockedIds[player.UserId]=nil end
            -- Never synchronously rebuild the roster during PlayerAdded.
            -- Both the new player row and their later inventory result flow
            -- through the coalesced UI refresh.
            queueInventoryRefresh()
            -- Avoid a second native account-list fetch at the exact moment
            -- the server is delivering the joining player's inventory.
            -- Recheck once Roblox has finished replicating the new player;
            -- the immediate GetCore read can still reflect the prior join.
            for _,delaySeconds in ipairs({1.25,3.5}) do
                task.delay(delaySeconds,function()
                    if isCurrent() and player.Parent==Players then
                        requestNativeBlockStatus()
                    end
                end)
            end
        end)
        pvSession.connect(Players.PlayerRemoving,function(player)
            -- Only invalidate the departing instance, not a new instance that
            -- may have joined quickly under the same UserId.
            local old=weaponSnapshots[player.UserId]
            if old and old.player==player then weaponSnapshots[player.UserId]=nil end
            if type(_G.pvBlocked)=="table" then _G.pvBlocked[player.Name]=nil end
            queueInventoryRefresh()
        end)
        btn(text,"Player Panel",function()
            text.Visible=false
            panel.Visible=true
            updateFilterToolbar()
            pageTitle.Text="PLAYER PANEL"
            search.Text=""
            roster.CanvasPosition=Vector2.zero
            verifiedBlockedIds=nil -- discard old snapshot when reopening
            refresh()
            requestNativeBlockStatus()
        end)
    end)()

    settings.tradeHook=true; pcall(hookTradeItems)


    btn(text,"Weapon Equipping",function()
        if _G.pvBuildWeapList then pcall(_G.pvBuildWeapList) end
        pcall(showPage,"Weapons")
    end)

    -- LOCAL VISUAL PLAYER (never inserts a Player instance or sends trade remotes).
    -- CRITICAL: a plain 'do ... end' does NOT create a new Luau register frame.
    -- This invoked function isolates all visual-player/chat UI locals from the
    -- already register-heavy main script (Luau limit: 200 local registers).
    do
        (function()
        local RunService=game:GetService("RunService")
        local visual = {
            token=0, username=nil, model=nil, row=nil, rowConn=nil,
            movementSerial=0, animationConnections={}, animationTracks={}, spawnCFrame=nil,
            chatSerial=0, lastChatAt=0, setPose=nil, jumpQueue=0, jumping=false,
            level=nil, popup=nil
        }
        -- Visual-only target shared with the Weapon Equipping page. This is
        -- deliberately not a Player instance and never sends equip remotes.
        _G.pvVisualWeaponTarget=nil
        -- Local-only replica of the top Roblox "friend joined you" banner.
        -- The public SetCore SendNotification API is a different (bottom-right)
        -- toast. Never access or manipulate protected CoreGui internals.
        -- Keep this on the visual table to avoid adding registers to the
        -- already-large Spawn Player UI function.
        visual.showJoinToast = function(username, userId)
            if not isCurrent() or not playerGui2 or not playerGui2.Parent then return end
            if visual.joinToast then
                pcall(function() visual.joinToast:Destroy() end)
                visual.joinToast=nil
            end
            local toastGui=Instance.new("ScreenGui")
            toastGui.Name="pvVisualFriendJoinedToast"
            toastGui.ResetOnSpawn=false
            toastGui.IgnoreGuiInset=true
            toastGui.DisplayOrder=1000000
            toastGui.ZIndexBehavior=Enum.ZIndexBehavior.Sibling
            toastGui.Parent=playerGui2
            pvSession.ownRoot(toastGui)
            visual.joinToast=toastGui

            local camera=workspace.CurrentCamera
            local screenWidth=(camera and camera.ViewportSize.X) or 800
            local message=username.." joined you"
            -- Real Roblox's friend-join toast keeps a generous fixed width.
            -- Measuring only the text made the previous version shrink and
            -- truncate the last words into '...'.
            local photoSize=40
            local leftPad=11
            local gap=10
            local rightPad=16
            local toastWidth=math.min(430,math.max(210,screenWidth-20))
            local container=Instance.new("Frame")
            container.Name="JoinBanner"
            container.AnchorPoint=Vector2.new(0.5,0)
            container.Position=UDim2.new(0.5,0,0,-68)
            container.Size=UDim2.fromOffset(toastWidth,58)
            container.BackgroundColor3=Color3.fromRGB(39,41,48)
            container.BorderSizePixel=0
            container.Parent=toastGui
            local radius=Instance.new("UICorner")
            radius.CornerRadius=UDim.new(0,12)
            radius.Parent=container
            local stroke=Instance.new("UIStroke")
            stroke.ApplyStrokeMode=Enum.ApplyStrokeMode.Border
            stroke.Color=Color3.fromRGB(63,66,77)
            stroke.Thickness=1
            stroke.Transparency=0.52
            stroke.Parent=container

            local photo=Instance.new("ImageLabel")
            photo.Name="RobloxAvatar"
            photo.Position=UDim2.fromOffset(leftPad,9)
            photo.Size=UDim2.fromOffset(photoSize,photoSize)
            photo.BackgroundColor3=Color3.fromRGB(28,34,42)
            photo.BorderSizePixel=0
            photo.ScaleType=Enum.ScaleType.Crop
            photo.Image="rbxthumb://type=AvatarHeadShot&id="..tostring(userId).."&w=150&h=150"
            photo.Parent=container
            local circle=Instance.new("UICorner")
            circle.CornerRadius=UDim.new(1,0)
            circle.Parent=photo
            local avatarOutline=Instance.new("UIStroke")
            avatarOutline.ApplyStrokeMode=Enum.ApplyStrokeMode.Border
            avatarOutline.Color=Color3.fromRGB(66,98,219)
            avatarOutline.Thickness=2
            avatarOutline.Parent=photo

            local label=Instance.new("TextLabel")
            label.Name="FriendJoinedText"
            label.BackgroundTransparency=1
            label.Position=UDim2.fromOffset(leftPad+photoSize+gap,0)
            label.Size=UDim2.fromOffset(math.max(0,toastWidth-(leftPad+photoSize+gap)-rightPad),58)
            label.Font=Enum.Font.GothamBold
            label.TextSize=18
            -- Only shrink the font when a narrow viewport or long username
            -- needs it. Never replace the message tail with an ellipsis.
            pcall(function()
                local available=toastWidth-(leftPad+photoSize+gap)-rightPad-4
                local measured=game:GetService("TextService"):GetTextSize(
                    message,18,Enum.Font.GothamBold,Vector2.new(2000,70))
                if measured.X>available then
                    label.TextSize=math.max(11,math.floor(18*available/measured.X))
                end
            end)
            label.TextColor3=Color3.fromRGB(245,245,248)
            label.TextTransparency=0
            label.TextStrokeTransparency=1
            label.TextXAlignment=Enum.TextXAlignment.Left
            label.TextYAlignment=Enum.TextYAlignment.Center
            label.TextTruncate=Enum.TextTruncate.None
            label.Text=message
            label.Parent=container

            Tween:Create(container,TweenInfo.new(0.28,Enum.EasingStyle.Quart,Enum.EasingDirection.Out),{
                Position=UDim2.new(0.5,0,0,21)
            }):Play()
            task.delay(5.1,function()
                if visual.joinToast~=toastGui or not toastGui.Parent then return end
                Tween:Create(container,TweenInfo.new(0.20,Enum.EasingStyle.Quad,Enum.EasingDirection.In),{
                    Position=UDim2.new(0.5,0,0,-68)
                }):Play()
                task.delay(0.24,function()
                    if visual.joinToast==toastGui then visual.joinToast=nil end
                    pcall(function() toastGui:Destroy() end)
                end)
            end)
        end
        visual.showJoinChat = function(username)
            local msg="Your friend "..tostring(username or "Friend").." has joined the experience."
            local success=false
            pcall(function()
                local textChat=game:GetService("TextChatService")
                local channels=textChat and textChat:FindFirstChild("TextChannels")
                -- Prefer the system channel so the message uses the smaller
                -- Roblox system-message style instead of normal player-chat styling.
                local chan=channels and (channels:FindFirstChild("RBXSystem") or channels:FindFirstChild("RBXGeneral"))
                if chan and chan.DisplaySystemMessage then
                    chan:DisplaySystemMessage(msg)
                    success=true
                end
            end)
            if success then return end
            pcall(function()
                game:GetService("StarterGui"):SetCore("ChatMakeSystemMessage",{
                    Text=msg,
                    Color=Color3.fromRGB(255,255,255),
                    Font=Enum.Font.SourceSans,
                    TextSize=16
                })
            end)
        end
        -- No visual-player status footer; keep status() as an internal no-op
        -- so existing actions can retain their own explicit notifications.
        local function status(_message)
        end
        local function valid(token)
            return isCurrent() and visual.token==token
        end
        -- Return the bottom of the oriented foot box in world space. Hats,
        -- accessories, weapons and HipHeight never participate in this measurement.
        visual.footBottom=function(foot)
            local cframe=foot.CFrame
            local half=foot.Size*0.5
            return cframe.Position.Y-(math.abs(cframe.RightVector.Y)*half.X
                +math.abs(cframe.UpVector.Y)*half.Y+math.abs(cframe.LookVector.Y)*half.Z)
        end
        visual.alignGround=function(model)
            local root=model and model:FindFirstChild("HumanoidRootPart")
            if not (root and model.Parent) then return false end
            local excluded={model}
            for _,player in ipairs(Players:GetPlayers()) do
                if player.Character then excluded[#excluded+1]=player.Character end
            end
            local cast=RaycastParams.new()
            cast.FilterType=Enum.RaycastFilterType.Exclude
            cast.FilterDescendantsInstances=excluded
            cast.RespectCanCollide=true
            local correction=nil
            for _,name in ipairs({"LeftFoot","RightFoot","Left Leg","Right Leg"}) do
                local foot=model:FindFirstChild(name)
                if foot and foot:IsA("BasePart") then
                    local pos=foot.Position
                    -- Start near the root, not above the roof of the room.
                    local hit=workspace:Raycast(Vector3.new(pos.X,root.Position.Y+1,pos.Z),
                        Vector3.new(0,-256,0),cast)
                    if hit and hit.Normal.Y>0.55 then
                        local delta=hit.Position.Y-visual.footBottom(foot)
                        correction=correction and math.max(correction,delta) or delta
                    end
                end
            end
            if correction==nil then return false end
            if math.abs(correction)>0.005 then
                model:PivotTo(model:GetPivot()+Vector3.new(0,correction,0))
            end
            model:SetAttribute("pvGrounded",true)
            return true
        end
        -- Stop a roaming task without waiting for a path computation / waypoint timeout.
        local function stopRoaming()
            visual.movementSerial=visual.movementSerial+1
            local model=visual.model
            local humanoid=model and model:FindFirstChildOfClass("Humanoid")
            local root=model and model:FindFirstChild("HumanoidRootPart")
            if humanoid and root then
                pcall(function() humanoid:MoveTo(root.Position) end)
                -- If switched OFF during a scripted jump, land the avatar
                -- instead of leaving it floating above the floor.
                pcall(visual.alignGround,model)
            end
            if visual.setPose then pcall(visual.setPose,"idle") end
        end

        local function stopAnimations()
            visual.setPose=nil
            visual.currentPose=nil
            for _,connection in ipairs(visual.animationConnections) do
                pcall(function() connection:Disconnect() end)
            end
            for _,track in pairs(visual.animationTracks) do
                pcall(function() track:Stop(0.1) end)
                pcall(function() track:Destroy() end)
            end
            visual.animationConnections={}
            visual.animationTracks={}
        end

        -- Client-only preview: the root is intentionally anchored and moved
        -- with PivotTo so Humanoid:MoveTo/physics cannot leave it frozen.
        -- Motor6D joints still animate normally using the avatar's animation pack.
        local function animateAvatar(model,description)
            stopAnimations()
            local humanoid=model:FindFirstChildOfClass("Humanoid")
            if not humanoid then return end
            local animator=humanoid:FindFirstChildOfClass("Animator")
            if not animator then
                animator=Instance.new("Animator")
                animator.Parent=humanoid
            end
            local tracks={}
            local function load(name,asset,priority)
                local animation=Instance.new("Animation")
                animation.AnimationId="rbxassetid://"..tostring(asset)
                local success,track=pcall(function() return animator:LoadAnimation(animation) end)
                animation:Destroy()
                if success and track then
                    track.Priority=priority
                    track.Looped=(name~="jump")
                    tracks[name]=track
                end
            end
            local function avatarAnimation(field,fallback)
                local success,id=pcall(function() return description[field] end)
                return (success and tonumber(id) and tonumber(id)>0) and tostring(id) or fallback
            end
            local r6Value=humanoid.RigType==Enum.HumanoidRigType.R6
            local defaults=r6Value and {idle="180435571",walk="180426354",jump="125750702",fall="180436148"}
                or {idle="507766666",walk="507777826",jump="507765000",fall="507767968"}
            local account=Players:GetPlayerByUserId(model:GetAttribute("pvPreviewUserId"))
            local source=account and account.Character
            local sourceHumanoid=source and source:FindFirstChildOfClass("Humanoid")
            local animate=sourceHumanoid and sourceHumanoid.RigType==humanoid.RigType
                and source:FindFirstChild("Animate")
            local function animationFor(state,field)
                -- A live target may use game-specific animations rather than
                -- the animation pack currently saved on their profile.
                local group=animate and animate:FindFirstChild(state)
                local clip=group and group:FindFirstChildWhichIsA("Animation",true)
                local id=clip and clip.AnimationId:match("%d+")
                if id then return id end
                return r6Value and defaults[state] or avatarAnimation(field,defaults[state])
            end
            load("idle",animationFor("idle","IdleAnimation"),Enum.AnimationPriority.Idle)
            load("walk",animationFor("walk","WalkAnimation"),Enum.AnimationPriority.Movement)
            load("jump",animationFor("jump","JumpAnimation"),Enum.AnimationPriority.Action)
            load("fall",animationFor("fall","FallAnimation"),Enum.AnimationPriority.Movement)
            visual.animationTracks=tracks

            local playing=nil
            visual.setPose=function(which,speed)
                if visual.model~=model or not model.Parent then return end
                visual.currentPose=which
                if playing~=which then
                    playing=which
                    for name,track in pairs(tracks) do
                        if name~=which then pcall(function() track:Stop(0.12) end) end
                    end
                    local track=tracks[which]
                    if track then pcall(function() track:Play(0.13,1,1) end) end
                end
                if which=="walk" and tracks.walk then
                    pcall(function() tracks.walk:AdjustSpeed(math.clamp((speed or 11)/12,0.7,1.5)) end)
                end
            end
            visual.setPose("idle")
            -- Re-seat the soles after animation/scale updates, including landing.
            -- Jump and walking retain control of their own vertical motion.
            local token=visual.token
            visual.animationConnections[#visual.animationConnections+1]=RunService.Heartbeat:Connect(function()
                if not valid(token) or visual.model~=model or not model.Parent
                    or visual.jumping or visual.currentPose~="idle" then return end
                visual.alignGround(model)
                visual.spawnCFrame=model:GetPivot()
            end)
        end

        -- Each button click queues ONE visual jump in place. Root is anchored
        -- for this client-only avatar, so Humanoid.Jump alone cannot move it.
        -- Use frame-synced vertical motion while the actual jump track plays.
        local function queueVisualJump()
            local model=visual.model
            if not (model and model.Parent and visual.username) then
                status("Spawn a visual player before jumping")
                notify("Spawn a visual player first")
                return
            end
            visual.jumpQueue=visual.jumpQueue+1
            if visual.jumping then return end
            visual.jumping=true
            local token=visual.token
            task.spawn(function()
                local function active()
                    return valid(token) and visual.model==model and model.Parent~=nil
                end
                while active() and visual.jumpQueue>0 do
                    visual.jumpQueue=visual.jumpQueue-1
                    local baseline=model:GetPivot()
                    local started=os.clock()
                    local humanoid=model:FindFirstChildOfClass("Humanoid")
                    local gravity=math.max(0.1,workspace.Gravity)
                    local launchSpeed=humanoid and (humanoid.UseJumpPower and humanoid.JumpPower
                        or math.sqrt(2*gravity*humanoid.JumpHeight)) or 50
                    -- Avoid an unbounded local animation in zero-gravity maps.
                    local airTime=math.min(10,(2*launchSpeed)/gravity)
                    local falling=false
                    if visual.setPose then visual.setPose("jump") end
                    while active() do
                        local elapsed=math.min(os.clock()-started,airTime)
                        local lift=math.max(0,launchSpeed*elapsed-0.5*gravity*elapsed*elapsed)
                        if not falling and elapsed>=launchSpeed/gravity then
                            falling=true
                            if visual.setPose then visual.setPose("fall") end
                        end
                        model:PivotTo(baseline+Vector3.new(0,lift,0))
                        if elapsed>=airTime then break end
                        RunService.RenderStepped:Wait()
                    end
                    if not active() then break end
                    model:PivotTo(baseline)
                    if visual.setPose then visual.setPose("idle") end
                    if visual.jumpQueue>0 then task.wait(0.08) end
                end
                -- Never clear a newer avatar's jump state from an old task.
                if active() then visual.jumping=false end
            end)
        end

        local function removeVisual(closeTrade)
            if visual.nameplateCleanup then visual.nameplateCleanup() end
            if visual.joinToast then
                pcall(function() visual.joinToast:Destroy() end)
                visual.joinToast=nil
            end
            if visual.popup then
                pcall(function() visual.popup:Destroy() end)
                visual.popup=nil
            end
            visual.chatSerial=visual.chatSerial+1 -- cancel queued visual chat and typing effects
            visual.token=visual.token+1 -- invalidate username/avatar loads in progress
            visual.jumpQueue=0 -- cancel queued jumps when removing/replacing avatar
            visual.jumping=false
            stopRoaming()
            stopAnimations()
            visual.spawnCFrame=nil
            local previous=visual.username
            visual.username=nil
            -- Remove the visual-only Weapon Equipping target and any selected
            -- skins before destroying the old avatar.
            local equipTarget=_G.pvVisualWeaponTarget
            if equipTarget and equipTarget.Character==visual.model then
                if _G.pvOtherSkins then _G.pvOtherSkins[equipTarget.UserId]=nil end
                if pvSession.upgradePartner==equipTarget then pvSession.upgradePartner=nil end
                equipTarget.Parent=nil
                equipTarget.Character=nil
                _G.pvVisualWeaponTarget=nil
                if type(_G.pvRefreshWeapWhoList)=="function" then
                    pcall(_G.pvRefreshWeapWhoList)
                end
            end
            if visual.rowConn then pcall(function() visual.rowConn:Disconnect() end) end
            visual.rowConn=nil
            if visual.row then pcall(function() visual.row:Destroy() end) end
            visual.row=nil
            if visual.model then pcall(function() visual.model:Destroy() end) end
            visual.model=nil
            if closeTrade and previous and _G.pvSpoofActive
                and _G.pvSpoofName=="("..previous..")" then
                pcall(cleanupTradeSpoof)
            end
        end
        pvSession.addCleanup(function() removeVisual(true) end)

        local function tradeWithVisual()
            local username=visual.username
            if not (username and visual.model and visual.model.Parent) then
                notify("Spawn a visual player first")
                return
            end
            -- startTradeSpoof builds the existing client-only trade UI.
            -- Do NOT fire a server trade request for this mock player.
            local success,errorMessage=startTradeSpoof(username)
            if success then
                status("Visual trade open: "..username.." (local only)")
                notify("Visual trade opened with "..username)
            else
                status("Could not open visual trade: "..tostring(errorMessage or "unknown error"))
                notify("Visual trade: "..tostring(errorMessage or "unavailable"))
            end
        end

        -- Use the same Inspect template as the Settings > Add Trade Bots menu.
        -- No server Player instance or remote trade is created for this row.
        local function showVisualInspect(username, anchor)
            if visual.username~=username or not (visual.model and visual.model.Parent) then return end
            if visual.popup then
                pcall(function() visual.popup:Destroy() end)
                visual.popup=nil
            end
            local main=playerGui2:FindFirstChild("MainGUI")
            local gameUI=main and main:FindFirstChild("Game")
            local leaderboard=gameUI and gameUI:FindFirstChild("Leaderboard")
            local inspect=leaderboard and leaderboard:FindFirstChild("Inspect")
            if not (inspect and inspect:IsA("GuiObject")) then
                -- The standard Inspect GUI isn't always available during loading.
                -- Avoid accidentally sending trade remotes to a non-player.
                notify("Leaderboard Inspect menu is unavailable - try again shortly")
                return
            end
            local popup=inspect:Clone()
            popup.Name="pvVisualInspect"
            popup:SetAttribute("pvClientVisualPlayer",true)
            -- Never run handlers cloned from the original leaderboard UI.
            for _,item in ipairs(popup:GetDescendants()) do
                if item:IsA("LocalScript") or item:IsA("Script") then
                    item:Destroy()
                end
            end
            popup.Parent=inspect.Parent
            visual.popup=popup
            local frame=popup:FindFirstChild("Container") or popup
            local user=frame:FindFirstChild("Username") or popup:FindFirstChild("Username",true)
            if user and (user:IsA("TextLabel") or user:IsA("TextButton")) then
                user.Text=username
            end
            local prestige=frame:FindFirstChild("Prestige",true)
            if prestige and prestige:IsA("GuiObject") then prestige.Visible=false end
            if anchor and anchor.Parent then
                pcall(function()
                    popup.Position=UDim2.new(popup.Position.X.Scale,popup.Position.X.Offset,
                        anchor.Position.Y.Scale,anchor.Position.Y.Offset)
                end)
            end
            popup.Visible=true
            popup.ZIndex=200
            local function close()
                if visual.popup==popup then visual.popup=nil end
                if popup.Parent then pcall(function() popup:Destroy() end) end
            end
            local trade=popup:FindFirstChild("Trade",true)
            if trade and trade:IsA("GuiButton") then
                trade.Visible=true
                pvSession.connect(trade.Activated,function()
                    if visual.popup~=popup then return end
                    close()
                    -- Same client-only sent-request flow as Add 5 Trade Bots.
                    local shown=false
                    if pvFakeTradeSent then
                        shown=pvFakeTradeSent(username,function(who)
                            if visual.username~=username then return end
                            local success,errorMessage=startTradeSpoof(who)
                            notify(success and ("Trading "..who.." (visual)") or (errorMessage or "Failed to open visual trade"))
                        end)
                    end
                    if shown then notify("Visual trade request sent to "..username)
                    else tradeWithVisual() end
                end)
            end
            local profile=popup:FindFirstChild("Profile",true)
            if profile and profile:IsA("GuiButton") then
                profile.Visible=true
                pvSession.connect(profile.Activated,function()
                    if visual.popup~=popup then return end
                    close()
                    local overrides, validStats=visual.getManualProfileStats()
                    if not validStats then return end
                    local success,errorMessage=pcall(pvOpenBotProfile,username,visual.level,overrides)
                    if not success then notify("Could not open visual profile: "..tostring(errorMessage)) end
                end)
            end
            local closeButton=popup:FindFirstChild("Close",true)
            if closeButton and closeButton:IsA("GuiButton") then
                pvSession.connect(closeButton.Activated,close)
            end
        end

        -- Keep the visual player's leaderboard badge matched to its chosen
        -- MM2 level, instead of retaining the cloned real player's badge art.
        -- Uses the same RankIconsEmpty module already used in ViewProfile.
        -- No real player data or the friend-join banner is modified.
        visual.updateLevelAppearance = function(row, requestedLevel)
            if not row then return end
            local level = tonumber(requestedLevel)
            if not level or level < 1 or level > 100 then return end
            level = math.floor(level)
            local imageAsset
            pcall(function()
                local rankModule=replicatedStorageService:FindFirstChild("RankIconsEmpty")
                if rankModule then imageAsset=require(rankModule)[level] end
            end)
            -- Do not keep another player's prestige marking on a local
            -- level-1-to-100 avatar (prestige is separate in MM2).
            local prestige=row:FindFirstChild("Prestige",true)
            if prestige and prestige:IsA("GuiObject") then prestige.Visible=false end

            -- In the live MM2 leaderboard the number sits inside an Icon
            -- ImageLabel; replace BOTH the numeral and that level's icon.
            -- Some game builds nest the icon under LevelContainer instead.
            local patchedIcon=false
            for _,obj in ipairs(row:GetDescendants()) do
                if (obj:IsA("TextLabel") or obj:IsA("TextButton")) and obj.Name=="Level" then
                    obj.Text=tostring(level)
                    local holder=obj.Parent
                    if holder and (holder:IsA("ImageLabel") or holder:IsA("ImageButton")) then
                        if type(imageAsset)=="string" and imageAsset~="" then
                            holder.Image=imageAsset
                            -- Render the real MM2 rank image with its own colours,
                            -- rather than the colour from the template player's badge.
                            holder.ImageColor3=Color3.new(1,1,1)
                            patchedIcon=true
                        end
                    end
                end
            end
            if not patchedIcon and type(imageAsset)=="string" and imageAsset~="" then
                local levelContainer=row:FindFirstChild("LevelContainer",true)
                local levelFrame=row:FindFirstChild("LevelFrame",true)
                local icon=(levelContainer and levelContainer:FindFirstChild("Icon"))
                    or (levelFrame and levelFrame:FindFirstChild("Icon"))
                if icon and (icon:IsA("ImageLabel") or icon:IsA("ImageButton")) then
                    icon.Image=imageAsset
                    icon.ImageColor3=Color3.new(1,1,1)
                end
            end
        end

        -- Adjust the visible level and keep the spawned player alive.
        local function setVisualLevel(input)
            local level=tonumber(tostring(input or ""))
            if not level or level~=math.floor(level) or level<1 or level>100 then
                notify("Choose a whole level between 1 and 100")
                return false
            end
            visual.level=level
            if visual.row and visual.row.Parent then
                visual.updateLevelAppearance(visual.row,level)
            end
            if visual.username then status("@"..visual.username.." visual level: "..level) end
            return true
        end

        -- FAKE CHAT: local-only bubble on a client visual; no game chat, remote,
        -- network message or player account is involved.
        -- Prefer Roblox's native bubble renderer for its exact game styling.
        -- Fall back to a small animated GUI if the current client cannot use it.
        local function previewBubble(head,message,seconds,typing)
            if not (head and head.Parent) then return nil end
            local previous=head:FindFirstChild("pvVisualChatPreview")
            if previous then pcall(function() previous:Destroy() end) end
            local TextService=game:GetService("TextService")
            local font=Enum.Font.GothamMedium
            local txtSize=19
            local maxTextWidth=220
            local width,height=110,46
            if not typing then
                local success,measured=pcall(function()
                    return TextService:GetTextSize(message,txtSize,font,Vector2.new(maxTextWidth,160))
                end)
                if success and measured then
                    width=math.clamp(measured.X+34,92,252)
                    height=math.clamp(measured.Y+22,40,96)
                end
            end
            local bubble=Instance.new("BillboardGui")
            bubble.Name="pvVisualChatPreview"
            bubble.Adornee=head
            bubble.Size=UDim2.fromOffset(width,height+18)
            -- Keep the message above (not overlapping) the visual username.
            -- World-space Y avoids unwanted sideways movement when the head tilts.
            bubble.StudsOffsetWorldSpace=Vector3.new(0,head.Size.Y/2+4.9,0)
            bubble.AlwaysOnTop=true
            bubble.LightInfluence=0
            bubble.MaxDistance=100
            bubble.Parent=head

            local scale=Instance.new("UIScale")
            scale.Scale=0.9
            scale.Parent=bubble

            local shadow=Instance.new("ImageLabel")
            shadow.Name="BubbleShadow"
            shadow.BackgroundTransparency=1
            shadow.Image="rbxassetid://6014261993"
            shadow.ImageColor3=Color3.new(0,0,0)
            shadow.ImageTransparency=0.80
            shadow.ScaleType=Enum.ScaleType.Slice
            shadow.SliceCenter=Rect.new(49,49,450,450)
            shadow.Size=UDim2.new(1,16,0,height+12)
            shadow.Position=UDim2.fromOffset(-8,-1)
            shadow.Parent=bubble

            local back=Instance.new("Frame")
            back.Name="BubbleBackground"
            back.Size=UDim2.fromOffset(width,height)
            back.BackgroundColor3=Color3.fromRGB(250,250,250)
            back.BackgroundTransparency=1
            back.BorderSizePixel=0
            back.Parent=bubble
            corner(back,math.min(18,math.floor(height*0.5)))

            local tail=Instance.new("Frame")
            tail.Name="BubbleTail"
            tail.AnchorPoint=Vector2.new(0.5,0)
            tail.Size=UDim2.fromOffset(14,14)
            tail.Position=UDim2.new(0.5,0,0,height-4)
            tail.Rotation=45
            tail.BackgroundColor3=back.BackgroundColor3
            tail.BackgroundTransparency=1
            tail.BorderSizePixel=0
            tail.ZIndex=(back.ZIndex or 1)-1
            tail.Parent=bubble

            local label=Instance.new("TextLabel")
            label.Name="BubbleText"
            label.Position=UDim2.fromOffset(14,7)
            label.Size=UDim2.new(1,-28,1,-14)
            label.BackgroundTransparency=1
            label.TextColor3=Color3.fromRGB(48,48,48)
            label.TextTransparency=1
            label.TextWrapped=true
            label.Text=message
            label.Font=font
            label.TextSize=txtSize
            label.LineHeight=1.0
            label.TextXAlignment=Enum.TextXAlignment.Center
            label.TextYAlignment=Enum.TextYAlignment.Center
            label.Parent=back

            local ease=TweenInfo.new(0.18,Enum.EasingStyle.Back,Enum.EasingDirection.Out)
            Tween:Create(scale,ease,{Scale=1}):Play()
            Tween:Create(shadow,TweenInfo.new(0.12),{ImageTransparency=0.87}):Play()
            Tween:Create(back,TweenInfo.new(0.12),{BackgroundTransparency=0}):Play()
            Tween:Create(tail,TweenInfo.new(0.12),{BackgroundTransparency=0}):Play()
            Tween:Create(label,TweenInfo.new(0.12),{TextTransparency=0}):Play()
            if not typing then
                task.delay(seconds or 4.5,function()
                    if not bubble.Parent then return end
                    Tween:Create(shadow,TweenInfo.new(0.16),{ImageTransparency=1}):Play()
                    Tween:Create(back,TweenInfo.new(0.16),{BackgroundTransparency=1}):Play()
                    Tween:Create(tail,TweenInfo.new(0.16),{BackgroundTransparency=1}):Play()
                    Tween:Create(label,TweenInfo.new(0.16),{TextTransparency=1}):Play()
                    Tween:Create(scale,TweenInfo.new(0.16),{Scale=0.95}):Play()
                    task.delay(0.18,function()
                        pcall(function() bubble:Destroy() end)
                    end)
                end)
            end
            return bubble
        end

        local function sayAsVisual(message)
            local model=visual.model
            local username=visual.username
            local head=model and model:FindFirstChild("Head")
            if not (head and head:IsA("BasePart") and username and model.Parent) then
                notify("Spawn a visual player first")
                status("Spawn a visual player before using fake chat")
                return false
            end
            message=tostring(message or ""):match("^%s*(.-)%s*$") or ""
            message=message:gsub("[\r\n]+"," ")
            if message=="" then
                notify("Type a fake chat message first")
                return false
            end
            -- Truncate without splitting a multi-byte Roblox username/message.
            local okCut,byteIndex=pcall(function() return utf8.offset(message,161) end)
            if okCut and byteIndex then message=message:sub(1,byteIndex-1)
            elseif #message>400 then message=message:sub(1,400) end
            if os.clock()-visual.lastChatAt<0.45 then
                status("Wait a moment before the next bubble")
                return false
            end
            visual.lastChatAt=os.clock()
            visual.chatSerial=visual.chatSerial+1
            local serial=visual.chatSerial
            local token=visual.token
            -- Show the actual chat message immediately: no initial typing dots
            -- and no artificial delay before Roblox's bubble animation.
            if not (valid(token) and visual.chatSerial==serial and visual.model==model
                    and model.Parent and head.Parent) then return false end

            -- A real player's bubble sits higher above the head than the
            -- engine places a bubble on this client-only NPC by default.
            -- Give native/legacy bubble chat an invisible welded origin so its
            -- own built-in sizing and animation remain intact, but at the
            -- correct height. The anchor is owned by the model and disappears
            -- with it when the visual player is removed.
            local nativeOrigin=head
            pcall(function()
                local anchor=model:FindFirstChild("pvVisualChatOrigin")
                if anchor and not anchor:IsA("BasePart") then
                    anchor:Destroy()
                    anchor=nil
                end
                if not anchor then
                    anchor=Instance.new("Part")
                    anchor.Name="pvVisualChatOrigin"
                    anchor.Size=Vector3.new(0.15,0.15,0.15)
                    anchor.Transparency=1
                    anchor.CanCollide=false
                    anchor.CanTouch=false
                    anchor.CanQuery=false
                    anchor.Massless=true
                    anchor.Anchored=false
                    anchor.CFrame=head.CFrame*CFrame.new(0,1.7,0)
                    anchor.Parent=model
                    local weld=Instance.new("WeldConstraint")
                    weld.Part0=head
                    weld.Part1=anchor
                    weld.Parent=anchor
                end
                nativeOrigin=anchor
            end)

            local usedNative=false
            -- The game's own Roblox bubble chat provides the matching
            -- pop/stack/fade animation; don't modify global chat settings.
            local textChat=game:GetService("TextChatService")
            local config=textChat:FindFirstChildOfClass("BubbleChatConfiguration")
            local configEnabled=true
            if config then
                pcall(function() configEnabled=config.Enabled end)
            end
            if configEnabled then
                usedNative=pcall(function()
                    textChat:DisplayBubble(nativeOrigin,message)
                end)
            end
            if not usedNative then
                -- Legacy chat engine, if present, uses the same game bubble
                -- style as real players in older MM2 clients.
                local okLegacy,legacy=pcall(function() return game:GetService("Chat") end)
                if okLegacy and legacy then
                    local legacyEnabled=false
                    pcall(function() legacyEnabled=legacy.BubbleChatEnabled end)
                    if legacyEnabled then
                        usedNative=pcall(function()
                            legacy:Chat(nativeOrigin,message,Enum.ChatColor.White)
                        end)
                    end
                end
            end
            if not usedNative then
                previewBubble(head,message,math.clamp(3+#message*0.055,4,8),false)
            end
            status("@"..username.." said: "..message:sub(1,42).." (local only)")
            return true
        end

        -- MM2 shows a thin yellow XP progress underline on the LOCAL player.
        -- A cloned leaderboard row inherits the decoration; it must not be
        -- shown on a client-side visual player. Never touch the real row.
        visual.hideLocalXpUnderline = function(clonedRow)
            if not clonedRow or not clonedRow:GetAttribute("pvClientVisualPlayer") then return end
            for _,item in ipairs(clonedRow:GetDescendants()) do
                if item:IsA("GuiObject") and not item:IsA("TextLabel") and not item:IsA("TextButton") then
                    local key=item.Name:lower()
                    local first=item.AbsoluteSize
                    local text2=item.Size
                    local horizontal=(first.X>=24 and first.Y>0 and first.Y<=9)
                        or (text2.Y.Scale==0 and text2.Y.Offset>0 and text2.Y.Offset<=9
                            and (text2.X.Scale>0 or text2.X.Offset>=24))
                    -- Progress fill names can vary between MM2 UI builds.
                    local progressName=(key:find("xp",1,true)~=nil)
                        or (key:find("progress",1,true)~=nil)
                        or (key:find("experience",1,true)~=nil)
                        or (key:find("underline",1,true)~=nil)
                    local bgValue=item.BackgroundColor3
                    local goldBg=(item.BackgroundTransparency<0.96 and bgValue.R>0.55
                        and bgValue.G>0.34 and bgValue.G<0.94 and bgValue.B<0.44 and bgValue.R>bgValue.G)
                    local goldImage=false
                    if item:IsA("ImageLabel") or item:IsA("ImageButton") then
                        local tint=item.ImageColor3
                        goldImage=(item.ImageTransparency<0.96 and tint.R>0.55
                            and tint.G>0.34 and tint.G<0.94 and tint.B<0.44
                            and tint.R>tint.G)
                    end
                    if horizontal and (goldBg or goldImage or progressName) then
                        item.Visible=false
                    end
                end
            end
        end

        local function makeLeaderboardRow(username)
            local main=playerGui2:FindFirstChild("MainGUI")
            local gameUI=main and main:FindFirstChild("Game")
            local leaderboard=gameUI and gameUI:FindFirstChild("Leaderboard")
            local cont=leaderboard and leaderboard:FindFirstChild("Container")
            if not cont then return nil end
            local template
            -- Prefer another REAL player's row as a template: the local
            -- player's row uniquely has the yellow XP progress underline.
            -- Still handle servers where only the local row is available.
            for _,child in ipairs(cont:GetChildren()) do
                if child:IsA("Frame") and child:FindFirstChild("PlayerLabel")
                    and child:FindFirstChild("ActionButton")
                    and not child:GetAttribute("pvClientVisualPlayer")
                    and not child.Name:match("^porkbot_") then
                    local lbl=child:FindFirstChild("PlayerLabel")
                    local name=lbl and tostring(lbl.Text):lower() or ""
                    local selfRow=(name==playerGui.Name:lower())
                        or (name==playerGui.DisplayName:lower())
                        or (child.Name==playerGui.Name)
                        or (child.Name==tostring(playerGui.UserId))
                    if not template then template=child end
                    if not selfRow then template=child break end
                end
            end
            local row
            if template then
                row=template:Clone()
                row.LayoutOrder=template.LayoutOrder+1
                for _,desc in ipairs(row:GetDescendants()) do
                    if desc:IsA("Script") or desc:IsA("LocalScript") or desc:IsA("ModuleScript") then
                        desc:Destroy()
                    end
                end
            else
                -- Custom fallback if this MM2 version doesn't expose the usual row.
                row=Instance.new("Frame")
                row.Size=UDim2.new(1,-pxValue(8),0,pxValue(28))
                row.BackgroundColor3=PINK_OFF
                row.BorderSizePixel=0
                corner(row,pxValue(6))
                local playerLabel=Instance.new("TextLabel")
                playerLabel.Name="PlayerLabel"
                playerLabel.Size=UDim2.new(1,-pxValue(8),1,0)
                playerLabel.Position=UDim2.fromOffset(pxValue(4),0)
                playerLabel.BackgroundTransparency=1
                playerLabel.Font=Enum.Font.GothamBold
                playerLabel.TextSize=pxValue(9)
                playerLabel.TextColor3=TValue.txt
                playerLabel.TextXAlignment=Enum.TextXAlignment.Left
                playerLabel.Parent=row
            end
            row.Name="pvVisualPlayer_"..username
            row:SetAttribute("pvClientVisualPlayer",true)
            local playerLabel=row:FindFirstChild("PlayerLabel",true)
            if playerLabel and (playerLabel:IsA("TextLabel") or playerLabel:IsA("TextButton")) then
                playerLabel.Text=username
                -- Font, TextSize, TextScaled and truncation stay as cloned.
            end
            -- Update the native MM2 level icon and number together.
            visual.updateLevelAppearance(row,visual.level)
            -- Remove the copied local-player-only gold XP underline.
            visual.hideLocalXpUnderline(row)
            -- A cloned GUI button has no inherited event connections; never
            -- use the real leaderboard's inspect/trade request handlers.
            local action=row:FindFirstChild("ActionButton",true)
            if not (action and action:IsA("GuiButton")) then
                action=Instance.new("TextButton")
                action.Name="pvVisualTradeAction"
                action.Size=UDim2.fromScale(1,1)
                action.BackgroundTransparency=1
                action.Text=""
                action.ZIndex=row.ZIndex+10
                action.Parent=row
            end
            row.Parent=cont
            -- Give layout a frame to resolve AbsoluteSize before the second
            -- geometry-based cleanup (UI may use Scale rather than Offset).
            task.defer(function()
                if row.Parent and row:GetAttribute("pvClientVisualPlayer") then
                    visual.hideLocalXpUnderline(row)
                end
            end)
            task.delay(0.12,function()
                if row.Parent and row:GetAttribute("pvClientVisualPlayer") then
                    visual.hideLocalXpUnderline(row)
                end
            end)
            visual.rowConn=action.Activated:Connect(function()
                if visual.row==row and visual.username==username and isCurrent() then
                    showVisualInspect(username,row)
                end
            end)
            return row
        end

        -- Keep the native renderer, with explicit wall visibility for this
        -- client-only avatar. Release the viewer override whenever it is hidden.
        local function configureVisualUsername(model, username)
            local humanoid=model and model:FindFirstChildOfClass("Humanoid")
            local head=model and model:FindFirstChild("Head")
            if not (humanoid and head and head:IsA("BasePart")) then return end
            if visual.nameplateCleanup then visual.nameplateCleanup() end
            -- Finish a running diagnostic before capturing original values.
            if type(_G.pvNameOcclusionTestRestore)=="function" then
                _G.pvNameOcclusionTestRestore()
            end
            local existing=head:FindFirstChild("pvVisibleUsernameFallback")
            if existing then existing:Destroy() end
            humanoid.DisplayName=username
            humanoid.NameDisplayDistance=100
            humanoid.HealthDisplayType=Enum.HumanoidHealthDisplayType.AlwaysOff
            humanoid.HealthDisplayDistance=0
            humanoid.DisplayDistanceType=Enum.HumanoidDisplayDistanceType.Subject

            local originals={}
            local connections={}
            local pendingHumanoid
            local currentViewer, lastVisible
            local cleaned=false
            local cleanup
            cleanup=function()
                if cleaned then return end
                cleaned=true
                if pendingHumanoid then pendingHumanoid:Disconnect(); pendingHumanoid=nil end
                for _,connection in ipairs(connections) do connection:Disconnect() end
                for key,original in pairs(originals) do
                    pcall(function()
                        -- Preserve a later setting written by another feature.
                        if key.Parent and key.NameOcclusion==Enum.NameOcclusion.NoOcclusion then
                            key.NameOcclusion=original
                        end
                    end)
                end
                if visual.nameplateCleanup==cleanup then visual.nameplateCleanup=nil end
            end
            visual.nameplateCleanup=cleanup
            local function allowNativeName(handle)
                if cleaned or not isCurrent() or visual.model~=model or not model.Parent then return end
                if originals[handle]==nil then originals[handle]=handle.NameOcclusion end
                handle.NameOcclusion=Enum.NameOcclusion.NoOcclusion
            end
            local function restoreViewer(handle)
                local original=handle and originals[handle]
                if original~=nil and handle.Parent and handle.NameOcclusion==Enum.NameOcclusion.NoOcclusion then
                    handle.NameOcclusion=original
                end
            end
            local function selectViewer(handle)
                restoreViewer(currentViewer)
                currentViewer=handle
                lastVisible=nil
            end
            local function watchCharacter(character)
                if pendingHumanoid then pendingHumanoid:Disconnect(); pendingHumanoid=nil end
                selectViewer(nil)
                if cleaned or not character then return end
                local humanoid2=character:FindFirstChildOfClass("Humanoid")
                if humanoid2 then
                    selectViewer(humanoid2)
                else
                    pendingHumanoid=character.ChildAdded:Connect(function(child)
                        if child:IsA("Humanoid") and playerGui.Character==character then
                            selectViewer(child)
                            if pendingHumanoid then pendingHumanoid:Disconnect(); pendingHumanoid=nil end
                        end
                    end)
                end
            end
            local rayParams=RaycastParams.new()
            rayParams.FilterType=Enum.RaycastFilterType.Exclude
            rayParams.IgnoreWater=true
            local function clearView(camera)
                local origin=camera.CFrame.Position
                local direction=head.Position-origin
                if direction.Magnitude<0.01 then return true end
                local ignored={model}
                if playerGui.Character then ignored[#ignored+1]=playerGui.Character end
                -- Invisible triggers and other humanoid models should not act
                -- as walls. Recast past them to find any solid wall behind.
                for _=1,24 do
                    rayParams.FilterDescendantsInstances=ignored
                    local hit=workspace:Raycast(origin,direction,rayParams)
                    if not hit then return true end
                    local part=hit.Instance
                    local skip
                    if part:IsA("BasePart") then
                        local opacity=(1-part.Transparency)*(1-part.LocalTransparencyModifier)
                        if opacity<0.01 then skip=part end
                    end
                    local ancestor=part.Parent
                    while not skip and ancestor and ancestor~=workspace do
                        if ancestor:IsA("Model") and ancestor:FindFirstChildOfClass("Humanoid") then
                            skip=ancestor
                            break
                        end
                        ancestor=ancestor.Parent
                    end
                    if not skip then return false end
                    ignored[#ignored+1]=skip
                end
                return false -- conservative if too many overlapping objects
            end
            local function updateVisibility()
                if cleaned then return end
                if not isCurrent() or visual.model~=model or not model.Parent or not head.Parent then
                    cleanup()
                    return
                end
                local camera=workspace.CurrentCamera
                local visible=false
                if camera then
                    local point,onScreen=camera:WorldToViewportPoint(head.Position)
                    local root=playerGui.Character and playerGui.Character:FindFirstChild("HumanoidRootPart")
                    local viewerPosition=root and root.Position or camera.CFrame.Position
                    if onScreen and point.Z>0 and (head.Position-viewerPosition).Magnitude<=100 then
                        visible=clearView(camera)
                    end
                end
                if visible~=lastVisible then
                    lastVisible=visible
                    humanoid.DisplayDistanceType=visible and Enum.HumanoidDisplayDistanceType.Subject
                        or Enum.HumanoidDisplayDistanceType.None
                    if visible then
                        if currentViewer then allowNativeName(currentViewer) end
                    else
                        restoreViewer(currentViewer)
                    end
                end
            end
            connections[#connections+1]=playerGui.CharacterAdded:Connect(watchCharacter)
            connections[#connections+1]=model.Destroying:Connect(cleanup)
            allowNativeName(humanoid)
            watchCharacter(playerGui.Character)
            updateVisibility()
            connections[#connections+1]=RunService.RenderStepped:Connect(updateVisibility)
        end


        -- Match MM2's REAL worn-weapon mounting rather than guessing rotations.
        -- MM2 displays use WeaponDisplays/{Knife,Gun}Display with a RigidConstraint
        -- pointing to an Attachment on a live character. Their Part1 attachment
        -- determines the orientation of the weapon mesh. Read BOTH attachments
        -- and use that exact torso-local transform for the preview's weld.
        -- The weapon looks are still the normal DefaultKnife / DefaultGun.
        local function addVisualDefaultBackWeapons(model)
            if not model or not model.Parent then return false end
            local defs={
                {slot="Knife", name="pvVisualBackDefaultKnife", torso="UpperTorso", anchor="KnifeBack",
                 id="121944778", texture="121944805", size=Vector3.new(0.4,3,0.7), scale=Vector3.new(1,1,1)},
                {slot="Gun", name="pvVisualBackDefaultGun", torso="LowerTorso", anchor="GunBelt",
                 id="79401392", texture="91723031", size=Vector3.new(0.2,1.83,1.03), scale=Vector3.new(1.6,1.6,1.6)},
            }
            local displays=workspace:FindFirstChild("WeaponDisplays")
            local fullNative=0
            for _,def in ipairs(defs) do
                local best, bestScore=nil, -1
                -- Prefer a genuine default item being worn by a REAL player.
                -- (Our locally created visual is not a Players entry.)
                if displays then
                    for _,data in ipairs(displays:GetChildren()) do
                        if data.Name==def.slot.."Display" and data:IsA("BasePart")
                            and not data:GetAttribute("pvMade") then
                            local rigidConstraint=data:FindFirstChildOfClass("RigidConstraint")
                            local a0Value=rigidConstraint and rigidConstraint.Attachment0
                            local a1Value=rigidConstraint and rigidConstraint.Attachment1
                            local ownerChar=a0Value and a0Value.Parent and a0Value.Parent.Parent
                            local owner=ownerChar and Players:GetPlayerFromCharacter(ownerChar)
                            if owner and a0Value and a1Value and a0Value:IsA("Attachment")
                                and a1Value:IsA("Attachment") and a0Value.Parent:IsA("BasePart") then
                                local mesh=data:IsA("MeshPart") and data.MeshId
                                    or (data:FindFirstChildOfClass("SpecialMesh")
                                        and data:FindFirstChildOfClass("SpecialMesh").MeshId)
                                local currentMesh=data:FindFirstChildOfClass("SpecialMesh")
                                local texture=data:IsA("MeshPart") and data.TextureID
                                    or (currentMesh and currentMesh.TextureId)
                                local meshNumber=mesh and tostring(mesh):match("%d+")
                                local textureNumber=texture and tostring(texture):match("%d+")
                                -- Base meshes are reused across several MM2 skins,
                                -- so only clone a native appearance if BOTH the
                                -- mesh and texture match the actual default item.
                                local exactDefault=meshNumber==def.id
                                    and textureNumber==def.texture
                                local onNativeAnchor=(a0Value.Name==def.anchor)
                                local score=(exactDefault and 100 or 0)
                                    +(onNativeAnchor and 20 or 0)
                                    +(owner~=playerGui and 5 or 0)
                                if score>bestScore then
                                    best={src=data, a0=a0Value, a1=a1Value, owner=owner,
                                          exact=exactDefault, torsoName=a0Value.Parent.Name}
                                    bestScore=score
                                end
                            end
                        end
                    end
                end

                local nativeScore=best and bestScore or 0
                local scoreName="pvBackNativeScore"..def.slot
                -- A later real-player reference may be better than the one
                -- available on spawn. Only rebuild if the reference improves.
                local previous=model:GetAttribute(scoreName)
                if previous==nil or nativeScore>previous then
                    local success=pcall(function()
                        local torso=model:FindFirstChild(best and best.torsoName or def.torso)
                            or model:FindFirstChild(def.torso) or model:FindFirstChild("Torso")
                        if not (torso and torso:IsA("BasePart")) then return end

                        local localPose
                        if best then
                            -- Same mounting equation used by RigidConstraint:
                            -- World(Attachment0) == World(Attachment1).
                            -- The weld uses this result as its Part0->Part1 C0.
                            localPose=best.a0.CFrame * best.a1.CFrame:Inverse()
                        else
                            -- No real worn weapon in this server yet. Use a
                            -- temporary mount; retry for a native sample below.
                            local nativeAnchor=torso:FindFirstChild(def.anchor)
                            if nativeAnchor and nativeAnchor:IsA("Attachment") then
                                localPose=nativeAnchor.CFrame
                            elseif def.slot=="Knife" then
                                localPose=CFrame.new(0,-0.05,0.58)
                                    * CFrame.Angles(0,0,math.rad(-75))
                            else
                                -- In normal MM2 the default gun is at the belt,
                                -- NOT on the shoulder next to the knife.
                                localPose=CFrame.new(0.73,-0.27,0.12)
                                    * CFrame.Angles(math.rad(-90),0,0)
                            end
                        end

                        local part
                        if best and best.exact then
                            -- Copy the source part's actual MM2 scaling and
                            -- mesh appearance; no hand-calibrated sizes.
                            part=best.src:Clone()
                            for _,obj in ipairs(part:GetChildren()) do
                                if not obj:IsA("SpecialMesh")
                                   and not obj:IsA("SurfaceAppearance") then
                                    obj:Destroy()
                                end
                            end
                        else
                            -- If nobody is wearing a default, use its REAL
                            -- default mesh while still copying the live mount.
                            part=Instance.new("Part")
                            part.Size=def.size
                            part.Material=Enum.Material.SmoothPlastic
                            part.Color=Color3.fromRGB(163,162,165)
                            local mesh=Instance.new("SpecialMesh")
                            mesh.Name="Mesh"
                            mesh.MeshType=Enum.MeshType.FileMesh
                            mesh.MeshId="rbxassetid://"..def.id
                            mesh.TextureId="rbxassetid://"..def.texture
                            mesh.Scale=def.scale
                            mesh.Parent=part
                        end
                        part.Name=def.name
                        part.Transparency=0
                        part.LocalTransparencyModifier=0
                        part.Anchored=false
                        part.CanCollide=false
                        part.CanTouch=false
                        part.CanQuery=false
                        part.Massless=true
                        part.CastShadow=false
                        part.CFrame=torso.CFrame*localPose

                        local weld=Instance.new("Weld")
                        weld.Name="pvNativeBackWeaponWeld"
                        weld.Part0=torso
                        weld.Part1=part
                        weld.C0=localPose
                        weld.C1=CFrame.new()
                        weld.Parent=part
                        part.Parent=model
                        -- Weapon Equipping can replace the default preview weapon.
                        -- Keep it hidden if a higher-quality native placement
                        -- sample arrives after the visual weapon was equipped.
                        if model:GetAttribute("pvVisualHideDefault"..def.slot) then
                            part.Transparency=1
                            part.LocalTransparencyModifier=1
                        end
                        -- New part gets the same name; destroy old only after
                        -- successful replacement to avoid flickering on retry.
                        for _,child in ipairs(model:GetChildren()) do
                            if child~=part and child.Name==def.name then
                                child:Destroy()
                            end
                        end
                        model:SetAttribute(scoreName,nativeScore)
                    end)
                end
                if model:GetAttribute(scoreName) and model:GetAttribute(scoreName)>=100 then
                    fullNative=fullNative+1
                end
            end
            model:SetAttribute("pvDefaultBackWeapons",model:FindFirstChild("pvVisualBackDefaultKnife")~=nil
                and model:FindFirstChild("pvVisualBackDefaultGun")~=nil)
            -- Wait for the game's WeaponDisplays if they appear after spawn.
            -- Stop retrying once both exact default references have been found.
            return fullNative==2
        end

