        visual.lastLoggedSpawnIndex=nil
        visual.pickLoggedFloor=function()
            for _,map in ipairs(visual.spawnMapLog.maps or {}) do
                -- The logger recorded this exact top-level map Model in Workspace.
                local anchorName=tostring(map.anchorPath or ""):match("^Workspace%.([^%.]+)$")
                local anchor=anchorName and workspace:FindFirstChild(anchorName)
                if anchor and anchor:IsA("Model") then
                    local spots=map.points or {}
                    if #spots>0 then
                        local ignored={}
                        for _,player in ipairs(Players:GetPlayers()) do
                            if player.Character then ignored[#ignored+1]=player.Character end
                        end
                        local cast=RaycastParams.new()
                        cast.FilterType=Enum.RaycastFilterType.Exclude
                        cast.FilterDescendantsInstances=ignored
                        cast.IgnoreWater=true
                        cast.RespectCanCollide=true
                        local overlap=OverlapParams.new()
                        overlap.FilterType=Enum.RaycastFilterType.Exclude
                        overlap.FilterDescendantsInstances=ignored
                        overlap.MaxParts=60
                        local first=math.random(1,#spots)
                        -- Try each logged square if necessary, starting randomly each spawn.
                        for step=0,#spots-1 do
                            local index=(first+step-1)%#spots+1
                            if #spots==1 or index~=visual.lastLoggedSpawnIndex then
                                local point=spots[index]
                                local floor=Vector3.new(point.x,point.y,point.z)
                                if point.relative then
                                    local rel=point.relative
                                    floor=anchor:GetPivot():PointToWorldSpace(Vector3.new(rel.x,rel.y,rel.z))
                                end
                                -- Recheck the *logged floor*, not a ceiling or floor below it.
                                local hit=workspace:Raycast(floor+Vector3.new(0,4,0),
                                    Vector3.new(0,-10,0),cast)
                                if hit and hit.Normal.Y>=0.72
                                    and math.abs(hit.Position.Y-floor.Y)<=1.5
                                    and hit.Instance:IsDescendantOf(anchor) then
                                    local clear=true
                                    -- This box starts just above the logged surface.
                                    local around=workspace:GetPartBoundsInBox(
                                        CFrame.new(floor.X,hit.Position.Y+3,floor.Z),
                                        Vector3.new(1.5,4.7,1.5),overlap)
                                    for _,part in ipairs(around) do
                                        if part:IsA("BasePart") and part.CanCollide then
                                            clear=false
                                            break
                                        end
                                    end
                                    if clear then
                                        visual.lastLoggedSpawnIndex=index
                                        return Vector3.new(floor.X,hit.Position.Y,floor.Z),map.mapName
                                    end
                                end
                            end
                        end
                    end
                end
            end
            return nil
        end

        local function createAvatar(username, userId, description)
            local account=Players:GetPlayerByUserId(userId)
            local source=account and account.Character
            local sourceHumanoid=source and source:FindFirstChildOfClass("Humanoid")
            local reference=sourceHumanoid
                or (playerGui.Character and playerGui.Character:FindFirstChildOfClass("Humanoid"))
            local rigType=reference and reference.RigType or Enum.HumanoidRigType.R15
            -- Preserve the account's supplied body proportions. The previous
            -- version applied universe avatar settings on top and could stretch it.
            -- A present target can supply its actual in-game description.
            if sourceHumanoid then
                local success,current=pcall(function() return sourceHumanoid:GetAppliedDescription() end)
                if success and current then description=current end
            end
            pcall(function() description.UseAvatarSettings=false end)
            local success,model=pcall(function()
                return Players:CreateHumanoidModelFromDescriptionAsync(description,rigType)
            end)
            if not success or not model then
                success,model=pcall(function()
                    return Players:CreateHumanoidModelFromDescription(description,rigType)
                end)
            end
            if not success or not model then return nil,"Roblox could not load this avatar" end
            local built,why=pcall(function()
                -- Use the account's exact username as the model name, just like
                -- a regular Roblox character (including original capitalization).
                model.Name=username
                model:SetAttribute("pvClientVisualPlayer",true)
                model:SetAttribute("pvPreviewUserId",userId)
                for _,part in ipairs(model:GetDescendants()) do
                    if part:IsA("BasePart") then
                        -- Anchored parts were the cause of the frozen robot pose.
                        part.Anchored=false
                        part.CanCollide=false
                        part.CanTouch=false
                        part.CanQuery=false
                        part.Massless=true
                    elseif part:IsA("Script") or part:IsA("LocalScript") then
                        part:Destroy()
                    end
                end
                local humanoid=model:FindFirstChildOfClass("Humanoid")
                if not humanoid then error("Avatar has no Humanoid") end
                local rootPart=model:FindFirstChild("HumanoidRootPart")
                if not rootPart then error("Avatar has no HumanoidRootPart") end
                -- This is a visual-only avatar. Move its anchored root using
                -- PivotTo so client NPC physics cannot freeze it in place.
                rootPart.CanCollide=false
                rootPart.CanQuery=false
                rootPart.Anchored=true
                rootPart.Massless=false
                model.PrimaryPart=rootPart
                humanoid.AutoRotate=false
                humanoid.PlatformStand=false
                if reference then
                    for _,property in ipairs({"WalkSpeed","UseJumpPower","JumpPower","JumpHeight"}) do
                        pcall(function() humanoid[property]=reference[property] end)
                    end
                end
                local character=playerGui.Character
                local root=character and character:FindFirstChild("HumanoidRootPart")
                local camera=workspace.CurrentCamera
                local origin=root and root.CFrame or (camera and camera.CFrame) or CFrame.new(0,8,0)
                -- Place the visual on a randomly selected logged floor square.
                -- The 3.5-stud offset is temporary; alignGround adjusts the feet exactly.
                local loggedFloor,loggedMap=visual.pickLoggedFloor()
                local oldTarget=(origin*CFrame.new(5,0,-4)).Position
                local oldPosition=Vector3.new(oldTarget.X,oldTarget.Y,oldTarget.Z)
                local oldLook=Vector3.new(origin.Position.X,oldTarget.Y,origin.Position.Z)
                if (oldLook-oldPosition).Magnitude<0.1 then
                    oldLook=oldPosition+Vector3.new(0,0,-1)
                end
                local originalNearbyCFrame=CFrame.lookAt(oldPosition,oldLook)
                if loggedFloor then
                    local position=loggedFloor+Vector3.new(0,3.5,0)
                    local yaw=math.random()*math.pi*2
                    model:PivotTo(CFrame.new(position)*CFrame.Angles(0,yaw,0))
                    model:SetAttribute("pvLoggedSpawnMap",loggedMap)
                    model:SetAttribute("pvLoggedFloor",loggedFloor)
                else
                    -- Other MM2 maps are not included in this Lobby-only log.
                    model:PivotTo(originalNearbyCFrame)
                end
                -- Require the avatar's actual Head as the overhead label anchor.
                local head=model:FindFirstChild("Head")
                if not (head and head:IsA("BasePart")) then
                    error("Avatar has no direct Head part for its username label")
                end
                model.Parent=workspace
                if not visual.alignGround(model) then
                    if loggedFloor then
                        -- If the map changed while the avatar was loading, fall back
                        -- to the old nearby placement rather than leave it in mid-air.
                        model:PivotTo(originalNearbyCFrame)
                        model:SetAttribute("pvLoggedSpawnMap",nil)
                        model:SetAttribute("pvLoggedFloor",nil)
                    end
                    if not visual.alignGround(model) then
                        error("No floor found at a logged or nearby spawn position")
                    end
                end
                -- Match real MM2 weapon poses when the game has native displays.
                -- Does not equip tools, edit inventories or send trade remotes.
                pcall(addVisualDefaultBackWeapons,model)
                task.spawn(function()
                    -- Some servers stream character weapon displays in late.
                    -- Upgrade the temporary mounts to native poses if found.
                    for _=1,12 do
                        if not isCurrent() or not model.Parent then return end
                        local success2,matched=pcall(addVisualDefaultBackWeapons,model)
                        if success2 and matched then return end
                        task.wait(1.5)
                    end
                end)
            end)
            if not built then
                pcall(function() model:Destroy() end)
                return nil,tostring(why)
            end
            return model,nil,description
        end

        local section=Instance.new("Frame")
