        levelBox.Name="pvVisualPlayerLevel"
        -- Leave this EMPTY: the user chooses their own level.
        levelBox.Text=""
        levelBox.ClearTextOnFocus=false
        -- Update the visual leaderboard level immediately as the user types.
        -- Empty/incomplete/invalid text leaves the last valid level unchanged.
        pvSession.connect(levelBox:GetPropertyChangedSignal("Text"),function()
            local typed=tostring(levelBox.Text or ""):match("^%s*(.-)%s*$") or ""
            if typed:match("^%d+$") then
                local value=tonumber(typed)
