        visual.spawn=function(onReady, upgradeUsername)
            -- nil means manual Spawn Player; an empty upgrade input means random.
            local typed=tostring(upgradeUsername~=nil and upgradeUsername or usernameBox.Text or ""):match("^%s*(.-)%s*$") or ""
            local randomUpgrade=upgradeUsername~=nil and typed==""
            if not randomUpgrade and (#typed<3 or #typed>20 or not typed:match("^[%w_]+$")) then
                status("Enter a valid Roblox username (3-20 letters, digits or _)")
                notify("Enter a valid Roblox username")
                return
            end
            -- Auto-fill only an empty upgrade level; preserve explicit choices.
            local levelText=tostring(levelBox.Text or ""):match("^%s*(.-)%s*$") or ""
            if upgradeUsername~=nil and levelText=="" then
                levelText=tostring(math.random(1,100))
                levelBox.Text=levelText
            end
            local typedLevel=tonumber(levelText)
            if not levelText:match("^%d+$") or not typedLevel
                or typedLevel<1 or typedLevel>100 then
                notify("Enter a visual level from 1 to 100 first")
                return
            end
            setVisualLevel(typedLevel)
            removeVisual(true)
            local token=visual.token
            status(randomUpgrade and "Finding a random Roblox account ..." or ("Looking up @"..typed.." ..."))
            task.spawn(function()
                if randomUpgrade then
                    -- A successful ID lookup supplies a real registered username.
                    -- Bound retries and cancel immediately when this spawn is replaced.
                    for attempt=1,12 do
                        if not valid(token) then return end
                        local candidateId=math.random(1,1000000000)
                        local okName,candidate=pcall(function()
                            return Players:GetNameFromUserIdAsync(candidateId)
                        end)
                        if not valid(token) then return end
                        if okName and type(candidate)=="string" and candidate~=""
                            and candidateId~=playerGui.UserId and candidate~=visual.lastUpgradeName then
                            typed=candidate
                            break
                        end
                        task.wait(0.15)
                    end
                    if typed=="" then
                        status("Could not resolve a random account. Try again or enter a username above.")
                        notify("Random username lookup failed; try again or enter a username")
                        return
                    end
                end
                local okId,userId=pcall(function() return Players:GetUserIdFromNameAsync(typed) end)
                if not valid(token) then return end
                if not okId or type(userId)~="number" or userId<=0 then
                    status("Username not found: @"..typed)
                    notify("Roblox username not found: "..typed)
                    return
                end
                local okDesc,desc=pcall(function() return Players:GetHumanoidDescriptionFromUserIdAsync(userId) end)
                if not okDesc then
                    okDesc,desc=pcall(function() return Players:GetHumanoidDescriptionFromUserId(userId) end)
                end
                if not valid(token) then return end
                if not okDesc or not desc then
                    status("Could not fetch @"..typed.."'s avatar")
                    notify("Avatar loading failed for "..typed)
                    return
                end
                -- Resolve the exact registered Roblox username from the user ID,
                -- so the overhead tag and leaderboard preserve the real casing.
                local realName=typed
                local okName,name=pcall(function()
                    return Players:GetNameFromUserIdAsync(userId)
                end)
                if not valid(token) then return end
                if okName and type(name)=="string" and name~="" then
                    realName=name
                end
                if usernameBox.Text==typed then usernameBox.Text=realName end
                status("Loading avatar for @"..realName.." ...")
                local model,why,appliedDescription=createAvatar(realName,userId,desc)
                if not valid(token) then
                    if model then pcall(function() model:Destroy() end) end
                    return
                end
                if not model then
                    status("Avatar load failed: "..tostring(why))
                    notify("Avatar load failed for "..realName)
                    return
                end
                visual.model=model
                visual.username=realName
                if upgradeUsername~=nil then visual.lastUpgradeName=realName end
                visual.spawnCFrame=model:GetPivot()
                configureVisualUsername(model,realName)
                animateAvatar(model,appliedDescription or desc)
                -- Expose this client-only avatar in Weapon Equipping's player
                -- selector, without adding a real Players entry.
                _G.pvVisualWeaponTarget={
                    pvIsVisual=true, Name=realName, UserId=-2147000001,
                    Character=model, Parent=model
                }
                if type(_G.pvRefreshWeapWhoList)=="function" then
                    pcall(_G.pvRefreshWeapWhoList)
                end
                -- Visual-only Roblox-style "joined you" banner; does not add a
                -- real friend, send a Roblox chat event, or affect other clients.
                visual.showJoinToast(realName,userId)
                visual.showJoinChat(realName)
                -- Spawned player stands idle until Jump is pressed.
                for _=1,12 do
                    if not valid(token) then return end
                    local okRow,row=pcall(makeLeaderboardRow,realName)
                    if okRow and row then visual.row=row break end
                    task.wait(0.25)
                end
                if not valid(token) then return end
                if visual.row then
                    status("@"..realName.." ready - use Jump to hop in place (local only)")
                    -- Don't overlap the new top join banner with another popup.
                else
                    status("Avatar spawned, but leaderboard is unavailable")
                    notify("Avatar spawned; leaderboard could not be updated")
                end
                -- Schedule the upgrade only after the normal visual join is complete.
                if type(onReady)=="function" then
                    local success,errorMessage=pcall(onReady,_G.pvVisualWeaponTarget)
                    if not success then notify("Fake upgrade failed: "..tostring(errorMessage)) end
                end
            end)
        end
        pvSession.spawnUpgradePlayer=visual.spawn
        pvSession.addCleanup(function() pvSession.spawnUpgradePlayer=nil end)
        local spawnButton=btn(fakePlayerControls,"Spawn Visual Player",function() visual.spawn() end)
        spawnButton.Name="pvSpawnVisualPlayer"
        local playerActions=Instance.new("Frame")
        playerActions.Name="pvVisualPlayerActions"
        playerActions.Size=UDim2.new(1,0,0,pxValue(30))
        playerActions.BackgroundTransparency=1
        playerActions.LayoutOrder=4
        playerActions.Parent=fakePlayerControls
        local jumpButton=btn(playerActions,"Jump",queueVisualJump)
        jumpButton.Name="pvVisualJumpButton"
        jumpButton.Size=UDim2.new(0.3,-pxValue(3),0,pxValue(30))
        -- The overhead username has its own visible, model-owned label.
        -- A local chat composer for this *already spawned* preview avatar.
        local fakeChatBox=box(fakePlayerControls,"What should the visual player say?")
        fakeChatBox.Name="pvVisualFakeChatInput"
        fakeChatBox.TextXAlignment=Enum.TextXAlignment.Left
        fakeChatBox.Size=UDim2.new(1,0,0,pxValue(30))
        fakeChatBox.Text=tostring(settings.visualAutoMessageText or "")
        visual.autoMessageSerial=0
        visual.autoMessageToggle=toggle(fakePlayerControls,"Auto Message After Equip",settings.visualAutoMessage==true,function(value)
            settings.visualAutoMessage=value
            visual.autoMessageSerial=visual.autoMessageSerial+1
            pcall(saveCfg)
        end)
        visual.autoMessageToggle.LayoutOrder=6
        pvSession.queueUpgradeMessage=function(target)
            if not settings.visualAutoMessage then return end
            local token=visual.token
            local serial=visual.autoMessageSerial
            task.delay(2,function()
                if not valid(token) or serial~=visual.autoMessageSerial
                    or not settings.visualAutoMessage or target~=_G.pvVisualWeaponTarget
                    or target.Character~=visual.model or not visual.model or not visual.model.Parent
                    or not fakeChatBox.Parent then return end
                local message=tostring(fakeChatBox.Text or ""):match("^%s*(.-)%s*$") or ""
                if message~="" then sayAsVisual(message) end
            end)
        end
        pvSession.addCleanup(function() pvSession.queueUpgradeMessage=nil end)
        local sayButton=btn(fakePlayerControls,"Say Message",function()
            if sayAsVisual(fakeChatBox.Text) and not settings.visualAutoMessage then
                fakeChatBox.Text=""
            end
        end)
        sayButton.Name="pvVisualSayMessage"
        -- Enter on a desktop keyboard acts like pressing the Say button.
        pvSession.connect(fakeChatBox.FocusLost,function(enterPressed)
            if enterPressed and sayAsVisual(fakeChatBox.Text) and not settings.visualAutoMessage then
                fakeChatBox.Text=""
            end
            settings.visualAutoMessageText=fakeChatBox.Text
            pcall(saveCfg)
        end)
        local removeButton=btn(playerActions,"Remove Player",function()
            removeVisual(true)
            status("Removed. No real player was joined or traded.")
            notify("Visual player removed")
        end)
        removeButton.Name="pvRemoveVisualPlayer"
        removeButton.Size=UDim2.new(0.7,-pxValue(3),0,pxValue(30))
        removeButton.Position=UDim2.new(0.3,pxValue(3),0,0)
        usernameBox.LayoutOrder=1
        levelBox.LayoutOrder=2
        spawnButton.LayoutOrder=3
        fakeChatBox.LayoutOrder=5
        sayButton.LayoutOrder=7
        task.defer(resizeSection)
        end)()
    end

end
