local meshDB = {}


PV_CAPTURED = nil
pcall(function()
    if type(isfile)=="function" and isfile("pvCapture.json") then
        PV_CAPTURED = HttpService:JSONDecode(readfile("pvCapture.json"))
    end
end)
pcall(function()
    if hasFile and isfileSafe(MESH_PATH) then
        meshDB = HttpService:JSONDecode(readfile(MESH_PATH)) or {}
    end
end)


wdbCount=0
pcall(function()


    local raw
    if hasFile and isfileSafe(WDB_PATH) then
        raw=HttpService:JSONDecode(readfile(WDB_PATH))
    elseif PV_WDB_JSON and #PV_WDB_JSON>2 then
        raw=HttpService:JSONDecode(PV_WDB_JSON)
    end
    do
        if type(raw)=="table" then
            for id,rawItem in pairs(raw) do
                if type(rawItem)=="table" and rawItem.m then
                    meshDB[id]={
                        mesh  = rawItem.m,
                        tex   = rawItem.t,
                        scale = (rawItem.sx and {rawItem.sx, rawItem.sy, rawItem.sz}) or nil,
                        color = rawItem.c,
                        mat   = rawItem.mat,
                        typ   = rawItem.typ,
                        mp    = rawItem.mp,
                        ov    = rawItem.ov,
                        off   = rawItem.off,
                    }
                    wdbCount=wdbCount+1
                end
            end
        end


        if type(PV_CAPTURED)=="table" then
            local number=0
            for id,PV_CAPTUREDItem in pairs(PV_CAPTURED) do
                if type(PV_CAPTUREDItem)=="table" and PV_CAPTUREDItem.m and PV_CAPTUREDItem.m~="" then
                    meshDB[id]={
                        mesh  = PV_CAPTUREDItem.m,
                        tex   = (PV_CAPTUREDItem.t~="" ) and PV_CAPTUREDItem.t or nil,
                        scale = PV_CAPTUREDItem.sc,
                        color = PV_CAPTUREDItem.col,
                        mat   = PV_CAPTUREDItem.mat,
                        typ   = PV_CAPTUREDItem.typ,
                        mp    = (PV_CAPTUREDItem.cls=="MeshPart") or nil,


                        size  = PV_CAPTUREDItem.sz,
                        off   = PV_CAPTUREDItem.of and PV_CAPTUREDItem.of[2] or nil,
                        dec   = PV_CAPTUREDItem.dec,
                        att   = PV_CAPTUREDItem.att,
                        real  = true,
                    }


                    if PV_CAPTUREDItem.att and #PV_CAPTUREDItem.att>=12 then
                        PV_CAP_MOUNTS = PV_CAP_MOUNTS or {}
                        PV_CAP_MOUNTS[id] = PV_CAPTUREDItem.att
                    end
                    number=number+1
                end
            end
            _G.pvCapturedLoaded = number
        end
    end
end)


do
    local useCount={}
    for _,meshDBItem in pairs(meshDB) do
        local model = meshDBItem and meshDBItem.mesh and tostring(meshDBItem.mesh):match("%d+")
        if model then useCount[model]=(useCount[model] or 0)+1 end
    end


    local badMesh={}
    for key,useCountItem in pairs(useCount) do if useCountItem>6 then badMesh[key]=true end end
    local dropped=0
    for index,meshDBItem in pairs(meshDB) do
        local model = meshDBItem and meshDBItem.mesh and tostring(meshDBItem.mesh):match("%d+")
        if model and badMesh[model] then meshDB[index]=nil; dropped=dropped+1 end
    end


    local skinDropped=0
    if type(skinCache)=="table" then
        for index,skinCacheItem in pairs(skinCache) do
            local model = skinCacheItem and skinCacheItem.mesh and tostring(skinCacheItem.mesh):match("%d+")
            if model and badMesh[model] then skinCache[index]=nil; skinDropped=skinDropped+1 end
        end
        if skinDropped>0 then skinDirty=true; pcall(saveSkins) end
    end
    _G.pvMeshPurged = dropped
    _G.pvSkinPurged = skinDropped
    _G.pvBadMesh = badMesh
end


