pvNameKey = {}
pvNameKeyT = {Gun={}, Knife={}}
function pvNorm(text) return tostring(text):lower():gsub("[^%a%d]","") end


pvNameKeyTC = {Gun={}, Knife={}}
for index,meshDBItem in pairs(meshDB) do
    local number=pvNorm(index); if number~="" and not pvNameKey[number] then pvNameKey[number]=index end


    local value=meshDBItem.typ
    if number~="" and (value=="Gun" or value=="Knife") then

        local base, isChroma
        if index:match("Chroma$") then base, isChroma = index:gsub("Chroma$",""), true
        elseif index:match("^Chroma") then base, isChroma = index:gsub("^Chroma",""), true
        else base, isChroma = index, false end


        local aliases = { pvNorm(base) }
        local stripped = base:gsub("Knife$",""):gsub("Gun$",""):gsub("_[GK]_%d+$","")
        if stripped~="" and stripped~=base then aliases[#aliases+1]=pvNorm(stripped) end
        local idx = isChroma and pvNameKeyTC[value] or pvNameKeyT[value]
        if not idx[number] then idx[number]=index end
        for _,alias in ipairs(aliases) do
            if alias~="" and not idx[alias] then idx[alias]=index end
        end
    end
end


for index,meshDBItem in pairs(meshDB) do
    if not meshDBItem.tex then
        local base=index:gsub("Chroma$",""):gsub("_%a_%d+$","")
        local bkValue=pvNameKey[pvNorm(base)]
        local button=bkValue and meshDB[bkValue]
        if button and button.tex and bkValue~=index then meshDBItem.tex=button.tex end
    end
end
function pvResolveKey(item)
    if not item then return nil end


    if not item.name then return nil end
    local number=pvNorm(item.name)
    do


        local t2Value=(item.type=="Gun") and "Gun" or "Knife"

        local n2Value = number
        if item.chroma and n2Value:sub(1,6)=="chroma" then n2Value = n2Value:sub(7) end
        if item.chroma then
            local hit = pvNameKeyTC[t2Value][n2Value] or pvNameKeyTC[t2Value][number]
            if hit then return hit end
        else
            local hit = pvNameKeyT[t2Value][number]
            if hit then return hit end
        end
    end
    local value=(item.type=="Gun") and "Gun" or "Knife"
    return pvNameKeyT[value][number] or nil
end


pvGameAng = {}
pcall(function()
    local Sync = require(game:GetService("ReplicatedStorage").Database.Sync)
    local GWValue = Sync and Sync.Weapons
    if not GWValue then return end
    for key,GWItem in pairs(GWValue) do
