            pvGameAng[key]=AValue
            if GWItem.ItemName then pvGameAng["n:"..pvNorm(GWItem.ItemName)]=AValue end
        end
    end


end)
function pvEquippedAngles(slot)
    local name = (slot=="Gun") and playerGui:GetAttribute("EquippedGun") or playerGui:GetAttribute("EquippedKnife")
    if not name then return {0,0,0} end
    return pvGameAng[name] or pvGameAng["n:"..pvNorm(name)] or {0,0,0}
end


pvBase = {
    Gun   = CFrame.new(0.130, 0, 0.075) * CFrame.fromOrientation(0, math.rad(-60), math.rad(90)),
    Knife = CFrame.new(),
}
function pvCaptureBase(slot, disp)
    if pvBase[slot] then return end
    local rigidConstraint=disp:FindFirstChildOfClass("RigidConstraint")
    local attachment=(rigidConstraint and rigidConstraint.Attachment1) or disp:FindFirstChildOfClass("Attachment")
    if not attachment then return end
    local eqValue=pvEquippedAngles(slot)
    pvBase[slot]=attachment.CFrame * CFrame.Angles(eqValue[1],eqValue[2],eqValue[3]):inverse()
end
local meshDirty=false
local function meshCount() local number=0 for _ in pairs(meshDB) do number=number+1 end return number end
local function saveMeshes()
    if not (hasFile and meshDirty) then return end
    meshDirty=false
    pcall(function()
        if type(isfolder)=="function" and not isfolder(CFG_DIR) then makefolder(CFG_DIR) end
        writefile(MESH_PATH, HttpService:JSONEncode(meshDB))
    end)
end
local nameToWeapon={}
for _,item in ipairs(items) do


    if item.kind=="Weapon" then
        local button=(item.base or item.name):lower()
        if not nameToWeapon[button] then nameToWeapon[button]=item end
        nameToWeapon[item.name:lower()]=item
    end
end
local function grabMesh(root)
    local stack={root}
    while #stack>0 do
        local x=table.remove(stack)
        if x:IsA("MeshPart") and x.MeshId~="" then
            return {mesh=x.MeshId, tex=(x.TextureID~="" and x.TextureID or nil),
                    size={x.Size.X,x.Size.Y,x.Size.Z}}
        end
        if x:IsA("SpecialMesh") and x.MeshId~="" then
            return {mesh=x.MeshId, tex=(x.TextureId~="" and x.TextureId or nil),
                    scale={x.Scale.X,x.Scale.Y,x.Scale.Z}}
        end
        for _,child in ipairs(x:GetChildren()) do stack[#stack+1]=child end
    end
end
local function harvestFrom(container)
    for _,obj in ipairs(container:GetChildren()) do
        if obj:IsA("Tool") or obj:IsA("Model") then
            local item=nameToWeapon[obj.Name:lower()]
            if item and not meshDB[item.id] then
                local model=grabMesh(obj)
                if model then
                    meshDB[item.id]=model; meshDirty=true
                    saveMeshes()
                end
            end
        end
    end
end


local PV_HOLDER="pvBodySkin"
local wornSlots={}
