function displayPart(slot)
    local character=playerGui.Character; if not character then return nil end
    local override=character:FindFirstChild((slot=="Gun") and "DisplayRefGun" or "DisplayRefKnife")
    return (override and override.Value) or character:FindFirstChild(slot.."Display")
end


function pvEnsureDisplay(slot)
    local character=playerGui.Character; if not character then return nil end
    local refName=(slot=="Gun") and "DisplayRefGun" or "DisplayRefKnife"
    local override=character:FindFirstChild(refName)
    if override and override.Value and override.Value.Parent then return override.Value end
    local torso, anchorName
    if slot=="Gun" then torso=character:FindFirstChild("LowerTorso") or character:FindFirstChild("Torso"); anchorName="GunBelt"
    else torso=character:FindFirstChild("UpperTorso") or character:FindFirstChild("Torso"); anchorName="KnifeBack" end
    local anchor=torso and torso:FindFirstChild(anchorName)
    if not anchor then return nil end
    local weaponDisplays=workspace:FindFirstChild("WeaponDisplays")
    if not weaponDisplays then weaponDisplays=Instance.new("Folder");weaponDisplays.Name="WeaponDisplays";weaponDisplays.Parent=workspace end


    local part=Instance.new("Part");part.Name=(slot=="Gun") and "GunDisplay" or "KnifeDisplay"
    part:SetAttribute("pvMade", true)
    part.Size=Vector3.new(0.2,0.2,0.2);part.Transparency=0;part.CanCollide=false;part.Massless=true;part.Anchored=false
    pcall(function() part.CanQuery=false;part.CanTouch=false end)
    local specialMesh=Instance.new("SpecialMesh");specialMesh.Name="Mesh";specialMesh.MeshType=Enum.MeshType.FileMesh;specialMesh.Parent=part
    local attachment=Instance.new("Attachment");attachment.Name="Attachment";attachment.Parent=part
    part.Parent=weaponDisplays
    local rigidConstraint=Instance.new("RigidConstraint");rigidConstraint.Attachment0=anchor;rigidConstraint.Attachment1=attachment;rigidConstraint.Parent=part
    if override then override.Value=part
    else local objectValue=Instance.new("ObjectValue");objectValue.Name=refName;objectValue.Value=part;objectValue.Parent=character end
    return part
end


