NATIVE_PATH = CFG_DIR.."/pv_native.json"
pvNativeCache = pvNativeCache or {}
for id,PV_NATIVE_DATAItem in pairs(PV_NATIVE_DATA) do
    if not pvNativeCache[id] then pvNativeCache[id]=Vector3.new(PV_NATIVE_DATAItem[1],PV_NATIVE_DATAItem[2],PV_NATIVE_DATAItem[3]) end
end
pvNativeDirty = false
pcall(function()
    if hasFile and isfileSafe(NATIVE_PATH) then
        local raw=HttpService:JSONDecode(readfile(NATIVE_PATH))
        if type(raw)=="table" then
            for index,rawItem in pairs(raw) do
                local id=tonumber(index)
                if id and type(rawItem)=="table" and #rawItem>=3 then
                    pvNativeCache[id]=Vector3.new(rawItem[1],rawItem[2],rawItem[3])
                end
            end
        end
    end
end)
function pvSaveNative()
    if not (hasFile and pvNativeDirty) then return end
    pvNativeDirty=false
    pcall(function()
        local out={}
        for id,pvNativeCacheItem in pairs(pvNativeCache) do out[tostring(id)]={pvNativeCacheItem.X,pvNativeCacheItem.Y,pvNativeCacheItem.Z} end
        if type(isfolder)=="function" and not isfolder(CFG_DIR) then makefolder(CFG_DIR) end
        writefile(NATIVE_PATH, HttpService:JSONEncode(out))
    end)
end
function nativeSize(mesh)
    local mid=tonumber(tostring(mesh):match("%d+")); if not mid then return nil end
    if pvNativeCache[mid] then return pvNativeCache[mid] end
    if not (Content and Content.fromAssetId) then return nil end
    local content=Content.fromAssetId(mid)
    local success,result=pcall(function() return game:GetService("AssetService"):CreateMeshPartAsync(content) end)
    if success and result then
        local text=result.Size; pcall(function() result:Destroy() end)
        pvNativeCache[mid]=text; pvNativeDirty=true
        task.delay(2,pvSaveNative)
        return text
    end
end


