    for _,rawItem in pairs(raw) do
        local model = rawItem.m and tostring(rawItem.m):match("%d+")
        if model and rawItem.sx and tonumber(rawItem.sx) then
            accept[model] = accept[model] or {}
            table.insert(accept[model], tonumber(rawItem.sx))
        end
    end
    for key,list in pairs(accept) do
        table.sort(list)
        PV_MESH_SCALE[key] = list[math.ceil(#list/2)]
