end)


PV_BUCKET_SCALE = {Gun={}, Knife={}}
pcall(function()
    local function bucket(nat)
        if nat < 10 then return "s" elseif nat < 45 then return "m"
        elseif nat < 55 then return "l" elseif nat < 80 then return "xl" else return "xxl" end
    end
    local raw = HttpService:JSONDecode(PV_WDB_JSON)
    local accept = {Gun={}, Knife={}}
    for _,rawItem in pairs(raw) do
        if rawItem.sx and tonumber(rawItem.sx) then
            local nativeSize2 = nativeSize(rawItem.m)
            if nativeSize2 then
                local slot = (rawItem.typ=="Gun") and "Gun" or "Knife"
                local button = bucket(math.max(nativeSize2.X,nativeSize2.Y,nativeSize2.Z))
                accept[slot][button] = accept[slot][button] or {}
                table.insert(accept[slot][button], tonumber(rawItem.sx))
            end
        end
    end
    for slot,tbl in pairs(accept) do
        for key,list in pairs(tbl) do
            if #list >= 3 then
                table.sort(list)
                PV_BUCKET_SCALE[slot][key] = list[math.ceil(#list/2)]
            end
        end
    end
    PV_BUCKET_OF = bucket
end)


PV_REAL_LEN = { Knife={3.00, 4.05}, Gun={1.83, 1.96} }


function pvFitSize(mesh, slot)
    local nativeSize2=nativeSize(mesh)
    if not nativeSize2 then return nil end
    local number=math.max(nativeSize2.X,nativeSize2.Y,nativeSize2.Z)
    local value=PV_TARGET[slot] or 2.5
    local func=(number>0.001) and (value/number) or 1
    return nativeSize2*func
end


PV_SIZE_MULT = {

    Gingerscope = 1.45,
    TreeGun2023 = 0.85, TreeGun2023Chroma = 0.85,
    TreeKnife2023 = 0.85, TreeKnife2023Chroma = 0.85,


}
function pvRenderScale(record, slot, id)

    if record.real then
        if record.scale and record.scale[1] then
            return Vector3.new(record.scale[1], record.scale[2] or record.scale[1], record.scale[3] or record.scale[1])
        end


        if record.size then
            local NcValue = nativeSize(record.mesh)
            local want = math.max(record.size[1] or 0, record.size[2] or 0, record.size[3] or 0)
            local nat  = NcValue and math.max(NcValue.X, NcValue.Y, NcValue.Z) or 0
            if want > 0.01 and nat > 0.001 then
                local func = want / nat
                return Vector3.new(func, func, func)
            end
        end
    end
    local nativeSize2=nativeSize(record.mesh)
    local mult=(tonumber(record.ov) or 1)*((id and PV_SIZE_MULT[id]) or 1)
    local scale
    if record.scale and record.scale[1] then
        scale=Vector3.new(record.scale[1], record.scale[2] or record.scale[1], record.scale[3] or record.scale[1])
    elseif record.mp then
        scale=Vector3.new(1,1,1)
    end
    if scale and nativeSize2 then


        local number=math.max(nativeSize2.X*scale.X, nativeSize2.Y*scale.Y, nativeSize2.Z*scale.Z)


        local loValue = (slot=="Gun") and 1.50 or 0.5
        local hiValue = (slot=="Gun") and 4.60 or 6.0
        if number < loValue or number > hiValue then scale=nil end
    end
    if scale then return scale*mult end


    local mid = record.mesh and tostring(record.mesh):match("%d+")
    local sib = (slot=="Gun") and mid and PV_MESH_SCALE[mid] or nil
    if sib and nativeSize2 then


        local value = sib * (mult or 1)
        local number = math.max(nativeSize2.X,nativeSize2.Y,nativeSize2.Z) * value
        if number >= 0.5 and number <= 6.0 then return Vector3.new(value, value, value) end
    end

    if slot=="Gun" and nativeSize2 and PV_BUCKET_OF and PV_BUCKET_SCALE[slot] then
        local button = PV_BUCKET_SCALE[slot][PV_BUCKET_OF(math.max(nativeSize2.X,nativeSize2.Y,nativeSize2.Z))]
        if button then
            local value = button * (mult or 1)
            local number = math.max(nativeSize2.X,nativeSize2.Y,nativeSize2.Z) * value
            if number >= 0.5 and number <= 6.0 then return Vector3.new(value,value,value) end
        end
    end
    local fit = pvFitScale(record.mesh, slot)
    if mult and mult > 1 and nativeSize2 then
        local MAXLEN = (slot=="Gun") and 3.2 or 4.6
        local base   = math.max(nativeSize2.X*fit.X, nativeSize2.Y*fit.Y, nativeSize2.Z*fit.Z)
        local want   = base * mult
        if want > MAXLEN then mult = MAXLEN / base end
        return fit * mult
    end
    return fit
end


