function pvNormId(unit) local text=tostring(unit or ""):match("%d+"); return text and ("rbxassetid://"..text) or "" end
function pvHarvest()
    local weaponDisplays=workspace:FindFirstChild("WeaponDisplays"); if not weaponDisplays then return 0 end

    local mine={}
    local character=playerGui.Character
    if character then for _,rnValue in ipairs({"DisplayRefGun","DisplayRefKnife"}) do
        local override=character:FindFirstChild(rnValue); if override and override.Value then mine[override.Value]=true end
    end end
    local got=0
    for _,data in ipairs(weaponDisplays:GetChildren()) do
        if data:IsA("BasePart") and not mine[data]
           and not tostring(data.Name):find("pvWorn") and not tostring(data.Name):find("pvClone") then
            local specialMesh=data:FindFirstChildOfClass("SpecialMesh")
            local mesh = data:IsA("MeshPart") and tostring(data.MeshId):match("%d+")
                         or (specialMesh and tostring(specialMesh.MeshId):match("%d+"))
            if mesh and not pvDisp[mesh] then
                local entry={ form=(data:IsA("MeshPart") and "MP" or "SM"),
                          sz={data.Size.X,data.Size.Y,data.Size.Z} }
                if specialMesh then
                    entry.sc={specialMesh.Scale.X,specialMesh.Scale.Y,specialMesh.Scale.Z}
                    entry.of={specialMesh.Offset.X,specialMesh.Offset.Y,specialMesh.Offset.Z}
                end
                local rigidConstraint=data:FindFirstChildOfClass("RigidConstraint")
                local attachment=(rigidConstraint and rigidConstraint.Attachment1) or data:FindFirstChildOfClass("Attachment")
                if attachment then entry.att={attachment.CFrame:GetComponents()} end
                local texture = data:IsA("MeshPart") and tostring(data.TextureID) or (specialMesh and tostring(specialMesh.TextureId))
                if texture and texture~="" then entry.tx=texture end
                entry.co={data.Color.R,data.Color.G,data.Color.B}
                entry.mt=tostring(data.Material):gsub("Enum%.Material%.","")
                pvDisp[mesh]=entry; pvDispDirty=true; got=got+1
            end
        end
    end
    if got>0 then pvSaveDisp() end
    return got
end


