_G.pvRealTried = _G.pvRealTried or {}
function pvRealAssetId(wid)
    local entry = Sync and Sync.Weapons and Sync.Weapons[wid]
    if not entry then return nil end
    local function asset(value)
        return tonumber(value) or tonumber(tostring(value or ""):match("%d+"))
    end
    return asset(entry.DisplayID) or asset(entry.ItemID)
end
function pvLoadRealMesh(wid, cbValue)
    if not wid then if cbValue then cbValue(false) end return end
    if _G.pvRealTried[wid] and meshDB[wid] then if cbValue then cbValue(true) end return end
    local aid = pvRealAssetId(wid)
    if not aid or type(game.GetObjects)~="function" then if cbValue then cbValue(false) end return end
    _G.pvRealTried[wid]=true
    task.spawn(function()
        local success,objs = pcall(function() return game:GetObjects("rbxassetid://"..aid) end)
        if not success or type(objs)~="table" or not objs[1] then if cbValue then cbValue(false) end return end
        local root=objs[1]
        local mesh,texture,size,scale

        local stack,best={root},nil
        while #stack>0 do
            local data=table.remove(stack)
            if data:IsA("MeshPart") and data.MeshId~="" then
                if not best or data.Name=="Handle" then
                    best={mesh=data.MeshId, tex=(data.TextureID~="" and data.TextureID or nil),
                          size={data.Size.X,data.Size.Y,data.Size.Z}}
                    if data.Name=="Handle" then break end
                end
            elseif data:IsA("SpecialMesh") and data.MeshId~="" then
                if not best then
                    best={mesh=data.MeshId, tex=(data.TextureId~="" and data.TextureId or nil),
                          scale={data.Scale.X,data.Scale.Y,data.Scale.Z}}
                end
            end
            for _,child in ipairs(data:GetChildren()) do stack[#stack+1]=child end
        end
        pcall(function() root:Destroy() end)
        if best then
            mesh,texture,size,scale = best.mesh,best.tex,best.size,best.scale
            meshDB[wid]={mesh=mesh, tex=texture, size=size, scale=scale, mp=(size~=nil) or nil, real=true, typ=Sync.Weapons[wid].ItemType}
            meshDirty=true
            pcall(saveMeshes)
        end
        if cbValue then cbValue(best~=nil) end
    end)
end


function pvMPSize(id, slot)
    local record=meshDB[id]; if not record then return nil end
    local HValue2=pvHarvested(id)
    if HValue2 and HValue2.sz then return Vector3.new(HValue2.sz[1],HValue2.sz[2],HValue2.sz[3]) end
    local nativeSize2=nativeSize(record.mesh)
    if nativeSize2 then
        local number=math.max(nativeSize2.X,nativeSize2.Y,nativeSize2.Z)
        local target=(slot=="Gun") and 2.7 or 3.4
        local func=(number>0.001) and (target/number) or 1
        return nativeSize2*func
    end
end


function pvSMScale(id, slot)
    local HValue2=pvHarvested(id); local record=meshDB[id]
    if HValue2 and HValue2.sc then return Vector3.new(HValue2.sc[1],HValue2.sc[2],HValue2.sc[3]) end
    if record and record.scale then return Vector3.new(record.scale[1],record.scale[2],record.scale[3]) end

    local nativeSize2=record and nativeSize(record.mesh)
    if nativeSize2 then local number=math.max(nativeSize2.X,nativeSize2.Y,nativeSize2.Z); local value=(slot=="Gun") and 2.7 or 3.4
        local func=(number>0.001) and (value/number) or 1; return Vector3.new(func,func,func) end
    return Vector3.new(1,1,1)
end


function pvRawWantCF(id, record, HValue2, slot)
