function pvBodyMountTune(slot, cframe)
    if not cframe then return cframe end


    local mode=settings.visualPositions and settings.visualPositions[slot]
    if mode~="Side" then return cframe end


    if slot=="Gun" then
        return cframe * CFrame.fromOrientation(math.rad(17), 0, 0)
    elseif slot=="Knife" then
        return cframe * CFrame.fromOrientation(math.rad(7), 0, 0)
    end
    return cframe
end

function pvWantCF(id, record, HValue2, slot)
    return pvBodyMountTune(slot, pvRawWantCF(id, record, HValue2, slot))
end


