function pvApplyFX(part, id)
    if not part then return end
    pvClearFX(part)
    -- Also clear any old Pork Hub trail when this gun is reapplied or re-equipped.
    if pvNorm(id)=="gingerscope" then return end
    local kind = PV_FX_KIND[id]
    if not kind then return end
    local function tag(oValue) oValue:SetAttribute("pvFX", true); oValue.Parent = part; return oValue end
    if kind == "lights" then

        local pointLight = Instance.new("PointLight")
        pointLight.Color = Color3.fromRGB(120,255,140); pointLight.Brightness = 2.2; pointLight.Range = 9
        tag(pointLight)
        local first = tag(Instance.new("Attachment"))
        local particleEmitter = Instance.new("ParticleEmitter")
        particleEmitter.Texture = "rbxassetid://241876428"
        particleEmitter.Color = ColorSequence.new(Color3.fromRGB(150,255,170), Color3.fromRGB(255,240,150))
        particleEmitter.Size = NumberSequence.new(0.22)
        particleEmitter.Transparency = NumberSequence.new({NumberSequenceKeypoint.new(0,0.15),
                                             NumberSequenceKeypoint.new(1,1)})
        particleEmitter.Lifetime = NumberRange.new(0.5,0.9); particleEmitter.Rate = 14
        particleEmitter.Speed = NumberRange.new(0); particleEmitter.LightEmission = 1
        particleEmitter.Parent = first; particleEmitter:SetAttribute("pvFX", true)
    elseif kind == "glow" then

        pcall(function() part.Material = Enum.Material.Neon end)
        local pointLight = Instance.new("PointLight")
        pointLight.Color = Color3.fromRGB(255,90,220); pointLight.Brightness = 3; pointLight.Range = 11
        tag(pointLight)
    elseif kind == "sun" then

        local pointLight = Instance.new("PointLight")
        pointLight.Color = Color3.fromRGB(255,168,80); pointLight.Brightness = 2.6; pointLight.Range = 10
        tag(pointLight)
    elseif kind == "trail" then

        local a0Value = tag(Instance.new("Attachment")); a0Value.Position = Vector3.new(0, 0.35, 0)
        local a1Value = tag(Instance.new("Attachment")); a1Value.Position = Vector3.new(0,-0.35, 0)
        local trail = Instance.new("Trail")
        trail.Attachment0 = a0Value; trail.Attachment1 = a1Value
        trail.Color = ColorSequence.new(Color3.fromRGB(255,190,120), Color3.fromRGB(255,110,60))
        trail.Transparency = NumberSequence.new({NumberSequenceKeypoint.new(0,0.25),
                                             NumberSequenceKeypoint.new(1,1)})
        trail.Lifetime = 0.45; trail.LightEmission = 0.8; trail.WidthScale = NumberSequence.new(1)
        trail.Enabled = true; trail.MinLength = 0.02; trail.FaceCamera = true
        tag(trail)
    end
end

