function pvSurface(disp, slot)
    if not disp:IsA("MeshPart") then

        pcall(function() disp.Transparency=0; disp.LocalTransparencyModifier=0 end)
        return disp
    end
    local name="pvWorn"..slot
    for _,child in ipairs(disp:GetChildren()) do
        if child.Name==name then pcall(function() child:Destroy() end) end
    end
    pcall(function() disp.Transparency=1; disp.LocalTransparencyModifier=1 end)
    local part=Instance.new("Part")
    part.Name=name; part.Size=Vector3.new(0.2,0.2,0.2)
    part.Transparency=0; part.CanCollide=false; part.Massless=true; part.Anchored=false
    pcall(function() part.CanQuery=false; part.CanTouch=false end)
    local specialMesh=Instance.new("SpecialMesh"); specialMesh.Name="Mesh"
    specialMesh.MeshType=Enum.MeshType.FileMesh; specialMesh.Parent=part
    part.CFrame=disp.CFrame
    part.Parent=disp
    local weldConstraint=Instance.new("WeldConstraint"); weldConstraint.Part0=part; weldConstraint.Part1=disp; weldConstraint.Parent=part
    return part
end


PV_VisualMounts = setmetatable({}, {__mode="k"})
function pvVisualMountAnchor(character,slot)
    if not character then return nil end
    local mode=settings.visualPositions and settings.visualPositions[slot]
    if mode~="Side" and mode~="Back" then mode=slot=="Gun" and "Side" or "Back" end
    local torso=character:FindFirstChild(mode=="Back" and "UpperTorso" or "LowerTorso") or character:FindFirstChild("Torso")
    if not torso then return nil end
    local anchorName=slot..(mode=="Back" and "Back" or "Belt")
    if character~=playerGui.Character then
        -- Copy our mount's local transform, rather than their native holster pose.
        local source=pvVisualMountAnchor(playerGui.Character,slot)
        local anchor=torso:FindFirstChild("pvOtherMount"..slot)
        if not anchor then
            anchor=Instance.new("Attachment");anchor.Name="pvOtherMount"..slot
            anchor.Parent=torso;pvSession.ownRoot(anchor)
        end
        anchor.CFrame=source and source.CFrame or (mode=="Back" and CFrame.new(slot=="Gun" and 0.35 or -0.35,0,0.55)
            or CFrame.new(slot=="Gun" and 0.85 or -0.85,-0.35,0.15))
        return anchor,torso
    end
    local anchor=torso:FindFirstChild(anchorName) or torso:FindFirstChild("pvMount"..anchorName)
    if not anchor then
        anchor=Instance.new("Attachment");anchor.Name="pvMount"..anchorName
        anchor.CFrame=mode=="Back" and CFrame.new(slot=="Gun" and 0.35 or -0.35,0,0.55)
            or CFrame.new(slot=="Gun" and 0.85 or -0.85,-0.35,0.15)
        anchor.Parent=torso
    end
    return anchor,torso
end
function pvApplyVisualMount(disp, slot, character)
    local character2=character or playerGui.Character
    local anchor,torso=pvVisualMountAnchor(character2,slot)
    if not anchor then return end
    local rigidConstraint=disp:FindFirstChildOfClass("RigidConstraint")
    if rigidConstraint then
        if character2==playerGui.Character and not PV_VisualMounts[rigidConstraint] then
            PV_VisualMounts[rigidConstraint]={anchor=rigidConstraint.Attachment0, att=rigidConstraint.Attachment1,
                cf=rigidConstraint.Attachment1 and rigidConstraint.Attachment1.CFrame}
        end
        rigidConstraint.Attachment0=anchor
        return
    end

    for _,joint in ipairs(character2:GetDescendants()) do
        if joint:IsA("Weld") and joint.Part1==disp then
            if character2==playerGui.Character and not PV_VisualMounts[joint] then
                PV_VisualMounts[joint]={part=joint.Part0,c0=joint.C0,c1=joint.C1}
            end
            joint.Part0=torso
            joint.C0=anchor.CFrame
            joint.C1=CFrame.new()
            return
        end
    end
end
function pvRestoreVisualMounts()
    for joint,old in pairs(PV_VisualMounts) do
        pcall(function()
            if joint:IsA("RigidConstraint") then
                joint.Attachment0=old.anchor
                if old.att and old.cf then old.att.CFrame=old.cf end
            else joint.Part0=old.part; joint.C0=old.c0; joint.C1=old.c1 end
        end)
    end
    table.clear(PV_VisualMounts)
end

