function pvStudioOwned(object,root)
    while object and object~=root do


        if object:GetAttribute("pvStudioOwned") or object:GetAttribute("pvFX")
           or object.Name:match("^pvWorn") or object.Name=="pvHeld" then return true end
        object=object.Parent
    end
    return false
end
function pvHideStudioOriginal(disp)
    for _,object in ipairs(disp:GetDescendants()) do
        if not pvStudioOwned(object,disp) then
            local property
            if object:IsA("BasePart") then property="LocalTransparencyModifier"
            elseif object:IsA("Decal") or object:IsA("Texture") then property="Transparency"
            elseif object:IsA("Beam") or object:IsA("Trail") or object:IsA("ParticleEmitter") then property="Enabled" end
            if property then
                if not PV_StudioHidden[object] then
                    PV_StudioHidden[object]={property=property,value=object[property],root=disp}
                end
                if property=="Enabled" then object[property]=false else object[property]=1 end
            end
        end
    end
end
function pvClearStudioDetails(root)
    if not root then return end
    for _,object in ipairs(root:GetDescendants()) do
        if object:GetAttribute("pvStudioOwned") then object:Destroy() end
    end
    root:SetAttribute("pvStudioKey",nil)
end
function pvRestoreStudioDetails(root)
    for object,old in pairs(PV_StudioHidden) do
        if not root or old.root==root then
            pcall(function() object[old.property]=old.value end)
            PV_StudioHidden[object]=nil
        end
    end
    for surf,old in pairs(PV_StudioOriginal) do
        if not root or surf==root or surf:IsDescendantOf(root) then
            pcall(function()
                pvClearStudioDetails(surf)
                surf.Size=old.size;surf.Transparency=old.transparency;surf.Reflectance=old.reflectance
                local specialMesh=pvFindDisplayMesh(surf)
                if specialMesh and old.vertex then specialMesh.VertexColor=old.vertex end
            end)
            PV_StudioOriginal[surf]=nil
        end
    end
end
function pvStudioPaint(part,record)
    if record.size then part.Size=Vector3.new(table.unpack(record.size)) end
    if record.color then part.Color=Color3.new(table.unpack(record.color)) end
    part.Material=PV_StudioMaterials[record.material] or Enum.Material.Plastic
    part.Transparency=record.transparency or 0
    part.Reflectance=record.reflectance or 0
end
function pvStudioDecals(part,record)
    for _,data in ipairs(record.decals or {}) do
        local decal=Instance.new(data.class=="Texture" and "Texture" or "Decal")
        decal.Name="pvStudioDecal";decal:SetAttribute("pvStudioOwned",true)
        decal.Texture=data.texture;decal.Face=Enum.NormalId:GetEnumItems()[1]
        for _,face in ipairs(Enum.NormalId:GetEnumItems()) do if face.Value==data.face then decal.Face=face;break end end
        decal.Transparency=data.transparency or 0
        if data.color then decal.Color3=Color3.new(table.unpack(data.color)) end
        if decal:IsA("Texture") then decal.StudsPerTileU=data.u;decal.StudsPerTileV=data.v end
        decal.Parent=part
    end
end
function pvApplyStudioDetails(surf,record,id)
    if not record.studio then pvClearStudioDetails(surf);return end
    if not PV_StudioOriginal[surf] then
        local specialMesh=pvFindDisplayMesh(surf)
        PV_StudioOriginal[surf]={size=surf.Size,transparency=surf.Transparency,reflectance=surf.Reflectance,vertex=specialMesh and specialMesh.VertexColor}
    end
    pvStudioPaint(surf,record)
    local mainMesh=pvFindDisplayMesh(surf)
    if mainMesh then
        mainMesh.Offset=record.offset and Vector3.new(table.unpack(record.offset)) or Vector3.new()
        mainMesh.VertexColor=record.vertex and Vector3.new(table.unpack(record.vertex)) or Vector3.new(1,1,1)
    end
    if surf:GetAttribute("pvStudioKey")==id and surf:FindFirstChild("pvStudioDetails") then return end
    pvClearStudioDetails(surf)
    local folder=Instance.new("Folder");folder.Name="pvStudioDetails";folder:SetAttribute("pvStudioOwned",true);folder.Parent=surf
    pvStudioDecals(surf,record)
    for _,data in ipairs(record.parts or {}) do
        local class=data.primitive
        if class~="WedgePart" and class~="CornerWedgePart" then class="Part" end
        local part=Instance.new(class);part.Name=data.name or "Detail"
        part:SetAttribute("pvStudioOwned",true)
        part.Anchored=false;part.CanCollide=false;part.CanTouch=false;part.CanQuery=false;part.Massless=true
        pvStudioPaint(part,data)
        if data.mesh and data.mesh~="" then
            local mesh=Instance.new("SpecialMesh");mesh.MeshType=Enum.MeshType.FileMesh
            mesh.MeshId=pvNormId(data.mesh);mesh.TextureId=pvNormId(data.tex)
            mesh.Scale=Vector3.new(table.unpack(data.scale or {1,1,1}))
            mesh.Offset=Vector3.new(table.unpack(data.offset or {0,0,0}))
            mesh.VertexColor=Vector3.new(table.unpack(data.vertex or {1,1,1}))
            mesh.Parent=part
        elseif part:IsA("Part") then
            for _,shape in ipairs(Enum.PartType:GetEnumItems()) do if shape.Value==data.shape then part.Shape=shape;break end end
        end
        part.CFrame=surf.CFrame*CFrame.new(table.unpack(data.cf))
        part.Parent=folder
        pvStudioDecals(part,data)
        local weld=Instance.new("WeldConstraint");weld.Part0=surf;weld.Part1=part;weld.Parent=part
    end
    surf:SetAttribute("pvStudioKey",id)
end
local function wearMesh(id, slot, fast)
    local record=meshDB[id]
    local disp=displayPart(slot) or pvEnsureDisplay(slot)
    if not (record and disp) then return false end


    local HValue2=nil
    local texture=record.tex

    pvApplyVisualMount(disp, slot)
    if record.studio then pvHideStudioOriginal(disp) end
    local surf=pvSurface(disp, slot)
    local specialMesh=pvFindDisplayMesh(surf)
    if not specialMesh then specialMesh=Instance.new("SpecialMesh");specialMesh.MeshType=Enum.MeshType.FileMesh;specialMesh.Parent=surf end


    _G.pvOrigMesh = _G.pvOrigMesh or {}
    if _G.pvOrigMesh[specialMesh]==nil then
        _G.pvOrigMesh[specialMesh] = {
            sm  = specialMesh,
            mid = specialMesh.MeshId, tex = specialMesh.TextureId,
            sc  = specialMesh.Scale,  of  = specialMesh.Offset,
            col = surf.Color, mat = surf.Material, surf = surf,
        }
    end
    pcall(function() specialMesh.MeshId=pvNormId(record.mesh) end)
    pcall(function() specialMesh.TextureId=pvNormId(texture) end)
    local scale
    if HValue2 and HValue2.sc then
        scale=Vector3.new(HValue2.sc[1],HValue2.sc[2],HValue2.sc[3])
    elseif HValue2 and HValue2.sz then
        local nativeSize2=nativeSize(record.mesh)
        if nativeSize2 then
            local number=math.max(nativeSize2.X,nativeSize2.Y,nativeSize2.Z)
            local number2=math.max(HValue2.sz[1],HValue2.sz[2],HValue2.sz[3])
            local func=(number>0.001) and (number2/number) or 1
            scale=Vector3.new(func,func,func)
        end
    end
    pcall(function() specialMesh.Scale = scale or pvRenderScale(record, slot, id) end)
    pcall(function() specialMesh.Offset=(HValue2 and HValue2.of) and Vector3.new(HValue2.of[1],HValue2.of[2],HValue2.of[3]) or Vector3.new(0,0,0) end)


    do
        local rigidConstraint = disp:FindFirstChildOfClass("RigidConstraint")
        local attachment = (rigidConstraint and rigidConstraint.Attachment1) or disp:FindFirstChildOfClass("Attachment")
        if attachment then
            local want = pvWantCF(id, record, HValue2, slot)
            if want then pcall(function() attachment.CFrame=want end) end
        end
    end
    if record.color then
        pcall(function() surf.Color=Color3.new(record.color[1],record.color[2],record.color[3]) end)
    elseif (not texture) or texture=="" then


        pcall(function() surf.Color = PV_GREY end)
    end
    if record.mat then pcall(function() surf.Material=Enum.Material[record.mat] end) end
    if not fast then pcall(pvApplyFX, surf, id) end


    do
        _G.pvChromaOn = _G.pvChromaOn or {}
        _G.pvChromaOn[slot] = nil
        for _,child in ipairs(surf:GetChildren()) do
            if child:GetAttribute("pvDecal") then pcall(function() child:Destroy() end) end
        end
        pcall(function()
            local m2Value = pvFindDisplayMesh(surf)
            if m2Value then m2Value.VertexColor = Vector3.new(1,1,1) end
        end)
    end
    if not fast then pvApplyStudioDetails(surf,record,id) end
    wornSlots[slot]=id


    if not fast then pcall(pvCleanDuplicateDisplays) end
    return true
end

