function pvRefreshVisualInventory()
    if PV_VisualUpdating then return end
    PV_VisualUpdating=true
    for slot,selection in pairs(PV_VisualSelection or {}) do
        pcall(function()
            ProfileData.Weapons.Equipped[slot]=selection.id
            EquipService.EquippedChanged:Fire(slot,selection.id)
        end)
    end
    pcall(function()
        local model=require(replicatedStorageService.Modules.InventoryModule)
        if model.GUI and model.GUI.MyInventory and model.MyInventory and model.MyInventory.Data then
            model.UpdateMyEquip()
        end
    end)
    PV_VisualUpdating=false
end
PV_VisualSelection={}
PV_VisualSeen={}
PV_VisualUpdating=false
_G.pvEquipIdleToken = _G.pvEquipIdleToken or {Knife=0,Gun=0}
_G.pvSaveDebounce = _G.pvSaveDebounce or 0

function pvScheduleEquipFinalize(slot,key,itemID,token)

    task.delay(0.24,function()
        if not (_G.pvEquipIdleToken and _G.pvEquipIdleToken[slot]==token) then return end
        local sel=PV_VisualSelection and PV_VisualSelection[slot]
        if not (sel and sel.key==key and sel.id==itemID) then return end


        pcall(wearMesh,key,slot,false)


        pcall(pvRefreshVisualInventory)


        _G.pvSaveDebounce=(_G.pvSaveDebounce or 0)+1
        local saveToken=_G.pvSaveDebounce
        task.delay(0.08,function()
            if _G.pvSaveDebounce==saveToken then pcall(saveCfg) end
        end)
    end)
end

function pvEquipVisualKey(key, slot, itemID)
    local record=meshDB[key]
    if not record then return false end
    slot=(slot=="Gun") and "Gun" or "Knife"
    itemID=itemID or key

    PV_VisualRequest[slot]=(PV_VisualRequest[slot] or 0)+1
    PV_VisualPending[slot]=nil
    PV_VisualSelection[slot]={key=key,id=itemID}
    PV_VisualSeen[slot]=itemID
    settings.bodyCleared=false
    wornSlots[slot]=key
    bodyWorn={}


    pcall(clearHolster)

    if slot=="Knife" then
        settings.loadout.wornKnife=key
        settings.loadout.knife=itemID
    else
        settings.loadout.wornGun=key
        settings.loadout.gun=itemID
    end


    pcall(function()
        ProfileData.Weapons.Equipped[slot]=itemID
    end)


    local shown=wearMesh(key,slot,true)


    pcall(pvReskinHeld,slot)

    _G.pvEquipIdleToken[slot]=(_G.pvEquipIdleToken[slot] or 0)+1
    pvScheduleEquipFinalize(slot,key,itemID,_G.pvEquipIdleToken[slot])

    return shown
end

function pvSyncInventorySlot(slot,id)
    if slot~="Knife" and slot~="Gun" then return false end
    if type(id)~="string" or id=="" then id="Default"..slot end
    local key=meshDB[id] and id or nil
    local item=byId[id]
    if key and meshDB[key] then return pvEquipVisualKey(key,slot,id) end

    PV_VisualRequest[slot]=(PV_VisualRequest[slot] or 0)+1
    local request=PV_VisualRequest[slot]
    local generation=_G.pvGen
    PV_VisualSeen[slot]=id
    PV_VisualSelection[slot]=nil
    wornSlots[slot]=nil
    if slot=="Knife" then settings.loadout.wornKnife=nil
    else settings.loadout.wornGun=nil end
    local disp=displayPart(slot)
    if disp then
        pvRestoreStudioDetails(disp)
        local stand=disp:FindFirstChild("pvWorn"..slot)
        if stand then stand:Destroy() end
        for key2,old in pairs(_G.pvOrigMesh or {}) do
            if old.surf==disp then
                pcall(function()
                    key2.MeshId=old.mid; key2.TextureId=old.tex
                    key2.Scale=old.sc; key2.Offset=old.of
                    disp.Color=old.col; disp.Material=old.mat
                end)
                _G.pvOrigMesh[key2]=nil
            end
        end
        pcall(function() disp.Transparency=0;disp.LocalTransparencyModifier=0 end)
    end
    pcall(saveCfg)
    if pvRealAssetId(id) then
        PV_VisualPending[slot]=id
        pcall(notify,"Loading visual: "..((item and item.name) or id))
        pvLoadRealMesh(id,function(got)
            if generation~=_G.pvGen or PV_VisualRequest[slot]~=request then return end
            PV_VisualPending[slot]=nil
            if got and meshDB[id] then
                pcall(pvEquipVisualKey,id,slot,id)
            else
                pcall(notify,((item and item.name) or id)..": visual model unavailable")
            end
        end)
    else
        pcall(notify,((item and item.name) or id)..": no supported visual model")
    end
    return false
end


local function scrubDisplays(keepWorn)
    local weaponDisplays=workspace:FindFirstChild("WeaponDisplays"); if not weaponDisplays then return end
    for _,data in ipairs(weaponDisplays:GetChildren()) do
        local text=tostring(data.Name)
        if text:find("pvClone") or text:find("pvDisp") then pcall(function() data:Destroy() end)
        else for _,child in ipairs(data:GetChildren()) do
            local text2=tostring(child.Name)
            local isWorn = text2:find("pvWorn")

            local slot = isWorn and text2:gsub("pvWorn","") or nil
            local keep = keepWorn and slot and wornSlots and wornSlots[slot]~=nil
            if (isWorn and not keep) or text2:find("pvClone") or text2:find("pvDisp") then
                pcall(function() child:Destroy() end)
            end
        end end
    end
end
local function clearWorn(slot)
    local slots = slot and {slot} or {"Gun","Knife"}
    for _,slot2 in ipairs(slots) do wornSlots[slot2]=nil end
    scrubDisplays()
    local character=playerGui.Character
    if character then local handle=character:FindFirstChild(PV_HOLDER); if handle then pcall(function() handle:Destroy() end) end end
end


function pvCleanDuplicateDisplays()
    local weaponDisplays=workspace:FindFirstChild("WeaponDisplays"); if not weaponDisplays then return 0 end
    local character=playerGui.Character
    local keep={}
    if character then
        for _,rnValue in ipairs({"DisplayRefGun","DisplayRefKnife"}) do
            local override=character:FindFirstChild(rnValue)
            if override and override.Value then keep[override.Value]=true end
        end
    end


    local killed=0
    for _,data in ipairs(weaponDisplays:GetChildren()) do
        local isDisp = (data.Name=="KnifeDisplay" or data.Name=="GunDisplay")
        -- Only remove displays positively identified as belonging to us.
        -- Other players' native displays share this folder and these names.
        local rigidConstraint=data:FindFirstChildOfClass("RigidConstraint")
        local anchor=rigidConstraint and rigidConstraint.Attachment0
        local localOwned=character and anchor and anchor:IsDescendantOf(character)
        if not keep[data] and localOwned and (isDisp or data:GetAttribute("pvMade")) then
            pcall(function() data:Destroy() end); killed=killed+1
        end
    end
    return killed
end

function killLegacyHolder()
    local character=playerGui.Character
    if character then local handle=character:FindFirstChild(PV_HOLDER); if handle then pcall(function() handle:Destroy() end) end end
    scrubDisplays()
end
pcall(killLegacyHolder)
pcall(pvCleanDuplicateDisplays)
pvSession.connect(playerGui.CharacterAdded,function()
    task.wait(1.4)
    pcall(killLegacyHolder)
    pcall(pvCleanDuplicateDisplays)
    for slot,id in pairs(wornSlots) do pcall(wearMesh,id,slot) end
end)


_G.pvHotbarWanted   = _G.pvHotbarWanted   or {}
_G.pvHotbarTargets  = _G.pvHotbarTargets  or {Knife={},Gun={}}
_G.pvHotbarMatch    = _G.pvHotbarMatch    or {}
_G.pvHotbarScanning = _G.pvHotbarScanning or {}
_G.pvHotbarWatching = _G.pvHotbarWatching or {}

function pvHotbarAid(value)
    return tostring(value or ""):match("%d+") or ""
end

function pvHotbarish(obj)
    local part=obj
    for _=1,7 do
        part=part and part.Parent
        if not part then break end
        local text=tostring(part.Name):lower()
        if text:find("hotbar",1,true) or text=="backpack" or text:find("backpack",1,true) then
            return true
        end
    end
    return false
end

function pvRememberHotbarTarget(slot,gui2)
    if not (gui2 and gui2.Parent and (gui2:IsA("ImageLabel") or gui2:IsA("ImageButton"))) then return end
    _G.pvHotbarTargets[slot]=_G.pvHotbarTargets[slot] or {}

    for _,x in ipairs(_G.pvHotbarTargets[slot]) do
        if x==gui2 then
            local icon=_G.pvHotbarWanted[slot]
            if icon and icon~="" then pcall(function() gui2.Image=icon end) end
            return
        end
    end

    table.insert(_G.pvHotbarTargets[slot],gui2)
    local icon=_G.pvHotbarWanted[slot]
    if icon and icon~="" then pcall(function() gui2.Image=icon end) end


    local busy=false
    pcall(function()
        gui2:GetPropertyChangedSignal("Image"):Connect(function()
            if busy or not gui2.Parent then return end
            local want=_G.pvHotbarWanted[slot]
            if not want or want=="" or gui2.Image==want then return end
            local model=_G.pvHotbarMatch[slot]
            local current=pvHotbarAid(gui2.Image)
            if model and (current==model.def or current==model.old or current==model.prev or current==model.want) then
                busy=true
                pcall(function() gui2.Image=want end)
                busy=false
            end
        end)
    end)
end

function pvPatchCachedHotbar(slot)
    local arr=_G.pvHotbarTargets[slot] or {}
    local alive={}
    local icon=_G.pvHotbarWanted[slot]
    for _,arrItem in ipairs(arr) do
        if arrItem and arrItem.Parent and (arrItem:IsA("ImageLabel") or arrItem:IsA("ImageButton")) then
            alive[#alive+1]=arrItem
            if icon and icon~="" and arrItem.Image~=icon then pcall(function() arrItem.Image=icon end) end
        end
    end
    _G.pvHotbarTargets[slot]=alive
    return #alive
end

function pvTryHotbarCandidate(gui2)
    if not (gui2 and (gui2:IsA("ImageLabel") or gui2:IsA("ImageButton")) and pvHotbarish(gui2)) then return end
    local current=pvHotbarAid(gui2.Image)
    if current=="" then return end
    for _,slot in ipairs({"Knife","Gun"}) do
        local model=_G.pvHotbarMatch[slot]
        if model and (current==model.want or current==model.old or current==model.prev or current==model.def) then
            pvRememberHotbarTarget(slot,gui2)
        end
    end
end


function pvInstallHotbarWatcher(root,key)
    if not root or _G.pvHotbarWatching[key] then return end
    _G.pvHotbarWatching[key]=true
    pcall(function()
        pvSession.connect(root.DescendantAdded,function(obj)
            if _G.pvGen~=MY_GEN then return end
            if obj:IsA("ImageLabel") or obj:IsA("ImageButton") then
                task.defer(function()
                    if _G.pvGen==MY_GEN and obj and obj.Parent then
                        pcall(pvTryHotbarCandidate,obj)
                    end
                end)
            end
        end)
    end)
end
pcall(function() pvInstallHotbarWatcher(game:GetService("CoreGui"),"CoreGui") end)
pcall(function() pvInstallHotbarWatcher(playerGui:FindFirstChild("PlayerGui"),"PlayerGui") end)

function pvPatchRoundHotbarIcon(tool, slot, visualId, newIcon, oldIcon, previousVisualIcon)
    if not (tool and newIcon and newIcon~="") then return 0 end
    local want=pvHotbarAid(newIcon); if want=="" then return 0 end

    _G.pvHotbarWanted[slot]=newIcon

    local defIcon=""
    pcall(function()
        local did="Default"..tostring(slot)
        local item=byId and byId[did]
        defIcon=item and item.img or ""
        if defIcon=="" then
            local entry=Sync and Sync.Weapons and Sync.Weapons[did]
            if entry then defIcon=resolveImg(did,entry.Image) end
        end
        defIcon=pvFixImg(defIcon)
    end)


    _G.pvHotbarMatch[slot]={
        want=want,
        old=pvHotbarAid(oldIcon),
        prev=pvHotbarAid(previousVisualIcon),
        def=pvHotbarAid(defIcon),
    }


    local number=pvPatchCachedHotbar(slot)
    if number>0 then return number end


    if _G.pvHotbarScanning[slot] then return 0 end
    _G.pvHotbarScanning[slot]=true

    task.defer(function()
        if _G.pvGen~=MY_GEN then _G.pvHotbarScanning[slot]=nil return end

        local function scan(root)
            if not root then return end
            local all=root:GetDescendants()

            for index,allItem in ipairs(all) do
                if allItem:IsA("ImageLabel") or allItem:IsA("ImageButton") then
                    pcall(pvTryHotbarCandidate,allItem)
                end
                if index%120==0 then task.wait() end
            end
        end

        pcall(function() scan(game:GetService("CoreGui")) end)
        pcall(function() scan(playerGui:FindFirstChild("PlayerGui")) end)
        _G.pvHotbarScanning[slot]=nil
        pvPatchCachedHotbar(slot)
    end)

    return 0
end


_G.pvHeldAssetCache   = _G.pvHeldAssetCache   or {}
_G.pvHeldAssetLoading = _G.pvHeldAssetLoading or {}
_G.pvHeldAssetCb      = _G.pvHeldAssetCb      or {}
_G.pvHeldAssetPending = _G.pvHeldAssetPending or {}
_G.pvOrigRoundGrip    = _G.pvOrigRoundGrip    or setmetatable({}, {__mode="k"})

function pvHeldSyncKey(visualKey, slot)
    local sid=visualKey
    pcall(function()
        local text=PV_VisualSelection and PV_VisualSelection[slot]
        if text and text.id and Sync and Sync.Weapons and Sync.Weapons[text.id] then sid=text.id end
    end)
    if Sync and Sync.Weapons and Sync.Weapons[sid] then return sid end
    if Sync and Sync.Weapons and Sync.Weapons[visualKey] then return visualKey end

    local target
    pcall(function()
        local item=byId and (byId[sid] or byId[visualKey])
        target=item and (item.base or item.name)
    end)
    if target and Sync and Sync.Weapons then
        local number=pvNorm(target)
        for index,Weapon in pairs(Sync.Weapons) do
            if type(Weapon)=="table" and Weapon.ItemType=="Gun" and Weapon.ItemName and pvNorm(Weapon.ItemName)==number then
                return index
            end
        end
    end
    return sid
end

function pvHeldGripFromData(data)
    if type(data)~="table" or #data<12 then return nil end
    local success,result=pcall(function() return CFrame.new(table.unpack(data)) end)
    return success and result or nil
end

function pvSanitizeHeldTool(tool)
    if not tool then return end
    pcall(function()
        tool.CanBeDropped=false
        tool.RequiresHandle=false
    end)
    for _,data in ipairs(tool:GetDescendants()) do
        if data:IsA("Script") or data:IsA("LocalScript") or data:IsA("ModuleScript") then
            pcall(function() data:Destroy() end)
        elseif data:IsA("BasePart") then
            pcall(function()
                data.Anchored=false
                data.CanCollide=false
                data.Massless=true
                data.CanTouch=false
                data.CanQuery=false
                data.CastShadow=false
            end)
        elseif data:IsA("TouchTransmitter") then
            pcall(function() data:Destroy() end)
        end
    end
end

function pvLoadExactHeldGun(syncId, cbValue)
    if not syncId then if cbValue then cbValue(false) end return end
    local cached=_G.pvHeldAssetCache[syncId]
    if cached~=nil then
        if cbValue then cbValue(cached~=false,cached~=false and cached or nil) end
        return
    end
    if _G.pvHeldAssetLoading[syncId] then
        if cbValue and not _G.pvHeldAssetCb[syncId] then _G.pvHeldAssetCb[syncId]=cbValue end
        return
    end

    _G.pvHeldAssetLoading[syncId]=true
    if cbValue then _G.pvHeldAssetCb[syncId]=cbValue end

    task.spawn(function()
        local result=nil
        pcall(function()
            local entry=Sync and Sync.Weapons and Sync.Weapons[syncId]
            if not entry then return end
            local function asset(value)
                return tonumber(value) or tonumber(tostring(value or ""):match("%d+"))
            end
            local aid=asset(entry.ItemID) or asset(entry.DisplayID)
            if not aid or type(game.GetObjects)~="function" then return end

            local objs=game:GetObjects("rbxassetid://"..aid)
            local root=type(objs)=="table" and objs[1] or nil
            if not root then return end

            local sourceTool=nil
            if root:IsA("Tool") and root:FindFirstChild("Handle",true) then
                sourceTool=root
            else
                for _,data in ipairs(root:GetDescendants()) do
                    if data:IsA("Tool") and data:FindFirstChild("Handle",true) then
                        sourceTool=data
                        break
                    end
                end
            end

            if not sourceTool then
                pcall(function() root:Destroy() end)
                return
            end

            local template=sourceTool:Clone()
            pvSanitizeHeldTool(template)
            local handle=template:FindFirstChild("Handle",true)
            if not (handle and handle:IsA("BasePart")) then
                pcall(function() template:Destroy() end)
                pcall(function() root:Destroy() end)
                return
            end

            local gui2=sourceTool.Grip
            result={template=template,grip={gui2:GetComponents()},assetId=aid}
            pcall(function() root:Destroy() end)
        end)

        _G.pvHeldAssetLoading[syncId]=nil
        _G.pvHeldAssetCache[syncId]=result or false

        local func=_G.pvHeldAssetCb[syncId]
        _G.pvHeldAssetCb[syncId]=nil
        if func then pcall(func,result~=nil,result) end
    end)
end

function pvQueueHeldGunLoad(syncId, visualId, handle)
    if not syncId or _G.pvHeldAssetCache[syncId]~=nil
       or _G.pvHeldAssetLoading[syncId] or _G.pvHeldAssetPending[syncId] then return end

    _G.pvHeldAssetPending[syncId]=true
    local gen=_G.pvGen


    task.delay(0.30,function()
        _G.pvHeldAssetPending[syncId]=nil
        if _G.pvGen~=gen or not handle or not handle.Parent then return end
        if not (wornSlots and wornSlots.Gun==visualId) then return end
        if pvHeldSyncKey(visualId,"Gun")~=syncId then return end

        pvLoadExactHeldGun(syncId,function(success)
            if _G.pvGen==gen and success and handle and handle.Parent
               and wornSlots and wornSlots.Gun==visualId then
                pcall(function() handle:SetAttribute("pvHeldPose",nil) end)
                task.defer(function() pcall(pvReskinHeld,"Gun") end)
            end
        end)
    end)
end

function pvClearHeldGunVisual(handle)
    if not handle then return end
    for _,name in ipairs({
        "pvHeld","pvHeldGunV18","pvHeldGunV19","pvHeldGunV20",
        "pvHeldRealGunV21","pvHeldRealGunV22"
    }) do
        local x=handle:FindFirstChild(name)
        if x then pcall(function() x:Destroy() end) end
    end
end

function pvBuildExactHeldGun(roundTool,roundHandle,id,syncId,entry)
    if not (roundTool and roundHandle and entry and entry.template) then return false end
    local targetGrip=pvHeldGripFromData(entry.grip)
    if not targetGrip then return false end

    local defaultGrip=CFrame.new()
    if roundTool:IsA("Tool") then
        if not _G.pvOrigRoundGrip[roundTool] then
            _G.pvOrigRoundGrip[roundTool]=roundTool.Grip
        end
        defaultGrip=_G.pvOrigRoundGrip[roundTool]
    end


    local correction=defaultGrip:Inverse()*targetGrip

    pvClearHeldGunVisual(roundHandle)

    local visualTool=entry.template:Clone()
    visualTool.Name="pvHeldRealGunV22"
    pvSanitizeHeldTool(visualTool)
    local visualHandle=visualTool:FindFirstChild("Handle",true)
    if not (visualHandle and visualHandle:IsA("BasePart")) then
        pcall(function() visualTool:Destroy() end)
        return false
    end


    local parts={}
    for _,data in ipairs(visualTool:GetDescendants()) do
        if data:IsA("BasePart") then parts[#parts+1]=data end
    end
    local sourceHandleCF=visualHandle.CFrame
    local rel={}
    for _,part in ipairs(parts) do
        rel[part]=sourceHandleCF:ToObjectSpace(part.CFrame)
    end

    visualTool.Parent=roundHandle
    pcall(function() roundHandle.LocalTransparencyModifier=1 end)

    local targetCF=roundHandle.CFrame*correction
    for _,part in ipairs(parts) do
        pcall(function() part.CFrame=targetCF*rel[part] end)
        if part~=visualHandle and not part:FindFirstChild("pvRigidV22") then
            local weldConstraint=Instance.new("WeldConstraint")
            weldConstraint.Name="pvRigidV22"
            weldConstraint.Part0=visualHandle
            weldConstraint.Part1=part
            weldConstraint.Parent=part
        end
    end

    local weld=Instance.new("Weld")
    weld.Name="pvHeldRealGunWeldV22"
    weld.Part0=roundHandle
    weld.Part1=visualHandle
    weld.C0=correction
    weld.C1=CFrame.new()
    weld.Parent=visualHandle

    pcall(function()
        visualTool:SetAttribute("pvHeldVisualId",tostring(id))
        visualTool:SetAttribute("pvHeldSyncId",tostring(syncId))
    end)
    return true
end

-- Both local and other-player held guns use exactly the same mesh and pose.
function pvRenderHeldGun(handle,id,record)
    if not (handle and record and record.mesh) then return false end
    local meshNum=tostring(record.mesh):match("%d+")
    if not meshNum then return false end
    local texNum=record.tex and tostring(record.tex):match("%d+") or nil


        local poseTag=tostring(id)..":Gun:v50:familyangle"
        if handle:GetAttribute("pvHeldSkin")~=id or handle:GetAttribute("pvHeldPose")~=poseTag or not handle:FindFirstChild("pvHeldFastGunV24") then
            pcall(function() handle.LocalTransparencyModifier=1 end)


            for _,name in ipairs({
                "pvHeld","pvHeldGunV18","pvHeldGunV19","pvHeldGunV20",
                "pvHeldRealGunV21","pvHeldRealGunV22"
            }) do
                local old=handle:FindFirstChild(name)
                if old then pcall(function() old:Destroy() end) end
            end

            local disp=handle:FindFirstChild("pvHeldFastGunV24")
            if not disp then
                disp=Instance.new("Part")
                disp.Name="pvHeldFastGunV24"
                disp.Size=Vector3.new(0.2,0.2,0.2)
                disp.Transparency=0
                disp.CanCollide=false
                disp.Massless=true
                pcall(function()
                    disp.CanQuery=false
                    disp.CanTouch=false
                    disp.CastShadow=false
                end)
                local specialMesh=Instance.new("SpecialMesh")
                specialMesh.Name="Mesh"
                specialMesh.MeshType=Enum.MeshType.FileMesh
                specialMesh.Parent=disp
                disp.Parent=handle

                local weld=Instance.new("Weld")
                weld.Name="pvHeldFastGunWeldV24"
                weld.Part0=handle
                weld.Part1=disp
                weld.C0=CFrame.new()
                weld.C1=CFrame.new()
                weld.Parent=disp
            end

            local model=pvFindDisplayMesh(disp)
            local heldScale=pvRenderScale(record,"Gun",id)
            if model then
                pcall(function()
                    model.MeshId="rbxassetid://"..meshNum
                    model.TextureId=texNum and ("rbxassetid://"..texNum) or ""
                    model.Scale=heldScale or Vector3.new(0.1,0.1,0.1)
                    if record.offset then
                        model.Offset=Vector3.new(record.offset[1] or 0,record.offset[2] or 0,record.offset[3] or 0)
                    else
                        model.Offset=Vector3.new()
                    end
                    model.VertexColor=Vector3.new(1,1,1)
                end)
            end

            local weld=disp:FindFirstChild("pvHeldFastGunWeldV24")
            if weld and weld:IsA("Weld") then


                local heldCF=pvHeldGunDefaultPose(id,record)
                pcall(function()
                    weld.Part0=handle
                    weld.Part1=disp
                    weld.C0=heldCF
                    weld.C1=CFrame.new()
                    disp.CFrame=handle.CFrame*heldCF
                end)
            end


            pcall(function()
                handle:SetAttribute("pvHeldSkin",id)
                handle:SetAttribute("pvHeldPose",poseTag)
            end)
        end
        return true
end

function pvReskinHeld(slot)
    if settings.bodyCleared then return end
    local character=playerGui.Character; if not character then return end

    local id=wornSlots and wornSlots[slot]


    if not id and slot=="Gun" then
        id="DefaultGun"
    end

    if not id then return end
    local record=meshDB[id]; if not (record and record.mesh) then return end

    local meshNum=tostring(record.mesh):match("%d+"); if not meshNum then return end
    local texNum=record.tex and tostring(record.tex):match("%d+") or nil

    local backpack=playerGui:FindFirstChildOfClass("Backpack") or playerGui:FindFirstChild("Backpack")
    local tool=character:FindFirstChild(slot) or (backpack and backpack:FindFirstChild(slot))
    if not (tool and (tool:IsA("Tool") or tool:IsA("Model"))) then return end
    if slot=="Knife" then _G.pvLastRoundKnifeSeen=os.clock() end


    if tool:IsA("Tool") then
        local item=byId and byId[id]
        local icon=item and item.img or ""
        if icon=="" then
            local entry=Sync and Sync.Weapons and Sync.Weapons[id]
            if entry then icon=resolveImg(id,entry.Image) end
        end
        icon=pvFixImg(icon)
        if icon~="" then
            local oldIcon=tool:GetAttribute("pvOrigRoundIcon")
            if oldIcon==nil then
                oldIcon=tostring(tool.TextureId or "")
                pcall(function() tool:SetAttribute("pvOrigRoundIcon",oldIcon) end)
            end
            local previousVisualId=tool:GetAttribute("pvHotbarVisualId")
            local first=(previousVisualId~=tostring(id))
            local previousVisualIcon=""
            if first and previousVisualId and tostring(previousVisualId)~="" then
                pcall(function()
                    local pwValue=byId and byId[tostring(previousVisualId)]
                    previousVisualIcon=pwValue and pwValue.img or ""
                    if previousVisualIcon=="" then
                        local peValue=Sync and Sync.Weapons and Sync.Weapons[tostring(previousVisualId)]
                        if peValue then previousVisualIcon=resolveImg(tostring(previousVisualId),peValue.Image) end
                    end
                    previousVisualIcon=pvFixImg(previousVisualIcon)
                end)
            end

            local parentKey=(tool.Parent==character) and "char" or ((backpack and tool.Parent==backpack) and "backpack" or tostring(tool.Parent))
            local lastParent=tostring(tool:GetAttribute("pvHotbarParent") or "")
            local texNow=tostring(tool.TextureId or ""):match("%d+") or ""
            local texWant=tostring(icon):match("%d+") or ""
            local needPatch=first or lastParent~=parentKey or texNow~=texWant

            if texNow~=texWant then pcall(function() tool.TextureId=icon end) end
            if needPatch then
                pcall(pvPatchRoundHotbarIcon,tool,slot,id,icon,oldIcon,previousVisualIcon)
                pcall(function()
                    tool:SetAttribute("pvHotbarVisualId",tostring(id))
                    tool:SetAttribute("pvHotbarParent",parentKey)
                end)


                task.delay(0.12,function()
                    if tool.Parent then pcall(pvPatchRoundHotbarIcon,tool,slot,id,icon,oldIcon,previousVisualIcon) end
                end)
            end
        end
    end

    local handle=tool:FindFirstChild("Handle") or tool:FindFirstChild("Handle",true)
    if not handle then return end

    if slot=="Gun" then
        pvRenderHeldGun(handle,id,record)
        return
    end

    local heldScale=pvRenderScale(record,slot,id)
    local poseTag=tostring(id)..":"..tostring(slot)..":v23"
    if handle:GetAttribute("pvHeldSkin")==id and handle:GetAttribute("pvHeldPose")==poseTag then return end

    if record.studio then pvHideStudioOriginal(handle) end
    local specialMesh=pvFindDisplayMesh(handle)
    if specialMesh then
        pcall(function()
            specialMesh.MeshId="rbxassetid://"..meshNum
            specialMesh.TextureId=texNum and ("rbxassetid://"..texNum) or ""
            if heldScale then specialMesh.Scale=heldScale end
        end)
    elseif handle:IsA("MeshPart") then
        pcall(function() handle.LocalTransparencyModifier=1 end)
        local disp=handle:FindFirstChild("pvHeld")
        if not disp then
            disp=Instance.new("Part")
            disp.Name="pvHeld"
            disp.Size=Vector3.new(0.2,0.2,0.2)
            disp.CanCollide=false
            disp.Massless=true
            pcall(function() disp.CanQuery=false; disp.CanTouch=false end)
            local specialMesh2=Instance.new("SpecialMesh")
            specialMesh2.MeshType=Enum.MeshType.FileMesh
            specialMesh2.Name="Mesh"
            specialMesh2.Parent=disp
            local weldConstraint=Instance.new("WeldConstraint")
            weldConstraint.Part0=handle
            weldConstraint.Part1=disp
            weldConstraint.Parent=disp
            disp.Parent=handle
        end
        pcall(function() disp.CFrame=handle.CFrame end)
        local model=pvFindDisplayMesh(disp)
        if model then pcall(function()
            model.MeshId="rbxassetid://"..meshNum
            model.TextureId=texNum and ("rbxassetid://"..texNum) or ""
            model.Scale=heldScale or Vector3.new(0.1,0.1,0.1)
        end) end
    end

    local heldSurf=handle:FindFirstChild("pvHeld") or handle
    pcall(pvApplyStudioDetails,heldSurf,record,id)
    pcall(pvApplyFX,heldSurf,id)
    pcall(function()
        handle:SetAttribute("pvHeldSkin",id)
        handle:SetAttribute("pvHeldPose",poseTag)
    end)
end


pcall(function()
    local function hookHeldContainer(container)
        if not container or container:GetAttribute("pvHeldWatcher") then return end
        container:SetAttribute("pvHeldWatcher",true)
        pvSession.connect(container.ChildAdded,function(child)
            if child.Name=="Gun" or child.Name=="Knife" then


                if child.Name=="Knife" and child:IsA("Tool") and not child:GetAttribute("pvThrowHook") then
                    child:SetAttribute("pvThrowHook",true)
                    pvSession.connect(child.Activated,function()
                        _G.pvThrowActiveUntil=os.clock()+2.8
                    end)
                end
                task.defer(function() pcall(pvReskinHeld,child.Name) end)
            end
        end)
    end
    hookHeldContainer(playerGui:FindFirstChildOfClass("Backpack") or playerGui:FindFirstChild("Backpack"))
    hookHeldContainer(playerGui.Character)
    pvSession.connect(playerGui.CharacterAdded,function(character)
        hookHeldContainer(character)
        task.defer(function()
            pcall(pvReskinHeld,"Gun")
            pcall(pvReskinHeld,"Knife")
        end)
    end)
    pcall(pvReskinHeld,"Gun")
    pcall(pvReskinHeld,"Knife")
end)


_G.pvThrowActiveUntil = _G.pvThrowActiveUntil or 0
_G.pvThrowCandidatePart = nil
_G.pvThrowFollowerV17 = _G.pvThrowFollowerV17 or nil

function pvThrowMeshId(value)
    return tostring(value or ""):match("%d+") or ""
end

function pvThrowPartMesh(part)
    if not (part and part:IsA("BasePart")) then return "" end
    local model=""
    pcall(function()
        if part:IsA("MeshPart") then
            model=pvThrowMeshId(part.MeshId)
        else
            local specialMesh=pvFindDisplayMesh(part)
            model=specialMesh and pvThrowMeshId(specialMesh.MeshId) or ""
        end
    end)
    return model
end

function pvThrowStrictPart(obj, allowVisual)
    if not obj then return nil end
    if obj:IsA("SpecialMesh") then obj=obj.Parent end
    if not (obj and obj:IsA("BasePart") and obj.Parent) then return nil end


    if obj:GetAttribute("pvThrowCandidateV17")==true then return obj end


    if obj.Anchored then return nil end

    local character=playerGui.Character
    if character and obj:IsDescendantOf(character) then return nil end
    local backpack=playerGui:FindFirstChildOfClass("Backpack") or playerGui:FindFirstChild("Backpack")
    if backpack and obj:IsDescendantOf(backpack) then return nil end

    local part=obj
    for _=1,10 do
        if not part or part==workspace then break end
        if part:IsA("Tool") then return nil end
        if part:IsA("Model") and part:FindFirstChildOfClass("Humanoid") then return nil end
        if part.Name=="WeaponDisplays" then return nil end
        part=part.Parent
    end


    local text=obj.Size
    if math.max(text.X,text.Y,text.Z) > 7 or (text.X*text.Y*text.Z) > 22 then return nil end


    local hrp=character and character:FindFirstChild("HumanoidRootPart")
    if hrp and (obj.Position-hrp.Position).Magnitude > 140 then return nil end

    local def=""
    pcall(function()
        local result=meshDB and meshDB.DefaultKnife
        def=result and pvThrowMeshId(result.mesh) or ""
    end)

    local selected=""
    pcall(function()
        local id=wornSlots and wornSlots.Knife
        local result=id and meshDB and meshDB[id]
        selected=result and pvThrowMeshId(result.mesh) or ""
    end)

    local current=pvThrowPartMesh(obj)
    if current=="" then return nil end
    if def~="" and current==def then return obj end
    if allowVisual and selected~="" and current==selected and os.clock()<=((_G.pvThrowActiveUntil) or 0) then
        return obj
    end
    return nil
end

function pvThrowDestroyFollower()
    local func=_G.pvThrowFollowerV17
    if type(func)=="table" then
        pcall(function() if func.conn then func.conn:Disconnect() end end)
        pcall(function() if func.visual and func.visual.Parent then func.visual:Destroy() end end)
    end
    _G.pvThrowFollowerV17=nil
end
pvSession.addCleanup(function() pcall(pvThrowDestroyFollower) end)

function pvThrowMakeVisual(part,id,record)
    if not (part and part.Parent and record and record.mesh) then return nil end


    local disp=part:FindFirstChild("pvThrowVisualV17")
    if not disp then
        disp=Instance.new("Part")
        disp.Name="pvThrowVisualV17"
        disp.Size=Vector3.new(0.2,0.2,0.2)
        disp.Anchored=true
        disp.Transparency=0
        disp.CanCollide=false
        disp.Massless=true
        pcall(function()
            disp.CanTouch=false
            disp.CanQuery=false
            disp.CastShadow=false
        end)
        local specialMesh=Instance.new("SpecialMesh")
        specialMesh.Name="Mesh"
        specialMesh.MeshType=Enum.MeshType.FileMesh
        specialMesh.Parent=disp


        disp.Parent=workspace
    end

    local meshNum=pvThrowMeshId(record.mesh)
    local texNum=pvThrowMeshId(record.tex)
    local scale=pvRenderScale(record,"Knife",id) or Vector3.new(0.1,0.1,0.1)
    local model=pvFindDisplayMesh(disp)
    if model then
        pcall(function()
            model.MeshId="rbxassetid://"..meshNum
            model.TextureId=(texNum~="") and ("rbxassetid://"..texNum) or ""
            model.Scale=scale
            if record.offset then
                model.Offset=Vector3.new(record.offset[1] or 0,record.offset[2] or 0,record.offset[3] or 0)
            end
        end)
    end

    if disp:GetAttribute("pvVisualId")~=tostring(id) then
        pcall(pvApplyStudioDetails,disp,record,id)
        pcall(pvApplyFX,disp,id)
        pcall(function() disp:SetAttribute("pvVisualId",tostring(id)) end)
    end
    return disp
end

function pvThrowStartFollower(part)
    part=pvThrowStrictPart(part,true)
    if not part then return false end

    local id=wornSlots and wornSlots.Knife
    local record=id and meshDB and meshDB[id]
    if not (id and record and record.mesh) then return false end

    pcall(function() part:SetAttribute("pvThrowCandidateV17",true) end)
    _G.pvThrowCandidatePart=part


    pvThrowDestroyFollower()

    local disp=pvThrowMakeVisual(part,id,record)
    if not disp then return false end


    pcall(function() part.LocalTransparencyModifier=1 end)

    local state={
        part=part,
        visual=disp,
        lift=0,
        lastGroundCheck=0,
        started=os.clock(),
        conn=nil,
    }
    _G.pvThrowFollowerV17=state

    local RunService=game:GetService("RunService")
    state.conn=pvSession.connect(RunService.RenderStepped,function()
        if _G.pvThrowFollowerV17~=state or _G.pvGen~=MY_GEN
           or not part.Parent or not disp.Parent then
            pvThrowDestroyFollower()
            return
        end


        if os.clock()-state.started > 6.0 then
            pvThrowDestroyFollower()
            return
        end

        local speed=999
        pcall(function() speed=part.AssemblyLinearVelocity.Magnitude end)


        if speed<3.0 and os.clock()-state.lastGroundCheck>0.10 then
            state.lastGroundCheck=os.clock()
            state.lift=0
            pcall(function()
                local rpValue=RaycastParams.new()
                rpValue.FilterType=Enum.RaycastFilterType.Exclude
                local exValue={part,disp}
                local character=playerGui.Character
                if character then exValue[#exValue+1]=character end
                rpValue.FilterDescendantsInstances=exValue


                local hit=workspace:Raycast(
                    part.Position+Vector3.new(0,1.5,0),
                    Vector3.new(0,-3.0,0),
                    rpValue
                )
                if hit then
                    local need=hit.Position.Y-part.Position.Y+0.18
                    if need>0.04 then state.lift=math.clamp(need,0.06,0.75) end
                end
            end)
        elseif speed>=3.0 then
            state.lift=0
        end


        pcall(function()
            disp.CFrame=part.CFrame+Vector3.new(0,state.lift,0)
        end)
    end)

    return true
end

pcall(function()
    local myGen=_G.pvGen
    local watched=setmetatable({}, {__mode="k"})

    local function watchPart(part)
        if _G.pvGen~=myGen or not part or not part.Parent then return end
        part=pvThrowStrictPart(part,true)
        if not part then return end
        if watched[part] then
            if _G.pvThrowCandidatePart~=part then pcall(pvThrowStartFollower,part) end
            return
        end
        watched[part]=true
        pcall(function() part:SetAttribute("pvThrowCandidateV17",true) end)


        pcall(pvThrowStartFollower,part)
        for _,data in ipairs({0.06,0.16,0.32,0.60,1.0}) do
            task.delay(data,function()
                if _G.pvGen==myGen and part.Parent and _G.pvThrowCandidatePart~=part then
                    pcall(pvThrowStartFollower,part)
                end
            end)
        end
    end

    local function armThrow()
        if _G.pvGen~=myGen or not (wornSlots and wornSlots.Knife) then return end
        _G.pvThrowActiveUntil=os.clock()+5

        local knife=playerGui.Character
        local tool=knife and knife:FindFirstChild("Knife")
        local handle=tool and tool:FindFirstChild("Handle")
        if handle and handle:IsA("BasePart") and not handle:GetAttribute("pvThrowHandleWatchV17") then
            handle:SetAttribute("pvThrowHandleWatchV17",true)
            pvSession.connect(handle.AncestryChanged,function()
                if _G.pvGen~=myGen then return end
                if handle.Parent and handle:IsDescendantOf(workspace)
                   and not (playerGui.Character and handle:IsDescendantOf(playerGui.Character)) then
                    task.defer(watchPart,handle)
                end
            end)
        end
    end

    local function hookKnife(tool)
        if not (tool and tool:IsA("Tool") and tool.Name=="Knife") then return end
        if tool:GetAttribute("pvThrowHookV17") then return end
        tool:SetAttribute("pvThrowHookV17",true)
        pvSession.connect(tool.Activated,armThrow)
    end

    local function hookContainer(child)
        if not child then return end
        for _,x in ipairs(child:GetChildren()) do hookKnife(x) end
        pvSession.connect(child.ChildAdded,hookKnife)
    end

    hookContainer(playerGui:FindFirstChildOfClass("Backpack") or playerGui:FindFirstChild("Backpack"))
    hookContainer(playerGui.Character)
    pvSession.connect(playerGui.CharacterAdded,function(character)
        pvThrowDestroyFollower()
        hookContainer(character)
        task.defer(function()
            hookContainer(playerGui:FindFirstChildOfClass("Backpack") or playerGui:FindFirstChild("Backpack"))
        end)
    end)

    pvSession.connect(UIS.InputBegan,function(input,processed)
        if processed or _G.pvGen~=myGen then return end
        local knife2=playerGui.Character
        local knife=knife2 and knife2:FindFirstChild("Knife")
        if not (knife and knife:IsA("Tool") and wornSlots and wornSlots.Knife) then return end
        if input.KeyCode==Enum.KeyCode.E
           or input.KeyCode==Enum.KeyCode.Q
           or input.UserInputType==Enum.UserInputType.MouseButton2 then
            armThrow()
        end
    end)


    pvSession.connect(workspace.DescendantAdded,function(obj)
        if _G.pvGen~=myGen or os.clock()>((_G.pvThrowActiveUntil) or 0) then return end
        if not (obj:IsA("BasePart") or obj:IsA("SpecialMesh")) then return end
        local part=pvThrowStrictPart(obj,true)
        if part then task.defer(watchPart,part) end
    end)
end)


_G.pvOtherSkins = _G.pvOtherSkins or {}
PV_OtherOriginal=setmetatable({}, {__mode="k"})
function pvRememberOtherPart(part,userId,slot)
    if PV_OtherOriginal[part] then return end
    local mesh=pvFindDisplayMesh(part)
    local rigidConstraint=part:FindFirstChildOfClass("RigidConstraint")
    local attachment=(rigidConstraint and rigidConstraint.Attachment1) or part:FindFirstChildOfClass("Attachment")
    local joint
    local plr=userId and Players:GetPlayerByUserId(userId)
    local character=plr and plr.Character
    if not rigidConstraint and character then
        for _,item in ipairs(character:GetDescendants()) do
            if item:IsA("Weld") and item.Part1==part then joint=item;break end
        end
    end
    local children={}
    for _,child in ipairs(part:GetChildren()) do children[child]=true end
    PV_OtherOriginal[part]={userId=userId,slot=slot,transparency=part.Transparency,localTransparency=part.LocalTransparencyModifier,
        mesh=mesh,meshId=mesh and mesh.MeshId,texture=mesh and mesh.TextureId,
        scale=mesh and mesh.Scale,offset=mesh and mesh.Offset,
        attachment=attachment,attachmentCF=attachment and attachment.CFrame,rigid=rigidConstraint,anchor=rigidConstraint and rigidConstraint.Attachment0,
        joint=joint,jointPart=joint and joint.Part0,jointC0=joint and joint.C0,jointC1=joint and joint.C1,children=children,heldSkin=part:GetAttribute("pvHeldSkin"),heldPose=part:GetAttribute("pvHeldPose"),skin=part:GetAttribute("pvOtherSkin")}
end
function pvRestoreOtherPlayer(plr)
    if not plr then return 0,0 end
    _G.pvOtherSkins[plr.UserId]=nil
    local restored,failed=0,0
    -- Recover marked displays from earlier script versions with no snapshot.
    local character=plr.Character
    if character then
        for _,slot in ipairs({"Knife","Gun"}) do
            local ref=character:FindFirstChild(slot=="Gun" and "DisplayRefGun" or "DisplayRefKnife")
            local disp=ref and ref:IsA("ObjectValue") and ref.Value or character:FindFirstChild(slot.."Display",true)
            local tool=character:FindFirstChild(slot)
            local handle=tool and tool:FindFirstChild("Handle")
            for _,part in pairs({display=disp,held=handle}) do
                if part and part:IsA("BasePart") and part:GetAttribute("pvOtherSkin") and not PV_OtherOriginal[part] then
                    pvRememberOtherPart(part,plr.UserId,slot)
                end
            end
        end
    end
    for part,old in pairs(PV_OtherOriginal) do
        if old.userId==plr.UserId then
            local success,reason=pcall(function()
                if not part.Parent then return end
                if part.Name=="pvOtherDisplayKnife" or part.Name=="pvOtherDisplayGun" then
                    part:Destroy();restored=restored+1;return
                end
                -- A pre-existing skin marker means the snapshot was taken after
                -- an older version had already changed the native weapon.
                local contaminated=old.skin~=nil
                local actualKey
                if contaminated and not part:IsA("MeshPart") then
                    local actual=plr:GetAttribute(old.slot=="Gun" and "EquippedGun" or "EquippedKnife")
                    actual=actual and tostring(actual)
                    if actual and meshDB[actual] then actualKey=actual end
                    if not actualKey then error("Original weapon data unavailable; respawn or rejoin to reset this older visual") end
                end
                for _,child in ipairs(part:GetChildren()) do
                    if (child.Name=="pvOther" or child:GetAttribute("pvFX") or child:GetAttribute("pvOtherHeld"))
                        or (not old.children[child] and child:IsA("SpecialMesh")) then child:Destroy() end
                end
                if actualKey then
                    local record=meshDB[actualKey]
                    local mesh=pvFindDisplayMesh(part)
                    if not mesh then mesh=Instance.new("SpecialMesh");mesh.MeshType=Enum.MeshType.FileMesh;mesh.Parent=part end
                    mesh.MeshId=pvNormId(record.mesh);mesh.TextureId=pvNormId(record.tex)
                    mesh.Scale=pvRenderScale(record,old.slot,actualKey)
                    mesh.Offset=record.offset and Vector3.new(table.unpack(record.offset)) or Vector3.new()
                    if old.attachment and old.attachment.Parent then
                        old.attachment.CFrame=pvWantCF(actualKey,record,nil,old.slot) or old.attachmentCF
                    end
                else
                    if old.mesh and old.mesh.Parent then
                        old.mesh.MeshId=old.meshId;old.mesh.TextureId=old.texture
                        old.mesh.Scale=old.scale;old.mesh.Offset=old.offset
                    end
                    if old.attachment and old.attachment.Parent then old.attachment.CFrame=old.attachmentCF end
                end
                if old.rigid and old.rigid.Parent then old.rigid.Attachment0=old.anchor end
                if old.joint and old.joint.Parent then
                    old.joint.Part0=old.jointPart;old.joint.C0=old.jointC0;old.joint.C1=old.jointC1
                end
                part.Transparency=contaminated and 0 or old.transparency
                part.LocalTransparencyModifier=contaminated and 0 or old.localTransparency
                part:SetAttribute("pvOtherSkin",nil)
                part:SetAttribute("pvHeldSkin",old.heldSkin)
                part:SetAttribute("pvHeldPose",old.heldPose)
                restored=restored+1
            end)
            if success then PV_OtherOriginal[part]=nil
            else failed=failed+1;warn("porkVisuals restore: "..tostring(reason)) end
        end
    end
    if character then
        for _,inst in ipairs(character:GetDescendants()) do
            if inst.Name=="pvOtherDisplayKnife" or inst.Name=="pvOtherDisplayGun" then
                inst:Destroy();restored=restored+1
            elseif inst.Name=="pvOtherMountKnife" or inst.Name=="pvOtherMountGun" then inst:Destroy() end
        end
    end
    return restored,failed
end
function pvOtherClearNotice(restored,failed)
    if failed>0 then return "Cleared "..restored.." weapon display(s). Couldn't recover "..failed.." older visual(s); respawn or rejoin, then try again." end
    if restored==0 then return "No changed weapon displays found to clear." end
    return "Cleared "..restored.." weapon display(s); original weapons restored."
end
