-- Leave the real players' weapon code unchanged. This helper only hides the
-- preview default knife/gun while a visual weapon skin is equipped.
function pvVisualDefaultVisibility(model,slot,show)
    if not (model and model.Parent) or (slot~="Knife" and slot~="Gun") then return end
    model:SetAttribute("pvVisualHideDefault"..slot,not show)
    local pvVisualBackDefault=model:FindFirstChild("pvVisualBackDefault"..slot)
    if pvVisualBackDefault and pvVisualBackDefault:IsA("BasePart") then
        pvVisualBackDefault.Transparency=show and 0 or 1
        pvVisualBackDefault.LocalTransparencyModifier=show and 0 or 1
    end
end
function pvSkinPart(part, key, slot, userId)
    if not (part and part:IsA("BasePart") and part.Parent) then return false end
    local record = meshDB[key]; if not (record and record.mesh) then return false end
    local meshNum = tostring(record.mesh):match("%d+"); if not meshNum then return false end
    local texNum = record.tex and tostring(record.tex):match("%d+") or nil
    pvRememberOtherPart(part,userId,slot)
    local scale = pvRenderScale(record, slot, key)
    local specialMesh = pvFindDisplayMesh(part)
    if not specialMesh and not part:IsA("MeshPart") then
        specialMesh=Instance.new("SpecialMesh");specialMesh.MeshType=Enum.MeshType.FileMesh;specialMesh.Parent=part
    end
    if specialMesh then
        part.Transparency=0;part.LocalTransparencyModifier=0
        do
            specialMesh.MeshId = "rbxassetid://"..meshNum
            specialMesh.TextureId = texNum and ("rbxassetid://"..texNum) or ""
            if scale then specialMesh.Scale = scale end
        end
    elseif part:IsA("MeshPart") then

        pcall(function() part.LocalTransparencyModifier = 1 end)
        local disp = part:FindFirstChild("pvOther")
        if not disp then
            disp = Instance.new("Part"); disp.Name = "pvOther"
            disp.Size = Vector3.new(0.2,0.2,0.2); disp.CanCollide = false; disp.Massless = true
            pcall(function() disp.CanQuery = false; disp.CanTouch = false end)
            local specialMesh2 = Instance.new("SpecialMesh"); specialMesh2.MeshType = Enum.MeshType.FileMesh; specialMesh2.Parent = disp
            local weldConstraint = Instance.new("WeldConstraint"); weldConstraint.Part0 = part; weldConstraint.Part1 = disp; weldConstraint.Parent = disp
            pcall(function() disp.CFrame = part.CFrame end)
            disp.Parent = part
        end
        disp.Transparency=0;disp.LocalTransparencyModifier=0
        local model = pvFindDisplayMesh(disp)
        if model then
            model.MeshId = "rbxassetid://"..meshNum
            model.TextureId = texNum and ("rbxassetid://"..texNum) or ""
            model.Scale = scale or Vector3.new(0.1,0.1,0.1)
        end
    end

    if part:GetAttribute("pvOtherSkin")~=tostring(key) then
        pcall(pvApplyFX, part:FindFirstChild("pvOther") or part, key)
    end

    pcall(function()
        local rigidConstraint = part:FindFirstChildOfClass("RigidConstraint")
        local attachment = (rigidConstraint and rigidConstraint.Attachment1) or part:FindFirstChildOfClass("Attachment")
        local want = attachment and pvWantCF(key, record, nil, slot)
        if want then attachment.CFrame = want end
    end)
    pcall(function() part:SetAttribute("pvOtherSkin", tostring(key)) end)
    return true
end
-- Other characters may not expose DisplayRefKnife/DisplayRefGun locally.
-- Create a client-only body display when neither a display nor held tool exists.
function pvEnsureOtherDisplay(character,slot,key)
    local name="pvOtherDisplay"..slot
    local existing=character:FindFirstChild(name)
    if existing and existing:IsA("BasePart") then return existing end
    local anchor=pvVisualMountAnchor(character,slot)
    if not anchor then return nil end
    local part=Instance.new("Part");part.Name=name
    part.Size=Vector3.new(0.2,0.2,0.2);part.Anchored=false;part.Massless=true
    part.CanCollide=false;part.CanTouch=false;part.CanQuery=false
    local attachment=Instance.new("Attachment");attachment.Parent=part
    attachment.CFrame=pvWantCF(key,meshDB[key],nil,slot) or CFrame.new()
    part.CFrame=anchor.WorldCFrame*attachment.CFrame:Inverse()
    local rigidConstraint=Instance.new("RigidConstraint");rigidConstraint.Attachment0=anchor;rigidConstraint.Attachment1=attachment;rigidConstraint.Parent=part
    part.Parent=character;pvSession.ownRoot(part)
    return part
end
function pvClearOtherDisplays()
    local restored,failed=0,0
    for _,plr in ipairs(Players:GetPlayers()) do
        local count,errors=pvRestoreOtherPlayer(plr)
        restored=restored+count;failed=failed+errors
    end
    return restored,failed
end
function pvApplyOther(plr)
    local want=plr and _G.pvOtherSkins[plr.UserId]
    local character=plr and plr.Character
    if not (want and character and character.Parent) then return false end
    local shown=false
    for slot,key in pairs(want) do
        local override=character:FindFirstChild(slot=="Gun" and "DisplayRefGun" or "DisplayRefKnife")
        local disp=override and override:IsA("ObjectValue") and override.Value
        if not (disp and disp:IsA("BasePart") and disp.Parent) then
            disp=character:FindFirstChild(slot.."Display",true)
        end
        if not (disp and disp:IsA("BasePart") and disp.Parent) then disp=nil end
        local tool=character:FindFirstChild(slot)
        local handle=tool and tool:FindFirstChild("Handle")
        if not (handle and handle:IsA("BasePart")) then handle=nil end
        local fallback=character:FindFirstChild("pvOtherDisplay"..slot)
        if disp or handle then
            if fallback then fallback:Destroy() end
        else
            disp=pvEnsureOtherDisplay(character,slot,key)
        end
        if disp then
            pvRememberOtherPart(disp,plr.UserId,slot)
            pvApplyVisualMount(disp,slot,character)
            shown=pvSkinPart(disp,key,slot,plr.UserId) or shown
        end
        if handle then
            if slot=="Gun" then
                pvRememberOtherPart(handle,plr.UserId,slot)
                local legacy=handle:FindFirstChild("pvOther")
                if legacy then legacy:Destroy() end
                shown=pvRenderHeldGun(handle,key,meshDB[key]) or shown
                local visual=handle:FindFirstChild("pvHeldFastGunV24")
                if visual then visual:SetAttribute("pvOtherHeld",true) end
                handle:SetAttribute("pvOtherSkin",tostring(key))
            else
                shown=pvSkinPart(handle,key,slot,plr.UserId) or shown
            end
        end
    end
    return shown
end
function pvSkinOther(plr,slot,key)
    if not (plr and plr.Parent and meshDB[key] and (slot=="Knife" or slot=="Gun")) then return false,"invalid" end
    _G.pvOtherSkins[plr.UserId]=_G.pvOtherSkins[plr.UserId] or {}
    _G.pvOtherSkins[plr.UserId][slot]=key
    local success,shown=pcall(pvApplyOther,plr)
    if not success then warn("porkVisuals other-player equip: "..tostring(shown));return false,"error" end
    return shown,shown and "shown" or "pending"
end

