    local miss={}
    local dupTick=0
    while _G.pvGen==myGen do
        pvTick("weapon-keeper", 0.6)


        dupTick = dupTick + 1
        if dupTick >= 10 then dupTick = 0; pcall(pvCleanDuplicateDisplays) end
        if next(wornSlots)==nil then continue end
        pcall(scrubDisplays, true)
        for slot in pairs(wornSlots) do pcall(pvReskinHeld, slot) end
        for slot,id in pairs(wornSlots) do
            local record=meshDB[id]; local disp=displayPart(slot) or pvEnsureDisplay(slot)
            if record and disp then
                pcall(pvApplyVisualMount,disp,slot)
                if record.studio then pcall(pvHideStudioOriginal,disp) end


                local current,curTex
                local stand=disp:FindFirstChild("pvWorn"..slot)
                if stand then
                    local specialMesh=pvFindDisplayMesh(stand)
                    current=specialMesh and specialMesh.MeshId; curTex=specialMesh and specialMesh.TextureId
                    disp.LocalTransparencyModifier=1
                elseif disp:IsA("MeshPart") then current=disp.MeshId;curTex=disp.TextureID
                else
                    local specialMesh=pvFindDisplayMesh(disp)
                    current=specialMesh and specialMesh.MeshId;curTex=specialMesh and specialMesh.TextureId
                end

                if pvNormId(current)~=pvNormId(record.mesh) or pvNormId(curTex)~=pvNormId(record.tex) then
                    miss[slot]=(miss[slot] or 0)+1
                    if miss[slot]>=2 then pcall(wearMesh,id,slot); miss[slot]=0 end
                else
                    miss[slot]=0


                    pcall(function()
                        local rigidConstraint=disp:FindFirstChildOfClass("RigidConstraint")
                        local attachment=(rigidConstraint and rigidConstraint.Attachment1) or disp:FindFirstChildOfClass("Attachment")
                        if not attachment then return end
                        local want=pvWantCF(id, record, nil, slot)
                        if not want then return end

                        local first={attachment.CFrame:GetComponents()}
                        local button={want:GetComponents()}
                        for index=1,12 do
                            if math.abs(first[index]-button[index]) > 0.001 then attachment.CFrame=want; return end
                        end
                    end)
                end
            end
        end
    end
end)


