        -- TailVisible is the native switch: while keyword filtering is on,
        -- keep all tails off but leave unmatched message bodies visible.
        -- Restore the user's prior value when filtering is disabled/unloaded.
        local tailConfig, originalTailVisible, tailChangedConnection
        local tailFilterActive = false
        local function setNativeTailHidden(shouldHide)
            tailFilterActive = shouldHide
            if not shouldHide then
                if tailChangedConnection then
                    tailChangedConnection:Disconnect()
                    tailChangedConnection = nil
                end
                if tailConfig and tailConfig.Parent and originalTailVisible ~= nil then
                    pcall(function() tailConfig.TailVisible = originalTailVisible end)
                end
                tailConfig, originalTailVisible = nil, nil
                return
            end

            local success, config = pcall(function()
                return game:GetService("TextChatService"):FindFirstChildOfClass("BubbleChatConfiguration")
            end)
            if not success or not config then return end
            if tailConfig ~= config then
                if tailChangedConnection then tailChangedConnection:Disconnect() end
                if tailConfig and tailConfig.Parent and originalTailVisible ~= nil then
                    pcall(function() tailConfig.TailVisible = originalTailVisible end)
                end
                tailConfig = config
                local readOk, original = pcall(function() return config.TailVisible end)
                originalTailVisible = readOk and original or nil
                -- Some chat versions reapply their configured appearance.
                -- Preserve the filter's tail-less state while it is active.
                tailChangedConnection = config:GetPropertyChangedSignal("TailVisible"):Connect(function()
                    if tailFilterActive and tailConfig == config then
                        pcall(function()
                            if config.TailVisible then config.TailVisible = false end
                        end)
                    end
                end)
            end
            pcall(function() config.TailVisible = false end)
        end
    
        local function words(value)
            local result, seen = {}, {}
            for entry in value:gmatch("[^,\r\n]+") do
                local term = entry:match("^%s*(.-)%s*$")
                local key = term:lower()
                if term ~= "" and not seen[key] then
                    seen[key] = true
                    result[#result + 1] = term
                end
            end
            return result
        end
    
        -- Pre-render keyword filter: hiding ExperienceChat GUI nodes only
        -- happens AFTER Roblox has begun constructing/animating a bubble.
        -- OnBubbleAdded runs before the bubble is rendered. It hides the
        -- message contents, but the engine can still create an exit shell.
        -- The GUI watchers below remain as a fallback for existing bubbles,
        -- legacy clients, and any ExperienceChat implementation variations.
        local bubbleChatService = game:GetService("TextChatService")
        local invisibleBubbleText = utf8.char(0x200B, 0x2060, 0x200B)
        local activeBubbleTerms = {}
        local bindings = {}
        local nativeTextReady, nativeBubbleReady = false, false
        local function filterStatus(guiState)
            if nativeTextReady then
                status.Text = "Keyword filter ready for new messages."
            elseif nativeBubbleReady then
                status.Text = "Bubble filter ready. " .. guiState
            else
                status.Text = guiState
            end
        end

        -- Remember a filtered message by MessageId as well as by text. Roblox
        -- can call OnBubbleAdded twice for a locally sent message; the second
        -- copy may already have filtered text (###) instead of the keyword.
        local filteredMessageIds = {}
        local function bubbleMessageKey(message)
            local success, key = pcall(function() return message.MessageId end)
            return (success and type(key) == "string" and key ~= "") and key or nil
        end

        -- Pre-render appearance overrides cannot CANCEL a bubble. On some
        -- ExperienceChat builds the exit transition makes a fresh default
        -- shell AFTER the message TextLabel has been removed. Keep the owning
        -- speaker's *BillboardGui* disabled through the full bubble lifetime.
        -- If a normal message from the same speaker arrives, release that
        -- speaker's guard immediately so their new message can display.
        local runService = game:GetService("RunService")
        local speakerActivity = {} -- [UserId] = {hiddenUntil, visibleUntil}
        local shieldedBillboards = {} -- [BillboardGui] = {wasEnabled, connection}
        local shieldRoots = {} -- [root] = connection
        local shieldEnabled, shieldAccumulator = false, 0

        local function getBubbleDurationWithExit()
            local duration = 15
            pcall(function()
                local cfg = bubbleChatService:FindFirstChildOfClass("BubbleChatConfiguration")
                if cfg then duration = tonumber(cfg.BubbleDuration) or duration end
            end)
            return math.clamp(duration, 1, 90) + 4
        end

        local function getSenderId(message)
            local success, id = pcall(function()
                local source = message.TextSource
                return source and source.UserId
            end)
            return (success and type(id) == "number" and id > 0) and id or nil
        end

        local function rememberBubbleSpeaker(message, filtered)
            local id = getSenderId(message)
            if not id then return end
            local now = os.clock()
            local untilTime = now + getBubbleDurationWithExit()
            local state = speakerActivity[id]
            if not state then
                state = {hiddenUntil = 0, visibleUntil = 0}
                speakerActivity[id] = state
            end
            if filtered then
                state.hiddenUntil = math.max(state.hiddenUntil, untilTime)
            else
                -- A real message must be allowed to appear even if this
                -- speaker previously sent a keyword-filtered message.
                state.visibleUntil = math.max(state.visibleUntil, untilTime)
            end
        end

        local function shouldShieldSpeaker(id, now)
            local state = speakerActivity[id]
            return state and state.hiddenUntil > now and state.visibleUntil <= now
        end

        local function billboardOwnerId(billboard)
            local success, adornee = pcall(function() return billboard.Adornee end)
            if not success then adornee = nil end
            -- The native renderer normally sets Adornee to a body part. Some
            -- legacy layouts instead parent the billboard to the character.
            local parent = billboard.Parent
            for id, state in pairs(speakerActivity) do
                local plr = Players:GetPlayerByUserId(id)
                local character = plr and plr.Character
                if character then
                    local matches = false
                    pcall(function()
                        matches = (adornee and (adornee == character or adornee:IsDescendantOf(character)))
                            or (parent and (parent == character or parent:IsDescendantOf(character)))
                    end)
                    if matches then return id end
                end
            end
            return nil
        end

        local function releaseShield(billboard)
            local shield = shieldedBillboards[billboard]
            if not shield then return end
            shieldedBillboards[billboard] = nil
            if shield.connection then shield.connection:Disconnect() end
            if billboard.Parent and shield.wasEnabled then
                pcall(function() billboard.Enabled = true end)
            end
        end

        local function shieldBillboard(billboard)
            local shield = shieldedBillboards[billboard]
            if not shield then
                shield = {wasEnabled = billboard.Enabled}
                shieldedBillboards[billboard] = shield
                shield.connection = billboard:GetPropertyChangedSignal("Enabled"):Connect(function()
                    if shieldedBillboards[billboard] == shield and billboard.Enabled then
                        billboard.Enabled = false
                    end
                end)
            end
            if billboard.Enabled then billboard.Enabled = false end
        end

        local function scanFadeShields()
            if not shieldEnabled then return end
            local now = os.clock()
            local hasActive = false
            for id, state in pairs(speakerActivity) do
                if state.hiddenUntil <= now and state.visibleUntil <= now then
                    speakerActivity[id] = nil
                elseif shouldShieldSpeaker(id, now) then
                    hasActive = true
                end
            end
            for billboard in pairs(shieldedBillboards) do
                local id = billboard.Parent and billboardOwnerId(billboard)
                if not id or not shouldShieldSpeaker(id, now) then
                    releaseShield(billboard)
                else
                    if billboard.Enabled then billboard.Enabled = false end
