            if not hasActive then return end
            local rootsToInspect = {}
            -- New ExperienceChat is normally under CoreGui; some clients use
            -- PlayerGui/BubbleChat instead. Do not scan unrelated game UI.
            local function collect(holder)
                for _, name in ipairs({"ExperienceChat", "BubbleChat"}) do
                    local root = holder:FindFirstChild(name)
                    if root then rootsToInspect[#rootsToInspect + 1] = root end
                end
            end
