        local function matchesChatMessage(message)
            if #activeBubbleTerms == 0 then return false end
            local success, body = pcall(function() return message.Text end)
            if not success or type(body) ~= "string" then return false end
            if body == invisibleBubbleText then return true end
            body = body:lower()
            local hasTranslation, translation = pcall(function() return message.Translation end)
            local translated = hasTranslation and type(translation) == "string" and translation:lower() or ""
            local key = bubbleMessageKey(message)
            if key and filteredMessageIds[key] then return true end
            for _, term in ipairs(activeBubbleTerms) do
                if body:find(term, 1, true) or translated:find(term, 1, true) then
                    if key then filteredMessageIds[key] = true end
                    return true
                end
            end
            return false
        end

        local function readCallback(name)
            local success, callback = pcall(function() return bubbleChatService[name] end)
            if not success and type(getcallbackvalue) == "function" then
                success, callback = pcall(getcallbackvalue, bubbleChatService, name)
            end
            return success and (callback == nil or type(callback) == "function"), callback
        end

        local function installFilter(name, apply)
            local readable, prior = readCallback(name)
            local binding = bindings[name]
            if not readable then return false end
            if binding and prior == binding.callback then return true end
            local callback = function(message, ...)
                local previous
                if prior then
                    local success, result = pcall(prior, message, ...)
                    if success then previous = result end
                end
                if not isCurrent() or #activeBubbleTerms == 0 then return previous end
                return apply(message, previous)
            end
            local success = pcall(function() bubbleChatService[name] = callback end)
            if success then bindings[name] = {callback=callback, prior=prior} end
            return success
        end

        local function hideMessageText(message, previous)
            if not matchesChatMessage(message) then return previous end
            local props = Instance.new("TextChatMessageProperties")
            props.Text = invisibleBubbleText
            props.PrefixText = invisibleBubbleText
            props.Translation = invisibleBubbleText
            return props
        end

        local function hideBubble(message, previous)
