            for name, binding in pairs(bindings) do
                local readable, current = readCallback(name)
                if readable and current == binding.callback then
                    pcall(function() bubbleChatService[name] = binding.prior end)
                end
                bindings[name] = nil
            end
        end

        -- Identify the *whole* message widget. The visible background and
        -- Caret/tail may be siblings of the TextLabel (not its descendants).
        -- Never hide the player's BillboardGui or the shared bubble stack:
        -- doing that would also remove unrelated messages from that player.
        local function isBubbleTail(obj)
            local name = obj.Name:lower()
            return name == "caret" or name == "tail" or name == "bubbletail"
                or name == "chatbubbletail" or name == "bubblechattail"
                or name == "chatbubbletailframe" or name == "bubbletailframe"
                or name == "bubblecaret" or name == "carettail"
        end

        local function hasOwnTail(frame)
            for _, child in ipairs(frame:GetChildren()) do
                if isBubbleTail(child) then return true end
            end
            return false
        end

        local function hasAnotherMessage(frame, label)
            -- A shared bubble stack can contain several messages with the
            -- same label name. Do not hide that stack, even if it has a caret.
            for _, child in ipairs(frame:GetDescendants()) do
                if child ~= label and child.Name == label.Name
                    and (child:IsA("TextLabel") or child:IsA("TextButton")) then
                    return true
                end
            end
            return false
        end

        local function isSharedBubbleStack(node, bubbles)
            if node == bubbles or node.Name == "BillboardFrame"
                or node.Name == "BubbleChatList" or node.Name == "bubbleChat" then
                return true
            end
            -- A UIListLayout usually arranges several different message cells.
            return node:FindFirstChildOfClass("UIListLayout") ~= nil
        end

        local function target(label, root)
            -- Regular chat history: each message owns one list row.
            local list = label:FindFirstAncestor("RCTScrollContentView")
            if list and label.Name == "TextMessage" then
                local row = label
                while row.Parent and row.Parent ~= list do row = row.Parent end
                if row.Parent == list and row:IsA("GuiObject") and row.Name:match("^[1-9]%d*%-") then
                    return row, true
                end
            end

            local bubbles = label:FindFirstAncestor("bubbleChat")
            if not bubbles or not bubbles:IsDescendantOf(root) then return end

            local node = label
            local fallback
            while node and node ~= bubbles and not node:IsA("BillboardGui") do
                if node:IsA("GuiObject") then
                    local parent = node.Parent
                    -- A Caret alongside the bubble body belongs to the same
                    -- message wrapper; hiding just the body leaves the tail.
                    if parent and parent:IsA("GuiObject") and hasOwnTail(parent)
                        and not isSharedBubbleStack(parent, bubbles)
                        and not hasAnotherMessage(parent, label) then
