                    end
                    -- The list's direct child is the complete message cell,
                    -- including all its decorative children.
                    if node ~= label and parent and parent:IsA("GuiObject")
                        and parent:FindFirstChildOfClass("UIListLayout") then
                        return node, false
                    end
                    if node.Name == "ChatBubble" or node.Name == "Bubble"
                        or node.Name == "BubbleChatImage" or node.Name == "ChatBubbleFrame"
                        or node.Name == "BubbleFrame" then
                        if not hasAnotherMessage(node, label) then fallback = node end
                    end
                end
                node = node.Parent
            end
            return fallback, false
        end
    
        local function start(terms)
            local roots, watched = {}, {}
            local connections = {}

            -- Roblox's ExperienceChat can render the triangular Caret beside
            -- (rather than inside) the actual message cell. Hiding the cell
            -- therefore leaves an orphaned arrow. Handle these separately,
            -- scoped to one player's billboard / bubble list, NOT all chat.
            local hiddenCarets = {}
            local hiddenBillboards = {}
            local refreshQueued = false
            local stopping = false

            local function inVisibleBranch(node, limit)
                while node and node ~= limit do
                    if node:IsA("GuiObject") and not node.Visible then return false end
                    node = node.Parent
                end
                return node == limit
            end

            local function caretScope(label, row)
                -- Prefer a per-speaker billboard; the broader ExperienceChat
                -- and bubbleChat nodes may contain other players' messages.
                local billboard = label:FindFirstAncestorWhichIsA("BillboardGui")
                if billboard then return billboard end
                local list = label:FindFirstAncestor("BubbleChatList")
                if list then return list end
                return row and row.Parent
            end

            local function otherVisibleBubble(scope, label)
                -- A caret belonging to a still-visible message must stay.
                -- Other message text nodes in this scope share the label name.
                for _, child in ipairs(scope:GetDescendants()) do
                    if child ~= label and child.Name == label.Name
                        and (child:IsA("TextLabel") or child:IsA("TextButton"))
                        and inVisibleBranch(child, scope) then
                        return true
                    end
                end
                return false
            end

            local function releaseCaret(caret)
                local state = hiddenCarets[caret]
                if not state then return end
                hiddenCarets[caret] = nil
                if state.connection then state.connection:Disconnect() end
                if caret.Parent and (state.wasVisible or state.rendererShowed) then
                    pcall(function() caret.Visible = true end)
                end
            end

            local function releaseBillboard(billboard)
                local state = hiddenBillboards[billboard]
                if not state then return end
                hiddenBillboards[billboard] = nil
                if state.connection then state.connection:Disconnect() end
                if billboard.Parent and state.wasEnabled then
                    pcall(function() billboard.Enabled = true end)
                end
            end

            local function hasUnfilteredBubble(billboard)
                -- Only resume a disabled billboard early if a real, visible,
                -- unfiltered bubble needs it; not for the outgoing fade frame.
                for label, record in pairs(watched) do
                    if not record.prefixed and not record.hidden and record.row.Parent
                        and caretScope(label, record.row) == billboard
                        and inVisibleBranch(label, billboard) then
                        return true
                    end
                end
                return false
            end

            local function refreshCarets()
                local needed = {}
                local neededBillboards = {}
                for label, record in pairs(watched) do
                    if record.hidden and not record.prefixed and record.row.Parent then
                        local scope = caretScope(label, record.row)
                        if scope and not otherVisibleBubble(scope, label) then
                            -- When no unfiltered bubble is visible above this
                            -- speaker, disable its entire BillboardGui too.
                            -- This catches already-rendered tail triangles even
                            -- if Roblox doesn't update TailVisible mid-animation.
                            if scope:IsA("BillboardGui") then
                                neededBillboards[scope] = true
                            end
                            for _, child in ipairs(scope:GetDescendants()) do
                                -- The message cell is already hidden. Only
                                -- separately rendered tails need explicit care.
                                if child:IsA("GuiObject") and isBubbleTail(child)
                                    and not child:IsDescendantOf(record.row) then
                                    needed[child] = true
                                end
                            end
                        end
                    end
                end
                for caret in pairs(hiddenCarets) do
                    if not needed[caret] then
                        local billboard = caret:FindFirstAncestorWhichIsA("BillboardGui")
                        -- Don't show an orphaned tail during the engine's fade
                        -- transition just because its text label was deleted.
                        if not caret.Parent or (billboard and hasUnfilteredBubble(billboard)) then
                            releaseCaret(caret)
                        end
                    end
                end
                for caret in pairs(needed) do
                    if not hiddenCarets[caret] then
                        local state = {wasVisible = caret.Visible}
                        hiddenCarets[caret] = state
                        -- The built-in renderer may toggle Caret.Visible again
                        -- during animation. Keep it hidden while it's orphaned.
                        state.connection = caret:GetPropertyChangedSignal("Visible"):Connect(function()
                            if hiddenCarets[caret] and caret.Visible then
                                state.rendererShowed = true
                                caret.Visible = false
                            end
                        end)
                    end
                    if caret.Visible then caret.Visible = false end
                end
                for billboard, state in pairs(hiddenBillboards) do
                    if not neededBillboards[billboard] then
                        if not billboard.Parent or hasUnfilteredBubble(billboard) then
                            releaseBillboard(billboard)
                        elseif os.clock() >= (state.holdUntil or 0) then
                            releaseBillboard(billboard)
                        elseif not state.releaseQueued then
                            -- Roblox can destroy a TextLabel before the 0.5s
                            -- exit tween ends. Do not immediately re-enable
                            -- its billboard (which reveals that final fade).
                            state.releaseQueued = true
                            task.delay(math.max(0.02, state.holdUntil-os.clock()), function()
                                if stopping then return end
                                if hiddenBillboards[billboard] == state then
                                    state.releaseQueued = false
                                    pcall(refreshCarets)
                                end
                            end)
                        end
                    end
                end
                for billboard in pairs(neededBillboards) do
                    if not hiddenBillboards[billboard] then
                        local state = {
                            wasEnabled = billboard.Enabled,
                            holdUntil = os.clock() + getBubbleDurationWithExit(),
                        }
                        hiddenBillboards[billboard] = state
                        state.connection = billboard:GetPropertyChangedSignal("Enabled"):Connect(function()
                            if hiddenBillboards[billboard] and billboard.Enabled then
                                billboard.Enabled = false
                            end
                        end)
                    end
                    -- Do not restart this timer every time a descendant
                    -- changes. It starts when the filtered cell is first seen
                    -- and outlasts the complete native expiry/exit transition.
                    if billboard.Enabled then billboard.Enabled = false end
                end
            end

            local function queueCaretRefresh()
                if stopping or refreshQueued then return end
                refreshQueued = true
                task.defer(function()
                    refreshQueued = false
                    if not stopping then pcall(refreshCarets) end
                end)
            end

            local function drop(label, beingRemoved)
                local record = watched[label]
                if not record then return end
                watched[label] = nil
                for _, connection in ipairs(record.connections) do connection:Disconnect() end
                if record.visibilityConnection then record.visibilityConnection:Disconnect() end
                -- When Roblox removes the message, restoring Visible=true
                -- exposes its last fade-out frames. Restore only when we're
                -- intentionally disabling the filter on a live message.
                if record.hidden and record.row.Parent and not beingRemoved then
                    record.row.Visible = true
                end
                queueCaretRefresh()
            end
    
            local function watch(label, root)
                if watched[label] or not (label:IsA("TextLabel") or label:IsA("TextButton")) then return end
                local row, prefixed = target(label, root)
                if not row then return end
                local record = {row = row, root = root, prefixed = prefixed, connections = {}}
                watched[label] = record
                filterStatus("Watching chat messages.")

                local function update()
                    if watched[label] ~= record or not record.row.Parent then return end
                    local body = label.ContentText
                    if record.prefixed then
                        -- Stock chat history prefixes the message with sender: .
                        body = body:match("^[^:]*:%s*(.*)$") or body
                    end
                    body = body:lower()
                    -- OnBubbleAdded may replace the rendered Text with our
                    -- invisible marker, so recognise that too in the GUI
                    -- fallback instead of waiting for a text keyword.
                    local matched = body:find(invisibleBubbleText, 1, true) ~= nil
                        or label.Text:find(invisibleBubbleText, 1, true) ~= nil
                    if not matched then
                        for _, term in ipairs(terms) do
                            if body:find(term, 1, true) then matched = true; break end
                        end
                    end
                    if matched then
                        record.hidden = true
                        -- This is the complete message container, not just text.
                        -- Reapply if Roblox tries to make it visible again.
                        if record.row.Visible then record.row.Visible = false end
                    elseif record.hidden then
                        record.hidden = false
                        record.row.Visible = true
                    end
                    if matched and not record.prefixed then
                        -- Hide the owning billboard in this same callback,
                        -- not on the next deferred frame of the animation.
                        pcall(refreshCarets)
                    end
                    queueCaretRefresh()
                end

                local function connectVisibility()
                    if record.visibilityConnection then record.visibilityConnection:Disconnect() end
                    record.visibilityConnection = record.row:GetPropertyChangedSignal("Visible"):Connect(update)
                end

                record.retarget = function()
                    if watched[label] ~= record or not label.Parent then return end
                    local nextRow = target(label, root)
                    if not nextRow or nextRow == record.row then return end
                    local oldRow, wasHidden = record.row, record.hidden
                    record.row = nextRow
                    connectVisibility()
                    update() -- hide new full wrapper before restoring its child
                    if wasHidden and oldRow.Parent and oldRow ~= nextRow
                        and oldRow:IsDescendantOf(nextRow) then
                        -- Never reveal an outgoing bubble that may be fading.
                        oldRow.Visible = true
                    end
                    queueCaretRefresh()
                end

                record.connections[1] = label:GetPropertyChangedSignal("ContentText"):Connect(update)
                connectVisibility()
                update()
            end
    
            local function detach(root)
                local events = roots[root]
                if not events then return end
                roots[root] = nil
                for _, event in ipairs(events) do event:Disconnect() end
                for label, record in pairs(watched) do
                    if record.root == root then drop(label) end
                end
            end
            local function attach(root)
                if root.Name ~= "ExperienceChat" or roots[root] then return end
                local children = root:GetDescendants()
                roots[root] = {
                    root.DescendantAdded:Connect(function(child)
                        if child:IsA("UIListLayout") and child:FindFirstAncestor("bubbleChat") then
                            for _, item in ipairs(child.Parent:GetDescendants()) do watch(item, root) end
                        else
                            watch(child, root)
                            -- Bubble GUI subtrees may be assembled off-screen
                            -- and parented after their TextLabels are created.
                            -- Walk those descendants *synchronously* so the
                            -- wrapper is hidden before its first drawn frame.
                            if child:IsA("GuiObject") or child:IsA("BillboardGui") then
                                for _, item in ipairs(child:GetDescendants()) do
                                    if item:IsA("TextLabel") or item:IsA("TextButton") then
                                        watch(item, root)
                                    end
                                end
                            end
                        end
                        -- Roblox sometimes adds the caret after the text label.
                        -- Re-evaluate affected message wrappers so the new tail
                        -- is hidden too, without affecting other chat bubbles.
                        if (isBubbleTail(child) or child.Name == "BubbleChatImage"
                            or child.Name == "ChatBubble" or child.Name == "Bubble")
                            and child:FindFirstAncestor("bubbleChat") then
                            task.defer(function()
                                if not roots[root] then return end
                                for label, record in pairs(watched) do
                                    if record.root == root and not record.prefixed and record.retarget then
                                        record.retarget()
                                    end
                                end
                                queueCaretRefresh()
                            end)
                        end
                    end),
                    root.DescendantRemoving:Connect(function(child)
                        drop(child, true)
                        if isBubbleTail(child) or child:IsA("TextLabel") then
                            queueCaretRefresh()
                        end
                    end),
                }
                filterStatus("Waiting for a supported chat message.")
                for _, child in ipairs(children) do pcall(watch, child, root) end
            end
            stopWatching = function()
                stopping = true
                for _, event in ipairs(connections) do event:Disconnect() end
                for root in pairs(roots) do detach(root) end
                for caret in pairs(hiddenCarets) do releaseCaret(caret) end
                for billboard in pairs(hiddenBillboards) do releaseBillboard(billboard) end
            end
            local function tryAttach(root)
                if not pcall(attach, root) and not next(watched) then
                    filterStatus("Chat window unavailable.")
                end
            end
            local function watchHolder(holder)
                table.insert(connections, holder.ChildAdded:Connect(tryAttach))
                table.insert(connections, holder.ChildRemoved:Connect(function(root)
                    if roots[root] then
                        detach(root)
                        if not next(roots) then filterStatus("Waiting for the chat window.") end
                    end
                end))
                local root = holder:FindFirstChild("ExperienceChat")
                if root then tryAttach(root) end
            end
            filterStatus("Waiting for the chat window.")
            local playerOK = pcall(watchHolder, playerGui2)
            local coreOK = pcall(function() watchHolder(game:GetService("CoreGui")) end)
            if not coreOK and not next(roots) then
                filterStatus(playerOK and "No readable chat window yet." or "Chat window unavailable.")
            end
        end
    
        local function saveEntries(updated)
            settings.hiddenChatKeywords = table.concat(updated, ", ")
            pvSession.refreshChatKeywords()
            saveCfg()
        end

        local function makeKeywordRow(term)
            local row = Instance.new("Frame")
            row.Size = UDim2.new(1, 0, 0, pxValue(32))
            row.AutomaticSize = Enum.AutomaticSize.Y
            row.BackgroundColor3 = BTN_BG
            row.BorderSizePixel = 0
            row.Parent = list
            corner(row, pxValue(8))
            local label = lbl(row, term, 10, TValue.txt)
            label.Size = UDim2.new(1, -pxValue(80), 0, pxValue(24))
            label.Position = UDim2.fromOffset(pxValue(8), pxValue(4))

            local remove = Instance.new("TextButton")
            remove.Text = "Remove"
            remove.Font = Enum.Font.GothamBold
            remove.TextSize = pxValue(10)
            remove.TextColor3 = TValue.txt
            remove.BackgroundColor3 = TValue.black
            remove.BorderSizePixel = 0
            remove.Size = UDim2.fromOffset(pxValue(60), pxValue(26))
            remove.Position = UDim2.new(1, -pxValue(64), 0, pxValue(3))
            remove.Parent = row
            corner(remove, pxValue(6))
            -- Destroying the row also disconnects this button's listener.
            remove.Activated:Connect(function()
                local index = table.find(entries, term)
                if index then
                    table.remove(entries, index)
                    saveEntries(entries)
                end
            end)
            return row
        end

        local function refresh()
            if stopWatching then stopWatching(); stopWatching = nil end
            entries = words(settings.hiddenChatKeywords)
            local terms, present = {}, {}
            for index, term in ipairs(entries) do
                terms[index] = term:lower()
                present[term] = true
                if not rows[term] then rows[term] = makeKeywordRow(term) end
                rows[term].LayoutOrder = index
            end
            for term, row in pairs(rows) do
                if not present[term] then
                    row:Destroy()
                    rows[term] = nil
                end
            end
            activeBubbleTerms = terms
            -- Changing keywords resets old speaker locks; matched messages
            -- from the new keyword list will register immediately.
            clearFadeShields()
            shieldEnabled = #terms > 0
            if #terms == 0 then
                uninstallFilters()
                setNativeTailHidden(false)
                status.Text = "Off. Add a word or phrase to hide matching chat on your screen."
                return
            end
            nativeTextReady = installFilter("OnIncomingMessage", hideMessageText)
            nativeBubbleReady = installFilter("OnBubbleAdded", hideBubble)
            pcall(setNativeTailHidden, true)
            if not pcall(start, terms) then
                if stopWatching then stopWatching(); stopWatching = nil end
                filterStatus("Chat window unavailable.")
            end
        end
        pvSession.refreshChatKeywords = refresh
        local function addKeywords()
            if #words(editor.Text) == 0 then return end
            local updated = words(settings.hiddenChatKeywords .. "," .. editor.Text)
            editor.Text = ""
            if #updated == #entries then
                notify("Already in the keyword list")
                return
            end
            saveEntries(updated)
        end
        local add = btn(panel, "Add", addKeywords)
        add.Size = UDim2.fromOffset(pxValue(56), pxValue(30))
        add.Position = UDim2.new(1, -pxValue(62), 0, pxValue(39))
        -- Match the original editor: tapping away also commits the draft.
        -- Add and FocusLost can both fire on one tap; clearing the draft makes it idempotent.
        pvSession.connect(editor.FocusLost, addKeywords)
        pvSession.addCleanup(function()
            if stopWatching then stopWatching() end
            uninstallFilters()
            clearFadeShields()
            setNativeTailHidden(false)
        end)
        refresh()
    end)()
    lbl(text2,"UI THEME:",10,TValue.pink)
    -- Four theme buttons; Custom controls expand inside the settings list only when opened.
    do
        local choices={}
        local names={["Pork UI"]="PORK",["Halloween"]="HALLOWEEN",["Christmas"]="CHRISTMAS",["Custom"]="CUSTOM"}
        local customExpanded=settings.uiTheme=="Custom"
        local customHolder

        local function refreshChoices()
            for theme,choice in pairs(choices) do
                local selected=settings.uiTheme==theme
                choice.Text=names[theme]..(selected and "  ✓" or "")
                local outline=choice:FindFirstChildOfClass("UIStroke")
                if outline then
                    outline.Color=selected and TValue.pink or TValue.line
                    outline.Transparency=selected and 0.12 or 0.60
                end
            end
            if customHolder then
                customHolder.Visible=customExpanded
                customHolder.Size=UDim2.new(1,0,0,customExpanded and pxValue(155) or 0)
            end
        end
        choices["Pork UI"]=btn(text2,"PORK",function()
            customExpanded=false
            pvSetUITheme("Pork UI",true)
            refreshChoices()
        end)
        choices["Halloween"]=btn(text2,"HALLOWEEN",function()
            customExpanded=false
            pvSetUITheme("Halloween",true)
            refreshChoices()
        end)
        choices["Christmas"]=btn(text2,"CHRISTMAS",function()
            customExpanded=false
            pvSetUITheme("Christmas",true)
            refreshChoices()
        end)
        choices["Custom"]=btn(text2,"CUSTOM",function()
            local alreadySelected=settings.uiTheme=="Custom"
            pvSetUITheme("Custom",true)
            customExpanded=(not alreadySelected) or (not customExpanded)
            refreshChoices()
        end)

        customHolder=Instance.new("Frame")
        customHolder.Name="pvCustomThemeDropdown"
        customHolder.BackgroundTransparency=1
        customHolder.BorderSizePixel=0
        customHolder.ClipsDescendants=false
        customHolder.Size=UDim2.new(1,0,0,0)
        customHolder.Parent=text2
        local stack=Instance.new("UIListLayout")
        stack.SortOrder=Enum.SortOrder.LayoutOrder
        stack.Padding=UDim.new(0,pxValue(7))
        stack.Parent=customHolder

        local description=lbl(customHolder,"Paste PNG, JPG, WebP, GIF, video:RobloxID, or a local file path.",8,TValue.sub)
        description.Size=UDim2.new(1,0,0,pxValue(38))
        -- Clip long pasted links to the input area, without deleting any text.
        -- The wrapper clips the TextBox's rendered text even while it is focused
        -- and Roblox scrolls the caret horizontally.
        local inputClip=Instance.new("Frame")
        inputClip.Name="CustomBackgroundInputClip"
        inputClip.Size=UDim2.new(1,0,0,pxValue(28))
        inputClip.BackgroundTransparency=1
        inputClip.BorderSizePixel=0
        inputClip.ClipsDescendants=true
        inputClip.Parent=customHolder
        corner(inputClip,pxValue(8))

        local bgInput=box(inputClip,"Image/GIF link, video:ID or file path")
        bgInput.Name="CustomBackgroundInput"
        bgInput.Size=UDim2.fromScale(1,1)
        bgInput.ClipsDescendants=true
        bgInput.TextXAlignment=Enum.TextXAlignment.Left
        bgInput.TextWrapped=false
        -- Important: TextTruncate.AtEnd freezes long URLs into an ellipsis.
        -- None leaves the complete URL editable; Roblox scrolls the caret
        -- horizontally while the containing inputClip masks overflow.
        bgInput.TextTruncate=Enum.TextTruncate.None
        bgInput.Text=settings.customBackground or ""

        btn(customHolder,"APPLY CUSTOM BG",function()
            local value=bgInput.Text
            if value:match("^%s*$") then
                notify("Paste an image, GIF or Roblox video ID first")
                return
            end
            notify("Loading custom background / animation...")
            pvSetCustomBackground(value,true,function(success,msg)
                -- This callback fires only after the custom background has been
                -- decoded/registered and applied (videos also pass IsLoaded).
                notify(success and "Custom BG loaded" or msg)
            end)
        end)
        btn(customHolder,"RESET CUSTOM BG",function()
            bgInput.Text=""
            pvSetCustomBackground("",true,function(success,msg) notify(msg) end)
        end)

        pvSession.configRefresh[#pvSession.configRefresh+1]=function()
            customExpanded=settings.uiTheme=="Custom"
            bgInput.Text=type(settings.customBackground)=="string" and settings.customBackground or ""
            refreshChoices()
        end
        refreshChoices()
    end
    lbl(text2,"Select a theme. Saves automatically.",8,TValue.sub)

    do
        local keys={"poor","middle","rich"}
        local fields,editors,arrows={},{},{}
        local function stack(parent,order,indent)
            local frame=Instance.new("Frame")
            frame.BackgroundTransparency=1
            frame.Size=UDim2.new(1,-pxValue(indent),0,0)
            frame.AutomaticSize=Enum.AutomaticSize.Y
            frame.LayoutOrder=order
            frame.Parent=parent
            local list=Instance.new("UIListLayout")
            list.SortOrder=Enum.SortOrder.LayoutOrder
            list.HorizontalAlignment=Enum.HorizontalAlignment.Right
            list.Padding=UDim.new(0,pxValue(5))
            list.Parent=frame
            return frame
        end
        local function disclosure(parent,title,order,onClick)
            local button=btn(parent,title,onClick)
            button.LayoutOrder=order
            button.TextXAlignment=Enum.TextXAlignment.Left
            pad(button,pxValue(10),0,pxValue(10),0)
            local arrow=lbl(button,"▼",9,TValue.sub)
            arrow.AutomaticSize=Enum.AutomaticSize.None
            arrow.TextXAlignment=Enum.TextXAlignment.Right
            arrow.Position=UDim2.fromScale(0.9,0)
            arrow.Size=UDim2.fromScale(0.1,1)
            return button,arrow
        end
        local panel=pvSession.makeSettingsPanel("FakeUpgradeRangesPanel","Fake Upgrade Ranges")
        local tiers=scroll(panel)
        tiers.Position=UDim2.fromOffset(0,pxValue(39))
        tiers.Size=UDim2.new(1,0,1,-pxValue(39))
        local function openEditor(key)
            local expand=not editors[key].Visible
            for _,other in ipairs(keys) do
                local visible=other==key and expand
                editors[other].Visible=visible
                arrows[other].Text=visible and "▲" or "▼"
            end
        end
        local function amountField(parent,title,order)
            local row=Instance.new("Frame")
            row.Size=UDim2.new(1,0,0,pxValue(28))
            row.BackgroundTransparency=1
            row.LayoutOrder=order
            row.Parent=parent
            local label=lbl(row,title,9,TValue.sub)
            label.AutomaticSize=Enum.AutomaticSize.None
            label.Size=UDim2.fromScale(0.48,1)
            local input=box(row,title)
            input.Position=UDim2.fromScale(0.48,0)
            input.Size=UDim2.fromScale(0.52,1)
            return input
        end
        local function readCents(text)
            local amount=text:match("^%s*%$?%s*(%d*%.?%d*)%s*$")
            if not amount or not amount:match("%d") or amount:match("%.%d%d%d") then return end
            local whole,fraction=amount:match("^(%d*)%.?(%d*)$")
            local cents=(tonumber(whole) or 0)*100+tonumber((fraction.."00"):sub(1,2))
            if cents<=9007199254740991 then return cents end
        end
        local refreshing=false
        for index,key in ipairs(keys) do
            local name=pvSession.upgradeTiers[key].label
            local button,arrow=disclosure(tiers,name,index*2,function() openEditor(key) end)
            arrows[key]=arrow
            local summary=lbl(button,"",9,TValue.sub)
            summary.AutomaticSize=Enum.AutomaticSize.None
            summary.TextXAlignment=Enum.TextXAlignment.Right
            summary.TextTruncate=Enum.TextTruncate.AtEnd
            summary.TextWrapped=false
            summary.Position=UDim2.fromScale(0.24,0)
            summary.Size=UDim2.new(0.76,-pxValue(20),1,0)
            local function showSummary()
                summary.Text=pvSession.getUpgradeTier(key).range
            end
            local editor=stack(tiers,index*2+1,8)
            editors[key]=editor
            editor.Visible=false
            local low=amountField(editor,"Minimum ($)",1)
            local high=amountField(editor,"Maximum ($)",2)
            local errorLabel=lbl(editor,"",9,TValue.sub)
            errorLabel.LayoutOrder=3
            errorLabel.Visible=false
            local revision=0
            local function saveRange(showError)
                local minimum,maximum=readCents(low.Text),readCents(high.Text)
                local message
                if not minimum or not maximum or maximum==0 then
                    message="Enter dollar amounts with up to two decimals and a positive maximum."
                elseif minimum>maximum then
                    message="Minimum must be at or below maximum."
                end
                errorLabel.Visible=showError and message~=nil
                if message then
                    if showError then errorLabel.Text=message end
                    return false
                end
                local current=pvSession.getUpgradeTier(key)
                if current.minimum~=minimum or current.maximum~=maximum then
                    if type(settings.fakeUpgradeRanges)~="table" then settings.fakeUpgradeRanges={} end
                    settings.fakeUpgradeRanges[key]={minimum=minimum,maximum=maximum}
                    showSummary()
                    saveCfg()
                end
                return true
            end
            local function edited()
                if refreshing then return end
                revision=revision+1
                local pending=revision
                errorLabel.Visible=false
                task.delay(0.4,function()
                    if pending==revision and isCurrent() then saveRange(false) end
                end)
            end
            for _,input in ipairs({low,high}) do
                pvSession.connect(input:GetPropertyChangedSignal("Text"),edited)
                pvSession.connect(input.FocusLost,function()
                    revision=revision+1
                    if saveRange(true) then
                        refreshing=true
                        input.Text=string.format("%.2f",readCents(input.Text)/100)
                        refreshing=false
                    end
                end)
            end
            fields[key]=function()
                revision=revision+1
                local tier=pvSession.getUpgradeTier(key)
                low.Text=string.format("%.2f",tier.minimum/100)
                high.Text=string.format("%.2f",tier.maximum/100)
                showSummary()
                errorLabel.Visible=false
            end
        end
        local function refreshFields()
            refreshing=true
            for _,key in ipairs(keys) do fields[key]() end
            refreshing=false
        end
        refreshFields()
        table.insert(pvSession.configRefresh,refreshFields)
    end

    lbl(text2,"FAKE LEADERBOARD BOTS",10,TValue.pink)
    local NAMES={"xTradeGodz","GodlyGiver","FreeSeerr","MM2_Kingg","LuckyTradez",
                 "SeerDealer","ChromaKingg","VoidHunterx","Godly4Youu","TradeMeNoww"}
