        if trade and trade:IsA("GuiButton") then
            if getconnections then pcall(function() for _,child in ipairs(getconnections(trade.MouseButton1Click)) do pcall(function() child:Disconnect() end) end end) end
            pvSession.connect(trade.MouseButton1Click,function()
                myValue:Destroy()
