        local profile=myValue:FindFirstChild("Profile",true)
        if profile and profile:IsA("GuiButton") then
            if getconnections then pcall(function() for _,child in ipairs(getconnections(profile.MouseButton1Click)) do pcall(function() child:Disconnect() end) end end) end
            pvSession.connect(profile.MouseButton1Click,function()
                myValue:Destroy()
                local success, errorMessage = pcall(pvOpenBotProfile, botName)
                if not success then notify("couldnt open profile: "..tostring(errorMessage)) end
            end)
        end
        local close=myValue:FindFirstChild("Close",true)
        if close and close:IsA("GuiButton") then
            if getconnections then pcall(function() for _,child in ipairs(getconnections(close.MouseButton1Click)) do pcall(function() child:Disconnect() end) end end) end
            pvSession.connect(close.MouseButton1Click,function() myValue:Destroy() end)
        end
