    local function addBots(number)
        local success,cont=pcall(function() return playerGui2.MainGUI.Game.Leaderboard.Container end)
        if not success or not cont then notify("Leaderboard not found");return end
        local tmpl
        for _,child in ipairs(cont:GetChildren()) do
            if child:IsA("Frame") and child:FindFirstChild("ActionButton") and child:FindFirstChild("PlayerLabel") then tmpl=child;break end
        end
