            local playerLabel=entry:FindFirstChild("PlayerLabel"); if playerLabel then playerLabel.Text=name end
            for _,data in ipairs(entry:GetDescendants()) do
                if data:IsA("TextLabel") and data.Name=="Level" then data.Text=tostring(pvBotStats(name).Level) end
            end
            entry.Parent=cont;made[#made+1]=entry
            local actionButton=entry:FindFirstChild("ActionButton")
            if actionButton then
                task.delay(0.35,function()
                    if getconnections then
