do
    settingsScroll = settingsScroll or scroll(pSet)
    local text=settingsScroll
    lbl(text,"SERVER",10,TValue.txt)
    -- Server hopping: paginate public servers and use ONLY joinable slots.
    -- High Pop targets 9+ current players, preferring 10/12 or 9/12 over
    -- the single remaining slot in 11/12 (which fills very quickly).
    local pvHopBusy=false
    local function hop(mode,button,label)
        if pvHopBusy then notify("Already searching for a server") return end
        pvHopBusy=true
        button.Text="Searching servers..."
        pcall(pvSaveConfigToDisk)

        task.spawn(function()
            local pid=game.PlaceId
            local order=(mode=="fewest") and "Asc" or "Desc"
            local minPlayers=(mode=="high") and 9 or 0
            local maxPages=(mode=="high") and 25 or 8
            local found,seen={},{}
            local pageCount=0
            local cursor=nil
            local fetchError=nil
            local requestLimit=100
            local usedCursors={}

            local function fetchPage(pageCursor)
                local url="https://games.roblox.com/v1/games/"..tostring(pid)
                    .."/servers/Public?sortOrder="..order
                    .."&excludeFullGames=true&limit="..requestLimit
                if pageCursor and pageCursor~="" then
                    url=url.."&cursor="..HttpService:UrlEncode(pageCursor)
                end

                -- Different executors support different HTTP methods. Try the
                -- request API first; fall back to the existing game:HttpGet helper.
                local body=nil
                local reason=nil
                if pvAPI and type(pvAPI.request)=="function" then
                    local success,result=pcall(pvAPI.request,{Url=url,Method="GET"})
                    if success and type(result)=="table" then
                        local status=tonumber(result.StatusCode or result.Status)
                        if type(result.Body)=="string" and (status==200 or (status==nil and result.Success==true)) then
                            body=result.Body
                        elseif status==429 then
                            return nil,"Roblox server list is rate-limited (429)"
                        elseif status then
                            reason="Server list HTTP "..tostring(status)
                        end
                    end
                end
                if not body then body=httpGet(url) end
                if type(body)~="string" then
                    return nil,reason or "Could not fetch public servers (HTTP access blocked)"
                end
                local success,data=pcall(function() return HttpService:JSONDecode(body) end)
                if not success or type(data)~="table" or type(data.data)~="table" then
                    return nil,"Roblox returned invalid server-list data"
                end
                return data,nil
            end

            local function addCandidate(server)
                if type(server)~="table" then return end
                local id=server.id
                local count=tonumber(server.playing)
                local capacity=tonumber(server.maxPlayers)
                if type(id)~="string" or id=="" or id==game.JobId or seen[id] then return end
                -- Full servers must NEVER be selected. The count is a snapshot;
                -- TeleportInitFailed below handles a server filling meanwhile.
                if not count or not capacity or capacity<=0 or count<minPlayers or count>=capacity then return end
                seen[id]=true
                found[#found+1]={id=id,playing=count,maxPlayers=capacity,free=capacity-count}
            end

            for page=1,maxPages do
                if not isCurrent() then pvHopBusy=false return end
                button.Text="Scanning servers ("..page.."/"..maxPages..")"
                local data,errorMessage=fetchPage(cursor)
                if not data then fetchError=errorMessage break end
                -- Some Roblox API responses unexpectedly return an empty
                -- 100-size first page. Retry at 50 before declaring none.
                if page==1 and #data.data==0 then
                    requestLimit=50
                    data,errorMessage=fetchPage(nil)
                    if not data then fetchError=errorMessage break end
                end
                pageCount=pageCount+1
                for _,server in ipairs(data.data) do addCandidate(server) end

                if mode=="high" then
                    -- Keep looking past packed 12/12 servers until we find
                    -- several 9+/12 servers with at least TWO open slots.
                    local roomy=0
                    for _,server in ipairs(found) do
                        if server.free>=2 then roomy=roomy+1 end
                    end
                    if roomy>=8 then break end
                elseif #found>=12 then
                    break
                end
                cursor=data.nextPageCursor
                if not cursor or cursor=="" or #data.data==0 or usedCursors[cursor] then break end
                usedCursors[cursor]=true
                task.wait(0.16) -- avoid hammering the public list API
            end

            if not isCurrent() then pvHopBusy=false return end
            if #found==0 then
                button.Text=label
                pvHopBusy=false
                if fetchError then
                    notify("Server Hop: "..fetchError)
                elseif mode=="high" then
                    notify("No joinable 9+ player server in "..pageCount.." pages. Try again shortly.")
                else
                    notify("No other joinable public server found")
                end
                return -- do NOT redirect to a random/low-pop server
            end

            if mode=="high" then
                table.sort(found,function(first,child)
                    -- 10/12 then 9/12 beat an 11/12 because the last
                    -- remaining slot is especially likely to disappear.
                    local arValue=first.free>=2 and 1 or 0
                    local crValue=child.free>=2 and 1 or 0
                    if arValue~=crValue then return arValue>crValue end
                    if first.playing~=child.playing then return first.playing>child.playing end
                    return first.free>child.free
                end)
            else
                table.sort(found,function(first,child)
                    if first.playing~=child.playing then return first.playing<child.playing end
                    return first.free>child.free
                end)
            end

            local attempt=0
            local maxAttempts=math.min(#found,10)
            local failedConn=nil
            local finished=false
            local function finish(message)
                if finished then return end
                finished=true
                pvHopBusy=false
                button.Text=label
                if failedConn then failedConn:Disconnect();failedConn=nil end
                if message then notify(message) end
            end

            local tryNext
            tryNext=function(expectedAttempt)
                if finished or not isCurrent() then return end
                if expectedAttempt and expectedAttempt~=attempt then return end
                if attempt>=maxAttempts then
                    finish("Couldn't join the available servers (they may have filled up). Try again.")
                    return
                end
                attempt=attempt+1
                local myAttempt=attempt
                local server=found[myAttempt]
                button.Text="Joining "..server.playing.."/"..server.maxPlayers.."..."
                notify("Joining "..server.playing.."/"..server.maxPlayers
                    .." server (attempt "..myAttempt.."/"..maxAttempts..")")
                local success,errorMessage=pcall(function()
                    Teleport:TeleportToPlaceInstance(pid,server.id,playerGui)
                end)
                if not success then
                    -- An immediate error means this instance is not joinable.
                    task.defer(function() tryNext(myAttempt) end)
                    return
                end
                -- pcall success means Roblox accepted the REQUEST, not that
                -- the join succeeded. If still here, try another server.
                task.delay(12,function()
                    if not finished and isCurrent() and attempt==myAttempt then
                        tryNext(myAttempt)
                    end
                end)
            end

            failedConn=pvSession.connect(Teleport.TeleportInitFailed,function(player,result,errorMessage,placeId,options)
                if finished or not isCurrent() or player~=playerGui or placeId~=pid then return end
                local current=found[attempt]
                if not current then return end
                local targetId=nil
                pcall(function() targetId=options and options.ServerInstanceId end)
                if targetId and targetId~="" and targetId~=current.id then return end
                local expected=attempt
                task.defer(function() tryNext(expected) end)
            end)
            tryNext()
        end)
    end
    btn(text,"Server Hop   Fewest Players",function(button) hop("fewest",button,"Server Hop   Fewest Players") end)
    btn(text,"Server Hop   High Pop",function(button) hop("high",button,"Server Hop   High Pop") end)
    btn(text,"Rejoin",function()
        local hasFake = type(settings.loadout)=="table" and type(settings.loadout.owned)=="table"
                        and next(settings.loadout.owned)~=nil
                        and type(savedSpawns)=="table" and next(savedSpawns)~=nil
        pcall(pvSaveConfigToDisk)
        notify("Rejoining...")
        pcall(function() Teleport:Teleport(game.PlaceId,playerGui) end)
    end)


end
do
    local text=scroll(pBots)
    lbl(text,"KEYBINDS",11,TValue.pink)


    local ROWS={
        {"restoreFPS", "Toggle FPS counter"},
        {"blockRecent","Block recent player"},
        {"clearOffer", "Clear my offer"},
        {"tradeRecent","Trade recent player"},
