_G.pvUltraState = _G.pvUltraState or nil
_G.pvUltraEpoch = _G.pvUltraEpoch or 0

function pvUltraProtected(x)
    local part=x
    while part and part~=workspace do

        if part:IsA("Model") and part:FindFirstChildOfClass("Humanoid") then return true end
        if part:IsA("Tool") or part:IsA("Accessory") then return true end
        local text=tostring(part.Name):lower()
        if text=="weapondisplays" or text:find("pvheld",1,true) or text:find("pvthrow",1,true) then
            return true
        end
        part=part.Parent
    end
    return false
end

function pvUltraApplyOne(data,SValue)
    if not SValue or not SValue.active or not data or not data.Parent then return end
    if pvUltraProtected(data) then return end

    if data:IsA("BasePart") then
        if not SValue.parts[data] then
            local mvValue=""
            pcall(function() mvValue=data.MaterialVariant end)
            SValue.parts[data]={
                mat=data.Material,
                cast=data.CastShadow,
                refl=data.Reflectance,
                variant=mvValue
            }
        end
        pcall(function() data.Material=Enum.Material.SmoothPlastic end)
        pcall(function() data.MaterialVariant="" end)
        pcall(function() data.CastShadow=false end)
        pcall(function() data.Reflectance=0 end)

        if data:IsA("MeshPart") and not SValue.meshparts[data] then
            local texture=""
            pcall(function() texture=data.TextureID end)
            SValue.meshparts[data]=texture
            pcall(function() data.TextureID="" end)
        end

    elseif data:IsA("Decal") or data:IsA("Texture") then
        if SValue.textures[data]==nil then SValue.textures[data]=data.Transparency end
        pcall(function() data.Transparency=1 end)

    elseif data:IsA("SpecialMesh") then
        if SValue.special[data]==nil then
            local texture=""
            pcall(function() texture=data.TextureId end)
            SValue.special[data]=texture
        end
        pcall(function() data.TextureId="" end)

    elseif data:IsA("SurfaceAppearance") then
        if SValue.surface[data]==nil then
            SValue.surface[data]=data.Parent
        end

        pcall(function() data.Parent=nil end)

    elseif data:IsA("PointLight") or data:IsA("SpotLight") or data:IsA("SurfaceLight")
        or data:IsA("ParticleEmitter") or data:IsA("Trail") or data:IsA("Beam")
        or data:IsA("Smoke") or data:IsA("Fire") or data:IsA("Sparkles") then
        if SValue.fx[data]==nil then
            local enabled=false
            pcall(function() enabled=data.Enabled end)
            SValue.fx[data]=enabled
        end
        pcall(function() data.Enabled=false end)
    end
end

function pvUltraFpsBooster(onValue)
    if onValue then
        if _G.pvUltraState and _G.pvUltraState.active then return end

        _G.pvUltraEpoch=(_G.pvUltraEpoch or 0)+1
        local epoch=_G.pvUltraEpoch
        local SValue={
            active=true,
            parts={},
            textures={},
            meshparts={},
            special={},
            surface={},
            fx={},
            conn=nil
        }
        _G.pvUltraState=SValue


        pcall(function()
            SValue.conn=pvSession.connect(workspace.DescendantAdded,function(data)
                if not SValue.active or _G.pvUltraEpoch~=epoch then return end
                task.defer(function()
                    if SValue.active and _G.pvUltraEpoch==epoch then
                        pcall(pvUltraApplyOne,data,SValue)
                    end
                end)
            end)
        end)


        task.spawn(function()
            local all=workspace:GetDescendants()
            for index,allItem in ipairs(all) do
                if not SValue.active or _G.pvUltraEpoch~=epoch then return end
                pcall(pvUltraApplyOne,allItem,SValue)
                if index%250==0 then task.wait() end
            end
        end)
    else
        local SValue=_G.pvUltraState
        if not SValue then return end

        _G.pvUltraEpoch=(_G.pvUltraEpoch or 0)+1
        SValue.active=false
        _G.pvUltraState=nil

        if SValue.conn then pcall(function() SValue.conn:Disconnect() end) end


        for key,value in pairs(SValue.parts or {}) do
            if key and key.Parent then
                pcall(function() key.Material=value.mat end)
                pcall(function() key.CastShadow=value.cast end)
                pcall(function() key.Reflectance=value.refl end)
                pcall(function() key.MaterialVariant=value.variant or "" end)
            end
        end

        for key,value in pairs(SValue.textures or {}) do
            if key then pcall(function() key.Transparency=value end) end
        end

        for key,value in pairs(SValue.meshparts or {}) do
            if key and key.Parent then pcall(function() key.TextureID=value or "" end) end
        end

        for key,value in pairs(SValue.special or {}) do
            if key and key.Parent then pcall(function() key.TextureId=value or "" end) end
        end


        for key,parent in pairs(SValue.surface or {}) do
            if key and parent and parent.Parent then pcall(function() key.Parent=parent end) end
        end

        for key,value in pairs(SValue.fx or {}) do
            if key and key.Parent then pcall(function() key.Enabled=value end) end
        end
    end
end
pvSession.addCleanup(function() pcall(pvUltraFpsBooster,false) end)

local pvStretchOn=false
local pvStretchFov=nil
local PV_STRETCH_FOV=45
function pvStretchRes(onValue, item, handle)
    item = item or 1080; handle = handle or 1080
    local function winFn()
        for _,number in ipairs({"setwindowsize","set_window_size","resizewindow","setresolution","setgamewindowsize"}) do
            local func=(getgenv and rawget(getgenv(),number)) or rawget(_G,number)
            if type(func)=="function" then return func end
        end
    end
    local func=winFn()
    if onValue then
        pvStretchOn=true
        if func then pcall(func,item,handle); return "window" end


        local cam=workspace.CurrentCamera
        if cam then
            pvStretchFov = pvStretchFov or cam.FieldOfView
            pcall(function() cam.FieldOfView=PV_STRETCH_FOV end)
            task.spawn(function()
                while pvStretchOn do
                    local child=workspace.CurrentCamera
                    if child and math.abs(child.FieldOfView-PV_STRETCH_FOV)>1 then pcall(function() child.FieldOfView=PV_STRETCH_FOV end) end
                    task.wait(0.4)
                end
            end)
        end
        return "zoom"
    else
        pvStretchOn=false
        if func then pcall(func,0,0) end
        local cam=workspace.CurrentCamera
        if cam and pvStretchFov then pcall(function() cam.FieldOfView=pvStretchFov end) end
        pvStretchFov=nil
        return "off"
    end
end
pvSession.addCleanup(function() pcall(pvStretchRes,false) end)

settings.ultraFpsBooster = false


pcall(function()
    local virtualUserService=game:GetService("VirtualUser")
    pvSession.connect(playerGui.Idled,function()
        if settings.antiAfk==false then return end
        pcall(function()
            virtualUserService:CaptureController()
            virtualUserService:ClickButton2(Vector2.new(0,0))
        end)
    end)
end)


function pvSaveConfigToDisk()
    if not hasFile then notify("no file access on this executor"); return end


    if type(settings.loadout)~="table" then settings.loadout={owned={},knife=nil,gun=nil} end
    if type(settings.loadout.owned)~="table" then settings.loadout.owned={} end
    for id in pairs(settings.loadout.owned) do
        if type(savedSpawns)~="table" or savedSpawns[id]~=true then
            settings.loadout.owned[id]=nil
        end
    end
    pcall(function()
        if type(isfolder)=="function" and not isfolder(CFG_DIR) then makefolder(CFG_DIR) end
        writefile(CFG_PATH, HttpService:JSONEncode(settings))
        writefile(SPAWN_PATH, HttpService:JSONEncode(savedSpawns or {}))
    end)
    notify("config saved")
end
-- Capture live UI geometry at export time, rather than waiting for a drag save.
function pvCaptureConfigUI()
    local function pack(unit) return {unit.X.Scale,unit.X.Offset,unit.Y.Scale,unit.Y.Offset} end
    settings.winPos={win.Position.X.Offset,win.Position.Y.Offset}
    settings.winSize={win.Size.X.Offset,win.Size.Y.Offset}
    pvSaveTabOrder()
    local state={windowPosition=pack(win.Position),windowSize=pack(win.Size),launcher=pack(tog.Position)}
    for name,page in pairs(pages) do if page.Visible then state.page=name end end
    local fps=HOST:FindFirstChild("PorkVisualsFPSCounter")
    local panel=fps and fps:FindFirstChildOfClass("Frame")
    if panel then state.fpsPosition=pack(panel.Position);state.fpsVisible=fps.Enabled end
    settings.uiSnapshot=state
end
function pvApplyConfigUI()
    local state=type(settings.uiSnapshot)=="table" and settings.uiSnapshot or {}
    local function unpackUDim(value)
        if type(value)~="table" then return nil end
        for index=1,4 do if type(value[index])~="number" then return nil end end
        return UDim2.new(value[1],value[2],value[3],value[4])
    end
    if _G.pvUiTweenWin then _G.pvUiTweenWin:Cancel() end
    if _G.pvUiTweenSettle then _G.pvUiTweenSettle:Cancel() end
    uiScale.Scale=1
    local size=unpackUDim(state.windowSize)
    if not size and type(settings.winSize)=="table" then
        size=UDim2.fromOffset(tonumber(settings.winSize[1]) or WValue,tonumber(settings.winSize[2]) or HValue)
    end
    if size then win.Size=size end
    local position=unpackUDim(state.windowPosition)
    if not position and type(settings.winPos)=="table" then
        position=UDim2.fromOffset(tonumber(settings.winPos[1]) or pxValue(14),tonumber(settings.winPos[2]) or pxValue(84))
    end
    if position then win.Position=position;pvSavedWinPos=position end
    local launcher=unpackUDim(state.launcher)
    if launcher then tog.Position=launcher end
    local fps=HOST:FindFirstChild("PorkVisualsFPSCounter")
    local panel=fps and fps:FindFirstChildOfClass("Frame")
    local fpsPosition=unpackUDim(state.fpsPosition)
    if panel and fpsPosition then panel.Position=fpsPosition end
    if fps and type(state.fpsVisible)=="boolean" then fps.Enabled=state.fpsVisible end
    pvApplyTabOrder()
    if type(state.page)=="string" and pages[state.page] then
        showPage(state.page)
    else
        for name,page in pairs(pages) do if page.Visible then showPage(name);break end end
    end
    for _,refresh in ipairs(pvSession.configRefresh) do pcall(refresh) end
end
-- Clipboard export is explicit; background and server-transition saves stay on disk.
function pvSaveConfig()
    local captured,captureError=pcall(pvCaptureConfigUI)
    if not captured then
        notify("Config save failed: "..tostring(captureError):sub(1,160))
        return false
    end
    local encoded,blob=pcall(function()
        return HttpService:JSONEncode({
            format="porkVisuals-config",version=1,
            settings=settings,savedSpawns=savedSpawns or {},
        })
    end)
    if not encoded or type(blob)~="string" then
        notify("Could not encode config: "..tostring(blob):sub(1,120));return false
    end
    -- Commit the loadable snapshot BEFORE any optional executor operations.
    pvSession.lastExportConfig=blob
    pcall(function() _G.pvLastSavedConfig=blob end)
    pcall(function()
        if type(getgenv)=="function" then getgenv().__porkVisualsSavedConfig=blob end
    end)
    if pvAPI.writefile then
        pcall(function()
            if type(isfolder)=="function" and not isfolder(CFG_DIR) and type(makefolder)=="function" then makefolder(CFG_DIR) end
            pvAPI.writefile(CFG_DIR.."/pv_saved_config.json",blob)
        end)
    end
    local copied,result=false,nil
    if pvAPI.setclipboard then copied,result=pcall(pvAPI.setclipboard,blob) end
    if copied and result~=false then
        notify("Config saved to clipboard")
    else
        notify("Config saved. Clipboard copy unavailable; Load Config will use the saved copy.")
    end
    return true
end

function pvImportConfig(blob,source)
    if type(blob)~="string" then notify("No config text supplied"); return false end
    if blob:match("^%s*$") then notify("Clipboard is empty"); return false end
    if #blob>4*1024*1024 then notify("Clipboard config is too large"); return false end
    local decoded,data=pcall(function() return HttpService:JSONDecode(blob) end)
    if not decoded or type(data)~="table" or data.format~="porkVisuals-config"
       or data.version~=1 or type(data.settings)~="table" or type(data.savedSpawns)~="table" then
        notify("Clipboard does not contain a valid PorkVisuals config"); return false
    end
    local value2,spawns=data.settings,data.savedSpawns
    if value2.hiddenChatKeywords == nil then value2.hiddenChatKeywords = "" end
    if value2.fakeUpgradeRanges==nil then value2.fakeUpgradeRanges={} end
    local richRange=type(value2.fakeUpgradeRanges)=="table" and value2.fakeUpgradeRanges.rich
    if type(richRange)=="table" and richRange.maximum==false then
        richRange.maximum=pvSession.upgradeTiers.rich.maximum
    end
    -- Validate first so malformed clipboard data cannot partly overwrite settings.
    local function valid(value,reference,depth)
        if depth>16 then return false end
        local kind=type(value)
        if reference~=nil and kind~=type(reference) then return false end
        if kind=="number" then return value==value and math.abs(value)<math.huge end
        if kind=="string" or kind=="boolean" then return true end
        if kind~="table" then return false end
        for index,valueItem in pairs(value) do
            if type(index)~="string" and type(index)~="number" then return false end
            if not valid(valueItem,type(reference)=="table" and reference[index] or nil,depth+1) then return false end
        end
        return true
    end
    local validConfig=valid(value2,settings,0) and type(value2.loadout)=="table"
        and type(value2.loadout.owned)=="table" and type(value2.keys)=="table"
    if validConfig then
        for id,amount in pairs(value2.loadout.owned) do
            if type(id)~="string" or type(amount)~="number" or amount<0 or amount%1~=0 then
                validConfig=false;break
            end
        end
        for id,flag in pairs(spawns) do
            if type(id)~="string" or type(flag)~="boolean" then validConfig=false;break end
        end
        for _,key in pairs(value2.keys) do
            if type(key)~="string" then validConfig=false;break end
        end
    end
    if not validConfig then notify("Clipboard config has invalid settings"); return false end
    local previousTheme=settings.uiTheme
    local previousOptimizer=settings.ultraFpsBooster
    for index,tItem in pairs(value2) do settings[index]=tItem end
    pvSession.refreshChatKeywords()
    savedSpawns=spawns
    for id in pairs(settings.loadout.owned) do
        if savedSpawns[id]~=true then settings.loadout.owned[id]=nil end
    end
    local number=0
    for id,amt in pairs(settings.loadout.owned) do
        local item=byId[id]
        if item and ProfileData[item.cat] and ProfileData[item.cat].Owned then
            ProfileData[item.cat].Owned[id]=item.evo and 1 or amt
            number=number+1
        end
    end
    local loadedTheme=settings.uiTheme
    settings.uiTheme=previousTheme
    pvSetUITheme(loadedTheme,false)
    pvApplyConfigUI()
    if type(settings.customBackground)=="string" and settings.customBackground~="" then
        pvSetCustomBackground(settings.customBackground,false,function(success)
            if success then notify("Custom BG loaded") end
        end)
    else
        pvSetCustomBackground("",false)
    end
    if pvHasBundledChristmasBackground then task.defer(function() pcall(pvHasBundledChristmasBackground) end) end
    PV_BLOCK_AFTER_TRADE=settings.autoBlock~=false
    if previousOptimizer~=settings.ultraFpsBooster then pcall(pvUltraFpsBooster,settings.ultraFpsBooster==true) end
    pcall(pvForceInventoryRefresh)
    saveCfg()
    notify("Config loaded from "..(source or "pasted text").." ("..number.." items restored)")
    return true
end


-- One-click import. A saved copy is not represented as a live clipboard read.
function pvLoadConfig()
    -- Prefer our explicit saved snapshot for reliable one-click Save -> Load.
    local blob=pvSession.lastExportConfig
    if type(blob)~="string" then pcall(function() blob=_G.pvLastSavedConfig end) end
    if type(blob)~="string" then
        pcall(function()
            if type(getgenv)=="function" then blob=getgenv().__porkVisualsSavedConfig end
        end)
    end
    if type(blob)~="string" and pvAPI.readfile then
        local success,saved=pcall(pvAPI.readfile,CFG_DIR.."/pv_saved_config.json")
        if success and type(saved)=="string" and saved~="" then blob=saved end
    end
    if type(blob)=="string" and blob~="" then return pvImportConfig(blob,"saved copy") end
    if pvAPI.getclipboard then
        local success,text=pcall(pvAPI.getclipboard)
        if success and type(text)=="string" and not text:match("^%s*$") then
            return pvImportConfig(text,"clipboard")
        end
    end
    -- Migrate configs saved by versions that only wrote pv_config.json.
    if pvAPI.readfile then
        local success,legacy=pcall(function()
            return HttpService:JSONDecode(pvAPI.readfile(CFG_PATH))
        end)
        if success and type(legacy)=="table" and type(legacy.loadout)=="table" then
            local spawns={}
            local readOK,stored=pcall(function()
                return HttpService:JSONDecode(pvAPI.readfile(SPAWN_PATH))
            end)
            if readOK and type(stored)=="table" then spawns=stored end
            local encoded,migrated=pcall(function()
                return HttpService:JSONEncode({format="porkVisuals-config",version=1,settings=legacy,savedSpawns=spawns})
            end)
            if encoded and pvImportConfig(migrated,"previous config file") then
                pvSession.lastExportConfig=migrated
                return true
            end
            return false
        end
    end
    notify("No saved copy found. Click Save Config and check its confirmation.")
    return false
end


task.defer(function()
    if type(settings.loadout)~="table" or type(settings.loadout.owned)~="table" then return end
    local number=0
    for id,amt in pairs(settings.loadout.owned) do
        local item=byId[id]
        if item and ProfileData[item.cat] and ProfileData[item.cat].Owned then
            ProfileData[item.cat].Owned[id] = item.evo and 1 or amt
            number=number+1
        end
    end
    if number>0 then pcall(pvForceInventoryRefresh) end
end)


do
    local RS_ = game:GetService("ReplicatedStorage")
    local function tradeOpen()
        if _G.pvSpoofActive then return true end
        local tradeGUI = playerGui2 and playerGui2:FindFirstChild("TradeGUI")
        return (tradeGUI and tradeGUI.Enabled) or false
    end
    local function reassert()
        if type(settings.loadout)~="table" or type(settings.loadout.owned)~="table" then return end
        local changed=false
        for id,amt in pairs(settings.loadout.owned) do
            local item=byId[id]
            if item and ProfileData[item.cat] and ProfileData[item.cat].Owned then
                local want   = item.evo and 1 or amt
                local current    = ProfileData[item.cat].Owned[id] or 0
                local target = math.max(current, want)
                if ProfileData[item.cat].Owned[id]~=target then
                    ProfileData[item.cat].Owned[id]=target; changed=true
                end
            end
        end


        if changed then
            if tradeOpen() then
                _G.pvInvDirty=true
            else


                local anyId
                for id in pairs(settings.loadout.owned) do anyId=id break end
                _G.pvPendingInv = {anyId, anyId and ProfileData.Weapons.Owned[anyId] or nil}
            end
        end
    end
    _G.pvInvRepinGen = (_G.pvInvRepinGen or 0) + 1
    do
        local myGen=_G.pvInvRepinGen
        task.spawn(function()
            local wasOpen=false
            while _G.pvInvRepinGen==myGen do
                local open=tradeOpen()
                if wasOpen and not open and _G.pvInvDirty then
                    _G.pvInvDirty=false
                    pcall(reassert)
                end
                wasOpen=open
                task.wait(0.2)
            end
        end)
    end


    local pending=false
    local function schedule()
        if pending then return end
        pending=true
        task.delay(0.35, function() pending=false; reassert() end)
    end
    for _,name in ipairs({"UpdateData","UpdateData2","UpdateData3"}) do
        local rem=RS_:FindFirstChild(name)
        if rem and rem:IsA("RemoteEvent") then
            pvSession.connect(rem.OnClientEvent,schedule)
        end
    end
end


function pvRealRequestUp()
    local mainGUI = playerGui2 and playerGui2:FindFirstChild("MainGUI")
    mainGUI = mainGUI and mainGUI:FindFirstChild("Game")
    mainGUI = mainGUI and mainGUI:FindFirstChild("Leaderboard")
    mainGUI = mainGUI and mainGUI:FindFirstChild("Container")
    local tradeRequest = mainGUI and mainGUI:FindFirstChild("TradeRequest")
    if not tradeRequest or not tradeRequest.Visible then return false end

    if _G.pvFakeReqName or _G.pvSentReqName then return false end
    return true
end
function pvPickRequester(preferName)
    if preferName and preferName~="" then return preferName end
    _G.pvReqRecent = _G.pvReqRecent or {}
    local function recent(number)
        for _,pvReqRecentItem in ipairs(_G.pvReqRecent) do if pvReqRecentItem==number then return true end end
        return false
    end
    local who
    for _=1,25 do
        local child = (pvRandomPartner and pvRandomPartner()) or "Player"
        if not recent(child) then who=child break end
        who = who or child
    end
    who = who or "Player"
    table.insert(_G.pvReqRecent, 1, who)
    while #_G.pvReqRecent > 8 do table.remove(_G.pvReqRecent) end
    return who
end
function pvFakeTradeRequest(onAccept, preferName)
    local mainGUI = playerGui2 and playerGui2:FindFirstChild("MainGUI")
    mainGUI = mainGUI and mainGUI:FindFirstChild("Game")
    mainGUI = mainGUI and mainGUI:FindFirstChild("Leaderboard")
    mainGUI = mainGUI and mainGUI:FindFirstChild("Container")
    local tradeRequest = mainGUI and mainGUI:FindFirstChild("TradeRequest")
    local receivingRequest = tradeRequest and tradeRequest:FindFirstChild("ReceivingRequest")
    if not (tradeRequest and receivingRequest) then return false, "unavailable" end


    if tradeRequest.Visible then return false, "busy" end

    local nameLbl = receivingRequest:FindFirstChild("Username")
    local accept     = receivingRequest:FindFirstChild("Accept")
    local dec     = receivingRequest:FindFirstChild("Decline")
    if not (nameLbl and accept and dec) then return false, "unavailable" end

    local who = pvPickRequester(preferName)
    local sendingRequest  = tradeRequest:FindFirstChild("SendingRequest")
    local savedName, savedTR, savedRR = nameLbl.Text, tradeRequest.Visible, receivingRequest.Visible
    local savedSR = sendingRequest and sendingRequest.Visible or nil

    nameLbl.Text = who
    if sendingRequest then pcall(function() sendingRequest.Visible=false end) end
    receivingRequest.Visible = true
    tradeRequest.Visible = true
    _G.pvFakeReqName = who

    local done, conns = false, {}
    local function cleanup()
        if done then return end
        done = true
        for _,conn in ipairs(conns) do pcall(function() conn:Disconnect() end) end
        pcall(function()
            nameLbl.Text = savedName
            receivingRequest.Visible   = savedRR
            tradeRequest.Visible   = savedTR
            if sendingRequest and savedSR~=nil then sendingRequest.Visible = savedSR end
        end)
        _G.pvFakeReqName = nil
    end
    conns[#conns+1] = pvSession.connect(accept.MouseButton1Click,function()
        cleanup()
        if onAccept then pcall(onAccept, who) end
    end)
    conns[#conns+1] = pvSession.connect(dec.MouseButton1Click,cleanup)
    task.delay(25, cleanup)
    -- Also return the request's actual chosen username for the trade panel UI.
    return true, who
end


function pvFakeTradeSent(who, onAccept)
    local mainGUI = playerGui2 and playerGui2:FindFirstChild("MainGUI")
    mainGUI = mainGUI and mainGUI:FindFirstChild("Game")
    mainGUI = mainGUI and mainGUI:FindFirstChild("Leaderboard")
    mainGUI = mainGUI and mainGUI:FindFirstChild("Container")
    local tradeRequest = mainGUI and mainGUI:FindFirstChild("TradeRequest")
    local sendingRequest = tradeRequest and tradeRequest:FindFirstChild("SendingRequest")
    if not (tradeRequest and sendingRequest) then return false, "unavailable" end
    if tradeRequest.Visible then return false, "busy" end

    local nameLbl = sendingRequest:FindFirstChild("Username")
    local cancel  = sendingRequest:FindFirstChild("Cancel")
    if not (nameLbl and cancel) then return false, "unavailable" end

    local receivingRequest = tradeRequest:FindFirstChild("ReceivingRequest")
    local savedName, savedTR, savedSR = nameLbl.Text, tradeRequest.Visible, sendingRequest.Visible
    local savedRR = receivingRequest and receivingRequest.Visible or nil

    nameLbl.Text = who
    if receivingRequest then pcall(function() receivingRequest.Visible=false end) end
    sendingRequest.Visible = true
    tradeRequest.Visible = true
    _G.pvSentReqName = who

    local done, conns = false, {}
    local function restore()
        pcall(function()
            nameLbl.Text = savedName
            sendingRequest.Visible   = savedSR
            tradeRequest.Visible   = savedTR
            if receivingRequest and savedRR~=nil then receivingRequest.Visible = savedRR end
        end)
        _G.pvSentReqName = nil
    end
    local function cleanup()
        if done then return end
        done = true
        for _,conn in ipairs(conns) do pcall(function() conn:Disconnect() end) end
        restore()
    end
    conns[#conns+1] = pvSession.connect(cancel.MouseButton1Click,cleanup)

    task.delay(1.6 + math.random()*2.2, function()
        if done then return end
        done = true
        for _,conn in ipairs(conns) do pcall(function() conn:Disconnect() end) end
        restore()
        if onAccept then pcall(onAccept, who) end
    end)
    return true
end
function pvDeleteConfig()
    -- Keep the last exported snapshot: executors without clipboard reading use
    -- this copy to support Save -> Delete -> Load. Delete only clears active/disk config.
    if pvAPI.writefile then pcall(pvAPI.writefile,CFG_DIR.."/pv_saved_config.json","") end
    if pvAPI.delfile then pcall(pvAPI.delfile,CFG_DIR.."/pv_saved_config.json") end

    _G.pvCfgEpoch = (_G.pvCfgEpoch or 0) + 1
    saveQueued = false


    local realOwned, realEquipped, gotReal = {}, nil, false
    pcall(function()
        local getFullInventory = replicatedStorageService.Remotes.Extras:FindFirstChild("GetFullInventory")
        local inventory = getFullInventory and getFullInventory:InvokeServer(playerGui.Name)
        if inventory and inventory.Weapons and type(inventory.Weapons.Owned)=="table" then
            for id,amt in pairs(inventory.Weapons.Owned) do realOwned[id]=amt end
            if type(inventory.Weapons.Equipped)=="table" then
                realEquipped={}
                for slot,id in pairs(inventory.Weapons.Equipped) do realEquipped[slot]=id end
            end
            gotReal=true
        end
    end)


    local wipe={}
    for id in pairs((settings.loadout and settings.loadout.owned) or {}) do wipe[id]=true end
    for id in pairs(savedSpawns or {}) do wipe[id]=true end

    pcall(function()
        local owned = ProfileData.Weapons and ProfileData.Weapons.Owned
        if not owned then return end
        if gotReal then

            for id in pairs(owned) do owned[id]=nil end
            for id,amt in pairs(realOwned) do owned[id]=amt end
        else

            for id in pairs(wipe) do owned[id]=nil end
        end
    end)
    if gotReal and realEquipped and ProfileData.Weapons and ProfileData.Weapons.Equipped then
        pcall(function()
            for slot in pairs(ProfileData.Weapons.Equipped) do ProfileData.Weapons.Equipped[slot]=nil end
            for slot,id in pairs(realEquipped) do ProfileData.Weapons.Equipped[slot]=id end
        end)
    end


    settings.hiddenChatKeywords = ""
    pvSession.refreshChatKeywords()
    settings.loadout={owned={},knife=nil,gun=nil}
    savedSpawns={}
    _G.pvPendingInv=nil
    _G.pvPendingFullInv=nil
    _G.pvInvDirty=false
    _lastCfgBlob=nil
    _lastSpawnBlob=nil


    local emptyCfg = HttpService:JSONEncode({loadout={owned={}}})
    local emptySpawn = "{}"
    if hasFile then
        pcall(function()
            if type(isfolder)=="function" and not isfolder(CFG_DIR) then makefolder(CFG_DIR) end
            writefile(CFG_PATH, emptyCfg)
            writefile(SPAWN_PATH, emptySpawn)
        end)

        local del = (pvAPI and pvAPI.delfile) or (type(delfile)=="function" and delfile)
        if type(del)=="function" then
            pcall(function() del(CFG_PATH) end)
            pcall(function() del(SPAWN_PATH) end)
        end


        pcall(function()
            if isfileSafe(CFG_PATH) then writefile(CFG_PATH, emptyCfg) end
            if isfileSafe(SPAWN_PATH) then writefile(SPAWN_PATH, emptySpawn) end
        end)
    end

    pcall(pvForceInventoryRefresh)
    notify(pvSession.lastExportConfig and "Config deleted. Load Config can restore your last saved backup." or "Config deleted. Clipboard unchanged.")
end

