    local myGen=_G.pvGen
    _G.pvLearned = _G.pvLearned or {}
    local dirty=false
    local function slotOf(data)
        if data.Name=="GunDisplay" then return "Gun" end
        if data.Name=="KnifeDisplay" then return "Knife" end
        return nil
    end
    local function learn()
        local weaponDisplays=workspace:FindFirstChild("WeaponDisplays")
        if not weaponDisplays then return end
        for _,data in ipairs(weaponDisplays:GetChildren()) do
            local slot=slotOf(data)


            if slot and not data:FindFirstChild("pvWorn"..slot) then
                local rigidConstraint=data:FindFirstChildOfClass("RigidConstraint")
                local attachment=(rigidConstraint and rigidConstraint.Attachment1) or data:FindFirstChildOfClass("Attachment")
                local a0Value=rigidConstraint and rigidConstraint.Attachment0
                local character=a0Value and a0Value.Parent and a0Value.Parent.Parent
                local plr=character and game:GetService("Players"):GetPlayerFromCharacter(character)
                if attachment and plr then


                    if plr~=playerGui then
                        local wid = (slot=="Gun") and plr:GetAttribute("EquippedGun")
                                                  or  plr:GetAttribute("EquippedKnife")
                        if wid and wid~="" and not (meshDB[wid] and meshDB[wid].studio) then
                            local key=pvNorm(tostring(wid))
                            if not _G.pvLearned[key] then
                                _G.pvLearned[key]=true


                                pvFixCF[key]=attachment.CFrame
                                local specialMesh=data:FindFirstChildOfClass("SpecialMesh")
                                local mid = data:IsA("MeshPart") and data.MeshId or (specialMesh and specialMesh.MeshId)
                                local tid = data:IsA("MeshPart") and data.TextureID or (specialMesh and specialMesh.TextureId)
                                if mid and mid~="" then
                                    local record = meshDB[wid] or {}
                                    record.mesh = mid
                                    if tid and tid~="" then record.tex = tid end
                                    record.typ  = slot
                                    record.real = true
                                    if specialMesh then
                                        record.scale = {specialMesh.Scale.X, specialMesh.Scale.Y, specialMesh.Scale.Z}
                                        record.mp    = nil
                                    else
                                        record.scale = nil
                                        record.mp    = true
                                    end
                                    record.color = {data.Color.R, data.Color.G, data.Color.B}
                                    record.mat   = data.Material.Name
                                    record.ov    = nil
                                    meshDB[wid] = record


                                    if PV_UNRENDERABLE then PV_UNRENDERABLE[wid]=nil end
                                    if PV_BAD_SIZE then PV_BAD_SIZE[wid]=nil end
                                end
                                dirty=true
                            end
                        end
                    end
                end
            end
        end
    end
    local function persist()
        if not (dirty and hasFile) then return end
        dirty=false
        pcall(function()
            local out={}
            for index,pvFixCFItem in pairs(pvFixCF) do out[index]={pvFixCFItem:GetComponents()} end
            out.__model = PV_MOUNT_MODEL
            if type(isfolder)=="function" and not isfolder(CFG_DIR) then makefolder(CFG_DIR) end
            writefile(CFG_DIR.."/pv_fix.json", HttpService:JSONEncode(out))
        end)
    end
    local number=0
    while _G.pvGen==myGen do
        pcall(learn)
        number=number+1
        if number%8==0 then pcall(persist) end
        pvTick("orient-harvest", 4)
    end
end)


