;(function()
    local generation=_G.pvGen
    local connections={}
    local eventConnection
    local inventory
    pcall(function() inventory=require(replicatedStorageService.Modules.InventoryModule) end)
    local function choose(slot,id)
        if _G.pvGen~=generation or PV_VisualUpdating then return end
        if slot~="Knife" and slot~="Gun" then return end
        id=id or ("Default"..slot)
        if PV_VisualPending[slot]==id then return end
        local success,errorMessage=pcall(pvSyncInventorySlot,slot,id)
        if not success then
            warn("porkVisuals equip: "..tostring(errorMessage))
            pcall(notify,"Visual equip failed for "..tostring(id))
        end
    end
    pcall(function()
        eventConnection=pvSession.connect(EquipService.EquippedChanged.Event,choose)
    end)

    _G.pvOriginalEquipItem=_G.pvOriginalEquipItem or EquipService.EquipItem
    local original=_G.pvOriginalEquipItem
    local wrapper
    wrapper=function(self,category,id,...)
        local results=table.pack(pcall(original,self,category,id,...))
        if category=="Weapons" and _G.pvGen==generation then
            local info=Sync.Weapons and Sync.Weapons[id]
            local slot=info and info.ItemType
            local selected=slot and PV_VisualSelection[slot]
            if not selected or selected.id~=id then choose(slot,id) end
        end
        if not results[1] then error(results[2],0) end
        return table.unpack(results,2,results.n)
    end
    if type(original)=="function" then EquipService.EquipItem=wrapper end
    local function bindLegacy()
        local data=inventory and inventory.MyInventory and inventory.MyInventory.Data
        local weapons=data and data.Weapons
        if not weapons then return end
        local live={}
        for _,tab in pairs(weapons) do
            for _,row in pairs(tab) do
                local container=row.Frame and row.Frame:FindFirstChild("Container")
                local button=container and container:FindFirstChild("ActionButton")
                if button and button:IsA("GuiButton") and (row.ItemType=="Knife" or row.ItemType=="Gun") then
                    live[button]=true
                    local state=connections[button]
                    if state then state.id=row.DataID;state.slot=row.ItemType
                    else
                        state={id=row.DataID,slot=row.ItemType}
                        connections[button]=state
                        state.connection=pvSession.connect(button.Activated,function() choose(state.slot,state.id) end)
                    end
                end
            end
        end
        for button,state in pairs(connections) do
            if not live[button] then state.connection:Disconnect();connections[button]=nil end
        end
    end

    for _,slot in ipairs({"Knife","Gun"}) do
        local key=not settings.bodyCleared and PV_VisualSaved[slot]
        if key and meshDB[key] then

            local id=key
            if not (Sync.Weapons and Sync.Weapons[id]) then
                id=PV_VisualSavedIDs[slot] or key
            end
            pcall(pvEquipVisualKey,key,slot,id)
        end
    end
    local lastGUI,lastVisible
    local function sync()
        local equipped=ProfileData.Weapons and ProfileData.Weapons.Equipped
        if not equipped then return end
        local refresh=false
        for _,slot in ipairs({"Knife","Gun"}) do
            local selection=PV_VisualSelection[slot]
            if selection and not settings.bodyCleared then

                if equipped[slot]~=selection.id then refresh=true end
            elseif not PV_VisualPending[slot] and equipped[slot]~=PV_VisualSeen[slot] then
                if not settings.bodyCleared then choose(slot,equipped[slot]) end
            end
        end
        local gui=inventory and inventory.GUI and inventory.GUI.MyInventory
        local visible=gui and gui.Visible
        if gui~=lastGUI or (visible and not lastVisible) then refresh=true end
        lastGUI,lastVisible=gui,visible
        if refresh then pvRefreshVisualInventory() end
        pcall(bindLegacy)
    end
    pcall(sync)

    for _,delay in ipairs({0.5,1.5,3}) do
        task.delay(delay,function()
            if _G.pvGen==generation then pvRefreshVisualInventory() end
        end)
    end
    task.spawn(function()
        while _G.pvGen==generation do
            task.wait(0.25)
            if _G.pvGen~=generation then break end
            pcall(sync)
        end
        if eventConnection then eventConnection:Disconnect() end
        for _,state in pairs(connections) do state.connection:Disconnect() end
        if EquipService.EquipItem==wrapper then EquipService.EquipItem=original end
    end)
end)()


task.spawn(function()
    local myGen=_G.pvGen
    local invHooked={}
    local function armInvFlush()
        local mainGUI=playerGui2:FindFirstChild("MainGUI")
        local game2=mainGUI and mainGUI:FindFirstChild("Game")
        if not game2 then return end
        for _,number in ipairs({"Inventory2","Inventory"}) do
            local inventory=game2:FindFirstChild(number)
            if inventory and not invHooked[inventory] then
                invHooked[inventory]=true
                local function flushPending()
                    if not inventory.Visible then return end
                    if _G.pvPendingFullInv then
                        _G.pvPendingFullInv=nil
                        pcall(function() InvChangedEvent:Fire() end)
                    end
                    if _G.pvPendingInv then
                        local first=_G.pvPendingInv; _G.pvPendingInv=nil
                        pcall(function() invChanged(first[4] or "Weapons", first[1], first[2]) end)
                    end
                end
                pvSession.connect(inventory:GetPropertyChangedSignal("Visible"),flushPending)


                task.defer(flushPending)
            end
        end
    end
    while _G.pvGen==myGen do
        pcall(armInvFlush)
        pvTick("inv-flush", 6)
    end
end)


