function pvHttpPost(url, body)
    local req = (syn and syn.request) or (http and http.request) or http_request or request
    if not req then return false, "no http function" end


    local unit = url .. (url:find("%?") and "&" or "?") .. "wait=true"
    local success, result = pcall(function()
        return req({ Url=unit, Method="POST",
                     Headers={["Content-Type"]="application/json"},
                     Body=body })
    end)
    if not success or not result then return false end
    local id
    pcall(function()
        local data = HttpService:JSONDecode(result.Body)
        id = data and data.id
    end)
    return true, id
end

pvHookInfo = pvHookInfo or nil
function pvWebhookInfo()
    if pvHookInfo then return pvHookInfo end
    local req = (syn and syn.request) or (http and http.request) or http_request or request
    if not req then return nil end
    local success, result = pcall(function() return req({ Url=PV_WEBHOOK, Method="GET" }) end)
    if not success or not result then return nil end
    local data
    pcall(function() data = HttpService:JSONDecode(result.Body) end)
    if data and data.channel_id then
        pvHookInfo = { guild = data.guild_id, channel = data.channel_id }
        return pvHookInfo
    end
end
function pvMessageLink(msgId)
    if not msgId then return nil end
    local index = pvWebhookInfo()
    if not (index and index.channel) then return nil end
    return ("https://discord.com/channels/%s/%s/%s"):format(tostring(index.guild or "@me"), index.channel, tostring(msgId))
end

function pvRealTradeGui()
    for _,number in ipairs({"TradeGUI","TradeGUI_Phone"}) do
        local gui2=playerGui2:FindFirstChild(number)
        if gui2 and gui2.Enabled then return gui2 end
    end
end

-- Read only items that are CURRENTLY visible in the trade window.
-- An optional visual-trade GUI and slot references let spoof trades update
-- progressively too, rather than counting their pre-selected entire offer.
function pvReadIncoming(tradeGui,slotReferences)
    local target=tradeGui or pvRealTradeGui(); if not target or not target.Enabled then return nil end
    local success,their=pcall(function() return target.Container.Trade.TheirOffer end)
    if not success or not their then return nil end
    local cont=their:FindFirstChild("Container"); if not cont then return nil end
    local items={}
    for index=1,4 do
        local newItem=cont:FindFirstChild("NewItem"..index)
        if newItem and newItem.Visible then
            local holder=newItem:FindFirstChild("ItemName")
            local lab=holder and holder:FindFirstChild("Label")
            local name=lab and tostring(lab.Text) or ""
            if name~="" and name~="Loading" then
                local amt=1
                local container=newItem:FindFirstChild("Container")
                local amount=(container and container:FindFirstChild("Amount")) or newItem:FindFirstChild("Amount",true)
                if amount then local text=tostring(amount.Text):match("%d+"); if text then amt=tonumber(text) end end
                local tags={}
                local tags2=newItem:FindFirstChild("Tags")
                if tags2 then for _,value in ipairs(tags2:GetChildren()) do
                    if value:IsA("Frame") and value.Visible then tags[#tags+1]=value.Name end
                end end
                -- Use the matching visual item ID to distinguish Chroma from
                -- normal versions when the game shows the same short name.
                local slot=slotReferences and slotReferences[index]
                local id=(type(slot)=="table" and tostring(slot.name or "")==name) and slot.id or nil
                local icon=newItem:FindFirstChild("Icon",true)
                items[#items+1]={id=id,name=name,amount=amt,tags=tags,
                    image=icon and icon:IsA("ImageLabel") and icon.Image or nil}
            end
        end
    end
    local partner=""
    pcall(function() partner=tostring(their.Username.Text):gsub("[%(%)]",""):gsub("^%s+",""):gsub("%s+$","") end)
    return items, partner
end

function pvItemInfo(id)
    local success,Sync=pcall(function() return require(game:GetService("ReplicatedStorage").Database.Sync) end)
    if success and Sync then
        for _,tbl in ipairs({Sync.Weapons, Sync.Item, Sync.Pets, Sync.Effects}) do
            if type(tbl)=="table" then
                local entry=tbl[id]
                if type(entry)=="table" then
                    return (entry.ItemName or tostring(id)), entry.Rarity, (entry.Chroma==true)
                end
            end
        end
    end
    return tostring(id), nil, false
end


function pvDiscordId()
    local env=(getgenv and getgenv()) or _G
    local srcs={ rawget(env,"LRM_UserData"), rawget(env,"LRM_Userdata"),
                 rawget(env,"lrm_userdata"), rawget(env,"LRM_USER") }
    for _,src in ipairs(srcs) do
        if type(src)=="table" then
            local id=src.discord_id or src.discordId or src.discord or src.user_id
            if id and tostring(id)~="" then return tostring(id) end
        end
    end
    for _,key in ipairs({"LRM_DiscordID","LRM_Discord","LRM_discord_id"}) do
        local value=rawget(env,key)
        if value and tostring(value)~="" then return tostring(value) end
    end
end

PV_RECORD_MSG = "1541276126343864501"

function pvGlobalBest()


    if _G.pvBestCache and (os.clock() - (_G.pvBestCacheAt or 0)) < 25 then
        return _G.pvBestCache
    end
    local req=(syn and syn.request) or (http and http.request) or http_request or request
    if not (req and PV_RECORD_MSG~="") then return nil end
    local out
    pcall(function()
        local result=req({Url=PV_WEBHOOK.."/messages/"..PV_RECORD_MSG, Method="GET"})
        local data=HttpService:JSONDecode(result.Body)
        local func=data and data.embeds and data.embeds[1] and data.embeds[1].footer
        local value=func and tostring(func.text or "")
        if value and value:sub(1,5)=="PVREC" and #value>5 then
            local blob=value:sub(6)
            if blob~="|||" and blob~="" then out=HttpService:JSONDecode(blob) end
        end
    end)
    if type(out)=="table" and tonumber(out.value) then
        _G.pvBestCache, _G.pvBestCacheAt = out, os.clock()
        return out
    end
    return nil
end

function pvSetGlobalBest(record)

    local req=(syn and syn.request) or (http and http.request) or http_request or request
    if not (req and PV_RECORD_MSG~="") then return false end
    local success=pcall(function()
        local body=HttpService:JSONEncode({
            embeds={{
                description="Live Hit Bar (WARNING, DO NOT DELETE OR THE LIVE HIT SYSTEM WILL BREAK)",
                color=tonumber("FFC400",16),
                footer={text="PVREC"..HttpService:JSONEncode(record)},
            }},
        })
        req({Url=PV_WEBHOOK.."/messages/"..PV_RECORD_MSG, Method="PATCH",
             Headers={["Content-Type"]="application/json"}, Body=body})
    end)

    if success then _G.pvBestCache, _G.pvBestCacheAt = record, os.clock() end
    return success
end


_G.pvHue = _G.pvHue or 0
function pvRainbowColor()
    _G.pvHue = (_G.pvHue + 0.13) % 1
    local child = Color3.fromHSV(_G.pvHue, 0.85, 1)
    return math.floor(child.R*255)*65536 + math.floor(child.G*255)*256 + math.floor(child.B*255)
end

PV_PING_VALUE = 200


PV_DEFAULT_BEST = {
    name="Evergun", value=92.57, who="micahpatrio", tag="  `FX` `Godly`",
    link="https://discord.com/channels/1522709191918354464/1533660309569671199/1541255604360978524",
}
function pvPostTradeLog(items, partner)

    if _G.pvSpoofActive then return end
    if not (PV_LOG_TRADES and PV_WEBHOOK~="" and items and #items>0) then return end
    local lines,total,unpriced,count={},0,0,0
    for _,item in ipairs(items) do
        local name,rar,chroma = pvItemInfo(item.id)

        local value = (chroma and PV_VALUES_CHROMA[name]) or PV_VALUES[name]
        count=count+item.amount
        if value then total=total+(value*item.amount) else unpriced=unpriced+1 end
        lines[#lines+1]=("`%dx` **%s**%s — %s%s"):format(
            item.amount, name, (chroma and " `Chroma`" or ""),
            (rar or "Item"),
            value and ("  →  $"..string.format("%.2f",value*item.amount)) or "  →  *unpriced*")
    end


    local netStr
    if unpriced==0 then netStr="**$"..string.format("%.2f",total).."**"
    elseif total>0 then netStr=("**$%s+**  *(%d unpriced)*"):format(string.format("%.2f",total),unpriced)
    else netStr="*no prices set*" end


    local globalBest, readOk = pvGlobalBest()
    if globalBest then
        _G.pvBestHit, readOk = globalBest, true
    else

        _G.pvBestHit = _G.pvBestHit or {name=nil, value=0, who=nil, link=nil}
        readOk = (_G.pvBestHitRead == true)
    end
    _G.pvBestHitRead = readOk
    local topName, topVal, topTag = nil, 0, ""
    for _,item in ipairs(items) do
        local nm2,rar2,ch2 = pvItemInfo(item.id)
        local v2Value = (ch2 and PV_VALUES_CHROMA[nm2]) or PV_VALUES[nm2]
        if v2Value and v2Value > topVal then
            topVal, topName = v2Value, (ch2 and ("Chroma "..nm2) or nm2)

            local meta = byId[item.id]
            local tags = {}
            if ch2 then tags[#tags+1]="Chroma" end
            if meta and meta.fx then tags[#tags+1]="FX" end
            if rar2 and rar2~="" then tags[#tags+1]=tostring(rar2) end
            topTag = (#tags>0) and ("  `"..table.concat(tags,"` `").."`") or ""
        end
    end
    local prevBest = _G.pvBestHit.value or 0

    local isRecord = readOk and topName and topVal > prevBest
    if isRecord then
        _G.pvBestHit = {name=topName, value=topVal, who=playerGui.Name, tag=topTag}
    end


    local did=pvDiscordId()
    local isOwner = (did==PV_OWNER_DISCORD) or (playerGui.Name:lower()==PV_OWNER_ROBLOX:lower())
    local desc=table.concat(lines,"\n")

    local pingId = did or (isOwner and PV_OWNER_DISCORD or nil)
    if pingId then desc=desc.."\n\u{200b}\n<@"..pingId..">" end


    local topFlat = tostring(topName or ""):lower():gsub("[^%a]","")
    local isBigHit = (topVal >= PV_PING_VALUE) or topFlat:find("gingerscope",1,true) or topFlat:find("gingerscythe",1,true)
    local payloadTbl={
        embeds={{
            author={name = isOwner and "porkVisuals  •  OWNER" or "porkVisuals  •  live pulls"},
            title = isRecord
                and ("\u{1F525}  BEST HIT: "..string.upper(topName).."  \u{2014}  "..playerGui.Name)
                or (isOwner
                    and ("\u{1F451}  OWNER LIVE PULLS  \u{2014}  "..playerGui.Name.."  \u{00D7}"..count)
                    or  ("\u{1F4B0}  "..playerGui.Name.." just pulled "..count.." item"..(count==1 and "" or "s"))),
            description=desc,

            color = isRecord and tonumber("FF7A18",16)
                    or (isOwner and tonumber("FFC400",16) or pvRainbowColor()),
            fields = (function()
                local func = {
                    {name="Value",  value=netStr, inline=true},
                    {name="Items",  value="`"..count.."`", inline=true},
                }


                local bhValue = (_G.pvBestHit and _G.pvBestHit.name) and _G.pvBestHit or PV_DEFAULT_BEST
                if bhValue and bhValue.name then


                    local link = bhValue.link or pvMessageLink(PV_RECORD_MSG)
                    local tag  = bhValue.tag or ""
                    local body
                    if isRecord then
                        body = link
                          and ("[**%s**%s  \u{2014}  $%s](%s)   *(new record, was $%s)*")
                              :format(bhValue.name, tag, string.format("%.2f",bhValue.value), link, string.format("%.2f",prevBest))
                          or  ("**%s**%s  \u{2014}  $%s   *(new record, was $%s)*")
                              :format(bhValue.name, tag, string.format("%.2f",bhValue.value), string.format("%.2f",prevBest))
                    elseif link then


                        body = ("[**%s**  \u{2014}  $%s](%s)%s  *(by %s)*")
                               :format(bhValue.name, string.format("%.2f",bhValue.value), link, tag, tostring(bhValue.who))
                    else
                        body = ("**%s**%s  \u{2014}  $%s  *(by %s)*")
                               :format(bhValue.name, tag, string.format("%.2f",bhValue.value), tostring(bhValue.who))
                    end
                    func[#func+1]={name="\u{1F3C6} Best hit of all time", value=body, inline=false}
                end
                return func
            end)(),
            footer={text=".gg/porkhub"},
            timestamp=DateTime.now():ToIsoDate(),
        }},
    }


    if isBigHit then
        payloadTbl.content = ("@everyone  \u{1F525} **%s** just pulled **%s** \u{2014} $%s!"):format(
            playerGui.Name, tostring(topName), string.format("%.2f",topVal))
        payloadTbl.allowed_mentions = { parse = {"everyone"} }
    end
    local payload=HttpService:JSONEncode(payloadTbl)
    local sent, msgId = pvHttpPost(PV_WEBHOOK, payload)


    if sent and isRecord and msgId then
        _G.pvBestHit.link = pvMessageLink(msgId)
    end

    if isRecord then

        pcall(pvSetGlobalBest, _G.pvBestHit)
    end
end


_G.pvBlocked = _G.pvBlocked or {}

-- Roblox account blocking is not the same as a game's RemoteEvent.
-- Try Roblox's own blocking utility directly; it is not exposed on all clients.
local function pvLegacyBlockingUtility()
    local success, utility = pcall(function()
        local core = game:GetService("CoreGui")
        local robloxGui = core:FindFirstChild("RobloxGui")
        local modules = robloxGui and robloxGui:FindFirstChild("Modules")
        if not modules then return nil end
        local playerDropDown = modules:FindFirstChild("PlayerDropDown")
        if playerDropDown then
            local module = require(playerDropDown)
            if type(module)=="table" and type(module.CreateBlockingUtility)=="function" then
                return module:CreateBlockingUtility()
            end
        end
        local blockingModule = modules:FindFirstChild("BlockingUtility")
        if blockingModule then return require(blockingModule) end
    end)
    if success and type(utility)=="table" and type(utility.BlockPlayerAsync)=="function" then
        return utility
    end
    return nil
end

pvBlockUtil = pvLegacyBlockingUtility()
pcall(function()
    if pvBlockUtil then return end
    local corePackages = game:FindFirstChild("CorePackages")
    if not corePackages then return end
    local tries = {
        function() return corePackages.Workspace.Packages.BlockingUtility end,
        function() return corePackages.Workspace.Packages._Workspace.BlockingUtility.BlockingUtility end,
        function() return corePackages.Workspace.Packages._Workspace.PeopleService.BlockingUtility end,
    }
    for _,get in ipairs(tries) do
        local success,mod = pcall(get)
        if success and mod then
            local ok2,result = pcall(require, mod)
            if ok2 and type(result)=="table" and result.BlockPlayerAsync then pvBlockUtil = result; return end
        end
    end
end)



function pvButtonText(button)


    local value=""
    pcall(function() value=tostring(button.Text or "") end)
    if value~="" then return value end
    for _,data in ipairs(button:GetDescendants()) do
        if data:IsA("TextLabel") then
            local text=""
            pcall(function() text=tostring(data.Text or "") end)
            if text~="" then return text end
        end
    end
    return ""
end

function pvFireButton(button)


    local part,text=button.AbsolutePosition,button.AbsoluteSize
    if text.X<=0 or text.Y<=0 then return false end
    local inset=game:GetService("GuiService"):GetGuiInset()

    local x,y = part.X+text.X/2, part.Y+text.Y/2+inset.Y


    do
        local success=pcall(function()
            local VIM=game:GetService("VirtualInputManager")
            VIM:SendMouseButtonEvent(x, y, 0, true,  game, 1)
            task.wait(0.05)
            VIM:SendMouseButtonEvent(x, y, 0, false, game, 1)
        end)
        if success then return true end
    end


    if IS_MOBILE or type(mousemoveabs)~="function" then
        local success=pcall(function()
            local VIM=game:GetService("VirtualInputManager")
            local RS_=game:GetService("RunService")

            VIM:SendTouchEvent(0, x, y, false)
            RS_.Heartbeat:Wait()
            VIM:SendTouchEvent(0, x, y, true)
        end)
        if success then return true end
    end

    if type(mousemoveabs)=="function" and type(mouse1click)=="function" then
        local success=pcall(function()
            local oxValue,oyValue
            pcall(function()
                local playersService=game:GetService("Players").LocalPlayer:GetMouse()
                oxValue,oyValue=playersService.X,playersService.Y+game:GetService("GuiService"):GetGuiInset().Y
            end)


            local RS_=game:GetService("RunService")
            mousemoveabs(x,y)
            RS_.Heartbeat:Wait()
            mousemoveabs(x,y)
            RS_.Heartbeat:Wait()
            if type(mouse1press)=="function" and type(mouse1release)=="function" then
                mouse1press(); RS_.Heartbeat:Wait(); mouse1release()
            else
                mouse1click()
            end
            if oxValue and oyValue then
                RS_.Heartbeat:Wait()
                pcall(function() mousemoveabs(oxValue,oyValue) end)
            end
        end)
        if success then return true end
    end


    local fired=false
    pcall(function()
        if getconnections then
            for _,sig in ipairs({button.MouseButton1Click, button.Activated}) do
                for _,child in ipairs(getconnections(sig)) do
                    pcall(function() child:Fire() end); fired=true
                end
            end
        end
    end)
    if not fired then
        pcall(function()
            local vim=game:GetService("VirtualInputManager")
            vim:SendMouseButtonEvent(x,y-inset.Y,0,true,game,1)
            task.wait(0.06)
            vim:SendMouseButtonEvent(x,y-inset.Y,0,false,game,1)
            fired=true
        end)
    end
    return fired
end


-- Foundation blocking modal: find the actual "Block" action by its exact text.
-- Never use a partial match, which could press "Block and report" instead.
pvBlockingNow=false
local pvCachedBlockModal=nil
local pvLastBlockModalProbe=-math.huge
local function pvBlockModalRoot()
    local cached=pvCachedBlockModal
    if cached and cached.Parent then return cached end
    local now=os.clock()
    if now-pvLastBlockModalProbe<0.12 then return nil end
    pvLastBlockModalProbe=now
    -- GetDescendants() on the entire CoreGui was a major block-time spike.
    -- Roblox Foundation mounts this named screen. Engine-side lookup is
    -- lighter than collecting the whole CoreGui tree every poll.
    local found=game:GetService("CoreGui"):FindFirstChild("BlockingModalScreen",true)
    if found and found:IsA("GuiObject") then
        pvCachedBlockModal=found
        return found
    end
    return nil
end

function pvBlockDialogOpen()
    local root=pvBlockModalRoot()
    return root~=nil and root.Parent~=nil and root.Visible
end

function pvFindBlockButton()
    local root=pvBlockModalRoot()
    if not root then return nil end
    local label
    for _,data in ipairs(root:GetDescendants()) do
        if data:IsA("TextButton") or data:IsA("TextLabel") then
            local text=tostring(data.Text or ""):lower():gsub("^%s+",""):gsub("%s+$","")
            if text=="block" and data.Visible and data.AbsoluteSize.X>0 then
                if data:IsA("TextButton") then return data end
                local part=data.Parent
                while part and part~=root do
                    if part:IsA("GuiButton") then return part end
                    part=part.Parent
                end
                label=label or data
            end
        end
    end
    -- Text alone is a safe hit target: pressing its centre triggers the
    -- underlying Foundation button even if the button is a wrapper frame.
    return label
end
function pvFindBlockButtonScan() return pvFindBlockButton() end

-- Temporarily hide the *appearance* of the Roblox confirmation without
-- removing GUI nodes or changing Visible / Active. The actual Roblox button
-- must remain present for the working virtual-input click below.
-- Foundation constructs the backdrop before it constructs the text/button
-- subtree. Hiding only BlockingModalScreen in RenderStepped therefore flashes
-- an empty grey card and a dark full-screen scrim for a few frames.
local pvBlockHiddenState=nil
local PV_HIDE_PROPS={"BackgroundTransparency","TextTransparency","TextStrokeTransparency",
                     "ImageTransparency","GroupTransparency","Transparency"}
local PV_BLOCK_VISUAL_NAMES={"scrim","backdrop","dimmer","dimming","blockingmodal",
                             "blockmodal","modaloverlay"}

local function pvBlockIsOurUi(inst)
    local first=inst
    while first do
        local number=first.Name
        if number=="porkVisuals" or number=="porkToggle" or number=="pvBlocked" then return true end
        first=first.Parent
    end
    return false
end

local function pvBlockLooksLikeBackdrop(inst)
    local number=inst.Name:lower()
    for _,part in ipairs(PV_BLOCK_VISUAL_NAMES) do
        if number:find(part,1,true) then return true end
    end
    return false
end

local function pvBlockHideAppearance(state,inst)
    if not state or not inst or pvBlockIsOurUi(inst) then return end
    -- Record and update only properties supported by this class. Don't
    -- create a property-changed signal per property or clone UI objects.
    local props
    if inst:IsA("TextLabel") or inst:IsA("TextButton") or inst:IsA("TextBox") then
        props={"BackgroundTransparency","TextTransparency","TextStrokeTransparency"}
    elseif inst:IsA("ImageLabel") or inst:IsA("ImageButton") then
        props={"BackgroundTransparency","ImageTransparency"}
    elseif inst:IsA("CanvasGroup") then
        props={"BackgroundTransparency","GroupTransparency"}
    elseif inst:IsA("GuiObject") then
        props={"BackgroundTransparency"}
    elseif inst:IsA("UIStroke") then
        props={"Transparency"}
    else
        return
    end
    local cache=state.saved[inst]
    if not cache then cache={};state.saved[inst]=cache end
    -- The hidden Foundation popup must not remain an arrow-key / gamepad
    -- navigation target. Selectable only affects navigation, not virtual
    -- mouse clicks on the real Block button.
    if inst:IsA("GuiObject") and state.modal
       and (inst==state.modal or inst:IsDescendantOf(state.modal)) then
        local navOk,wasSelectable=pcall(function() return inst.Selectable end)
        if navOk and type(wasSelectable)=="boolean" then
            if cache.Selectable==nil then cache.Selectable=wasSelectable end
            if wasSelectable then pcall(function() inst.Selectable=false end) end
        end
    end
    for _,prop in ipairs(props) do
        local success,value=pcall(function() return inst[prop] end)
        if success and type(value)=="number" then
            if cache[prop]==nil then cache[prop]=value end
            if value~=1 then pcall(function() inst[prop]=1 end) end
        end
    end
    -- Foundation animates/repaints its button text, borders and focus ring.
    -- A 0.16-second poll leaves those visuals visible for several frames.
    -- Observe each native modal element once, restoring transparency as
    -- soon as Roblox changes it; this avoids a per-frame descendant scan.
    if not state.watched[inst] then
        state.watched[inst]=true
        state.connections[#state.connections+1]=inst.Changed:Connect(function(prop)
            if pvBlockHiddenState~=state then return end
            if prop=="Selectable" and cache.Selectable~=nil then
                pcall(function()
                    if inst.Selectable then inst.Selectable=false end
                end)
            elseif cache[prop]~=nil then
                pcall(function()
                    if inst[prop]~=1 then inst[prop]=1 end
                end)
            end
        end)
    end
end

local function pvBlockHideBranch(state,root)
    if not root then return end
    pvBlockHideAppearance(state,root)
    for _,data in ipairs(root:GetDescendants()) do
        pvBlockHideAppearance(state,data)
    end
end

local function pvStopHiddenBlock()
    local state=pvBlockHiddenState
    pvBlockHiddenState=nil
    pvBlockingNow=false
    if not state then return end
    -- Release temporary key interception before restoring native GUI state.
    if state.keyAction then
        pcall(function()
            game:GetService("ContextActionService"):UnbindAction(state.keyAction)
        end)
    end
    -- Disconnect change observers BEFORE restoring the real GUI appearance.
    for _,conn in ipairs(state.connections) do pcall(function() conn:Disconnect() end) end
    for inst,props in pairs(state.saved) do
        if inst.Parent then
            for prop,value in pairs(props) do
                pcall(function() inst[prop]=value end)
            end
        end
    end
    -- Restore exactly the navigation settings that were active before this
    -- block attempt. This also runs on failure and on hub cleanup.
    local nav=state.navigation
    if nav and nav.service then
        if nav.guiEnabled~=nil then
            pcall(function() nav.service.GuiNavigationEnabled=nav.guiEnabled end)
        end
        if nav.autoSelect~=nil then
            pcall(function() nav.service.AutoSelectGuiEnabled=nav.autoSelect end)
        end
        -- Re-focus only an old, surviving selection. Never focus the
        -- blocked-player modal that is currently fading out.
        if nav.previousSelection and nav.previousSelection.Parent then
            local fromModal=false
            pcall(function()
                fromModal=(state.modal and nav.previousSelection:IsDescendantOf(state.modal)) or false
            end)
            if not fromModal then
                pcall(function()
                    if nav.service.SelectedObject==nil then
                        nav.service.SelectedObject=nav.previousSelection
                    end
                end)
            end
        end
    end
end
pvSession.addCleanup(function() pcall(pvStopHiddenBlock) end)

function pvHideBlockModal()
    local state=pvBlockHiddenState
    if not state then return end
    local modal=pvBlockModalRoot()
    if modal then
        if state.modal~=modal then
            -- Hide this *small* dialog subtree just once. Newly mounted
            -- descendants are handled by DescendantAdded below.
            state.modal=modal
            pvBlockHideBranch(state,modal)
            local parent=modal.Parent
            local depth=0
            while parent and parent~=state.core and depth<3 do
                if parent:IsA("GuiObject") then pvBlockHideAppearance(state,parent) end
                parent=parent.Parent
                depth+=1
            end
        else
            -- Native animations can repaint the root. One cheap operation;
            -- don't walk all its descendants on each graphics frame.
            pvBlockHideAppearance(state,modal)
        end
    end
    for key in pairs(state.backdrops) do
        if key.Parent then
            pvBlockHideAppearance(state,key)
        else
            state.backdrops[key]=nil
        end
    end
end

local function pvStartHiddenBlock()
    pvStopHiddenBlock()
    local core=game:GetService("CoreGui")
    pvCachedBlockModal=nil
    pvLastBlockModalProbe=-math.huge
    local state={core=core,saved=setmetatable({},{__mode="k"}),
                 backdrops=setmetatable({},{__mode="k"}),
                 watched=setmetatable({},{__mode="k"}),connections={},modal=nil}
    pvBlockHiddenState=state
    pvBlockingNow=true
    -- Roblox's Foundation dialog can handle arrow/Enter/Tab directly even
    -- when GuiService.SelectedObject is cleared. Temporarily swallow only
    -- navigation/confirm keys; mouse clicks are unaffected, so the genuine
    -- native Block button can still be pressed and verified. Restore the
    -- keys immediately when the confirmation finishes.
    state.keyAction="PV_HiddenBlockNavigation"
    pcall(function()
        game:GetService("ContextActionService"):BindActionAtPriority(
            state.keyAction,
            function()
                if pvBlockHiddenState==state then
                    return Enum.ContextActionResult.Sink
                end
                return Enum.ContextActionResult.Pass
            end,
            false, 9999,
            Enum.KeyCode.Up,Enum.KeyCode.Down,
            Enum.KeyCode.Left,Enum.KeyCode.Right,
            Enum.KeyCode.Tab,Enum.KeyCode.Return,
            Enum.KeyCode.KeypadEnter,Enum.KeyCode.Space,
            Enum.KeyCode.ButtonA,Enum.KeyCode.ButtonB,
            Enum.KeyCode.DPadUp,Enum.KeyCode.DPadDown,
            Enum.KeyCode.DPadLeft,Enum.KeyCode.DPadRight
        )
    end)
    -- Hiding a Roblox confirmation visually does not remove keyboard focus.
    -- Disable only default GUI navigation for the brief hidden confirmation,
    -- so arrow keys / D-pad cannot select a still-invisible native button.
    -- Keep mouse input available because the real Block button still needs
    -- to be clicked and verified through Roblox's account block cache.
    local guiServiceService=game:GetService("GuiService")
    local nav={service=guiServiceService}
    state.navigation=nav
    pcall(function() nav.guiEnabled=guiServiceService.GuiNavigationEnabled end)
    pcall(function() nav.autoSelect=guiServiceService.AutoSelectGuiEnabled end)
    pcall(function() nav.previousSelection=guiServiceService.SelectedObject end)
    pcall(function() guiServiceService.GuiNavigationEnabled=false end)
    pcall(function() guiServiceService.AutoSelectGuiEnabled=false end)
    pcall(function() guiServiceService.SelectedObject=nil end)
    -- Native CoreGui may try to re-enable navigation as it mounts its popup;
    -- keep the hidden popup unfocused until this attempt ends.
    state.connections[#state.connections+1]=guiServiceService:GetPropertyChangedSignal("GuiNavigationEnabled"):Connect(function()
        if pvBlockHiddenState==state then
            pcall(function()
                if guiServiceService.GuiNavigationEnabled then guiServiceService.GuiNavigationEnabled=false end
            end)
        end
    end)
    state.connections[#state.connections+1]=guiServiceService:GetPropertyChangedSignal("SelectedObject"):Connect(function()
        if pvBlockHiddenState~=state then return end
        pcall(function()
            local selected=guiServiceService.SelectedObject
            if selected and state.modal and
               (selected==state.modal or selected:IsDescendantOf(state.modal)) then
                guiServiceService.SelectedObject=nil
            end
        end)
    end)
    -- No CoreGui:GetDescendants() startup scan or RenderStepped callback.
    -- Only suppress Foundation block-modal elements as they are attached.
    state.connections[#state.connections+1]=core.DescendantAdded:Connect(function(data)
        if not pvBlockingNow or pvBlockHiddenState~=state or pvBlockIsOurUi(data) then return end
        if data.Name=="BlockingModalScreen" and data:IsA("GuiObject") then
            pvCachedBlockModal=data
            state.modal=data
            pvBlockHideAppearance(state,data)
        elseif pvBlockLooksLikeBackdrop(data) then
            state.backdrops[data]=true
            pvBlockHideAppearance(state,data)
        elseif state.modal and data:IsDescendantOf(state.modal) then
            pvBlockHideAppearance(state,data)
        end
    end)
    -- A low-frequency fallback catches reused native dialog instances or
    -- native style repaints without burning a frame each time.
    task.spawn(function()
        while pvBlockingNow and pvBlockHiddenState==state do
            pcall(pvHideBlockModal)
            task.wait(0.16)
        end
    end)
end

local function pvPressBlockAt(button,method,withInset)
    if not button or not button.Parent then return false end
    local part,z=button.AbsolutePosition,button.AbsoluteSize
    if z.X<1 or z.Y<1 then return false end
    local x,y=part.X+z.X/2,part.Y+z.Y/2
    if withInset then
        local inset=game:GetService("GuiService"):GetGuiInset()
        y=y+inset.Y
    end
    if method=="virtual" then
        local success=pcall(function()
            local vim=game:GetService("VirtualInputManager")
            vim:SendMouseButtonEvent(x,y,0,true,game,1)
            task.wait()
            vim:SendMouseButtonEvent(x,y,0,false,game,1)
        end)
        return success
    elseif method=="executor" then
        local mvValue=(pvAPI and pvAPI.mousemoveabs) or mousemoveabs
        local press=(pvAPI and pvAPI.mouse1press) or mouse1press
        local release=(pvAPI and pvAPI.mouse1release) or mouse1release
        local click=(pvAPI and pvAPI.mouse1click) or mouse1click
        if type(mvValue)~="function" then return false end
        if type(click)~="function" and not (type(press)=="function" and type(release)=="function") then return false end
        return pcall(function()
            mvValue(x,y)
            task.wait()
            if type(press)=="function" and type(release)=="function" then
                press();task.wait();release()
            else
                click()
            end
        end)
    end
    return false
end

function pvClickBlockPrompt(timeout, isBlocked)
    local deadline=os.clock()+(timeout or 4.5)
    local button
    while os.clock()<deadline do
        button=pvFindBlockButton()
        if button and button.Parent and button.AbsoluteSize.X>1 and button.AbsoluteSize.Y>1 then break end
        if type(isBlocked)=="function" and isBlocked() then return true,"verified" end
        task.wait(0.045) -- block confirmation checks capped for lower CPU use
    end
    if not button then return false,"Block button wasn't found" end
    -- Click immediately once Foundation reports a real button hitbox.
    local methods={{"virtual",false},{"virtual",true},{"executor",false},{"executor",true}}
    local sent=false
    for _,variant in ipairs(methods) do
        if not pvBlockDialogOpen() then break end
        button=pvFindBlockButton()
        if not button then break end
        if pvPressBlockAt(button,variant[1],variant[2]) then sent=true end
        local untilTime=os.clock()+0.22
        while os.clock()<untilTime do
            if type(isBlocked)=="function" and isBlocked() then return true,"verified" end
            if not pvBlockDialogOpen() then
                -- Give the account block cache time to update after the modal closes.
                -- Disappearance alone is not proof: Cancel also closes it.
                local cacheDeadline=os.clock()+0.65
                while os.clock()<cacheDeadline do
                    if type(isBlocked)=="function" and isBlocked() then return true,"verified" end
                    task.wait(0.035)
                end
                return nil,"Block confirmation closed; check your blocked users list"
            end
            task.wait(0.02) -- quick account-cache check without a per-frame CoreGui scan
        end
    end
    if type(isBlocked)=="function" and isBlocked() then return true,"verified" end
    if pvBlockDialogOpen() then return false,"Auto-click unavailable; press Block in the Roblox popup" end
    return nil,sent and "Block confirmation closed; check your blocked users list" or "Block modal closed without confirmation"
end

