function pvBlockFailAlert(player, reason)


    if true then return false end
    local url = _G.pvBlockWebhook
    if type(url)~="string" or not url:find("^https?://") or url:find("PASTE_YOUR") then return false end
    local req = (syn and syn.request) or (http and http.request) or http_request or request
        or (fluxus and fluxus.request) or (getgenv and getgenv().request)
    if type(req)~="function" then return false end
    local ping = ""
    local pid = tostring(_G.pvBlockPingId or "")
    if pid:match("^%d+$") then ping = "<@"..pid.."> " end
    local HttpService=game:GetService("HttpService")
    local body=HttpService:JSONEncode({
        username = "porkVisuals",
        content  = ("%s⚠️ **Block failed** — `%s` (id %d) had a problem: %s"):format(
            ping, player.Name, player.UserId, tostring(reason)),
        allowed_mentions = { parse = { "users" } },
    })
    return pcall(function()
        req({ Url=url, Method="POST", Headers={["Content-Type"]="application/json"}, Body=body })
    end)
end
-- Real account blocking uses Roblox's own API. No game RemoteEvent can
-- bypass Roblox's confirmation; auto-press the real button when required.
function autoBlockPlayer(player)
    if not player or not player:IsA("Player") then return false,"invalid player" end
    if player==playerGui then return false,"cannot block yourself" end
    local uid=tonumber(player.UserId)
    if not uid or uid<=0 then return false,"invalid user ID" end
    if _G.pvBlockInProgress then return false,"another block is in progress" end
    _G.pvBlockInProgress=true
    local blockStart=os.clock()
    local function perform()
        local starterGuiService=game:GetService("StarterGui")
        local function contains(ids)
            if type(ids)~="table" then return false end
            for key,id in pairs(ids) do
                if tonumber(id)==uid or (id==true and tonumber(key)==uid) then return true end
            end
            return false
        end
        local blockStatusLastCheck=-math.huge
        local blockStatusCached=false
        local function isBlocked()
            if blockStatusCached then return true end
            local now=os.clock()
            if now-blockStatusLastCheck<0.16 then return false end
            blockStatusLastCheck=now
            local success,ids=pcall(function() return starterGuiService:GetCore("GetBlockedUserIds") end)
            if success and contains(ids) then blockStatusCached=true;return true end
            local util=pvBlockUtil
            if util then
                local yes=false
                pcall(function() yes=util.IsPlayerBlockedByUserId(uid)==true end)
                if yes then blockStatusCached=true;return true end
            end
            return false
        end
        if isBlocked() then return true,"already blocked" end
        -- Fast path for this client: the protected native utility was rejected.
        -- Go straight to the working Roblox popup + automatic real button click.
        -- Account-side confirmation still depends on Roblox, not on this script.
        pvStartHiddenBlock()
        local opened=false
        for _=1,4 do
            local success=pcall(function() starterGuiService:SetCore("PromptBlockPlayer",player) end)
            if success then opened=true;break end
            task.wait(0.05)
        end
        if not opened then return false,"Roblox block confirmation unavailable" end
        local result,reason=pvClickBlockPrompt(4.5,isBlocked)
        if result==true then return true,"verified" end
        -- If the automatic press was rejected, display the real popup so
        -- they can still click Block themselves; don't claim it worked.
        if isBlocked() then return true,"verified" end
        return result,reason
    end
    local success,result,reason=pcall(perform)
    if success and result==true and pvBlockHiddenState then
        -- Don't restore the confirmation's opacity during its exit animation:
        -- an active native modal may linger longer than a fixed 0.4 seconds.
        -- Bound the wait so navigation is always returned promptly.
        local finishingState=pvBlockHiddenState
        task.spawn(function()
            task.wait(0.28)
            local deadline=os.clock()+1.5
            while pvBlockHiddenState==finishingState and
                  os.clock()<deadline and pvBlockDialogOpen() do
                task.wait(0.08)
            end
            if pvBlockHiddenState==finishingState then pvStopHiddenBlock() end
        end)
    else
        -- If automatic blocking failed, restore the visible popup so the
        -- user can still press the real Block confirmation manually.
        pvStopHiddenBlock()
    end
    _G.pvLastBlockMs=math.floor((os.clock()-blockStart)*1000+0.5)
    _G.pvBlockInProgress=false
    if success then
        if result==true then _G.pvBlocked[player.Name]=true end
        return result,reason
    end
    return false,"block attempt error: "..tostring(result)
end

function pvBlockNotice(result,reason,name)
    if result==true then return "Blocked "..tostring(name) end
    if result==nil then return tostring(reason or "Check Roblox's blocked users list") end
    return "Block: "..tostring(reason or "could not complete")
end

function pvBlockViaMenu(player)
    local CoreGui=game:GetService("CoreGui")
    local vim=game:GetService("VirtualInputManager")
    local function txt(gui2)
        local out={}
        local value="" ; pcall(function() value=tostring(gui2.Text or "") end)
        if value~="" then out[#out+1]=value end
        for _,x in ipairs(gui2:GetDescendants()) do
            if x:IsA("TextLabel") then
                local text="" ; pcall(function() text=tostring(x.Text or "") end)
                if text~="" then out[#out+1]=text end
            end
        end
        return table.concat(out,"|")
    end
    local function click(gui2)
        local part,text=gui2.AbsolutePosition,gui2.AbsoluteSize
        if text.X<=0 or text.Y<=0 then return false end
        local x,y=part.X+text.X/2,part.Y+text.Y/2
        vim:SendMouseButtonEvent(x,y,0,true,game,1); task.wait(0.09)
        vim:SendMouseButtonEvent(x,y,0,false,game,1)
        return true
    end
    local function esc()
        vim:SendKeyEvent(true,Enum.KeyCode.Escape,false,game); task.wait(0.1)
        vim:SendKeyEvent(false,Enum.KeyCode.Escape,false,game)
    end
    local success=pcall(function()
        local shield=CoreGui.RobloxGui:FindFirstChild("SettingsClippingShield")

        if not (shield and shield.Visible) then esc(); task.wait(1.6) end
        local hub=CoreGui.RobloxGui.SettingsClippingShield.SettingsShield.MenuContainer
        local ptValue=hub.Page.HubBar.TabHeaderContainer.HubBarContainer:FindFirstChild("PeopleTab")
        if ptValue then click(ptValue); task.wait(1.6) end
        local ppValue=hub.Page.PageViewClipper.PageView.PageViewInnerFrame:FindFirstChild("peoplepage")
        if not ppValue then return end
        local want=tostring(player.Name):lower()
        local row
        for _,data in ipairs(ppValue:GetDescendants()) do
            local okv,vis=pcall(function() return data.Visible end)
            if data:IsA("GuiButton") and okv and vis and txt(data):lower():find(want,1,true) then
                row=data break
            end
        end
        if not row then return end
        click(row); task.wait(1.4)
        local button=pvFindBlockButton()
        if button then pvFireButton(button); task.wait(0.5) end
        esc()
    end)
    return success
end

function pvResolvePlayer(who)
    local player=Players:FindFirstChild(who)
    if player then return player end
    local want=tostring(who):lower()
    for _,part in ipairs(Players:GetPlayers()) do
        if part.Name:lower()==want or tostring(part.DisplayName):lower()==want then return part end
    end
end

