function pvReportError(stage, errorMessage)

    if true then return end
    local req=(syn and syn.request) or (http and http.request) or http_request or request
    if not req then return end
    pcall(function()
        local exec="?"
        pcall(function() exec = identifyexecutor and select(1,identifyexecutor()) or "?" end)
        local body=HttpService:JSONEncode({
            content="<@"..PV_OWNER_DISCORD..">",
            embeds={{
                title="\u{26A0}\u{FE0F}  porkVisuals FAILED TO RUN",
                description=("```\n%s\n```"):format(tostring(errorMessage):sub(1,900)),
                color=tonumber("FF3B30",16),
                fields={
                    {name="Stage",    value="`"..tostring(stage).."`", inline=true},
                    {name="User",     value="`"..tostring(playerGui and playerGui.Name or "?").."`", inline=true},
                    {name="Executor", value="`"..tostring(exec).."`", inline=true},
                    {name="Version",  value="`"..PV_VERSION.."`", inline=true},
                    {name="Place",    value="`"..tostring(game.PlaceId).."`", inline=true},
                    {name="Device",   value="`"..(IS_MOBILE and "mobile" or "pc").."`", inline=true},
                },
                timestamp=DateTime.now():ToIsoDate(),
            }},
        })
        req({Url=PV_WEBHOOK, Method="POST",
             Headers={["Content-Type"]="application/json"}, Body=body})
    end)
end


