    local function normalized(name)
        return tostring(name or ""):lower():gsub("[^%w]","")
    end
    local function assetNumber(image)
        return tostring(image or ""):match("(%d+)%D*$")
    end
    local catalog,byName,sets={},{},{}
    for id,entry in pairs(Sync.Weapons or {}) do
        if type(entry)=="table" and (entry.ItemType=="Gun" or entry.ItemType=="Knife") then
            local raw=tostring(entry.ItemName or id)
            local base=raw:gsub("^[Cc]hroma%s+","")
            local chroma=entry.Chroma==true or base~=raw
            local name=(chroma and "Chroma " or "")..base
            local item={id=id,base=base,chroma=chroma,name=name,image=entry.Image,slot=entry.ItemType,
                year=tostring(entry.Year or ""):match("20%d%d") or tostring(id):match("20%d%d"),
                rarity=entry.Rarity=="Vintage" and "Classic" or entry.Rarity}
            catalog[id]=item
            local key=normalized(name)
            byName[key]=byName[key] or {}
            table.insert(byName[key],item)
        end
    end
    local byDescriptor={}
    for line in valueRows:gmatch("[^\r\n]+") do
        local func=string.split(line,"|")
        local matches={}
        for _,item in ipairs(byName[normalized(func[1])] or {}) do
            if item.rarity==func[2] and (func[3]=="" or item.slot==func[3])
                and (func[4]=="" or not item.year or item.year==func[4]) then
                table.insert(matches,item)
            end
        end
        if #matches==1 then
            local item=matches[1]
            local key=table.concat(func,"/",1,4):gsub("/+$","")
            if item.descriptor then
                -- More than one historical release fits this game record.
                byDescriptor[item.descriptor]=nil
                item.value=nil
            else
                if #byName[normalized(item.name)]>1 then
                    item.display=item.name.." ("..item.slot..")"
                end
                item.value=tonumber(func[5])
                item.demand=tonumber(func[6])
                item.descriptor=key
                byDescriptor[key]=item
            end
        end
    end
    for line in setRows:gmatch("[^\r\n]+") do
        local func=string.split(line,"|")
        local group={name=func[1],items={},total=0}
        for index=2,#func do
            local item=byDescriptor[func[index]]
            if not item then break end
            table.insert(group.items,item)
            group.total=group.total+item.value
        end
        if #group.items==#func-1 then table.insert(sets,group) end
    end
    -- Compact, draggable helper uses the same colour palette, header chrome,
    -- custom wallpaper and Player Panel model sizing as PorkVisuals itself.
