    gui.ZIndexBehavior=Enum.ZIndexBehavior.Sibling
    gui.DisplayOrder=1000100
    gui.Parent=playerGui2
    pvSession.ownRoot(gui)

    local helperW,helperH=pxValue(244),pxValue(242)
