    local helperSnowflakes={}
    do
        local atlas = pvSession.getChristmasSnowAtlas and pvSession.getChristmasSnowAtlas() or nil
        local rng = Random.new(2401)
        local function addHelperFlake(size, alpha, x, y, speed, spin, phase, variant)
            local imageLabel=Instance.new("ImageLabel")
            imageLabel.Name="ChristmasSnowflake"
            imageLabel.BackgroundTransparency=1
            imageLabel.BorderSizePixel=0
            imageLabel.AnchorPoint=Vector2.new(.5,.5)
            imageLabel.Size=UDim2.fromOffset(size,size)
            imageLabel.Position=UDim2.fromScale(x,y)
            imageLabel.ZIndex=3
            imageLabel.ImageTransparency=alpha
            if atlas then
                imageLabel.Image=atlas
                imageLabel.ImageRectOffset=Vector2.new(128*variant,0)
                imageLabel.ImageRectSize=Vector2.new(128,128)
            end
            imageLabel.Parent=helperSnowLayer
            helperSnowflakes[#helperSnowflakes+1]={f=imageLabel,x=x,y=y,size=size,alpha=alpha,phase=phase,speed=speed,spin=spin,rotation=rng:NextNumber(0,360)}
        end
        -- Full-height field: six interior rows plus five rows along both gutters.
        -- Keep the snow behind text and cards; the footer gets its own coverage.
        for index=1,28 do
            local edge=index>18
            local size=pxValue(edge and rng:NextNumber(9,14) or rng:NextNumber(12,20))
            local x,y
            if edge then
                local jValue=index-19
                x=(jValue%2==0 and .045 or .955)+rng:NextNumber(-.004,.004)
                y=.14+math.floor(jValue/2)*.19+rng:NextNumber(-.012,.012)
            else
                local jValue=index-1
                local col,row=jValue%3,math.floor(jValue/3)
                x=.19+col*.31+rng:NextNumber(-.035,.035)
                y=.075+row*.172+rng:NextNumber(-.014,.014)
            end
            addHelperFlake(size, edge and rng:NextNumber(.38,.55) or rng:NextNumber(.22,.43), x, y, rng:NextNumber(.20,.50), rng:NextNumber(4,12)*((index%2==0) and 1 or -1), rng:NextNumber(0,math.pi*2), (index-1)%4)
        end
    end

    do
        local RunService=game:GetService("RunService")
        local helperSnowElapsed,helperSnowAccum=0,0
        pvSession.connect(RunService.Heartbeat,function(dtValue)
            if settings.uiTheme~="Christmas" or not helperSnowLayer.Visible or not card.Visible or not card.Parent then helperSnowAccum=0 return end
            helperSnowAccum=helperSnowAccum+math.min(dtValue,.1)
            if helperSnowAccum<1/30 then return end
            local step=helperSnowAccum
            helperSnowAccum=0
            helperSnowElapsed=helperSnowElapsed+step
            for _,flake in ipairs(helperSnowflakes) do
                local phase=helperSnowElapsed*flake.speed+flake.phase
                local x=flake.x+0.018*math.sin(phase)
                local y=flake.y+0.026*math.sin(phase*.72+flake.phase)
                local dim=card.AbsoluteSize
                local number=math.min(.47,(flake.size*.72+3)/math.max(1,dim.X))
                local number2=math.min(.47,(flake.size*.72+3)/math.max(1,dim.Y))
                flake.f.Position=UDim2.fromScale(math.clamp(x,number,1-number),math.clamp(y,number2,1-number2))
                flake.f.Rotation=(flake.rotation+helperSnowElapsed*flake.spin)%360
                flake.f.ImageTransparency=math.clamp(flake.alpha+.12*math.sin(phase*1.5),0,1)
            end
        end)
    end

