    -- Display this script's existing USD estimates. Supreme points remain the
    -- separate input to chooseReturn; there is no fixed points-to-dollar rate.
    local function usdPrice(item)
        local prices
        if item.chroma then prices=PV_VALUES_CHROMA else prices=PV_VALUES end
        local value=prices and tonumber(prices[item.base])
        if value and value>0 and value<math.huge then return value end
        return nil
    end
    local function usdText(value)
        return value and string.format("$%.2f",value) or "USD unavailable"
    end
    local function usdTotal(items)
        local total=0
        for _,item in ipairs(items) do
            local price=usdPrice(item)
            if not price then return nil end
            total=total+price
        end
        return total
    end
    local function updateSummary(partner,offer,target)
        local cleanName=tostring(partner or "Unknown player"):gsub("[%c]"," "):gsub("^%s+",""):gsub("%s+$","")
