    local function showReturnModels(best,setName)
        clearReturnModels()
        -- Record exactly the weapons shown in the most recent suggestion.
        -- Matching ANY one of these in YOUR sent offer qualifies for success.
        suggestedItemIds={}
        for _,item in ipairs(best) do
            suggestedItemIds[tostring(item.id)]=true
        end
        suggestedTiles.Visible=true
        suggestionHeading.Text=setName and ("SUGGESTED RETURN  ·  "..setName) or "SUGGESTED RETURN"
        returnTotal.Text="RETURN TOTAL  "..usdText(usdTotal(best))
        returnTotal.Visible=true
        local count=#best
        local compact=count>2
        for index=1,count do
            local item=best[index]
            local tile=Instance.new("Frame")
            tile.Name="ReturnWeapon_"..index
            local columns=count==1 and 1 or 2
            local rows=compact and 2 or 1
            tile.Size=UDim2.new(1/columns,-pxValue(2),1/rows,compact and -pxValue(1) or 0)
            tile.Position=UDim2.new(((index-1)%columns)/columns,pxValue(1),math.floor((index-1)/columns)/rows,0)
            tile.BorderSizePixel=0
            tile.ZIndex=6
            tile.Parent=suggestedTiles
            corner(tile,pxValue(6))
            local tileStroke=stroke(tile,0.62,1,TValue.line)

            local preview=Instance.new("Frame")
            preview.Name="WeaponPreview"
            preview.AnchorPoint=Vector2.new(0.5,0)
            preview.Position=UDim2.new(0.5,0,0,pxValue(2))
            preview.Size=UDim2.fromOffset(pxValue(46),pxValue(38))
            if compact then
                preview.AnchorPoint=Vector2.new(0,0.5)
                preview.Position=UDim2.new(0,pxValue(2),0.5,0)
                preview.Size=UDim2.fromOffset(pxValue(28),pxValue(30))
            end
            preview.BackgroundTransparency=1
            preview.ClipsDescendants=true
            preview.ZIndex=7
            preview.Parent=tile
            preview:SetAttribute("pvHelperWeaponPreview",true)

            local icon=Instance.new("ImageLabel")
            icon.Name="WeaponIcon"
            icon.Size=UDim2.fromScale(1,1)
            icon.BackgroundTransparency=1
            icon.ScaleType=Enum.ScaleType.Fit
            icon.ZIndex=7
            icon.Parent=preview
            pcall(function() icon.Image=resolveImg(item.id,item.image) end)

            local name=Instance.new("TextLabel")
            name.Name="WeaponName"
            name.Position=UDim2.new(0,pxValue(2),0,pxValue(42))
            name.Size=UDim2.new(1,-pxValue(4),0,pxValue(13))
            name.BackgroundTransparency=1
            if compact then
                name.Position=UDim2.fromOffset(pxValue(32),pxValue(2))
                name.Size=UDim2.new(1,-pxValue(34),0,pxValue(19))
                name.TextWrapped=true
            end
            name.Text=item.display or item.name
            name.TextSize=pxValue(8)
            name.Font=Enum.Font.GothamBold
            name.TextTruncate=Enum.TextTruncate.AtEnd
            name.ZIndex=7
            name.Parent=tile

            local price=Instance.new("TextLabel")
            price.Name="USDPrice"
            price.Position=UDim2.new(0,pxValue(2),0,pxValue(56))
            price.Size=UDim2.new(1,-pxValue(4),0,pxValue(13))
            price.BackgroundTransparency=1
            price.Text=usdText(usdPrice(item))
            if compact then
                price.Position=UDim2.fromOffset(pxValue(32),pxValue(21))
                price.Size=UDim2.new(1,-pxValue(34),0,pxValue(10))
            end
            price.TextSize=pxValue(9)
            price.Font=Enum.Font.GothamBold
            price.ZIndex=7
            price.Parent=tile

            tileStyles[#tileStyles+1]={tile=tile,edge=tileStroke,name=name,price=price}
        end
        if type(pvSession.refreshUpgradeHelperTheme)=="function" then
            pvSession.refreshUpgradeHelperTheme()
        end
    end

