    local function syncWallpaper()
        if not card.Parent then return end
        local custom=settings.uiTheme=="Custom"
        local usePicture,useVideo=false,false
        pcall(function()
            if srcPicture then
                wallpaper.Image=srcPicture.Image
                usePicture=custom and srcPicture.Visible
            end
            if srcVideo then
                wallpaperVideo.Video=srcVideo.Video
                useVideo=custom and srcVideo.Visible
            end
        end)
        wallpaper.Visible=usePicture and true or false
        wallpaperVideo.Visible=useVideo and true or false
        wallpaperDim.Visible=wallpaper.Visible or wallpaperVideo.Visible
        pcall(function() wallpaperVideo.Playing=wallpaperVideo.Visible and card.Visible end)
    end

    local function refreshTheme()
        if not card.Parent then return end
        local halloween=settings.uiTheme=="Halloween"
        local christmas=settings.uiTheme=="Christmas"
        local accent=TValue.pink
        backGradient.Color=helperGradientColor()
        rim.Color=accent
        rimDepth.Enabled=halloween
        brand.TextColor3=accent
        -- Match the main header Discord tag in every theme (Pork UI / Halloween / Custom).
        tag.TextColor3=christmas and Color3.fromRGB(255,230,166) or (halloween and Color3.fromRGB(255,206,128) or Color3.fromRGB(255,140,205))
        close.TextColor3=halloween and Color3.fromRGB(255,173,80) or accent
        headerLine.BackgroundColor3=accent
        title.TextColor3=TValue.txt
        summaryCard.BackgroundColor3=TValue.pane
        summaryCard.BackgroundTransparency=christmas and 0.38 or 0.25
        summaryEdge.Color=TValue.line
        withLabel.TextColor3=TValue.sub
        partnerName.TextColor3=TValue.txt
        offerLabel.TextColor3=TValue.sub
        offerValue.TextColor3=TValue.txt
        targetLabel.TextColor3=TValue.sub
        targetValue.TextColor3=accent
        summaryRule.BackgroundColor3=TValue.line
        statDivider.BackgroundColor3=TValue.line
        suggestionHeading.TextColor3=accent
        -- Success remains a green status regardless of the active theme.
        returnTotal.TextColor3=TValue.txt
        notice.TextColor3=TValue.sub
        for _,entry in ipairs(tileStyles) do
            entry.tile.BackgroundColor3=TValue.pane
            entry.tile.BackgroundTransparency=christmas and 0.34 or 0.08
            entry.edge.Color=TValue.line
            entry.name.TextColor3=TValue.txt
            entry.price.TextColor3=accent
        end
        local christmasImage=""
        pcall(function()
            if srcChristmasPicture and srcChristmasPicture:IsA("ImageLabel") then christmasImage=srcChristmasPicture.Image end
        end)
        christmasWallpaper.Image=christmasImage
        christmasWallpaper.Visible=christmas and christmasImage~=""
        christmasDim.Visible=christmas
        helperSnowLayer.Visible=christmas
        for _,ornament in ipairs(decorations) do ornament.Visible=halloween end
        syncWallpaper()
    end
    pvSession.refreshUpgradeHelperTheme=refreshTheme
    refreshTheme()

