    -- Drag from the top bar on desktop or touch. Save the last position.
    local function moveHelper(x,y)
        local camera=workspace.CurrentCamera
        local viewport=camera and camera.ViewportSize or Vector2.new(1280,720)
        x=math.clamp(x,pxValue(4),math.max(pxValue(4),viewport.X-helperW-pxValue(4)))
        y=math.clamp(y,pxValue(4),math.max(pxValue(4),viewport.Y-helperH-pxValue(4)))
        card.Position=UDim2.fromOffset(x,y)
    end
    if type(settings.upgradeHelperPos)=="table" then
        local savedX=tonumber(settings.upgradeHelperPos[1])
        local savedY=tonumber(settings.upgradeHelperPos[2])
        if savedX and savedY then task.defer(function()
            if card.Parent then moveHelper(savedX,savedY) end
        end) end
    end
    local dragging=false
    local dragInput,dragOrigin,windowOrigin
    pvSession.connect(dragBar.InputBegan,function(input)
        if input.UserInputType~=Enum.UserInputType.MouseButton1
            and input.UserInputType~=Enum.UserInputType.Touch then return end
        dragging=true
        dragInput=input.UserInputType==Enum.UserInputType.Touch and input or nil
        dragOrigin=input.Position
        windowOrigin=card.AbsolutePosition
    end)
    pvSession.connect(UIS.InputChanged,function(input)
        if not dragging then return end
        if dragInput then
            if input~=dragInput then return end
        elseif input.UserInputType~=Enum.UserInputType.MouseMovement then return end
        local delta=input.Position-dragOrigin
        moveHelper(windowOrigin.X+delta.X,windowOrigin.Y+delta.Y)
    end)
    pvSession.connect(UIS.InputEnded,function(input)
        if not dragging then return end
        if dragInput and input~=dragInput then return end
        if not dragInput and input.UserInputType~=Enum.UserInputType.MouseButton1 then return end
        dragging=false
        dragInput=nil
        local pos=card.AbsolutePosition
        settings.upgradeHelperPos={math.floor(pos.X+0.5),math.floor(pos.Y+0.5)}
        saveCfg()
    end)
    -- Keep an earned recommendation visible even after the incoming trade
    -- closes. Only a confirmed trade where WE send a suggested item completes it.
    local pendingSuggestion=false
    local lastSignature=nil
    local searchToken=0
    local wasEnabled=false
    local lastTradeGui=nil
    local lastGuiWasOpen=false
    pvSession.connect(close.Activated,function()
        searchToken=searchToken+1
        pendingSuggestion=false
        suggestedItemIds={}
        clearReturnModels()
        card.Visible=false
    end)
