    successLayer.ZIndex=70
    successLayer.Parent=card
    corner(successLayer,pxValue(12))
    local successGradient=Instance.new("UIGradient")
    successGradient.Rotation=90
    successGradient.Color=ColorSequence.new({
        ColorSequenceKeypoint.new(0,Color3.fromRGB(19,37,29)),
        ColorSequenceKeypoint.new(1,Color3.fromRGB(12,23,19))
    })
    successGradient.Parent=successLayer

    local successBrand=Instance.new("TextLabel")
    successBrand.Name="SuccessBrand"
    successBrand.Position=UDim2.fromOffset(pxValue(12),pxValue(17))
    successBrand.Size=UDim2.new(1,-pxValue(24),0,pxValue(18))
    successBrand.BackgroundTransparency=1
    successBrand.Text="porkVisuals"
    successBrand.Font=Enum.Font.GothamBold
    successBrand.TextSize=pxValue(13)
    successBrand.TextColor3=Color3.fromRGB(172,230,189)
    successBrand.ZIndex=71
    successBrand.Parent=successLayer

    -- One bold glyph instead of two misaligned bars; no gap in the checkmark.
    local checkBadge=Instance.new("Frame")
    checkBadge.Name="GreenCheckmark"
    checkBadge.AnchorPoint=Vector2.new(0.5,0)
    checkBadge.Position=UDim2.new(0.5,0,0,pxValue(62))
    checkBadge.Size=UDim2.fromOffset(pxValue(76),pxValue(76))
    checkBadge.BackgroundColor3=Color3.fromRGB(46,201,107)
    checkBadge.BackgroundTransparency=0
    checkBadge.BorderSizePixel=0
    checkBadge.ZIndex=72
    checkBadge.Parent=successLayer
    corner(checkBadge,pxValue(100))
    stroke(checkBadge,0.62,pxValue(2),Color3.fromRGB(196,255,209))
    local checkScale=Instance.new("UIScale")
    checkScale.Scale=1
    checkScale.Parent=checkBadge

    local checkMark=Instance.new("TextLabel")
    checkMark.Name="SolidCheckmark"
    checkMark.BackgroundTransparency=1
    checkMark.Position=UDim2.fromOffset(0,-pxValue(1))
    checkMark.Size=UDim2.fromScale(1,1)
    checkMark.Text="✔"
    checkMark.Font=Enum.Font.GothamBold
    checkMark.TextSize=pxValue(53)
    checkMark.TextColor3=Color3.fromRGB(255,255,255)
    checkMark.TextXAlignment=Enum.TextXAlignment.Center
    checkMark.TextYAlignment=Enum.TextYAlignment.Center
    checkMark.ZIndex=73
    checkMark.Parent=checkBadge

    local successTitle=Instance.new("TextLabel")
    successTitle.Name="TradeCompletedTitle"
    successTitle.Position=UDim2.fromOffset(pxValue(8),pxValue(155))
    successTitle.Size=UDim2.new(1,-pxValue(16),0,pxValue(23))
    successTitle.BackgroundTransparency=1
    successTitle.Text="TRADE COMPLETED"
    successTitle.TextColor3=Color3.fromRGB(113,252,161)
    successTitle.Font=Enum.Font.GothamBold
    successTitle.TextSize=pxValue(13)
    successTitle.TextScaled=false
    successTitle.TextWrapped=false
    successTitle.TextTruncate=Enum.TextTruncate.AtEnd
    successTitle.ZIndex=72
    successTitle.Parent=successLayer

    local successCaption=Instance.new("TextLabel")
    successCaption.Name="TradeCompletedCaption"
    successCaption.Position=UDim2.fromOffset(pxValue(12),pxValue(186))
    successCaption.Size=UDim2.new(1,-pxValue(24),0,pxValue(23))
    successCaption.BackgroundTransparency=1
    successCaption.Text="Suggested weapon sent"
    successCaption.TextColor3=Color3.fromRGB(187,216,193)
    successCaption.Font=Enum.Font.Gotham
    successCaption.TextSize=pxValue(10)
    successCaption.TextWrapped=true
    successCaption.ZIndex=72
    successCaption.Parent=successLayer

    -- Our side of the trade (not TheirOffer). Read visible game trade slots;
    -- keep a final snapshot because the real GUI may close before the
    -- AcceptTrade success event reaches this script.
    local function readRealSentItems(tradeGui)
        local target=tradeGui or pvRealTradeGui()
        if not target or not target.Enabled then return nil end
        local success,side=pcall(function() return target.Container.Trade.YourOffer end)
        if not success or not side then return nil end
        local container=side:FindFirstChild("Container")
        if not container then return nil end
        local rows={}
        for index=1,4 do
            local slot=container:FindFirstChild("NewItem"..index)
            if slot and slot.Visible then
                local holder=slot:FindFirstChild("ItemName")
                local label=holder and holder:FindFirstChild("Label")
                local name=label and tostring(label.Text) or ""
                if name~="" and name~="Loading" then
                    local tags={}
                    local tagFrame=slot:FindFirstChild("Tags")
                    if tagFrame then
                        for _,tag in ipairs(tagFrame:GetChildren()) do
                            if tag:IsA("GuiObject") and tag.Visible then
                                tags[#tags+1]=tag.Name
                            end
                        end
                    end
                    local amount=1
                    local inner=slot:FindFirstChild("Container")
                    local amountLabel=(inner and inner:FindFirstChild("Amount"))
                        or slot:FindFirstChild("Amount",true)
                    if amountLabel and amountLabel:IsA("TextLabel") then
                        amount=tonumber(tostring(amountLabel.Text):match("%d+")) or 1
                    end
                    local icon=slot:FindFirstChild("Icon",true)
                    rows[#rows+1]={name=name,tags=tags,amount=amount,
                        image=icon and icon:IsA("ImageLabel") and icon.Image or nil}
                end
            end
        end
        return rows
    end

    -- Resolved using the SAME catalog/Chroma distinction as recommendations.
    local resolve
    local function includesSuggestedSentItem(sent)
        if type(sent)~="table" then return false end
        for _,row in ipairs(sent) do
            if type(row)=="table" then
                -- The visual trade keeps exact IDs; real trade slots expose
                -- names and Chroma tags instead.
                if row.id and suggestedItemIds[tostring(row.id)] then return true end
                local item=resolve and resolve(row)
                if item then
                    if (not row.id or tostring(row.id)==tostring(item.id))
                        and suggestedItemIds[tostring(item.id)] then
                        return true
                    end
                end
            end
        end
        return false
    end

    pvSession.showUpgradeTradeSuccess=function(mode,outgoingItems)
        if not isCurrent() or not settings.upgradeValueHelper then return end
        if completionActive or completionHold then return end
        -- The other player's accepted/received items are NOT enough.
        -- A pending suggested return survives an incoming-only trade and can
        -- complete on a later trade after we actually give a suggested item.
        if not pendingSuggestion or not next(suggestedItemIds) then return end

        -- Incoming items are NEVER sufficient. Require at least one weapon
        -- listed in Suggested Return to be on OUR outgoing side when done.
        if mode=="Visual trade" then
            -- Snapshot provided by the visual completion handler BEFORE it
            -- clears the outgoing-offer table.
            if not includesSuggestedSentItem(outgoingItems) then return end
        elseif mode=="Real trade" then
            -- Prefer the final live outgoing slots; otherwise use the most
            -- recent snapshot taken while the real trade GUI was visible.
            local live=readRealSentItems()
            if live then
                lastRealSent=live
                lastRealSentAt=os.clock()
            elseif os.clock()-lastRealSentAt>4 then
                return
            end
            if not includesSuggestedSentItem(lastRealSent) then return end
        else
            return
        end
        pendingSuggestion=false
        completionActive=true
        completionHold=true
        completionToken=completionToken+1
        local token=completionToken
        lastSignature=nil

        -- The overlay is opaque from the FIRST frame: no old tiles or labels
        -- bleed through while the completed state is appearing.
        successTitle.Text=mode=="Visual trade"
            and "VISUAL TRADE COMPLETED" or "TRADE COMPLETED"
        successCaption.Text=mode=="Visual trade"
            and "Suggested weapon sent in visual trade"
            or "Suggested weapon sent successfully"
        successLayer.Visible=true
        card.Visible=true

        -- Only the badge pops. Never scale or fade the entire helper window.
        checkScale.Scale=0.72
        Tween:Create(checkScale,
            TweenInfo.new(0.29,Enum.EasingStyle.Back,Enum.EasingDirection.Out),
            {Scale=1.06}):Play()
        task.delay(0.30,function()
            if not isCurrent() or completionToken~=token then return end
            Tween:Create(checkScale,TweenInfo.new(0.12,Enum.EasingStyle.Quad),
                {Scale=1}):Play()
        end)

        -- Close cleanly with no shrinking/fading; keep the suggestion hidden.
        task.delay(1.85,function()
            if not isCurrent() or completionToken~=token then return end
            card.Visible=false
            successLayer.Visible=false
            checkScale.Scale=1
            completionActive=false
            clearReturnModels()
        end)
    end
    pvSession.addCleanup(function()
        completionToken=completionToken+1
        pvSession.showUpgradeTradeSuccess=nil
    end)

    resolve=function(row)
        if row.id then return catalog[row.id] end
        local name=tostring(row.name or "")
        local base=name:gsub("^[Cc]hroma%s+","")
        local chroma=base~=name
        for _,tag in ipairs(row.tags or {}) do
            if tostring(tag):lower()=="chroma" then chroma=true end
        end
        local items=byName[normalized((chroma and "Chroma " or "")..base)]
        if not items then return nil end
        if #items==1 then return items[1] end
        local image=assetNumber(row.image)
        if not image then return nil end
        local match
        for _,item in ipairs(items) do
            if assetNumber(item.image)==image then
                if match then return nil end
                match=item
            end
        end
        return match
    end
    -- Each generic return uses distinct Godlies, Ancients, or Corrupt. Compare
    -- singles and pairs as blocks so a four-slot search never enumerates quartets.
    local function eligibleReturn(item)
        return item.value and item.value>0 and
            (item.rarity=="Godly" or item.rarity=="Ancient"
                or (item.rarity=="Unique" and item.base=="Corrupt"))
    end
    local function priceCents(item)
        local price=usdPrice(item)
        return price and math.floor(price*100+0.5) or nil
    end
    local function chooseReturn(goal,incoming,targetCents,checkpoint)
        local best,bestScore,bestLabel,bestTotal=nil,math.huge,nil,0
        local bestCount=math.huge
        local expanded=false
        local bestCents=math.huge
        local function bundleCents(items)
            local cents=0
            for _,item in ipairs(items) do
                local price=priceCents(item)
                if not eligibleReturn(item) or not price then return nil end
                cents=cents+price
            end
            return cents
        end
        local minimumSetCents=math.ceil(targetCents*97/100)
        local minimumSetValue=goal*97/100
        local function consider(first,button,total,bonus,label,wholeSet)
            local aCents,bCents=bundleCents(first),bundleCents(button)
            if not aCents or not bCents then return false end
            local cents=aCents+bCents
            -- Suggestions with adds and generic combinations must reach both targets.
            local requiredCents=wholeSet and minimumSetCents or targetCents
            local requiredValue=wholeSet and minimumSetValue or goal
            if cents<requiredCents or total<requiredValue then return false end
            local count=#first+#button
            local score=(total-goal)/goal+0.012*(count-1)-bonus
            if count>bestCount or (count==bestCount and
                (cents>bestCents or (cents==bestCents and score>=bestScore))) then
                return true
            end
            local result={}
            for _,item in ipairs(first) do table.insert(result,item) end
            for _,item in ipairs(button) do table.insert(result,item) end
            best,bestScore,bestLabel,bestTotal=result,score,label,total
            bestCount,bestCents=count,cents
            return true
        end
        local empty={}
        local ceiling=goal*1.15
        -- Match sets against every incoming slot. The most valuable offered
        -- component(s) determine which set to complete when several apply.
        local relatedSets={}
        for _,group in ipairs(sets) do
            local contribution=0
            for _,item in ipairs(group.items) do
                contribution=contribution+item.value*(incoming[item.id] or 0)
            end
            if contribution>0 then
                local cents=bundleCents(group.items)
                if cents then
                    table.insert(relatedSets,{group=group,contribution=contribution,cents=cents})
                end
            end
        end
        table.sort(relatedSets,function(first,button)
            if first.contribution~=button.contribution then return first.contribution>button.contribution end
            if #first.group.items~=#button.group.items then return #first.group.items<#button.group.items end
            if first.group.total~=button.group.total then return first.group.total<button.group.total end
            return first.group.name<button.group.name
        end)
        -- A complete matching set can fall 3% short of either 2x target.
        -- Test it before searching for individual adds.
        for _,entry in ipairs(relatedSets) do
            local group=entry.group
            if entry.cents>=minimumSetCents and group.total>=minimumSetValue
                and group.total<=ceiling then
                return group.items,group.total,group.name
            end
        end
        local pool={}
        for id,item in pairs(catalog) do
            if eligibleReturn(item) and priceCents(item) and not incoming[id] then
                table.insert(pool,item)
            end
        end
        if #pool==0 then
            for _,item in pairs(catalog) do
                if eligibleReturn(item) and priceCents(item) then table.insert(pool,item) end
            end
        end
        table.sort(pool,function(first,button)
            if first.value~=button.value then return first.value<button.value end
            if first.demand~=button.demand then return first.demand>button.demand end
            return tostring(first.id)<tostring(button.id)
        end)
        -- Keep all USD variants even when their Supreme values are equal.
        local singles,pairsByValue={},{}
        for _,item in ipairs(pool) do
            table.insert(singles,{item,total=item.value,cents=priceCents(item)})
        end
        table.sort(singles,function(first,button)
            if first.cents~=button.cents then return first.cents<button.cents end
            if first.total~=button.total then return first.total<button.total end
            return tostring(first[1].id)<tostring(button[1].id)
        end)
        -- For fixed a, the b items already run in price/value/order sequence.
        -- Merge those sorted runs incrementally so sorting can yield between frames.
        local runs={}
        local order=0
        for index,single in ipairs(singles) do
            local run={}
            for jValue=index+1,#singles do
                checkpoint()
                local button=singles[jValue]
                order=order+1
                run[#run+1]={single[1],button[1],total=single.total+button.total,cents=single.cents+button.cents,order=order}
            end
            if #run>0 then runs[#runs+1]=run end
        end
        local function before(first,button)
            if first.cents~=button.cents then return first.cents<button.cents end
            if first.total~=button.total then return first.total<button.total end
            return first.order<button.order
        end
        while #runs>1 do
            local merged={}
            for index=1,#runs,2 do
                local left,right=runs[index],runs[index+1]
                if right then
                    local run={}
                    local layout,result=1,1
                    while layout<=#left or result<=#right do
                        checkpoint()
                        if result>#right or (layout<=#left and before(left[layout],right[result])) then
                            run[#run+1]=left[layout]
                            layout=layout+1
                        else
                            run[#run+1]=right[result]
                            result=result+1
                        end
                    end
                    merged[#merged+1]=run
                else
                    merged[#merged+1]=left
                end
            end
            runs=merged
        end
        pairsByValue=runs[1] or {}
        -- Suffix maxima skip blocks that cannot reach the Supreme floor.
        for _,blocks in ipairs({singles,pairsByValue}) do
            local maximum=0
            for index=#blocks,1,-1 do
                checkpoint()
                maximum=math.max(maximum,blocks[index].total)
                blocks[index].maxTotal=maximum
            end
        end
        local function fits(first,button)
            for _,item in ipairs(first) do
                if item==button[1] or item==button[2] then return false end
            end
            return true
        end
        -- Blocks are ordered by USD, then Supreme. Find the smallest USD
        -- overpay that also passes the Supreme range and distinct-item checks.
        local function complete(prefix,subtotal,blocks,bonus,label)
            checkpoint()
            if #blocks==0 or #prefix+#blocks[1]>bestCount then return end
            local prefixCents=bundleCents(prefix)
            if not prefixCents then return end
            local loValue,hiValue=1,#blocks+1
            while loValue<hiValue do
                local mid=math.floor((loValue+hiValue)/2)
                if prefixCents+blocks[mid].cents<targetCents then loValue=mid+1 else hiValue=mid end
            end
            for index=loValue,#blocks do
                checkpoint()
                local button=blocks[index]
                local total=subtotal+button.total
                if subtotal+button.maxTotal<goal then break end
                if total>=goal and (expanded or total<=ceiling) and fits(prefix,button)
                    and consider(prefix,button,total,bonus,label) then
                    break
                end
            end
        end
        local function searchSet(group,bonus)
            if not expanded and group.total>ceiling then return end
            consider(group.items,empty,group.total,bonus+0.01,group.name,true)
            local label=group.name.." + adds"
            if #group.items<4 then complete(group.items,group.total,singles,bonus,label) end
            if #group.items<=2 then complete(group.items,group.total,pairsByValue,bonus,label) end
        end
        for _,entry in ipairs(relatedSets) do
            searchSet(entry.group,0.09)
            if not best then
                expanded=true
                searchSet(entry.group,0.09)
                expanded=false
            end
            if best then return best,bestTotal,bestLabel end
        end

        complete(empty,0,singles,0)
        complete(empty,0,pairsByValue,0)
        for _,single in ipairs(singles) do complete(single,single.total,pairsByValue,0) end
        for _,pairsByValueItem in ipairs(pairsByValue) do
            checkpoint()
            if pairsByValueItem.total<=ceiling then complete(pairsByValueItem,pairsByValueItem.total,pairsByValue,0) end
        end
        -- With no viable matching set, compare ordinary sets and singles.
        for _,group in ipairs(sets) do searchSet(group,0.035) end
        if not best then
            -- Widen the upper Supreme bound while enforcing both minimums.
            expanded=true
            complete(empty,0,singles,0)
            complete(empty,0,pairsByValue,0)
            for _,single in ipairs(singles) do complete(single,single.total,pairsByValue,0) end
            for _,pairsByValueItem in ipairs(pairsByValue) do complete(pairsByValueItem,pairsByValueItem.total,pairsByValue,0) end
            for _,group in ipairs(sets) do searchSet(group,0) end
        end
        return best,bestTotal,bestLabel
    end
    local function suggest(rows,partner,mode)
        local total=0
        local incoming={}
        local offerCents,hasUSD=0,true
        local unknown=false
        local signature={mode,tostring(partner)}
        for _,row in ipairs(rows) do
            local item=resolve(row)
            local count=math.max(1,math.floor(tonumber(row.amount or row.count) or 1))
            local cents=item and priceCents(item)
            if cents then offerCents=offerCents+cents*count else hasUSD=false end
            if item and item.value then
                total=total+item.value*count
                incoming[item.id]=(incoming[item.id] or 0)+count
                table.insert(signature,tostring(item.id)..":"..count)
            else
                unknown=true
                table.insert(signature,"unknown")
            end
        end
        table.sort(signature)
        signature=table.concat(signature,"|")
        if signature==lastSignature then return end
        lastSignature=signature
        searchToken=searchToken+1
        local token=searchToken
        card.Visible=true
        pendingSuggestion=false
        suggestedItemIds={}
        clearReturnModels()
        if unknown or total<=0 then
            updateSummary(partner,nil,nil)
            notice.Text="An offered item has no verified Supreme value or could not be identified."
            notice.Visible=true
            return
        end
        if not hasUSD then
            updateSummary(partner,nil,nil)
            notice.Text="A USD price is needed for every offered weapon."
            notice.Visible=true
            return
        end
        local goal=total*2
        updateSummary(partner,offerCents/100,offerCents*2/100)
        notice.Text="Calculating return…"
        notice.Visible=true
        local function active()
            return token==searchToken and lastSignature==signature and isCurrent()
                and settings.upgradeValueHelper and card.Visible
        end
        task.defer(function()
            if not active() then return end
            local deadline=os.clock()+0.002
            local steps=0
            local function checkpoint()
                steps=steps+1
                if steps<32 then return end
                steps=0
                if os.clock()<deadline then return end
                task.wait()
                if not active() then error("offer changed",0) end
                deadline=os.clock()+0.002
            end
            local success,best,_,setName=pcall(chooseReturn,goal,incoming,offerCents*2,checkpoint)
            if not active() then return end
            if not success then
                notice.Text="Could not calculate a return."
            elseif best then
                showReturnModels(best,setName)
                pendingSuggestion=true
            else
                notice.Text="No eligible return reaches both targets within four weapons."
            end
        end)
    end
    task.spawn(function()
        while isCurrent() do
            if settings.upgradeValueHelper then
                if not wasEnabled then lastSignature=nil end
                wasEnabled=true
                pcall(function()
                    local rows,partner,mode
                    local tradeGuiOpen=false
                    local activeGui=nil
                    if _G.pvSpoofActive then
                        -- A visual trade plans all its weapons up front, but
                        -- displays them in stages. Calculate from the visible
                        -- offer slots so each new weapon updates the suggestion.
                        local visualGui=playerGui2:FindFirstChild("pvTradeGUI")
                        if visualGui and visualGui.Enabled then
                            tradeGuiOpen=true
                            activeGui=visualGui
                            rows,partner=pvReadIncoming(visualGui,theirOfferedRef)
                        end
                        if not partner or partner=="" then
                            partner=tostring(_G.pvSpoofName or "Visual player"):gsub("[%(%)]","")
                        end
                        mode="Visual trade"
                    else
                        -- Capture sent weapons independent of their incoming
                        -- offer. A trade where we only RECEIVE cannot qualify.
                        local realGui=pvRealTradeGui()
                        if realGui then
                            tradeGuiOpen=true
                            activeGui=realGui
                        end
                        rows,partner=pvReadIncoming(realGui)
                        mode="Real trade"
                    end
                    -- A newly opened trade is a new opportunity to calculate,
                    -- even when it happens to show the same offer as the last.
                    if tradeGuiOpen and (not lastGuiWasOpen or activeGui~=lastTradeGui) then
                        lastSignature=nil
                        lastRealSent={} -- prevent stale outgoing-item matches
                        lastRealSentAt=-math.huge
                    end
                    lastGuiWasOpen=tradeGuiOpen
                    lastTradeGui=activeGui
                    if activeGui and not _G.pvSpoofActive then
                        local sent=readRealSentItems(activeGui)
                        if sent then
                            lastRealSent=sent
                            lastRealSentAt=os.clock()
                        end
                    end
                    if completionActive then
                        -- Keep success overlay visible during the closing animation.
                    elseif completionHold then
                        -- Never show old suggestions again while the completed
                        -- offer is still on screen. Reset on the next empty trade.
                        if not tradeGuiOpen or not rows or #rows==0 then
                            -- Some real-trade GUIs stay enabled between trades.
                            completionHold=false
                            lastSignature=nil
                        end
                        card.Visible=false
                    elseif rows and #rows>0 then
                        suggest(rows,partner,mode)
                    elseif pendingSuggestion then
                        -- A visual/real trade may close as soon as THEY give
                        -- the items, or briefly show empty slots between adds.
                        -- Don't wipe the recommendation just because they
                        -- finished giving us items. Keep it until OUR suggested
                        -- outgoing item is sent on a completed trade, the user
                        -- clears it, or a new priced offer replaces it.
                        card.Visible=true
                    else
                        if lastSignature~=nil or card.Visible then clearReturnModels() end
                        lastSignature=nil
                        card.Visible=false
                    end
                end)
            else
                if wasEnabled then clearReturnModels() end
                wasEnabled=false
                completionToken=completionToken+1
                completionActive=false
                completionHold=false
                pendingSuggestion=false
                lastTradeGui=nil
                lastGuiWasOpen=false
                lastSignature=nil
                suggestedItemIds={}
                lastRealSent={}
                lastRealSentAt=-math.huge
                successLayer.Visible=false
                card.Visible=false
            end
            task.wait(0.2)
        end
    end)
end)()
end
